class StageText(str):
    def __new__(cls, value: str, receipt: dict):
        instance = super().__new__(cls, value)
        instance.receipt = receipt
        return instance


class FinalReviewJSONError(ValueError):
    """Raised when all safe final-review JSON routes remain incomplete."""

    def __init__(self, message: str, detail: dict | None = None):
        super().__init__(message)
        self.detail = detail or {}
        self.reliability_failure = ReliabilityFailure(
            "final_review_json", FailureClass.SYNTAX_PROTOCOL,
            "final_review", protocol_only=True,
        )


class RevisionPlanError(RuntimeError):
    pass


class TargetedGroupError(RuntimeError):
    pass


class ProtocolReceiptRouteExhaustedError(RuntimeError):
    """All explicit routes failed before a receipt reached validation."""

    def __init__(self, failure: ReliabilityFailure):
        terminal = replace(failure, retryable=False)
        super().__init__(
            f"{terminal.boundary} route schedule exhausted: {terminal.code}"
        )
        self.reliability_failure = terminal


class ContextCapacityPreflightError(RuntimeError):
    """The request needs a different topology before a provider call."""

    def __init__(
        self, *, pressure: str, estimated_input_tokens: int,
        authority_input_tokens: int, output_reserve: int,
        context_window: int,
    ) -> None:
        super().__init__(
            "input context overflow preflight: lossless story authority plus "
            f"output reserve requires {estimated_input_tokens + output_reserve} "
            f"tokens for context window {context_window}; topology={pressure}"
        )
        self.pressure = pressure
        self.estimated_input_tokens = estimated_input_tokens
        self.authority_input_tokens = authority_input_tokens
        self.output_reserve = output_reserve
        self.context_window = context_window
        self.reliability_failure = ReliabilityFailure(
            "input_context_overflow", FailureClass.CONTEXT_CAPACITY,
            "model_dispatch", unit_id=pressure,
        )


class PlanningRecoveryUnavailableError(RuntimeError):
    """A semantic planning defect was found, but no model route was usable."""

    def __init__(self, issues: list[dict], execution_failures: list[dict]):
        self.issues = issues
        self.execution_failures = execution_failures
        details = "; ".join(
            str(item.get("error") or item.get("failure_class") or "unknown")[:240]
            for item in execution_failures
            if isinstance(item, dict)
        )
        super().__init__(
            "规划语义问题尚未解决，修复调用不可用；最佳规划和有效上游进度已保留"
            + (f"（{details}）" if details else "")
        )
        self.reliability_failure = ReliabilityFailure(
            "planning_recovery_unavailable", FailureClass.SEMANTIC_INVARIANT,
            "planning_recovery",
        )


class ExpansionRejectedError(ValueError):
    def __init__(self, code: str, category: str, message: str):
        super().__init__(message)
        self.code = code
        self.category = category


class PolishTokenBudgetError(RuntimeError):
    pass


class IncompleteModelOutputError(RuntimeError):
    """The transport finished, but the artifact did not prove completeness."""

    def __init__(self, stage: str, partial: StageText):
        super().__init__(f"{stage} output remained incomplete after output-limit recovery")
        self.stage = stage
        self.partial = partial
        self.receipt = partial.receipt
        self.reliability_failure = ReliabilityFailure(
            "output_incomplete", FailureClass.OUTPUT_TRUNCATION, stage,
        )


class GeneratedArtifactShapeError(ValueError):
    """A model artifact ended normally but needs protocol-level recovery."""

    def __init__(self, message: str, *, issues: list[dict] | None = None):
        super().__init__(message)
        self.issues = [
            dict(item) for item in (issues or []) if isinstance(item, dict)
        ]
        self.reliability_failure = ReliabilityFailure(
            "generated_artifact_shape", FailureClass.SYNTAX_PROTOCOL,
            "generated_artifact", protocol_only=True,
        )


class DraftSemanticValidationError(ValueError):
    def __init__(self, task_id: str, issues: str | list[dict]):
        normalized = (
            issues if isinstance(issues, list)
            else [{"code": "semantic_contract_failed", "message": str(issues)}]
        )
        detail = "；".join(
            str(item.get("message") or item.get("code")) for item in normalized
        )
        super().__init__(f"正文语义完整性检查未通过（{task_id}）：{detail}")
        self.task_id = task_id
        self.issues = normalized
        self.reliability_failure = ReliabilityFailure(
            "draft_semantic_contract", FailureClass.SEMANTIC_INVARIANT,
            "draft_validation", unit_id=task_id,
        )


def _draft_narrative_contract_fields(project: Project) -> dict[str, str]:
    contract = ensure_narrative_contract(project)
    return {
        "viewpoint": render_narrative_contract(contract),
        "narrative_mode": contract.mode,
        "narrator_character_id": contract.narrator_character_id,
        "narrator_name": contract.narrator_name,
        "self_reference": contract.self_reference,
    }


# ponytail: one local console process needs serialization, not a lock registry.
_SHORT_REVISION_LOCK = threading.Lock()


class WorkflowService:
    SHORT_SEGMENT_SEPARATOR = "\n\n<!-- NOVEL_FLYWHEEL_SEGMENT -->\n\n"
    SHORT_CHECKPOINT_VERSION = 3
    SHORT_PLAN_FIELD_ALIASES = PLAN_FIELD_ALIASES
    INITIAL_POLISH_INPUT_CAP = 120_000
    STRUCTURAL_POLISH_INPUT_CAP = 60_000

    def __init__(self, db: Database, projects: ProjectStore, gateway: ModelGateway,
                 skills: SkillGate, crewai_data_dir: Path | None = None,
                 skill_prompts: SkillPromptCompactor | None = None,
                 constraint_prompts: ConstraintPromptCompactor | None = None,
                 local_nlp=None, references=None) -> None:
        self.db = db
        self.projects = projects
        self.gateway = gateway
        self.skills = skills
        self.crewai_data_dir = crewai_data_dir or db.path.parent / "crewai"
        self.memory = StoryMemory(db)
        self.story_states = StoryStateStore(db)
        self.skill_prompts = skill_prompts or SkillPromptCompactor()
        self.constraint_prompts = constraint_prompts or ConstraintPromptCompactor()
        self.local_nlp = local_nlp
        self.references = references
        self.generated_artifacts = GeneratedArtifactGateway()
        self.protocol_route_circuit = ProtocolRouteCircuitBreaker()

    def _convert_generated_object(
        self, raw: str, run_path: Path, *, contract_name: str,
        semantic_normalizer: Callable[[object], dict | None] | None = None,
        expected_event_ids: Sequence[str] = (),
        owns_opening: bool = True, owns_ending: bool = True,
    ) -> dict:
        """Convert and audit one model artifact before domain code consumes it."""

        audit_root = run_path / "receipts" / "artifact-conversions"
        try:
            result = self.generated_artifacts.convert_object(
                raw,
                contract_name=contract_name,
                semantic_normalizer=semantic_normalizer,
                expected_event_ids=expected_event_ids,
                owns_opening=owns_opening,
                owns_ending=owns_ending,
            )
        except ArtifactConversionError as exc:
            write_conversion_audit(audit_root, exc.audit)
            raise
        write_conversion_audit(audit_root, result.audit)
        return result.payload

    def _short_revision_lock(self, run_id: str) -> threading.Lock:
        return _SHORT_REVISION_LOCK

    def _restore_snapshot_after_failure(
        self, run_id: str, snapshot: ProjectSnapshot,
    ) -> bool:
        try:
            snapshot.restore()
        except Exception as recovery_error:
            self.db.add_run_event(
                run_id, "warning", "snapshot_restore_failed",
                "项目文件恢复未完全完成，系统已保留最初的失败原因",
                stage="archive", metadata={
                    "recovery_error": str(recovery_error)[:500],
                },
            )
            return False
        return True

    @staticmethod
    def _formal_promotion_file_hash(path: Path) -> str | None:
        return hashlib.sha256(path.read_bytes()).hexdigest() if path.is_file() else None

    @staticmethod
    def _formal_promotion_project_path(
        project: Project, relative: object,
    ) -> Path:
        if not isinstance(relative, str) or not relative.strip():
            raise RuntimeError("正式稿晋升恢复日志包含无效文件路径")
        project_root = project.path.resolve()
        path = (project_root / relative).resolve()
        if not path.is_relative_to(project_root):
            raise RuntimeError("正式稿晋升恢复日志包含项目外路径")
        return path

    @staticmethod
    def _set_formal_promotion_journal_status(
        journal_path: Path, status: str, **updates,
    ) -> None:
        try:
            journal = json.loads(journal_path.read_text(encoding="utf-8"))
        except (OSError, UnicodeError, json.JSONDecodeError):
            return
        if not isinstance(journal, dict):
            return
        journal.update(updates)
        journal["status"] = status
        atomic_write(
            journal_path,
            json.dumps(journal, ensure_ascii=False, indent=2, sort_keys=True),
        )

    def _recover_short_formal_promotions(self, project: Project) -> None:
        """Resolve any process-interrupted formal manuscript promotion.

        A prepared journal means formal files may have been partially written.
        If StoryState did not advance, restore the pre-promotion snapshot. If
        StoryState already committed and all file hashes match, finalize the
        promotion. A later StoryState revision supersedes the stale journal and
        must never be overwritten by its older snapshot.
        """
        for journal_path in sorted(project.path.glob(
            "runs/*/outputs/formal-promotion-journal.json",
        )):
            try:
                journal = json.loads(journal_path.read_text(encoding="utf-8"))
            except (OSError, UnicodeError, json.JSONDecodeError):
                continue
            if not isinstance(journal, dict) or journal.get("version") != 1:
                continue
            if journal.get("status") not in {"prepared", "files_written"}:
                continue
            run_id = str(journal.get("run_id") or journal_path.parents[2].name)
            base_revision = int(journal.get("base_revision") or -1)
            target_revision = int(journal.get("target_revision") or -1)
            files = journal.get("files")
            if base_revision < 0 or target_revision != base_revision + 1 \
                    or not isinstance(files, list) or not files:
                raise RuntimeError("正式稿晋升恢复日志无效，已停止新的写作任务")
            state = self.story_states.ensure(project.id, project.path)
            resolved_files: list[tuple[Path, dict]] = []
            seen_paths: set[Path] = set()
            for item in files:
                if not isinstance(item, dict) \
                        or not isinstance(item.get("new_sha256"), str):
                    raise RuntimeError("正式稿晋升恢复日志包含无效文件记录")
                path = self._formal_promotion_project_path(project, item.get("path"))
                if path in seen_paths:
                    raise RuntimeError("正式稿晋升恢复日志包含重复文件记录")
                seen_paths.add(path)
                resolved_files.append((path, item))
            required_paths = {
                (project.path / "manuscript" / "story.md").resolve(),
                (project.path / "chapters" / "chapter-01.md").resolve(),
                (project.path / "memory" / "canon.json").resolve(),
            }
            if seen_paths != required_paths:
                raise RuntimeError("正式稿晋升恢复日志的权威文件集合不完整")
            expected_match = all(
                self._formal_promotion_file_hash(path) == item["new_sha256"]
                for path, item in resolved_files
            )
            snapshot_relative = journal.get("snapshot_path")
            if not isinstance(snapshot_relative, str):
                raise RuntimeError("正式稿晋升恢复日志缺少项目快照位置")
            snapshot_root = (project.path / snapshot_relative).resolve()
            snapshots_root = (project.path / "snapshots").resolve()
            if not snapshot_root.is_relative_to(snapshots_root):
                raise RuntimeError("正式稿晋升恢复快照不在项目快照目录内")
            if state.revision == target_revision and expected_match:
                ProjectSnapshot(project.path, snapshot_root, []).discard()
                journal["status"] = "committed_recovered"
                atomic_write(
                    journal_path,
                    json.dumps(journal, ensure_ascii=False, indent=2, sort_keys=True),
                )
                self.db.add_run_event(
                    run_id, "success", "formal_promotion_recovered",
                    "检测到正式稿与故事状态均已提交，已完成中断后的晋升收尾",
                    stage="archive",
                )
                continue
            if state.revision == target_revision:
                recovery_contents: list[tuple[Path, str]] = []
                recovery_root = (
                    journal_path.parent / "formal-promotion-payload"
                ).resolve()
                try:
                    for path, item in resolved_files:
                        recovery_relative = item.get("recovery_path")
                        if not isinstance(recovery_relative, str):
                            raise RuntimeError(
                                "故事状态已提交但正式稿不完整，恢复日志缺少确定性恢复载荷；"
                                "已保留恢复日志并停止新的写作任务"
                            )
                        recovery_path = self._formal_promotion_project_path(
                            project, recovery_relative,
                        )
                        if not recovery_path.is_relative_to(recovery_root):
                            raise RuntimeError(
                                "正式稿晋升恢复载荷不在当前运行的载荷目录内"
                            )
                        content = recovery_path.read_text(encoding="utf-8")
                        if hashlib.sha256(content.encode("utf-8")).hexdigest() \
                                != item["new_sha256"]:
                            raise RuntimeError("正式稿晋升恢复载荷哈希不匹配")
                        recovery_contents.append((path, content))
                except (OSError, UnicodeError) as exc:
                    raise RuntimeError(
                        "故事状态已提交但正式稿不完整，且确定性恢复载荷不可用；"
                        "已保留恢复日志并停止新的写作任务"
                    ) from exc
                for path, content in recovery_contents:
                    atomic_write(path, content)
                if not all(
                    self._formal_promotion_file_hash(path) == item["new_sha256"]
                    for path, item in resolved_files
                ):
                    raise RuntimeError(
                        "故事状态已提交但正式稿确定性恢复后仍不一致；"
                        "已保留恢复日志并停止新的写作任务"
                    )
                ProjectSnapshot(project.path, snapshot_root, []).discard()
                journal["status"] = "committed_repaired"
                atomic_write(
                    journal_path,
                    json.dumps(journal, ensure_ascii=False, indent=2, sort_keys=True),
                )
                self.db.add_run_event(
                    run_id, "warning", "formal_promotion_repaired",
                    "检测到故事状态已提交但正式稿文件不完整，已按哈希绑定载荷恢复",
                    stage="archive",
                )
                continue
            if state.revision == base_revision:
                try:
                    snapshot = ProjectSnapshot.load(project.path, snapshot_root)
                except ValueError as exc:
                    raise RuntimeError(
                        "正式稿晋升中断且原始快照不可用，已停止新的写作任务"
                    ) from exc
                snapshot.restore()
                snapshot.discard()
                candidate_id = str(journal.get("candidate_id") or "")
                if candidate_id:
                    self.story_states.reject(
                        candidate_id, "formal promotion recovered after process interruption",
                    )
                journal["status"] = "rolled_back_recovered"
                atomic_write(
                    journal_path,
                    json.dumps(journal, ensure_ascii=False, indent=2, sort_keys=True),
                )
                self.db.add_run_event(
                    run_id, "warning", "formal_promotion_rolled_back",
                    "检测到正式稿晋升在故事状态提交前中断，已恢复原正式稿",
                    stage="archive",
                )
                continue
            if state.revision > target_revision:
                # Another later accepted promotion owns the current formal
                # state. Never restore an older snapshot over it.
                ProjectSnapshot(project.path, snapshot_root, []).discard()
                journal["status"] = "superseded"
                atomic_write(
                    journal_path,
                    json.dumps(journal, ensure_ascii=False, indent=2, sort_keys=True),
                )
                continue
            raise RuntimeError("正式稿晋升恢复状态与 StoryState 版本不一致")

    def _analyze_manuscript(
        self, text: str, run_path: Path, project: Project, label: str,
    ) -> dict:
        output = run_path / "outputs" / f"analysis-{label}.json"
        try:
            cached = json.loads(output.read_text(encoding="utf-8"))
        except (OSError, json.JSONDecodeError):
            cached = {}
        if analysis_matches(cached, text):
            return cached
        enabled = bool(
            self.projects.get(project.id).metadata.get("optimized_local_review_enabled", False)
        )
        nlp_analyze = self.local_nlp.analyze if enabled and self.local_nlp else None
        sources = self.references.comparison_sources(project.id) if enabled and self.references else []
        baseline = self.projects.active_learning_data(project.id, "market_baseline")
        report = analyze_manuscript(
            text, nlp_analyze=nlp_analyze, comparison_sources=sources,
            market_baseline=baseline,
        )
        output.parent.mkdir(parents=True, exist_ok=True)
        atomic_write(output, json.dumps(report, ensure_ascii=False, indent=2))
        return report

    def _constraints_with_platform_rules(self, project: Project, constraints: str) -> str:
        marker = "\n\nMATCHED PLATFORM RULE REFERENCES:\n"
        if marker in constraints or not self.references or not hasattr(self.references, "platform_rules"):
            return constraints
        rules = self.references.platform_rules(project.metadata.get("platform"))
        if not rules:
            return constraints
        compact = [
            {"title": item["title"], "text": item["text"][:8000]}
            for item in rules[:5]
        ]
        return constraints + marker + json.dumps(compact, ensure_ascii=False)

    async def run_short(self, project_id: str, use_crewai: bool = True,
                        run_id: str | None = None) -> dict:
        project = self.projects.get(project_id)
        if project.mode != "short":
            raise ValueError("Short-story workflow requires a short project")
        if use_crewai:
            return await self._run_in_crewai(lambda: self._short_pipeline(project, run_id))
        return await self._short_pipeline(project, run_id)

    async def run_short_revision(
        self, project_id: str, issue_ids: list[str],
        run_id: str | None = None,
    ) -> dict:
        project = self.projects.get(project_id)
        if project.mode != "short":
            raise ValueError("定向返修目前只支持短篇作品")
        return await self._short_revision_pipeline(project, issue_ids, run_id)

    def decide_short_revision_group(
        self, run_id: str, group_id: str, decision: str,
        candidate_hash: str,
    ) -> dict:
        with self._short_revision_lock(run_id):
            return self._decide_short_revision_group(
                run_id, group_id, decision, candidate_hash,
            )

    def _decide_short_revision_group(
        self, run_id: str, group_id: str, decision: str,
        candidate_hash: str,
    ) -> dict:
        if decision not in {"adopted", "rejected"}:
            raise ValueError("Unsupported revision decision")
        operations = RevisionOperations(self.db, self.projects, self)
        authority = operations.load_state(run_id)
        run = authority["run"]
        if run.get("status") not in {
            "waiting_confirmation", "waiting_local_fix",
        }:
            raise RevisionOperationError(
                409, "revision_run_invalid",
                "当前返修任务不在可确认修改的阶段。",
            )
        state = authority["state"]
        if candidate_hash != state.get("candidate_hash"):
            raise RevisionOperationError(
                409, "revision_candidate_changed",
                "返修候选稿已经变化，请刷新后重试。",
            )
        records_value = state["groups"].get("groups")
        if not isinstance(records_value, list):
            raise RevisionOperationError(
                409, "revision_run_invalid",
                "返修记录不完整或已经损坏，请重新开始本次返修。",
            )
        record = next(
            (
                item for item in records_value
                if isinstance(item, dict) and item.get("group_id") == group_id
            ),
            None,
        )
        if record is None:
            raise RevisionOperationError(
                404, "revision_group_not_found", "没有找到这个修改组。",
            )
        automatic_decision = (
            "adopted"
            if (
                record.get("kind") == "mechanical"
                and record.get("status") == "ready_for_confirmation"
                and record.get("patch_result", {}).get("accepted") is True
            )
            else None
        )
        existing = record.get("decision") or automatic_decision
        if existing is not None:
            if existing == decision:
                return self._short_revision_public_group(
                    operations.read(run_id), group_id,
                )
            raise RevisionOperationError(
                409, "revision_group_already_decided",
                "这个修改组已经作出相反决定，不能重复更改。",
            )
        if (
            record.get("kind") not in {"semantic", "expansion"}
            or record.get("status") != "ready_for_confirmation"
            or record.get("patch_result", {}).get("accepted") is not True
        ):
            raise RevisionOperationError(
                409, "revision_group_not_ready",
                "这个修改组尚未通过本地检查，不能确认。",
            )
        record["decision"] = decision
        record["decision_candidate_hash"] = candidate_hash
        if decision == "rejected":
            record["issue_status"] = "unresolved"

        contract = state["contract"]
        completed = set(state.get("completed_groups", []))
        report = state.get("report")
        gate = report.get("gate") if isinstance(report, dict) else None
        store = authority["store"]
        files = [
            store.output / name
            for name in (
                store.GROUPS, store.CANDIDATE, store.CHECKPOINT, store.REPORT,
            )
        ]
        snapshot = ProjectSnapshot.create(
            authority["project"].path,
            (
                authority["project"].path
                / "snapshots"
                / f"revision-decision-{uuid.uuid4().hex[:12]}"
            ),
            files,
        )
        try:
            self._save_short_revision_state(
                store, contract, run_id, records_value, state["candidate"],
                completed, gate, str(run["status"]),
            )
        except Exception:
            snapshot.restore()
            raise
        return self._short_revision_public_group(
            operations.read(run_id), group_id,
        )

    @staticmethod
    def _short_revision_public_group(summary: dict, group_id: str) -> dict:
        for group in summary["groups"]:
            if group.get("group_id") == group_id:
                return group
        raise RevisionOperationError(
            404, "revision_group_not_found", "没有找到这个修改组。",
        )

    async def finalize_short_revision(self, run_id: str) -> dict:
        try:
            return await self._finalize_short_revision(run_id)
        except RevisionOperationError as exc:
            run = self.db.get_run(run_id) or {}
            if run.get("status") == "failed":
                stage = str(run.get("current_stage") or "revision_finalize")
                record_production_failure(
                    self.db, run_id,
                    workflow=str(run.get("workflow") or "short-revision"),
                    stage=stage,
                    raw_error=describe_error(exc),
                    user_message=str(run.get("error") or exc.message),
                    event_type="short_revision_failed",
                    failure=getattr(exc, "reliability_failure", None),
                )
            raise
        except asyncio.CancelledError:
            self.db.update_run(run_id, "failed", "revision_finalize")
            raise
        except Exception as exc:
            run = self.db.get_run(run_id)
            if run is not None and run.get("status") != "completed":
                self.db.update_run(
                    run_id, "failed", "revision_finalize",
                    error="返修终审未完成，已保留修改决定，可以稍后重试。",
                )
                record_production_failure(
                    self.db, run_id,
                    workflow=str(run.get("workflow") or "short-revision"),
                    stage="revision_finalize",
                    raw_error=describe_error(exc),
                    user_message="返修终审未完成，已保留修改决定，可以稍后重试。",
                    event_type="short_revision_failed",
                    failure=getattr(exc, "reliability_failure", None),
                )
            raise

    async def _finalize_short_revision(self, run_id: str) -> dict:
        operations = RevisionOperations(self.db, self.projects, self)
        run = self.db.get_run(run_id)
        if run is None:
            raise RevisionOperationError(
                404, "run_not_found", "没有找到这次运行。",
            )
        if run.get("workflow") != "short-revision":
            raise RevisionOperationError(
                409, "revision_run_invalid", "该任务不是定向返修任务。",
            )
        if run.get("status") == "completed":
            raise RevisionOperationError(
                409, "revision_already_finalized", "这次返修已经完成终审。",
            )

        project = self.projects.get(str(run["project_id"]))
        run_path = project.path / "runs" / run_id
        if self.recover_short_revision_promotion(run_id):
            return operations.read(run_id)

        authority = operations.load_state(run_id)
        run = authority["run"]
        if run.get("status") not in {
            "waiting_confirmation", "waiting_local_fix", "failed", "interrupted",
        }:
            raise RevisionOperationError(
                409, "revision_run_invalid", "当前返修任务不能进入终审。",
            )
        state = authority["state"]
        contract = state["contract"]
        records = state["groups"].get("groups")
        if not isinstance(records, list):
            raise RevisionOperationError(
                409, "revision_run_invalid",
                "返修记录不完整或已经损坏，请重新开始本次返修。",
            )

        adopted_records: list[dict] = []
        rejected_issue_ids: set[str] = set()
        for record in records:
            if not isinstance(record, dict):
                raise RevisionOperationError(
                    409, "revision_run_invalid",
                    "返修记录不完整或已经损坏，请重新开始本次返修。",
                )
            kind = record.get("kind")
            patch_result = record.get("patch_result")
            ready = (
                record.get("status") == "ready_for_confirmation"
                and isinstance(patch_result, dict)
                and patch_result.get("accepted") is True
                and isinstance(record.get("patch_group"), dict)
            )
            if kind == "mechanical":
                if not ready:
                    raise RevisionOperationError(
                        409, "revision_group_not_ready",
                        "仍有机械修改未通过本地检查，不能开始终审。",
                    )
                adopted_records.append(record)
                continue
            if kind not in {"semantic", "expansion"}:
                raise RevisionOperationError(
                    409, "revision_run_invalid",
                    "返修记录包含不支持的修改组。",
                )
            if not ready:
                raise RevisionOperationError(
                    409, "revision_group_not_ready",
                    "仍有语义修改未通过本地检查，不能开始终审。",
                )
            decision = record.get("decision")
            if decision not in {"adopted", "rejected"}:
                raise RevisionOperationError(
                    409, "revision_decisions_incomplete",
                    "请先确认或拒绝每一个语义修改组。",
                )
            if record.get("decision_candidate_hash") != state.get(
                "candidate_hash"
            ):
                raise RevisionOperationError(
                    409, "revision_candidate_changed",
                    "修改决定对应的候选稿已经变化，请刷新后重试。",
                )
            if decision == "adopted":
                adopted_records.append(record)
            else:
                rejected_issue_ids.update(record.get("issue_ids", []))

        candidate = authority["protected"]["source"]
        adopted_groups = []
        patch_results = []
        for record in adopted_records:
            patch_group = record["patch_group"]
            result = {
                "group_id": record["group_id"],
                **apply_patch_group(
                    candidate, patch_group, self._text_hash(candidate),
                ),
            }
            if result["accepted"] is not True:
                raise RevisionOperationError(
                    409, "revision_group_not_ready",
                    "已确认修改无法按冻结原稿完整重放，请重新开始本次返修。",
                )
            candidate = result["text"]
            adopted_groups.append(patch_group)
            patch_results.append(result)

        if not self.db.claim_run_status(
            run_id,
            {"waiting_confirmation", "waiting_local_fix", "failed", "interrupted"},
            "running",
            "revision_gate",
        ):
            current = self.db.get_run(run_id) or {}
            if current.get("status") == "completed":
                raise RevisionOperationError(
                    409, "revision_already_finalized", "这次返修已经完成终审。",
                )
            raise RevisionOperationError(
                409, "revision_run_invalid", "这次返修正在由另一个请求处理。",
            )

        analysis = self._analyze_manuscript(
            candidate, run_path, project, "repair-final",
        )
        adopted_issue_ids = {
            issue_id
            for record in adopted_records
            for issue_id in record.get("issue_ids", [])
        }
        adopted_issues = [
            item
            for item in contract.get("selected_issues", [])
            if (
                isinstance(item, dict)
                and item.get("issue_id") in adopted_issue_ids
            )
        ]
        gate_contract = {
            "manuscript_hash": contract["manuscript_hash"],
            "required_text": self._repair_literals(
                adopted_issues, "required_text",
            ),
            "forbidden_text": self._repair_literals(
                adopted_issues, "forbidden_text",
            ),
            "groups": adopted_groups,
        }
        minimum_han, maximum_han = self._short_revision_target_range(
            project,
            source_han=effective_han_characters(
                authority["protected"]["source"],
            ),
        )
        gate = evaluate_candidate_gate(
            source=authority["protected"]["source"],
            candidate=candidate,
            source_hash=authority["protected"]["source_hash"],
            analysis=analysis,
            contract=gate_contract,
            patch_results=patch_results,
            story_state=contract["story_state"]["data"],
            passage_locks=contract["passage_locks"],
            minimum_han=minimum_han,
            maximum_han=maximum_han,
        )
        report = (
            dict(state.get("report"))
            if isinstance(state.get("report"), dict) else {}
        )
        if not gate["passed"]:
            report.update({
                "status": "waiting_local_fix",
                "gate": gate,
                "next_action": "请先处理未通过的本地检查，再重新终审。",
            })
            authority["store"].write_report(report)
            self.db.update_run(
                run_id, "waiting_local_fix", "revision_gate",
            )
            raise RevisionOperationError(
                409, "revision_gate_failed",
                "候选稿未通过整篇本地检查，尚未调用终审模型。",
            )

        semantic_authority = contract.get("semantic_authority")
        if isinstance(semantic_authority, dict):
            revision_constraints = (
                project.path / "constraints.md"
            ).read_text(encoding="utf-8")
            try:
                revision_integrity = await self._verify_atomic_candidate_semantics(
                    run_id, run_path, project,
                    revision_constraints,
                    str(semantic_authority.get("source_text") or ""),
                    candidate, semantic_authority,
                    suffix="-revision-final",
                    failure_stage="repair_groups", verify_whole=True,
                )
            except asyncio.CancelledError:
                raise
            except (DraftSemanticValidationError, ValueError) as exc:
                issues = (
                    exc.issues if isinstance(exc, DraftSemanticValidationError)
                    else [{"code": "whole_semantic_gate", "message": str(exc)}]
                )
                try:
                    recovered = await self._recover_short_revision_semantic_subset(
                        run_id, run_path, project, revision_constraints,
                        authority["protected"]["source"], semantic_authority,
                        adopted_records, issues,
                    )
                except asyncio.CancelledError:
                    raise
                except (DraftSemanticValidationError, ValueError) as recovery_exc:
                    report.update({
                        "status": "waiting_local_fix",
                        "gate": gate,
                        "semantic_issues": issues,
                        "next_action": (
                            "自动隔离冲突修改后仍未恢复整篇语义，"
                            "请重新生成或拒绝相关修改组后再次终审。"
                        ),
                    })
                    authority["store"].write_report(report)
                    self.db.update_run(
                        run_id, "waiting_local_fix", "revision_semantic_gate",
                    )
                    self.db.add_run_event(
                        run_id, "warning", "short_revision_semantic_gate_rejected",
                        "已采用修改发生整篇冲突，自动隔离后仍未恢复，未调用终审",
                        stage="revision_semantic_gate", metadata={
                            "issues": issues,
                            "recovery_error": str(recovery_exc)[:500],
                        },
                    )
                    raise RevisionOperationError(
                        409, "revision_semantic_gate_failed",
                        "候选稿未通过原子节拍和整篇因果复核，自动隔离后仍未恢复。",
                    ) from recovery_exc
                except Exception as recovery_exc:
                    report.update({
                        "status": "failed",
                        "gate": gate,
                        "next_action": (
                            "语义冲突隔离复核暂时不可用，"
                            "已保留全部修改决定，可稍后重试。"
                        ),
                    })
                    authority["store"].write_report(report)
                    self.db.update_run(
                        run_id, "failed", "revision_semantic_gate",
                        error="语义冲突隔离复核暂时不可用，可以稍后重试。",
                    )
                    self.db.add_run_event(
                        run_id, "error", "short_revision_semantic_review_unavailable",
                        "整篇语义冲突隔离复核暂时不可用，已保留修改决定",
                        stage="revision_semantic_gate", metadata={
                            "failure_class": classify_model_failure(recovery_exc),
                        },
                    )
                    raise RevisionOperationError(
                        502, "revision_semantic_review_unavailable",
                        "整篇语义冲突隔离复核暂时不可用，请稍后重试。",
                    ) from None

                candidate = recovered["candidate"]
                adopted_records = recovered["records"]
                adopted_groups = recovered["groups"]
                patch_results = recovered["results"]
                revision_integrity = recovered["integrity"]
                rejected_issue_ids.update(recovered["rejected_issue_ids"])
                analysis = self._analyze_manuscript(
                    candidate, run_path, project, "repair-final-recovered",
                )
                adopted_issue_ids = {
                    issue_id
                    for record in adopted_records
                    for issue_id in record.get("issue_ids", [])
                }
                adopted_issues = [
                    item
                    for item in contract.get("selected_issues", [])
                    if (
                        isinstance(item, dict)
                        and item.get("issue_id") in adopted_issue_ids
                    )
                ]
                gate_contract = {
                    "manuscript_hash": contract["manuscript_hash"],
                    "required_text": self._repair_literals(
                        adopted_issues, "required_text",
                    ),
                    "forbidden_text": self._repair_literals(
                        adopted_issues, "forbidden_text",
                    ),
                    "groups": adopted_groups,
                }
                gate = evaluate_candidate_gate(
                    source=authority["protected"]["source"],
                    candidate=candidate,
                    source_hash=authority["protected"]["source_hash"],
                    analysis=analysis,
                    contract=gate_contract,
                    patch_results=patch_results,
                    story_state=contract["story_state"]["data"],
                    passage_locks=contract["passage_locks"],
                    minimum_han=minimum_han,
                    maximum_han=maximum_han,
                )
                if not gate["passed"]:
                    report.update({
                        "status": "waiting_local_fix",
                        "gate": gate,
                        "semantic_issues": issues,
                        "next_action": (
                            "冲突修改已隔离，但恢复后的安全组合未通过整篇本地检查。"
                        ),
                    })
                    authority["store"].write_report(report)
                    self.db.update_run(
                        run_id, "waiting_local_fix", "revision_gate",
                    )
                    raise RevisionOperationError(
                        409, "revision_gate_failed",
                        "冲突修改隔离后的候选稿未通过整篇本地检查。",
                    )
            except Exception as exc:
                report.update({
                    "status": "failed",
                    "gate": gate,
                    "next_action": "语义复核暂时不可用，已保留全部修改决定，可稍后重试。",
                })
                authority["store"].write_report(report)
                self.db.update_run(
                    run_id, "failed", "revision_semantic_gate",
                    error="语义复核暂时不可用，可以稍后重试。",
                )
                self.db.add_run_event(
                    run_id, "error", "short_revision_semantic_review_unavailable",
                    "原子节拍复核暂时不可用，已保留修改决定和安全检查点",
                    stage="revision_semantic_gate", metadata={
                        "failure_class": classify_model_failure(exc),
                    },
                )
                raise RevisionOperationError(
                    502, "revision_semantic_review_unavailable",
                    "原子节拍复核暂时不可用，已保留修改决定，请稍后重试。",
                ) from None
            atomic_write(
                run_path / "outputs" / "revision-integrity.json",
                json.dumps(revision_integrity, ensure_ascii=False, indent=2),
            )
            report["narrative_integrity"] = {
                "path": "outputs/revision-integrity.json",
                "sha256": hashlib.sha256(
                    (run_path / "outputs" / "revision-integrity.json").read_bytes(),
                ).hexdigest(),
            }

        protected = authority["protected"]
        baseline_review = {
            **protected["review"],
            "scoring_profile_id": protected["checkpoint"].get(
                "scoring_profile_id", "legacy-v1",
            ),
            "judge_signature": protected["checkpoint"].get(
                "judge_signature", "legacy-unknown",
            ),
        }
        baseline = build_review_baseline(
            protected["source"],
            contract["analysis"],
            [],
            baseline_review,
        )
        initial_review = {
            **baseline_review,
            "issues": [
                (
                    {**item, "status": "unresolved"}
                    if item.get("issue_id") in rejected_issue_ids else dict(item)
                )
                for item in contract.get("issue_ledger", [])
                if isinstance(item, dict)
            ],
        }
        constraints = (project.path / "constraints.md").read_text(
            encoding="utf-8",
        )
        try:
            review, review_audit = await self._incremental_manuscript_review(
                run_id, run_path, project, constraints,
                candidate, analysis, baseline, initial_review,
                suffix="-revision-final",
                revision_source_hash=protected["source_hash"],
                patch_groups=adopted_groups,
            )
        except asyncio.CancelledError:
            self.db.update_run(run_id, "failed", "final_review")
            raise
        except Exception:
            report.update({
                "status": "failed",
                "gate": gate,
                "next_action": "终审暂时不可用，可以保留现有决定后重试。",
            })
            authority["store"].write_report(report)
            self.db.update_run(
                run_id, "failed", "final_review",
                error="终审暂时不可用，可以稍后重试。",
            )
            self.db.add_run_event(
                run_id, "error", "short_revision_review_unavailable",
                "终审暂时不可用，已保留所有修改决定，可以稍后重试。",
                stage="final_review",
            )
            raise RevisionOperationError(
                502, "revision_review_unavailable",
                "终审暂时不可用，已保留修改决定，请稍后重试。",
            ) from None

        return self._commit_short_revision_promotion(
            operations, run_id, run_path, project, candidate, contract,
            records, gate, state, report, review, review_audit,
            rejected_issue_ids,
        )

    def recover_short_revision_promotion(self, run_id: str) -> bool:
        with QUALITY_CHECKPOINT_LOCK:
            run = self.db.get_run(run_id)
            if run is None or run.get("workflow") != "short-revision":
                return False
            project = self.projects.get(str(run["project_id"]))
            run_path = project.path / "runs" / run_id
            journal_path = (
                project.path / "snapshots" / f"revision-promotion-{run_id}"
            )
            marker = load_quality_checkpoint(run_path)
            promoted = bool(
                marker is not None
                and marker.get("manuscript_path") == "outputs/candidate.md"
                and marker.get("terminal_reviewed_hash")
                == marker.get("manuscript_hash")
            )
            if promoted:
                was_completed = run.get("status") == "completed"
                self.db.update_run(run_id, "completed", "revision_completed")
                if not was_completed:
                    self.db.add_run_event(
                        run_id, "success", "short_revision_completed",
                        "返修候选稿已通过检查并成为新的受保护最佳稿。",
                        stage="revision_completed",
                    )
                ProjectSnapshot(
                    project.path, journal_path, [],
                ).discard()
                return True
            if journal_path.is_dir():
                try:
                    journal = ProjectSnapshot.load(project.path, journal_path)
                except ValueError:
                    ProjectSnapshot(project.path, journal_path, []).discard()
                    return False
                journal.restore()
                journal.discard()
            return False

    def _commit_short_revision_promotion(
        self, operations: RevisionOperations, run_id: str, run_path: Path,
        project: Project, candidate: str, contract: dict, records: list[dict],
        gate: dict, state: dict, report: dict, review: dict,
        review_audit: dict, rejected_issue_ids: set[str],
    ) -> dict:
        with QUALITY_CHECKPOINT_LOCK:
            try:
                authority = operations.load_state(run_id)
            except RevisionOperationError:
                self.db.update_run(run_id, "failed", "revision_authority")
                raise
            current_state = authority["state"]
            if current_state.get("contract_hash") != state.get("contract_hash"):
                self.db.update_run(run_id, "failed", "revision_authority")
                raise RevisionOperationError(
                    409, "revision_source_changed",
                    "终审期间受保护原稿已经变化，请重新开始本次返修。",
                )
            if any(
                current_state.get(key) != state.get(key)
                for key in ("groups_hash", "candidate_hash")
            ):
                self.db.update_run(run_id, "failed", "revision_authority")
                raise RevisionOperationError(
                    409, "revision_candidate_changed",
                    "终审期间返修决定或候选稿已经变化，请刷新后重试。",
                )

            current_protected = authority["protected"]
            current_review = {
                **current_protected["review"],
                "scoring_profile_id": current_protected["checkpoint"].get(
                    "scoring_profile_id", "legacy-v1",
                ),
                "judge_signature": current_protected["checkpoint"].get(
                    "judge_signature", "legacy-unknown",
                ),
            }
            review = self._force_rejected_revision_issues(
                review, contract.get("issue_ledger", []), rejected_issue_ids,
            )
            comparison = compare_quality_candidates(current_review, review)
            review_mode = str(review_audit.get("review_mode") or "full")
            full_review_reasons = list(review_audit.get("fallback_reasons") or [])
            if not comparison["promote"]:
                report.update({
                    "status": "waiting_confirmation",
                    "gate": gate,
                    "review_mode": review_mode,
                    "full_review_reasons": full_review_reasons,
                    "comparison": comparison,
                    "next_action": "候选稿没有超过当前受保护最佳稿，请调整决定后再试。",
                })
                authority["store"].write_report(report)
                self.db.update_run(
                    run_id, "waiting_confirmation", "quality_comparison",
                )
                raise RevisionOperationError(
                    409, "revision_not_improved",
                    "候选稿没有达到替换当前受保护最佳稿的条件。",
                )

            outcome, _reasons = quality_outcome_for_profile(
                review, str(review.get("scoring_profile_id") or "legacy-v1"),
            )
            store = authority["store"]
            repair_checkpoint = {
                key: value for key, value in current_state.items()
                if key not in {"contract", "groups", "candidate", "report"}
            }
            repair_checkpoint.update({
                "status": "completed",
                "candidate_hash": repair_artifact_hash(candidate),
            })
            journal_path = (
                project.path / "snapshots" / f"revision-promotion-{run_id}"
            )
            snapshot = ProjectSnapshot.create(project.path, journal_path, [
                store.output / store.CANDIDATE,
                store.output / store.CHECKPOINT,
                store.output / store.REPORT,
                store.output / "quality-checkpoint.json",
                store.output / "short-execution-index.json",
            ])
            try:
                store.write_candidate(candidate)
                store.write_checkpoint(repair_checkpoint)
                promoted_report = self._write_short_revision_report(
                    store, run_id, records, candidate, gate, "completed", contract,
                )
                promoted_report.update({
                    "review_mode": review_mode,
                    "full_review_reasons": full_review_reasons,
                    "comparison": comparison,
                    "next_action": "返修候选稿已成为新的受保护最佳稿。",
                })
                store.write_report(promoted_report)
                digest = self._text_hash(candidate)
                semantic_authority = contract.get("semantic_authority")
                if isinstance(semantic_authority, dict):
                    atomic_write(
                        store.output / "short-execution-index.json",
                        json.dumps(
                            semantic_authority.get("execution_manifest"),
                            ensure_ascii=False, indent=2,
                        ),
                    )
                write_quality_checkpoint(run_path, {
                    "manuscript_path": "outputs/candidate.md",
                    "manuscript_hash": digest,
                    "score": float(review["score"]),
                    "scoring_profile_id": str(
                        review.get("scoring_profile_id") or "legacy-v1"
                    ),
                    "judge_signature": str(
                        review.get("judge_signature") or "legacy-unknown"
                    ),
                    "best_attempt": 1,
                    "review": review,
                    "issue_ledger": issue_ledger(review.get("issues", [])),
                    "outcome": outcome,
                    "terminal_reviewed_hash": digest,
                    **({
                        "narrative_integrity": report["narrative_integrity"],
                    } if isinstance(report.get("narrative_integrity"), dict) else {}),
                })
            except Exception:
                snapshot.restore()
                snapshot.discard()
                self.db.update_run(
                    run_id, "failed", "revision_promotion",
                    error="返修结果保存失败，可以保留决定后重试。",
                )
                raise
            self.db.update_run(run_id, "completed", "revision_completed")
            self.db.add_run_event(
                run_id, "success", "short_revision_completed",
                "返修候选稿已通过检查并成为新的受保护最佳稿。",
                stage="revision_completed",
            )
            snapshot.discard()
            return operations.read(run_id)

    @staticmethod
    def _force_rejected_revision_issues(
        review: dict, frozen_ledger: list[dict],
        rejected_issue_ids: set[str],
    ) -> dict:
        result = dict(review)
        issues = issue_ledger(result.get("issues", []))
        by_id = {
            item.get("issue_id"): index
            for index, item in enumerate(issues)
            if isinstance(item, dict)
        }
        frozen = {
            item.get("issue_id"): item
            for item in frozen_ledger
            if isinstance(item, dict)
        }
        for issue_id in rejected_issue_ids:
            if issue_id in by_id:
                index = by_id[issue_id]
                issues[index] = {**issues[index], "status": "unresolved"}
            elif issue_id in frozen:
                issues.append({**frozen[issue_id], "status": "unresolved"})
        result["issues"] = issues
        return result

    async def _short_revision_pipeline(
        self, project: Project, issue_ids: list[str],
        run_id: str | None = None,
    ) -> dict:
        selected_ids = self._selected_repair_issue_ids(issue_ids)
        protected = self._protected_short_revision_source(project)
        ledger_by_id = {
            item.get("issue_id"): item
            for item in protected["issue_ledger"]
            if isinstance(item, dict) and isinstance(item.get("issue_id"), str)
        }
        unknown = [issue_id for issue_id in selected_ids if issue_id not in ledger_by_id]
        if unknown:
            raise ValueError("所选问题已不属于当前受保护最佳稿，请重新确认")
        story_state = self.story_states.get(project.id)
        if story_state is None:
            raise ValueError("当前作品缺少可校验的 StoryState，不能开始定向返修")

        run_id, run_path = self._begin_run(project, "short-revision", run_id)
        store = RepairRunStore(run_path)
        try:
            resume = (store.output / store.CHECKPOINT).is_file()
            if not resume and any(
                (store.output / name).is_file()
                for name in (store.CONTRACT, store.GROUPS, store.CANDIDATE)
            ):
                resume = True
            if resume:
                state = store.load_resume_state(protected["source_hash"])
                contract = state["contract"]
                frozen_ids = contract.get("selected_issue_ids")
                if (
                    not isinstance(frozen_ids, list)
                    or set(frozen_ids) != set(selected_ids)
                    or len(frozen_ids) != len(selected_ids)
                ):
                    raise ValueError("继续返修时所选问题必须与原返修合同一致")
                selected_ids = list(frozen_ids)
                records = state["groups"]["groups"]
                candidate = state["candidate"]
                completed = set(state["completed_groups"])
            else:
                analysis = self._analyze_manuscript(
                    protected["source"], run_path, project, "repair-source",
                )
                selected_issues = [
                    self._json_copy(ledger_by_id[issue_id])
                    for issue_id in selected_ids
                ]
                current_han = effective_han_characters(protected["source"])
                nominal_minimum_han, nominal_maximum_han = (
                    self._short_revision_target_range(project)
                )
                deficit_han = max(0, nominal_minimum_han - current_han)
                causal_chain_artifact = LearningSystem(
                    self.db, self.references, self.projects, self.gateway,
                ).get_artifact(project.id, "short_causal_chain")
                expansion_issue_id = next((
                    issue["issue_id"] for issue in selected_issues
                    if deficit_han and self._is_length_deficit_issue(issue)
                ), None)
                groups = [{
                    "group_id": issue_id,
                    "issue_ids": [issue_id],
                    "kind": (
                        "expansion"
                        if issue_id == expansion_issue_id
                        else "mechanical"
                        if self._mechanical_issue_code(ledger_by_id[issue_id])
                        else "semantic"
                    ),
                    "requires_user_confirmation": True,
                } for issue_id in selected_ids]
                contract = {
                    "version": 1,
                    "manuscript_hash": protected["source_hash"],
                    "source_run_id": protected["run_id"],
                    "terminal_reviewed_hash": protected["checkpoint"][
                        "terminal_reviewed_hash"
                    ],
                    "selected_issue_ids": selected_ids,
                    "selected_issues": selected_issues,
                    "issue_ledger": self._json_copy(protected["issue_ledger"]),
                    "review": self._json_copy(protected["review"]),
                    "story_state": {
                        "revision": story_state.revision,
                        "data": self._json_copy(story_state.data),
                    },
                    "seven_step_causal_chain": (
                        self._json_copy(causal_chain_artifact["data"])
                        if (
                            causal_chain_artifact is not None
                            and causal_chain_artifact.get("status") == "active"
                        )
                        else None
                    ),
                    "passage_locks": self._json_copy(
                        self.db.list_locks(project.id),
                    ),
                    "semantic_authority": self._json_copy(
                        protected.get("semantic_authority"),
                    ),
                    "analysis": analysis,
                    "required_text": self._repair_literals(
                        selected_issues, "required_text",
                    ),
                    "forbidden_text": self._repair_literals(
                        selected_issues, "forbidden_text",
                    ),
                    "length_budget": {
                        "current_han": current_han,
                        "minimum_han": nominal_minimum_han,
                        "maximum_han": nominal_maximum_han,
                        "deficit_han": deficit_han,
                    },
                    "groups": groups,
                }
                store.write_contract(contract)
                records = [{
                    **group,
                    "status": "pending",
                    "attempts": 0,
                    "message": "等待处理",
                } for group in groups]
                candidate = protected["source"]
                completed: set[str] = set()
                self._write_short_revision_progress(
                    store, contract, records, candidate, completed, "running",
                )

            issues = {
                item["issue_id"]: item
                for item in contract["selected_issues"]
            }
            constraints = (project.path / "constraints.md").read_text(
                encoding="utf-8",
            )
            provider_failures = False
            for group in contract["groups"]:
                group_id = group["group_id"]
                if group_id in completed:
                    continue
                candidate_before_group = candidate
                record = next(
                    item for item in records if item["group_id"] == group_id
                )
                issue = issues[group_id]
                record["attempts"] = int(record.get("attempts", 0)) + 1
                record["status"] = "processing"
                record["message"] = "正在生成安全补丁"
                patch_group = None
                try:
                    if group["kind"] == "mechanical":
                        patch_group = self._mechanical_patch_group(
                            issue, candidate, group_id,
                        )
                        if patch_group is None:
                            result = {
                                "group_id": group_id,
                                "accepted": False,
                                "text": candidate,
                                "failures": [{
                                    "patch": 0,
                                    "code": "mechanical_scope_not_unique",
                                }],
                                "diffs": [],
                            }
                        else:
                            result = {
                                "group_id": group_id,
                                **apply_patch_group(
                                    candidate, patch_group,
                                    self._text_hash(candidate),
                                ),
                            }
                    elif group["kind"] == "expansion":
                        patch_group = await self._expansion_patch_group(
                            run_id, run_path, project, constraints,
                            contract, issue, group_id, candidate,
                            record, store, records, completed,
                        )
                        result = {
                            "group_id": group_id,
                            **apply_patch_group(
                                candidate, patch_group,
                                self._text_hash(candidate),
                            ),
                        }
                    else:
                        request = self._semantic_patch_request(
                            contract, issue, group_id, candidate,
                        )
                        contract_error: ValueError | None = None
                        patch_group = None
                        for protocol_attempt in range(2):
                            protocol_request = dict(request)
                            if contract_error is not None:
                                protocol_request["protocol_repair"] = {
                                    "error": str(contract_error)[:500],
                                    "instruction": (
                                        "候选稿和修改目标保持不变，只重新返回完整 JSON 修改合同。"
                                        "operation 使用 replace、insert_before 或 insert_after；"
                                        "kind 使用 semantic。"
                                    ),
                                }
                            raw = await self._stage(
                                run_id, run_path, project, "revision_plan",
                                constraints,
                                json.dumps(protocol_request, ensure_ascii=False),
                                suffix=(
                                    f"-repair-{group_id}"
                                    if protocol_attempt == 0 else
                                    f"-repair-{group_id}-protocol-{protocol_attempt + 1}"
                                ),
                                allow_tools=False,
                                output_source_characters=len(
                                    request.get("target_excerpt", ""),
                                ),
                                targeted_retry=True,
                            )
                            try:
                                value = normalize_repair_contract(
                                    self._convert_generated_object(
                                        raw, run_path,
                                        contract_name="revision_plan",
                                    ), candidate, {group_id},
                                )
                                if len(value["groups"]) != 1:
                                    raise ValueError("模型必须一次只返回一个修改组")
                                current_group = value["groups"][0]
                                if (
                                    current_group.get("group_id") != group_id
                                    or current_group.get("issue_ids") != [group_id]
                                    or current_group.get("kind") != "semantic"
                                ):
                                    raise ValueError("模型返回的修改组与当前问题不一致")
                            except ValueError as exc:
                                contract_error = exc
                                if protocol_attempt == 0:
                                    self.db.add_run_event(
                                        run_id, "info",
                                        "short_revision_contract_retry",
                                        "正文保持不变，正在只重新获取当前修改组的机器执行合同",
                                        stage="repair_groups", metadata={
                                            "group_id": group_id,
                                            "error": str(exc)[:500],
                                        },
                                    )
                                continue
                            patch_group = current_group
                            break
                        if patch_group is None:
                            record.update({
                                "status": "rejected",
                                "message": (
                                    "模型返回的修改格式未通过本地验收，"
                                    "当前修改组未应用"
                                ),
                            })
                            record.pop("patch_group", None)
                            record["patch_result"] = {
                                "group_id": group_id,
                                "accepted": False,
                                "text": candidate,
                                "failures": [{
                                    "patch": 0,
                                    "code": "repair_contract_rejected",
                                }],
                                "diffs": [],
                            }
                            self._save_short_revision_state(
                                store, contract, run_id, records, candidate,
                                completed, None, "running",
                            )
                            self.db.add_run_event(
                                run_id, "warning",
                                "short_revision_group_rejected",
                                (
                                    "模型返回的修改格式未通过本地验收，"
                                    "当前修改组未应用"
                                ),
                                stage="repair_groups",
                                metadata={
                                    "group_id": group_id,
                                    "category": "contract_validation",
                                    "error": str(contract_error or "")[:500],
                                },
                            )
                            continue
                        result = {
                            "group_id": group_id,
                            **apply_patch_group(
                                candidate, patch_group,
                                self._text_hash(candidate),
                            ),
                        }
                except ExpansionRejectedError as exc:
                    record.update({
                        "status": "rejected",
                        "message": str(exc),
                    })
                    record.pop("patch_group", None)
                    record["patch_result"] = {
                        "group_id": group_id,
                        "accepted": False,
                        "text": candidate,
                        "failures": [{
                            "patch": 0,
                            "code": exc.code,
                        }],
                        "diffs": [],
                    }
                    self._save_short_revision_state(
                        store, contract, run_id, records, candidate,
                        completed, None, "running",
                    )
                    self.db.add_run_event(
                        run_id, "warning",
                        "short_revision_group_rejected", str(exc),
                        stage="repair_groups",
                        metadata={
                            "group_id": group_id,
                            "category": exc.category,
                        },
                    )
                    continue
                except asyncio.CancelledError:
                    record.update({
                        "status": "cancelled",
                        "message": "当前修改组已取消，之前完成的修改仍已保留",
                    })
                    self._save_short_revision_state(
                        store, contract, run_id, records, candidate, completed,
                        None, "cancelled",
                    )
                    self.db.update_run(
                        run_id, "cancelled", "repair_groups",
                        error="用户取消了当前返修",
                    )
                    self.db.add_run_event(
                        run_id, "warning", "short_revision_cancelled",
                        "当前返修已取消，已完成的修改组和检查点均已保留",
                        stage="repair_groups", metadata={"group_id": group_id},
                    )
                    raise
                except TargetedGroupError:
                    provider_failures = True
                    record.update({
                        "status": "failed",
                        "message": "首选和备用模型均失败，可从本修改组继续",
                    })
                    record.pop("patch_group", None)
                    record["patch_result"] = {
                        "group_id": group_id,
                        "accepted": False,
                        "text": candidate,
                        "failures": [{
                            "patch": 0, "code": "model_routes_failed",
                        }],
                        "diffs": [],
                    }
                    self._save_short_revision_state(
                        store, contract, run_id, records, candidate, completed,
                        None, "running",
                    )
                    self.db.add_run_event(
                        run_id, "warning", "short_revision_group_failed",
                        "当前修改组生成失败，已保留其他完成结果并继续处理独立问题",
                        stage="repair_groups", metadata={"group_id": group_id},
                    )
                    continue
                except Exception:
                    message = (
                        "当前修改组发生意外错误，"
                        "运行已停止并保留安全检查点"
                    )
                    record.update({
                        "status": "failed",
                        "message": message,
                    })
                    record.pop("patch_group", None)
                    record["patch_result"] = {
                        "group_id": group_id,
                        "accepted": False,
                        "text": candidate,
                        "failures": [{
                            "patch": 0,
                            "code": "unexpected_group_error",
                        }],
                        "diffs": [],
                    }
                    self._save_short_revision_state(
                        store, contract, run_id, records, candidate, completed,
                        None, "failed",
                    )
                    self.db.update_run(
                        run_id, "failed", "repair_groups", error=message,
                    )
                    self.db.add_run_event(
                        run_id, "error", "short_revision_group_error",
                        message, stage="repair_groups",
                        metadata={
                            "group_id": group_id,
                            "category": "unexpected_local_error",
                        },
                    )
                    raise

                if patch_group is not None:
                    record["patch_group"] = patch_group
                record["patch_result"] = result
                if result["accepted"]:
                    completed.add(group_id)
                    replayed, replay_failure = self._replay_repair_records(
                        protected["source"], records, completed,
                    )
                    if replay_failure is None:
                        candidate = replayed
                        semantic_integrity = None
                        semantic_authority = contract.get("semantic_authority")
                        if (
                            group["kind"] != "mechanical"
                            and isinstance(semantic_authority, dict)
                        ):
                            try:
                                semantic_integrity = (
                                    await self._verify_atomic_candidate_semantics(
                                        run_id, run_path, project, constraints,
                                        str(semantic_authority.get("source_text") or ""),
                                        candidate, semantic_authority,
                                        suffix=f"-repair-{group_id}-candidate",
                                        failure_stage="repair_groups",
                                        verify_whole=False,
                                    )
                                )
                            except DraftSemanticValidationError as exc:
                                try:
                                    (
                                        patch_group, result, semantic_integrity,
                                    ) = await self._repair_short_revision_semantic_group(
                                        run_id, run_path, project, constraints,
                                        contract, issue, group_id,
                                        candidate_before_group, candidate,
                                        patch_group, exc,
                                    )
                                except DraftSemanticValidationError as repair_exc:
                                    completed.discard(group_id)
                                    candidate, _ = self._replay_repair_records(
                                        protected["source"], records, completed,
                                    )
                                    record.pop("patch_group", None)
                                    record["patch_result"] = {
                                        "group_id": group_id,
                                        "accepted": False,
                                        "text": candidate,
                                        "failures": [{
                                            "patch": 0,
                                            "code": "semantic_repair_exhausted",
                                        }],
                                        "diffs": [],
                                    }
                                    record.update({
                                        "status": "rejected",
                                        "message": (
                                            "当前修改组两次原子语义修复仍未通过，"
                                            "已恢复该组执行前的候选稿"
                                        ),
                                        "semantic_issues": repair_exc.issues,
                                    })
                                    self._save_short_revision_state(
                                        store, contract, run_id, records,
                                        candidate, completed, None, "running",
                                    )
                                    self.db.add_run_event(
                                        run_id, "warning",
                                        "short_revision_semantic_repair_exhausted",
                                        "当前修改组未能安全修复，已撤销该组并继续其他独立问题",
                                        stage="repair_groups", metadata={
                                            "group_id": group_id,
                                            "issues": repair_exc.issues,
                                        },
                                    )
                                    continue
                                candidate = result["text"]
                                record["patch_group"] = patch_group
                                record["patch_result"] = result
                        if semantic_integrity is not None:
                            record["semantic_integrity"] = semantic_integrity
                        record.update({
                            "status": "ready_for_confirmation",
                            "message": (
                                "机械修复已应用到候选稿"
                                if group["kind"] == "mechanical"
                                else "修改已通过本地补丁检查，等待用户确认"
                            ),
                        })
                    else:
                        completed.discard(group_id)
                        candidate, _ = self._replay_repair_records(
                            protected["source"], records, completed,
                        )
                        record.update({
                            "status": "failed",
                            "message": "当前修改与已完成修改冲突，未应用到候选稿",
                        })
                else:
                    record.update({
                        "status": "rejected",
                        "message": "修改锚点未通过本地验收，当前修改组未应用",
                    })
                self._save_short_revision_state(
                    store, contract, run_id, records, candidate, completed,
                    None, "running",
                )
                if not result["accepted"]:
                    self.db.add_run_event(
                        run_id, "warning", "short_revision_group_rejected",
                        "修改锚点未通过本地验收，当前修改组未应用",
                        stage="repair_groups",
                        metadata={
                            "group_id": group_id,
                            "category": "patch_validation",
                        },
                    )

            analysis = self._analyze_manuscript(
                candidate, run_path, project, "repair-candidate",
            )
            gate_contract, patch_results = self._repair_gate_evidence(
                contract, records,
            )
            minimum_han, maximum_han = self._short_revision_target_range(
                project,
                source_han=effective_han_characters(protected["source"]),
            )
            gate = evaluate_candidate_gate(
                source=protected["source"],
                candidate=candidate,
                source_hash=protected["source_hash"],
                analysis=analysis,
                contract=gate_contract,
                patch_results=patch_results,
                story_state=contract["story_state"]["data"],
                passage_locks=contract["passage_locks"],
                minimum_han=minimum_han,
                maximum_han=maximum_han,
            )
            if provider_failures:
                status = "failed"
                message = "部分返修组生成失败，已保留其他完成结果，可从失败组继续"
                self._save_short_revision_state(
                    store, contract, run_id, records, candidate, completed,
                    gate, status,
                )
                self.db.update_run(
                    run_id, status, "repair_groups", error=message,
                )
                self.db.add_run_event(
                    run_id, "error", "short_revision_failed", message,
                    stage="repair_groups",
                )
                raise RuntimeError(message)

            status = (
                "waiting_confirmation"
                if gate["passed"] else "waiting_local_fix"
            )
            report = self._save_short_revision_state(
                store, contract, run_id, records, candidate, completed,
                gate, status,
            )
            self.db.update_run(run_id, status, "repair_gate")
            if gate["passed"]:
                self.db.add_run_event(
                    run_id, "info", "short_revision_waiting_confirmation",
                    "候选稿已通过本地检查，等待你确认各修改组",
                    stage="repair_gate",
                )
            else:
                self.db.add_run_event(
                    run_id, "warning", "short_revision_gate_rejected",
                    "候选稿未通过本地检查，终审尚未调用，请先处理列出的问题",
                    stage="repair_gate",
                    metadata={
                        "blocking_codes": [
                            item["code"] for item in gate["blocking"]
                        ],
                    },
                )
            return {
                **report,
                "candidate": candidate,
                "protected_best_unchanged": True,
            }
        except asyncio.CancelledError:
            raise
        except Exception:
            run = self.db.get_run(run_id)
            if run and run["status"] not in {"failed", "cancelled"}:
                message = "定向返修未完成，已保留可恢复的检查点"
                self.db.update_run(
                    run_id, "failed", run.get("current_stage"), error=message,
                )
                self.db.add_run_event(
                    run_id, "error", "short_revision_failed", message,
                    stage=run.get("current_stage"),
                )
            raise

    def _protected_short_revision_source(self, project: Project) -> dict:
        best = None
        for run in self.db.list_runs(project.id):
            run_path = project.path / "runs" / run["id"]
            checkpoint = load_quality_checkpoint(run_path)
            if checkpoint is None:
                continue
            source_hash = checkpoint.get("manuscript_hash")
            if checkpoint.get("terminal_reviewed_hash") != source_hash:
                continue
            source = checkpoint_manuscript(run_path, checkpoint)
            if self._text_hash(source) != source_hash:
                continue
            review = checkpoint.get("review")
            if not isinstance(review, dict):
                continue
            terminal_ledger = issue_ledger(review.get("issues", []))
            ledger = checkpoint.get("issue_ledger")
            if not isinstance(ledger, list):
                ledger = terminal_ledger
            if {
                item.get("issue_id") for item in ledger
                if isinstance(item, dict)
            } != {
                item.get("issue_id") for item in terminal_ledger
                if isinstance(item, dict)
            }:
                continue
            candidate = {
                "run_id": run["id"],
                "checkpoint": checkpoint,
                "source": source,
                "source_hash": source_hash,
                "review": review,
                "issue_ledger": ledger,
            }
            semantic_authority = self._quality_semantic_authority(
                project, run_path, checkpoint, source,
            )
            if semantic_authority is not None:
                candidate["semantic_authority"] = semantic_authority
            if (
                best is None
                or checkpoint["score"] > best["checkpoint"]["score"]
            ):
                best = candidate
        if best is not None:
            return best
        raise ValueError("当前项目没有与终审结果绑定的受保护最佳稿")

    def _quality_semantic_authority(
        self, project: Project, run_path: Path, checkpoint: dict, source: str,
    ) -> dict | None:
        """Load only a hash-bound, replayable atomic authority for a protected best draft."""
        reference = checkpoint.get("narrative_integrity")
        if not isinstance(reference, dict):
            return None
        relative_path = reference.get("path")
        expected_sha256 = reference.get("sha256")
        if not isinstance(relative_path, str) or not relative_path.startswith("outputs/"):
            return None
        if not isinstance(expected_sha256, str):
            return None
        try:
            integrity_path = (run_path / relative_path).resolve()
            integrity_path.relative_to(run_path.resolve())
            integrity_bytes = integrity_path.read_bytes()
            if hashlib.sha256(integrity_bytes).hexdigest() != expected_sha256:
                return None
            integrity = json.loads(integrity_bytes.decode("utf-8"))
            manifest_payload = json.loads(
                (run_path / "outputs" / "short-execution-index.json").read_text(
                    encoding="utf-8",
                )
            )
            manifest = parse_execution_manifest(manifest_payload)
        except (
            OSError, UnicodeError, json.JSONDecodeError, TypeError, ValueError,
        ):
            return None
        resolved = self._integrity_publication_segments(
            run_path, integrity, source,
        )
        if resolved is None:
            return None
        source_parts, integrity_source_text = resolved
        receipts = integrity.get("semantic_segment_receipts")
        if (
            manifest.status != "ready"
            or execution_manifest_receipt_binding_issues(manifest)
            or integrity.get("status") != "passed"
            or integrity.get("draft_sha256")
            != self._text_hash(integrity_source_text)
            or integrity.get("execution_manifest_sha256")
            != execution_manifest_sha256(manifest)
            or len(manifest.segments) != len(source_parts)
            or not isinstance(receipts, list)
            or len(receipts) != len(source_parts)
        ):
            return None
        try:
            for index, (segment, prose, receipt) in enumerate(
                zip(manifest.segments, source_parts, receipts, strict=True), 1,
            ):
                contract = self._manifest_segment_contract(
                    project, manifest, integrity, segment, prose, index,
                )
                validate_semantic_receipt(contract, prose, receipt)
            expected_beat_ids = [
                beat_id
                for segment in manifest.segments
                for beat_id in segment.beat_ids
            ]
            validate_whole_draft_receipt(
                str(
                    integrity.get("authority_sha256")
                    or manifest.authority_sha256
                ),
                integrity_source_text,
                source_parts,
                expected_beat_ids,
                integrity.get("whole_semantic_receipt"),
            )
        except (TypeError, ValueError):
            return None
        return {
            "execution_manifest": execution_manifest_payload(manifest),
            "source_integrity": integrity,
            "source_text": source,
            "source_segments": source_parts,
        }

    @staticmethod
    def _selected_repair_issue_ids(issue_ids: list[str]) -> list[str]:
        if not isinstance(issue_ids, list):
            raise ValueError("请选择需要返修的问题")
        result = []
        for issue_id in issue_ids:
            if (
                not isinstance(issue_id, str)
                or not issue_id.strip()
                or issue_id != issue_id.strip()
            ):
                raise ValueError("所选问题编号无效")
            if issue_id not in result:
                result.append(issue_id)
        if not result:
            raise ValueError("请至少选择一个需要返修的问题")
        return result

    @staticmethod
    def _json_copy(value):
        return json.loads(json.dumps(value, ensure_ascii=False))

    @staticmethod
    def _text_hash(text: str) -> str:
        return hashlib.sha256(text.encode("utf-8")).hexdigest()

    @staticmethod
    def _repair_literals(issues: list[dict], key: str) -> list[str]:
        result = []
        for issue in issues:
            values = issue.get(key)
            values = [values] if isinstance(values, str) else values
            for value in values if isinstance(values, list) else []:
                if isinstance(value, str) and value and value not in result:
                    result.append(value)
        return result

    @staticmethod
    def _mechanical_issue_code(issue: dict) -> str | None:
        allowed = {
            "ascii_dialogue_quotes",
            "cjk_spacing",
            "duplicate_punctuation",
            "c0_control",
            "consecutive_duplicate_blocks",
        }
        for key in ("mechanical_code", "code", "category"):
            value = issue.get(key)
            if isinstance(value, str) and value in allowed:
                return value
        return None

    @staticmethod
    def _is_length_deficit_issue(issue: dict) -> bool:
        codes = {
            "length", "length_deficit", "word_count",
            "minimum_han_not_met",
        }
        return any(
            issue.get(key) in codes
            for key in ("category", "code", "issue_type")
        )

    @staticmethod
    def _expansion_anchor_candidates(candidate: str) -> list[dict]:
        max_candidates = 24
        max_anchor_characters = 120
        max_preview_characters = 160
        candidates = []
        seen = set()

        def add_anchor(raw: str, raw_start: int) -> bool:
            anchor = raw.strip()
            if (
                len(anchor) < 4
                or len(anchor) > max_anchor_characters
                or anchor in seen
                or candidate.count(anchor) != 1
            ):
                return False
            position = raw_start + raw.index(anchor)
            preview_start = max(0, position - 48)
            preview_start = min(
                preview_start,
                max(0, len(candidate) - max_preview_characters),
            )
            candidates.append({
                "anchor": anchor,
                "position": position,
                "preview": candidate[
                    preview_start:preview_start + max_preview_characters
                ],
            })
            seen.add(anchor)
            return True

        paragraph_start = 0
        separators = [
            *re.finditer(r"(?:\r?\n){2,}", candidate),
            None,
        ]
        for separator in separators:
            paragraph_end = (
                separator.start() if separator is not None else len(candidate)
            )
            paragraph = candidate[paragraph_start:paragraph_end]
            if paragraph.strip():
                added = False
                if len(paragraph.strip()) <= max_anchor_characters:
                    added = add_anchor(paragraph, paragraph_start)
                if not added:
                    for sentence in re.finditer(
                        r"[^。！？!?；;\r\n]+"
                        r"(?:[。！？!?；;]+[”’」』]?|$)",
                        paragraph,
                    ):
                        add_anchor(
                            sentence.group(0),
                            paragraph_start + sentence.start(),
                        )
            if separator is not None:
                paragraph_start = separator.end()

        candidates.sort(key=lambda item: item["position"])
        if len(candidates) <= max_candidates:
            return candidates
        selected = []
        available = list(candidates)
        text_end = max(0, len(candidate) - 1)
        for index in range(max_candidates):
            target = text_end * index / (max_candidates - 1)
            closest = min(
                available,
                key=lambda item: (
                    abs(item["position"] - target),
                    item["position"],
                ),
            )
            selected.append(closest)
            available.remove(closest)
        return sorted(selected, key=lambda item: item["position"])

    async def _expansion_patch_group(
        self, run_id: str, run_path: Path, project: Project,
        constraints: str, contract: dict, issue: dict,
        group_id: str, candidate: str,
        record: dict, store: RepairRunStore, records: list[dict],
        completed: set[str],
    ) -> dict:
        budget = contract["length_budget"]
        anchor_candidates = self._expansion_anchor_candidates(candidate)
        if not anchor_candidates:
            raise ValueError("候选稿缺少可安全定位的扩写锚点")
        allowed_anchors = {
            item["anchor"] for item in anchor_candidates
        }
        scene_records = record.get("expansion_plan")
        if not isinstance(scene_records, list):
            request = {
                "schema": "short-expansion-plan-v1",
                "group_id": group_id,
                "candidate_hash": self._text_hash(candidate),
                "issue": issue,
                "current_han": budget["current_han"],
                "minimum_han": budget["minimum_han"],
                "maximum_han": budget["maximum_han"],
                "deficit_han": budget["deficit_han"],
                "story_state": contract["story_state"]["data"],
                "seven_step_causal_chain": contract.get(
                    "seven_step_causal_chain",
                ),
                "anchor_candidates": anchor_candidates,
                "instructions": EXPANSION_CONTRACT,
            }
            scenes = None
            plan_error: ValueError | None = None
            for protocol_attempt in range(2):
                protocol_request = dict(request)
                if plan_error is not None:
                    protocol_request["protocol_repair"] = {
                        "error": str(plan_error)[:500],
                        "instruction": (
                            "候选稿、缺口和场景目标保持不变，只重新返回完整 JSON 扩写计划。"
                            "operation 使用 insert_before 或 insert_after。"
                        ),
                    }
                raw_plan = await self._stage(
                    run_id, run_path, project, "revision_plan", constraints,
                    json.dumps(protocol_request, ensure_ascii=False),
                    suffix=(
                        f"-expand-plan-{group_id}"
                        if protocol_attempt == 0 else
                        f"-expand-plan-{group_id}-protocol-{protocol_attempt + 1}"
                    ),
                    allow_tools=False,
                    output_source_characters=budget["deficit_han"],
                    targeted_retry=True,
                )
                try:
                    scenes = self._normalize_expansion_plan(
                        self._convert_generated_object(
                            raw_plan, run_path,
                            contract_name="generated_narrative_artifact",
                        ), candidate,
                        budget["deficit_han"], allowed_anchors,
                    )
                except ValueError as exc:
                    plan_error = exc
                    if protocol_attempt == 0:
                        self.db.add_run_event(
                            run_id, "info", "short_expansion_contract_retry",
                            "正文保持不变，正在只重新获取扩写场景的机器执行合同",
                            stage="repair_groups", metadata={
                                "group_id": group_id,
                                "error": str(exc)[:500],
                            },
                        )
                    continue
                break
            if scenes is None:
                raise ExpansionRejectedError(
                    "expansion_contract_rejected",
                    "expansion_contract_validation",
                    "扩写规划未通过本地验收，当前修改组未应用",
                ) from None
            scene_records = [{
                "scene_index": index,
                "contract": scene,
                "status": "pending",
            } for index, scene in enumerate(scenes, 1)]
            record["expansion_plan"] = scene_records
            self._save_short_revision_state(
                store, contract, run_id, records, candidate,
                completed, None, "running",
            )
        try:
            scenes = self._normalize_expansion_plan(
                {
                    "scenes": [
                        scene_record["contract"]
                        for scene_record in scene_records
                    ],
                },
                candidate,
                budget["deficit_han"],
                allowed_anchors,
            )
        except (KeyError, TypeError, ValueError):
            raise ExpansionRejectedError(
                "expansion_contract_rejected",
                "expansion_contract_validation",
                "扩写规划未通过本地验收，当前修改组未应用",
            ) from None
        patches = []
        for index, (scene, scene_record) in enumerate(
            zip(scenes, scene_records, strict=True), 1,
        ):
            draft = scene_record.get("draft")
            if scene_record.get("status") != "drafted" or not isinstance(
                draft, dict,
            ):
                draft_request = {
                    "schema": "short-expansion-scene-v1",
                    "group_id": group_id,
                    "scene_index": index,
                    "scene_count": len(scenes),
                    "contract": scene,
                    "authoritative_facts": [
                        *contract["story_state"]["data"].get(
                            "locked_facts", [],
                        ),
                        *contract["story_state"]["data"].get(
                            "confirmed_facts", [],
                        ),
                    ],
                    "seven_step_causal_chain": contract.get(
                        "seven_step_causal_chain",
                    ),
                    "instructions": (
                        "只返回严格 JSON，不得改写锚点或其他正文。"
                        "text 必须是可直接插入的场景正文，"
                        "并逐项回报合同中的状态字段。"
                    ),
                }
                raw_scene = await self._stage(
                    run_id, run_path, project, "draft", constraints,
                    json.dumps(draft_request, ensure_ascii=False),
                    suffix=f"-expand-draft-{group_id}-{index}",
                    allow_tools=False,
                    output_source_characters=scene["target_han"],
                    targeted_retry=True,
                )
                try:
                    draft = self._convert_generated_object(
                        raw_scene, run_path,
                        contract_name="generated_narrative_artifact",
                    )
                    self._validate_expansion_draft(draft, scene)
                except ValueError:
                    raise ExpansionRejectedError(
                        "expansion_draft_rejected",
                        "expansion_draft_validation",
                        "扩写场景未通过本地验收，当前修改组未应用",
                    ) from None
                scene_record["draft"] = draft
                scene_record["status"] = "drafted"
                self._save_short_revision_state(
                    store, contract, run_id, records, candidate,
                    completed, None, "running",
                )
            try:
                scene_text = self._validate_expansion_draft(draft, scene)
            except ValueError:
                raise ExpansionRejectedError(
                    "expansion_draft_rejected",
                    "expansion_draft_validation",
                    "扩写场景未通过本地验收，当前修改组未应用",
                ) from None
            patches.append({
                "operation": scene["operation"],
                "old_text": scene["anchor"],
                "new_text": (
                    f"\n\n{scene_text}"
                    if scene["operation"] == "insert_after"
                    else f"{scene_text}\n\n"
                ),
            })
        return {
            "group_id": group_id,
            "issue_ids": [group_id],
            "kind": "semantic",
            "requires_user_confirmation": True,
            "requires_full_review": True,
            "impact_flags": ["scene_inserted"],
            "expansion_contracts": scenes,
            "patches": patches,
        }

    @staticmethod
    def _normalize_expansion_plan(
        value: dict, candidate: str, deficit_han: int,
        allowed_anchors: set[str] | None = None,
    ) -> list[dict]:
        scenes = value.get("scenes")
        if not isinstance(scenes, list) or not scenes:
            raise ValueError("扩写计划必须包含至少一个场景")
        normalized = []
        anchors = set()
        for scene in scenes:
            if not isinstance(scene, dict):
                raise ValueError("扩写场景合同格式无效")
            for key in (
                "purpose", "entry_state", "exit_state", "anchor",
                "time", "evidence_source", "transition",
            ):
                if not isinstance(scene.get(key), str) or not scene[key].strip():
                    raise ValueError("扩写场景合同缺少必要状态")
            target_han = scene.get("target_han")
            if (
                not isinstance(target_han, int)
                or isinstance(target_han, bool)
                or target_han <= 0
            ):
                raise ValueError("扩写场景目标汉字数无效")
            anchor = scene["anchor"]
            if (
                anchor in anchors
                or candidate.count(anchor) != 1
                or (
                    allowed_anchors is not None
                    and anchor not in allowed_anchors
                )
            ):
                raise ValueError("扩写场景锚点必须唯一")
            raw_operation = scene.get(
                "raw_operation", scene.get("operation"),
            )
            operation = canonical_patch_operation(raw_operation)
            if operation not in {"insert_before", "insert_after"}:
                raise ValueError("扩写场景只能使用插入操作")
            if scene.get("requires_full_review") is not True:
                raise ValueError("扩写场景必须要求全文复核")
            new_facts = scene.get("new_facts")
            if (
                not isinstance(new_facts, list)
                or any(
                    not isinstance(fact, str) or not fact.strip()
                    for fact in new_facts
                )
            ):
                raise ValueError("扩写场景新增事实必须是非空字符串列表")
            anchors.add(anchor)
            normalized.append({
                **scene,
                "raw_operation": raw_operation,
                "operation": operation,
                "new_facts": [fact.strip() for fact in new_facts],
            })
        if sum(scene["target_han"] for scene in normalized) != deficit_han:
            raise ValueError("扩写场景目标汉字数总和必须等于本地缺口")
        return normalized

    @staticmethod
    def _validate_expansion_draft(value: dict, contract: dict) -> str:
        text = value.get("text")
        if not isinstance(text, str) or not text.strip():
            raise ValueError("扩写场景正文为空")
        target_han = contract["target_han"]
        actual_han = effective_han_characters(text)
        if actual_han < target_han or actual_han > math.ceil(target_han * 1.1):
            raise ValueError("扩写场景有效汉字数超出本地允许范围")
        for key in (
            "entry_state", "exit_state", "time",
            "evidence_source", "transition", "new_facts",
        ):
            if value.get(key) != contract.get(key):
                raise ValueError("扩写场景状态与规划合同不一致")
        return text.strip()

    def _mechanical_patch_group(
        self, issue: dict, candidate: str, group_id: str,
    ) -> dict | None:
        code = self._mechanical_issue_code(issue)
        evidence = issue.get("evidence")
        if (
            code is None
            or not isinstance(evidence, str)
            or not evidence
            or candidate.count(evidence) != 1
        ):
            return None
        repaired = repair_mechanical_text(evidence)
        applied = {
            item.get("code")
            for item in repaired.get("applied", [])
            if isinstance(item, dict)
        }
        if applied != {code} or repaired["text"] == evidence:
            return None
        return {
            "group_id": group_id,
            "issue_ids": [group_id],
            "kind": "mechanical",
            "requires_user_confirmation": True,
            "patches": [{
                "operation": "replace",
                "old_text": evidence,
                "new_text": repaired["text"],
            }],
        }

    def _semantic_patch_request(
        self, contract: dict, issue: dict, group_id: str, candidate: str,
    ) -> dict:
        evidence = issue.get("evidence")
        evidence = evidence if isinstance(evidence, str) else ""
        offset = candidate.find(evidence) if evidence else -1
        if offset < 0:
            target = evidence
            before = after = ""
        else:
            target = evidence
            before = candidate[max(0, offset - 1200):offset]
            after = candidate[offset + len(evidence):offset + len(evidence) + 1200]
        state = contract["story_state"]["data"]
        return {
            "schema": "targeted-repair-group-v1",
            "group_id": group_id,
            "candidate_hash": self._text_hash(candidate),
            "issue": issue,
            "target_excerpt": target,
            "previous_context": before,
            "next_context": after,
            "authoritative_facts": [
                *state.get("locked_facts", []),
                *state.get("confirmed_facts", []),
            ],
            "passage_locks": [{
                "id": item.get("id"),
                "label": item.get("label"),
                "mode": item.get("mode"),
            } for item in contract["passage_locks"]],
            "instructions": (
                "只返回一个 JSON 修改合同。只处理当前 issue_id；old_text 必须在候选稿中"
                "唯一出现；不得改动上下文或未选问题；语义修改必须要求用户确认。"
            ),
        }

    def _write_short_revision_progress(
        self, store: RepairRunStore, contract: dict, records: list[dict],
        candidate: str, completed: set[str], status: str,
    ) -> None:
        groups = {"groups": records}
        ordered_completed = [
            group["group_id"]
            for group in contract["groups"]
            if group["group_id"] in completed
        ]
        store.write_groups(groups)
        store.write_candidate(candidate)
        store.write_checkpoint({
            "version": 1,
            "status": status,
            "source_hash": contract["manuscript_hash"],
            "contract_hash": repair_artifact_hash(contract),
            "groups_hash": repair_artifact_hash(groups),
            "candidate_hash": repair_artifact_hash(candidate),
            "completed_groups": ordered_completed,
        })

    def _save_short_revision_state(
        self, store: RepairRunStore, contract: dict, run_id: str,
        records: list[dict], candidate: str, completed: set[str],
        gate: dict | None, status: str,
    ) -> dict:
        self._write_short_revision_progress(
            store, contract, records, candidate, completed, status,
        )
        return self._write_short_revision_report(
            store, run_id, records, candidate, gate, status, contract,
        )

    def _replay_repair_records(
        self, source: str, records: list[dict], completed: set[str],
    ) -> tuple[str, str | None]:
        candidate = source
        for record in records:
            group_id = record["group_id"]
            if group_id not in completed:
                continue
            patch_group = record.get("patch_group")
            if not isinstance(patch_group, dict):
                return candidate, group_id
            result = {
                "group_id": group_id,
                **apply_patch_group(
                    candidate, patch_group, self._text_hash(candidate),
                ),
            }
            record["patch_result"] = result
            if not result["accepted"]:
                return candidate, group_id
            candidate = result["text"]
        return candidate, None

    @staticmethod
    def _repair_gate_evidence(
        contract: dict, records: list[dict],
    ) -> tuple[dict, list[dict]]:
        record_by_id = {record["group_id"]: record for record in records}
        groups = []
        results = []
        for group in contract["groups"]:
            record = record_by_id[group["group_id"]]
            patch_group = record.get("patch_group")
            groups.append(
                patch_group
                if isinstance(patch_group, dict)
                else {**group, "patches": []}
            )
            result = record.get("patch_result")
            results.append(
                result
                if isinstance(result, dict)
                else {
                    "group_id": group["group_id"],
                    "accepted": False,
                    "text": "",
                    "failures": [{
                        "patch": 0, "code": "group_incomplete",
                    }],
                    "diffs": [],
                }
            )
        return {
            "manuscript_hash": contract["manuscript_hash"],
            "required_text": contract.get("required_text", []),
            "forbidden_text": contract.get("forbidden_text", []),
            "groups": groups,
        }, results

    @staticmethod
    def _short_revision_target_range(
        project: Project, *, source_han: int | None = None,
    ) -> tuple[int, int]:
        target = max(0, int(project.metadata.get("target_words") or 0))
        if project.metadata.get("platform_profile_id") == "zhihu-salt-short":
            minimum, maximum = int(target * 0.9), int(target * 1.1)
        else:
            minimum = maximum = target
        if source_han is not None:
            # A previously accepted formal manuscript is valid upstream
            # authority. A targeted non-length repair must not become
            # impossible merely because that source already sits just outside
            # today's configured target range. Extend the gate only far
            # enough to include the accepted source; the candidate still may
            # not worsen an existing underlength or overlength deviation.
            source = max(0, int(source_han))
            minimum = min(minimum, source)
            maximum = max(maximum, source)
        return minimum, maximum

    def _write_short_revision_report(
        self, store: RepairRunStore, run_id: str, records: list[dict],
        candidate: str, gate: dict | None, status: str,
        contract: dict | None = None,
    ) -> dict:
        issues = {
            item.get("issue_id"): item
            for item in (contract or {}).get("selected_issues", [])
            if isinstance(item, dict) and isinstance(item.get("issue_id"), str)
        }

        def public_group(record: dict) -> dict:
            patch_group = record.get("patch_group")
            patch_result = record.get("patch_result")
            patches = (
                patch_group.get("patches", [])
                if isinstance(patch_group, dict) else []
            )
            failures = (
                patch_result.get("failures", [])
                if isinstance(patch_result, dict) else []
            )
            issue_ids = record.get("issue_ids", [])
            issue = (
                issues.get(issue_ids[0])
                if isinstance(issue_ids, list) and issue_ids else None
            )
            if isinstance(issue, dict):
                issue = dict(issue)
                if record.get("issue_status"):
                    issue["status"] = record["issue_status"]
            decision = record.get("decision")
            if (
                decision is None
                and record.get("kind") == "mechanical"
                and isinstance(patch_result, dict)
                and patch_result.get("accepted") is True
            ):
                decision = "adopted"
            before = [
                patch.get("old_text")
                for patch in patches
                if isinstance(patch, dict) and isinstance(
                    patch.get("old_text"), str,
                )
            ]
            after = [
                patch.get("new_text")
                for patch in patches
                if isinstance(patch, dict) and isinstance(
                    patch.get("new_text"), str,
                )
            ]
            return {
                "group_id": record["group_id"],
                "issue_ids": issue_ids,
                "kind": record.get("kind"),
                "status": record.get("status"),
                "decision": decision,
                "message": record.get("message"),
                "attempts": record.get("attempts", 0),
                "patches": patches,
                "failures": failures,
                "issue": issue,
                "before": before,
                "after": after,
                "related_positions": (
                    patch_group.get("related_positions", [])
                    if isinstance(patch_group, dict) else []
                ),
                "local_checks": {
                    "passed": (
                        patch_result.get("accepted") is True
                        if isinstance(patch_result, dict) else False
                    ),
                    "failures": failures,
                },
            }

        groups = {
            record["group_id"]: public_group(record)
            for record in records
        }
        next_action = {
            "waiting_confirmation": "请查看每个语义修改组并决定采用或拒绝",
            "waiting_local_fix": "请先处理未通过的本地检查或失败修改组",
            "failed": "可从失败的修改组继续运行",
            "cancelled": "可继续本次返修，已完成结果不会丢失",
            "running": "正在继续处理其他独立修改组",
        }.get(status, "请查看返修结果")
        report = {
            "id": run_id,
            "status": status,
            "candidate_path": "outputs/candidate.md",
            "candidate_hash": repair_artifact_hash(candidate),
            "groups": groups,
            "gate": gate,
            "next_action": next_action,
            "protected_best_unchanged": True,
        }
        full_review_reasons = []
        for record in records:
            patch_group = record.get("patch_group")
            patch_result = record.get("patch_result")
            if (
                not isinstance(patch_group, dict)
                or not isinstance(patch_result, dict)
                or patch_result.get("accepted") is not True
            ):
                continue
            for reason in patch_group.get("impact_flags", []):
                if reason not in full_review_reasons:
                    full_review_reasons.append(reason)
        report["review_mode"] = (
            "full" if full_review_reasons else "incremental"
        )
        report["full_review_reasons"] = full_review_reasons
        store.write_report(report)
        return report

    async def run_chapter(self, project_id: str, chapter_goal: str,
                          use_crewai: bool = True, run_id: str | None = None) -> dict:
        project = self.projects.get(project_id)
        if project.mode != "long":
            raise ValueError("Long chapter workflow requires a long project")
        pipeline = lambda: self._chapter_pipeline(project, chapter_goal, run_id)
        return await self._run_in_crewai(pipeline) if use_crewai else await pipeline()

    async def run_long_setup(self, project_id: str, use_crewai: bool = True,
                             run_id: str | None = None) -> dict:
        project = self.projects.get(project_id)
        if project.mode != "long":
            raise ValueError("Long setup workflow requires a long project")
        pipeline = lambda: self._long_setup_pipeline(project, run_id)
        return await self._run_in_crewai(pipeline) if use_crewai else await pipeline()

    async def run_materials_audit(self, project_id: str, use_crewai: bool = True,
                                  run_id: str | None = None) -> dict:
        project = self.projects.get(project_id)
        pipeline = lambda: self._materials_audit_pipeline(project, run_id)
        return await self._run_in_crewai(pipeline) if use_crewai else await pipeline()

    async def run_materials_repair(self, project_id: str, use_crewai: bool = True,
                                   run_id: str | None = None) -> dict:
        project = self.projects.get(project_id)
        pipeline = lambda: self._materials_repair_pipeline(project, run_id)
        return await self._run_in_crewai(pipeline) if use_crewai else await pipeline()

    def _material_manuscript(self, project: Project) -> str:
        for run in self.db.list_runs(project.id):
            for name in ("best-candidate.md", "polish.md"):
                path = project.path / "runs" / run["id"] / "outputs" / name
                if path.is_file() and (text := path.read_text(encoding="utf-8")).strip():
                    return text
        formal = project.path / "manuscript" / "story.md"
        if formal.is_file():
            return formal.read_text(encoding="utf-8")
        return "\n\n".join(path.read_text(encoding="utf-8")
                            for path in sorted((project.path / "chapters").glob("chapter-*.md")))

    def _material_reference(self, project: Project) -> str:
        files = [project.path / "constraints.md"]
        for folder in ("characters", "worldbuilding", "plot"):
            files.extend(sorted((project.path / folder).rglob("*.md")))
        parts = []
        for path in files:
            if path.is_file() and "_index.md" not in path.name:
                parts.append(f"FILE {path.relative_to(project.path).as_posix()}\n{path.read_text(encoding='utf-8')}")
        return "\n\n".join(parts)[:60_000]

    async def _materials_audit_pipeline(self, project: Project,
                                        run_id: str | None = None) -> dict:
        run_id, run_path = self._begin_run(project, "materials-audit", run_id)
        try:
            manuscript = self._material_manuscript(project)
            if not manuscript.strip():
                raise RuntimeError("No manuscript is available for conflict checking")
            reference = self._material_reference(project)
            constraints = self.projects.load_constraints(project.id)
            issues = []
            windows = review_windows(manuscript)
            checkpoint_root = run_path / "outputs" / "materials-audit-checkpoints"
            checkpoint_root.mkdir(parents=True, exist_ok=True)
            fallback_circuit_open = any(
                event["event_type"] == "materials_audit_circuit_opened"
                for event in self.db.list_run_events(run_id)
            )
            for window in windows:
                checkpoint_path = checkpoint_root / f"window-{window['index']:03d}.json"
                source_hash = hashlib.sha256(
                    (reference + "\0" + constraints + "\0" + window["text"]
                     + f"\0{window['index']}/{len(windows)}").encode("utf-8")
                ).hexdigest()
                try:
                    checkpoint = json.loads(checkpoint_path.read_text(encoding="utf-8"))
                except (OSError, json.JSONDecodeError):
                    checkpoint = {}
                if (checkpoint.get("source_hash") == source_hash
                        and isinstance(checkpoint.get("issues"), list)):
                    issues.extend(item for item in checkpoint["issues"] if isinstance(item, dict))
                    self.db.add_run_event(
                        run_id, "success", "materials_audit_checkpoint_reused",
                        f"材料审核第 {window['index']}/{len(windows)} 窗口已从检查点恢复",
                        stage="final_review", metadata={"window": window["index"]},
                    )
                    continue
                prompt = (
                    "MATERIAL CONSISTENCY AUDIT. Compare this manuscript window against the project "
                    "reference. Return JSON only: {\"issues\":[...]}. Each issue must contain category, "
                    "severity (low|medium|high|critical), evidence, location, old_setting, new_setting, "
                    "and action. Report only evidenced contradictions, not style preferences. Do not rewrite.\n\n"
                    f"PROJECT REFERENCE:\n{reference}\n\nWINDOW {window['index']}/{len(windows)} "
                    f"CHARACTERS {window['start']}-{window['end']}:\n{window['text']}"
                )
                result = await self._stage(
                    run_id, run_path, project, "final_review", constraints, prompt,
                    suffix=f"-window-{window['index']}", allow_tools=False,
                    prefer_configured_fallback=fallback_circuit_open,
                )
                if (not fallback_circuit_open
                        and getattr(result, "receipt", {}).get("fallback_used")):
                    fallback_circuit_open = True
                    self.db.add_run_event(
                        run_id, "warning", "materials_audit_circuit_opened",
                        "材料审核首选模型已回退成功，后续窗口直接使用配置备用模型",
                        stage="final_review", metadata={"window": window["index"]},
                    )
                value = self._convert_generated_object(
                    result, run_path, contract_name="material_audit",
                )
                window_issues = [item for item in value.get("issues", []) if isinstance(item, dict)]
                issues.extend(window_issues)
                atomic_write(checkpoint_path, json.dumps({
                    "source_hash": source_hash, "issues": window_issues,
                }, ensure_ascii=False, indent=2))
            report = {"project_id": project.id, "issues": issues, "count": len(issues)}
            atomic_write(run_path / "outputs" / "conflict-report.json",
                         json.dumps(report, ensure_ascii=False, indent=2))
            state = self.story_states.ensure(project.id, project.path)
            if issues:
                candidate = self.story_states.create_candidate(
                    project.id, run_id, state.revision, "materials_audit",
                    hashlib.sha256(json.dumps(issues, ensure_ascii=False).encode()).hexdigest(),
                    {"issue_count": len(issues)},
                )
                ledger = [item for item in state.data.get("issue_ledger", [])
                          if item.get("source") != "materials_audit"]
                ledger.extend({**item, "source": "materials_audit"} for item in issues)
                self.story_states.commit(candidate.id, state.revision,
                                         {**state.data, "issue_ledger": ledger})
            self.db.update_run(run_id, "completed", "archive")
            return self.db.get_run(run_id) or {"id": run_id, "status": "completed"}
        except asyncio.CancelledError:
            self.db.update_run(run_id, "cancelled", error="Cancelled by user")
            raise
        except Exception as exc:
            self.db.update_run(run_id, "failed", error=str(exc))
            raise

    async def _materials_repair_pipeline(self, project: Project,
                                         run_id: str | None = None) -> dict:
        run_id, run_path = self._begin_run(project, "materials-repair", run_id)
        try:
            audit = next((item for item in self.db.list_runs(project.id)
                          if item["workflow"] == "materials-audit" and item["status"] == "completed"), None)
            if not audit:
                raise RuntimeError("Run a material conflict audit before repair")
            report_path = project.path / "runs" / audit["id"] / "outputs" / "conflict-report.json"
            report = json.loads(report_path.read_text(encoding="utf-8"))
            issues = report.get("issues", [])
            if not issues:
                raise RuntimeError("The latest material audit has no conflicts to repair")
            manuscript = self._material_manuscript(project)
            constraints = self.projects.load_constraints(project.id)
            repaired = await self._polish_short_segments(
                run_id, run_path, project, constraints, manuscript,
                json.dumps({"material_conflicts": issues}, ensure_ascii=False),
                suffix="-materials", structural=True,
            )
            initial = normalize_review({
                "score": 80, "dimensions": {"commercial": 80, "story": 80, "prose": 80},
                "hard_fail": False, "decision": "revise", "issues": issues,
            })
            final, evidence = await self._full_manuscript_review(
                run_id, run_path, project, constraints, repaired, initial,
                suffix="-materials",
            )
            outcome, reasons = quality_outcome(final)
            atomic_write(run_path / "outputs" / "best-candidate.md", repaired)
            atomic_write(run_path / "outputs" / "quality-report.json", json.dumps({
                "status": outcome, "failure_reasons": reasons, "final_review": final,
                "final_review_evidence": evidence, "source_audit": audit["id"],
            }, ensure_ascii=False, indent=2))
            if outcome == "failed":
                raise RuntimeError("Material conflict repair did not pass the final quality gate")
            self.db.update_run(run_id, "completed", "archive")
            return self.db.get_run(run_id) or {"id": run_id, "status": "completed"}
        except asyncio.CancelledError:
            self.db.update_run(run_id, "cancelled", error="Cancelled by user")
            raise
        except Exception as exc:
            self.db.update_run(run_id, "failed", error=str(exc))
            raise

    async def _long_setup_pipeline(self, project: Project, run_id: str | None = None) -> dict:
        run_id, run_path = self._begin_run(project, "long-setup", run_id)
        outline_path = project.path / "memory" / "book-plan.md"
        canon_path = project.path / "memory" / "canon.json"
        volumes_path = project.path / "memory" / "volumes.json"
        snapshot = ProjectSnapshot.create(
            project.path, project.path / "snapshots" / run_id, [outline_path, canon_path, volumes_path],
        )
        try:
            constraints = self.projects.load_constraints(project.id)
            brief = (
                "Expand the immutable confirmed outline into a complete long-form execution plan with "
                "fixed ending, protagonist arc, act structure, "
                "3-5 volumes, chapter map, hooks, foreshadowing, characters, relationships, world rules, "
                "timeline and knowledge boundaries. Do not replace or contradict the confirmed outline.\n\n" +
                json.dumps(project.metadata, ensure_ascii=False, indent=2)
            )
            outline = await self._stage(run_id, run_path, project, "planning", constraints, brief)
            review = self._review(await self._stage(
                run_id, run_path, project, "review", constraints, outline,
            ))
            if review["score"] < 80 or review["hard_fail"]:
                raise RuntimeError("Book setup review did not pass")
            canon = self._convert_generated_object(
                await self._stage(
                    run_id, run_path, project, "maintenance", constraints, outline,
                ),
                run_path, contract_name="maintenance_facts",
            )
            if not isinstance(canon.get("facts"), list):
                raise ValueError("Maintenance output must contain a facts array")
            atomic_write(outline_path, outline)
            atomic_write(canon_path, json.dumps(canon, ensure_ascii=False, indent=2))
            if isinstance(canon.get("volumes"), list):
                atomic_write(volumes_path, json.dumps({"volumes": canon["volumes"]}, ensure_ascii=False, indent=2))
            for index, fact in enumerate(canon["facts"]):
                if isinstance(fact, dict):
                    key = str(fact.get("fact_key") or f"setup.{index}")
                    value = str(fact.get("value") or fact.get("fact") or "")
                    self.memory.add_fact(project.id, key, value, True, "book-setup")
            self._post_write_maintenance(run_id, project)
            self.db.update_run(run_id, "completed", "archive")
            return self.db.get_run(run_id) or {"id": run_id, "status": "completed"}
        except asyncio.CancelledError:
            snapshot.restore()
            self.db.update_run(run_id, "cancelled", error="Cancelled by user")
            raise
        except Exception as exc:
            snapshot.restore()
            self.db.update_run(run_id, "failed", error=str(exc))
            raise

    async def _chapter_pipeline(self, project: Project, chapter_goal: str,
                                run_id: str | None = None) -> dict:
        numbers = [
            int(match.group(1)) for path in project.path.joinpath("chapters").glob("chapter-*.md")
            if (match := re.fullmatch(r"chapter-(\d+)\.md", path.name))
        ]
        chapter_number = max(numbers, default=0) + 1
        chapter_id = f"chapter-{chapter_number:02d}"
        chapter_path = project.path / "chapters" / f"{chapter_id}.md"
        canon_path = project.path / "memory" / "canon.json"
        run_id, run_path = self._begin_run(project, "long-chapter", run_id)
        self._ensure_previous_volume_passed(project, chapter_number)
        snapshot = ProjectSnapshot.create(
            project.path, project.path / "snapshots" / run_id, [chapter_path, canon_path],
        )
        committed = False
        try:
            constraints = self.projects.load_constraints(project.id)
            context = self.memory.context(project.id, chapter_goal)
            brief = json.dumps({
                "chapter_number": chapter_number,
                "goal": chapter_goal,
                "project": project.metadata,
                "retrieved_memory": context,
            }, ensure_ascii=False, indent=2)
            plan = await self._stage(run_id, run_path, project, "planning", constraints, brief)
            draft = await self._stage(run_id, run_path, project, "draft", constraints, plan)
            draft_analysis = self._analyze_manuscript(draft, run_path, project, "draft")
            review = self._review(await self._stage(
                run_id, run_path, project, "review", constraints,
                f"MEMORY:\n{json.dumps(context, ensure_ascii=False)}\n\nDRAFT:\n{draft}\n\n"
                "LOCAL FULL MANUSCRIPT SUMMARY:\n"
                f"{json.dumps(compact_analysis(draft_analysis), ensure_ascii=False)}",
            ))
            polished, _ = await self._quality_polish(
                run_id, run_path, project, constraints, draft, review,
                chapter_number=chapter_number,
                chapter_goal=chapter_goal,
                volume_end=self._is_volume_end(project, chapter_number),
            )
            canon = self._convert_generated_object(
                await self._stage(
                    run_id, run_path, project, "maintenance", constraints, polished,
                ),
                run_path, contract_name="maintenance_facts",
            )
            if not isinstance(canon.get("facts"), list):
                raise ValueError("Maintenance output must contain a facts array")
            atomic_write(chapter_path, self._chapter_file(project, polished, chapter_number))
            self._record_voice_drift(run_id, project, chapter_number, polished)
            atomic_write(canon_path, json.dumps(canon, ensure_ascii=False, indent=2))
            self._post_write_maintenance(run_id, project)
            self.memory.index_chapter(project.id, chapter_id, chapter_number, polished, chapter_goal)
            if isinstance(canon.get("state"), dict):
                self.memory.save_state(project.id, chapter_id, canon["state"])
            committed = True
            await self._audit_volume_boundary(run_id, run_path, project, chapter_number, constraints)
            self.db.update_run(run_id, "completed", "archive")
            return self.db.get_run(run_id) or {"id": run_id, "status": "completed"}
        except asyncio.CancelledError:
            if not committed:
                snapshot.restore()
            self.db.update_run(run_id, "cancelled", error="Cancelled by user")
            raise

        except Exception as exc:
            if not committed:
                snapshot.restore()
            self.db.update_run(run_id, "failed", error=str(exc))
            raise

    def _record_voice_drift(self, run_id: str, project: Project, chapter_number: int,
                            text: str) -> None:
        folder = project.path / "memory" / "style-metrics"
        history = []
        for path in sorted(folder.glob("chapter-*.json"))[-5:]:
            try:
                value = json.loads(path.read_text(encoding="utf-8"))
            except (OSError, json.JSONDecodeError):
                continue
            if isinstance(value, dict):
                history.append(value.get("metrics", value))
        metrics = prose_metrics(text)
        drift = compare_voice_metrics(metrics, history)
        atomic_write(folder / f"chapter-{chapter_number:02d}.json", json.dumps(
            {"chapter": chapter_number, "metrics": metrics, "drift": drift},
            ensure_ascii=False, indent=2,
        ))
        self.db.add_run_event(
            run_id, "warning" if drift["drifted"] else "success", "voice_drift",
            "检测到跨章文风漂移，已记录为优化建议" if drift["drifted"] else "跨章文风指标稳定",
            stage="quality", metadata=drift,
        )

    async def _short_pipeline(self, project: Project, run_id: str | None = None) -> dict:
        run_id, run_path = self._begin_run(project, "short-story", run_id)
        try:
            self._recover_short_formal_promotions(project)
        except Exception as exc:
            self.db.update_run(run_id, "failed", "archive", error=str(exc))
            raise
        state = self.story_states.ensure(project.id, project.path)
        candidate_id = None
        draft_candidate_id = None
        state_committed = False
        promotion_journal_path: Path | None = None
        formal = [
            project.path / "manuscript" / "story.md",
            project.path / "chapters" / "chapter-01.md",
            project.path / "memory" / "canon.json",
        ]
        snapshot = ProjectSnapshot.create(
            project.path,
            project.path / "snapshots" / f"{run_id}-{uuid.uuid4().hex[:8]}",
            formal,
        )
        try:
            constraints = self.projects.load_constraints(project.id)
            target_words = int(project.metadata["target_words"])
            segment_count = self._short_segment_count(target_words)
            checkpoint_context = self._short_checkpoint_context(
                project, state.revision, state.data, constraints, segment_count,
            )
            readiness_conflicts = detect_canon_conflicts(
                project, state.data,
                str((state.data.get("outline") or {}).get("content") or ""),
            )
            if readiness_conflicts:
                raise ValueError(
                    f"正式大纲与项目资料有 {len(readiness_conflicts)} 处冲突，请先在作品应用中确认设定"
                )
            checkpoint = self._find_short_checkpoint(
                project, run_id, segment_count, checkpoint_context,
            )
            if checkpoint:
                checkpoint_plan = (checkpoint / "planning.md").read_text(encoding="utf-8")
                if self._short_plan_issues(project, state.data, checkpoint_plan, segment_count):
                    self.db.add_run_event(
                        run_id, "warning", "checkpoint_plan_rejected",
                        "上一轮规划没有通过新的分段与设定检查，本次将重新规划",
                        stage="planning",
                    )
                    checkpoint = None
            partial_checkpoint = (
                None if checkpoint else self._find_short_partial_checkpoint(
                    project, run_id, state.revision, state.data, constraints,
                    segment_count,
                )
            )
            resumed_best = False
            if checkpoint:
                plan, draft, source_artifact, causal_chain = self._restore_short_checkpoint(
                    checkpoint, run_path / "outputs", checkpoint_context,
                )
                resumed_best = source_artifact == "best-candidate.md"
                constraints += (
                    "\n\n# Short Story Causal Chain\n\n"
                    + compact_causal_chain(causal_chain)
                )
                self.db.add_run_event(
                    run_id, "success", "checkpoint_reused", "已复用上一轮完整规划和分段草稿",
                    stage="draft", metadata={
                        "source_run": checkpoint.parent.name,
                        "source_artifact": source_artifact,
                    },
                )
            elif partial_checkpoint:
                plan = (partial_checkpoint / "planning.md").read_text(encoding="utf-8")
                causal_chain = json.loads(
                    (partial_checkpoint / "short-causal-chain.json").read_text(
                        encoding="utf-8"
                    )
                )
                atomic_write(run_path / "outputs" / "planning.md", plan)
                atomic_write(
                    run_path / "outputs" / "short-causal-chain.json",
                    json.dumps(causal_chain, ensure_ascii=False, indent=2),
                )
                atomic_write(
                    run_path / "outputs" / "short-execution-index.json",
                    (partial_checkpoint / "short-execution-index.json").read_text(
                        encoding="utf-8",
                    ),
                )
                planning_adaptation = None
                adaptation_source = partial_checkpoint / "planning-adaptations.json"
                if adaptation_source.is_file():
                    planning_adaptation = json.loads(
                        adaptation_source.read_text(encoding="utf-8"),
                    )
                    atomic_write(
                        run_path / "outputs" / "planning-adaptations.json",
                        json.dumps(planning_adaptation, ensure_ascii=False, indent=2),
                    )
                formal_outline = state.data.get("outline") or {}
                formal_outline_content = str(formal_outline.get("content") or "")
                formal_outline_events = (
                    narrative_outline_event_contracts(formal_outline_content)
                    if formal_outline_content.strip()
                    else formal_outline.get("events") or []
                )
                await self._ensure_short_execution_manifest(
                    run_id, run_path, project, constraints, state.revision,
                    state.data, plan, causal_chain, formal_outline_events,
                    segment_count, planning_adaptation,
                )
                for source in sorted(
                    (partial_checkpoint / "draft-checkpoints").glob("segment-*.json")
                ):
                    atomic_write(
                        run_path / "outputs" / "draft-checkpoints" / source.name,
                        source.read_text(encoding="utf-8"),
                    )
                constraints += (
                    "\n\n# Short Story Causal Chain\n\n"
                    f"{compact_causal_chain(causal_chain)}"
                )
                draft = await self._draft_short_in_segments(
                    run_id, run_path, project, constraints, plan,
                )
                self._save_short_checkpoint(
                    run_path / "outputs", checkpoint_context,
                )
                self.db.add_run_event(
                    run_id, "success", "partial_draft_checkpoint_reused",
                    "已复用上一任务通过校验的正文前缀，并从首个缺失分段继续",
                    stage="draft", metadata={
                        "source_run": partial_checkpoint.parent.name,
                    },
                )
            else:
                formal_outline = state.data.get("outline") or {}
                formal_outline_content = str(formal_outline.get("content") or "")
                formal_outline_events = (
                    narrative_outline_event_contracts(formal_outline_content)
                    if formal_outline_content.strip()
                    else formal_outline.get("events") or []
                )
                brief = json.dumps({
                    **project.metadata,
                    "formal_story_facts": canon_profile(project, state.data),
                    "formal_outline_events": narrative_outline_events(
                        formal_outline_events
                    ),
                    "generation_contract": {
                        "target_total_words": target_words,
                        "segment_count": segment_count,
                        "require_segment_map": segment_count > 1,
                        "segment_heading_format": (
                            f"### 第 1 段：标题，依次编号到 ### 第 {segment_count} 段：标题"
                        ),
                        "segment_block_fields": (
                            [
                                "事件ID：认领正式大纲事件表中的一个或多个 ID；连续分段可共同完成同一事件",
                                "大纲依据：对应的正式大纲事件名称",
                                "段首承接：上一段留下的人物位置、动作、关系和已知信息",
                                "本段事件：本段唯一负责的事件",
                                "段末交接：留给下一段的人物位置、动作、关系和已知信息",
                            ] if segment_count > 1 else []
                        ),
                    },
                    "short_causal_chain_contract": {
                        "purpose": "append whole-story causal-chain JSON without replacing the outline",
                        "start_marker": "SHORT_CAUSAL_CHAIN_JSON_START",
                        "end_marker": "SHORT_CAUSAL_CHAIN_JSON_END",
                        "fields": [
                            "core_goal", "opening", "cycles", "accidents", "reversal", "ending",
                            "question_chain", "relationship_arc",
                        ],
                        "cycle_shape": [
                            "obstacle", "effort", "result", "state_change", "escalation", "next_question",
                        ],
                        "opening_shape": [
                            "pressure", "anomaly", "reader_question", "future_promise",
                        ],
                        "ending_shape": ["surface_goal", "inner_goal", "cost"],
                    },
                }, ensure_ascii=False, indent=2)
                expected_plan_characters = max(3000, 1200 * segment_count)
                resumable_adaptation_plan = (
                    self._resumable_current_planning_adaptation_plan(
                        run_path, project, state.data, segment_count,
                        checkpoint_context["generation_context_sha256"],
                    )
                )
                if resumable_adaptation_plan is not None:
                    plan, causal_chain, legacy_context = resumable_adaptation_plan
                    self.db.add_run_event(
                        run_id, "success", "planning_adaptation_plan_reused",
                        "已复用哈希匹配且问题最少的完整规划候选，继续本地检查和适配审核",
                        stage="planning", metadata={
                            "planning_sha256": hashlib.sha256(
                                plan.encode("utf-8"),
                            ).hexdigest(),
                            "legacy_context_inferred": legacy_context,
                        },
                    )
                else:
                    proactive_split = self._route_requires_semantic_split(
                        "planning", expected_plan_characters,
                    )
                    try:
                        if proactive_split:
                            raise IncompleteModelOutputError(
                                "planning", StageText(
                                    "", {"finish_reason": "predicted_limit"},
                                ),
                            )
                        plan = await self._stage(
                            run_id, run_path, project, "planning", constraints, brief,
                            allow_tools=self._planning_uses_tools(state),
                            expected_output_characters=expected_plan_characters,
                            completion_check=lambda value: self._short_plan_output_complete(
                                project, state.data, value, segment_count,
                            ),
                        )
                    except IncompleteModelOutputError:
                        plan = await self._plan_short_in_batches(
                            run_id, run_path, project, constraints, brief,
                            state.data, segment_count,
                        )
                    plan, causal_chain = self._extract_short_causal_chain(run_id, plan)
                original_local_plan = plan
                plan = await self._recover_short_plan_local_gate(
                    run_id, run_path, project, constraints, brief, state.data,
                    plan, segment_count, expected_plan_characters,
                    generation_context_sha256=(
                        checkpoint_context["generation_context_sha256"]
                    ),
                )
                if plan != original_local_plan:
                    # An embedded causal chain belongs to the exact plan that
                    # produced it. Local repair may preserve most segments, but
                    # it still changes causal authority, so regenerate the chain
                    # from the final accepted plan instead of reusing stale data.
                    causal_chain = None
                plan, planning_adaptation, plan_changed = (
                    await self._ensure_short_plan_adaptations(
                        run_id, run_path, project, constraints, state.data, plan,
                        formal_outline_events, segment_count,
                        generation_context_sha256=(
                            checkpoint_context["generation_context_sha256"]
                        ),
                    )
                )
                if plan_changed:
                    causal_chain = None
                atomic_write(run_path / "outputs" / "planning.md", plan)
                causal_chain = await self._ensure_short_causal_chain(
                    run_id, run_path, project, constraints, plan,
                    formal_outline_events, causal_chain,
                )
                self._save_short_causal_chain(run_id, project, causal_chain)
                await self._ensure_short_execution_manifest(
                    run_id, run_path, project, constraints, state.revision,
                    state.data, plan, causal_chain, formal_outline_events,
                    segment_count, planning_adaptation,
                )
                constraints += (
                    "\n\n# Short Story Causal Chain\n\n"
                    f"{compact_causal_chain(causal_chain)}"
                )
                draft = await self._draft_short_in_segments(
                    run_id, run_path, project, constraints, plan,
                )
                atomic_write(run_path / "outputs" / "draft.md", draft)
                self._save_short_checkpoint(
                    run_path / "outputs", checkpoint_context,
                )
            draft_analysis = self._analyze_manuscript(
                draft, run_path, project, "draft",
            )
            draft_candidate = self.story_states.create_candidate(
                project.id, run_id, state.revision, "draft",
                hashlib.sha256(draft.encode("utf-8")).hexdigest(),
                {"artifact": "outputs/draft.md"},
            )
            draft_candidate_id = draft_candidate.id
            review_checkpoint = (
                None if resumed_best or checkpoint is None else self._find_short_stage_output(
                    project, checkpoint.parent.name, "review.md",
                )
            )
            review = None
            if review_checkpoint:
                try:
                    review_text = review_checkpoint.read_text(encoding="utf-8")
                    review = self._review(review_text)
                except (ValueError, json.JSONDecodeError):
                    review = None
                else:
                    atomic_write(run_path / "outputs" / "review.md", review_text)
                    self.db.add_run_event(
                        run_id, "success", "checkpoint_reused", "已复用上一轮有效编辑审核",
                        stage="review", metadata={"source_run": review_checkpoint.parent.parent.name},
                    )
            if review is None:
                review_input = (
                    f"MANUSCRIPT LENGTH: {len(draft)} characters.\n\nLABELED EXCERPTS:\n"
                    f"{reader_sample(draft, project.mode, limit=6000)}\n\n"
                    "LOCAL FULL MANUSCRIPT SUMMARY:\n"
                    f"{json.dumps(compact_analysis(draft_analysis), ensure_ascii=False)}"
                )
                review_text = await self._stage(
                    run_id, run_path, project, "review", constraints, review_input,
                    allow_tools=False,
                )
                review = self._review(review_text)
            if checkpoint and checkpoint.parent.name == run_id:
                polish_parts = self._split_polish_segments(draft)
                checkpoint_root = run_path / "outputs" / "polish-checkpoints" / "initial"
                completed_parts, next_part = self._polish_checkpoint_progress(
                    checkpoint_root, polish_parts,
                    self._polish_retry_signature(self.db.get_role_binding("polish") or {}),
                )
                self.db.add_run_event(
                    run_id, "success", "polish_resume_ready",
                    f"已复用当前任务的规划、完整草稿和审核，将从润色第 {next_part}/{len(polish_parts)} 段继续",
                    stage="polish", metadata={
                        "completed_segments": completed_parts,
                        "next_segment": next_part,
                        "total_segments": len(polish_parts),
                    },
                )
            polished, _ = await self._quality_polish(
                run_id, run_path, project, constraints, draft, review,
            )
            publish_text = "\n\n".join(self._split_segments(polished))
            publish_analysis = self._analyze_manuscript(
                publish_text, run_path, project, "publish",
            )
            publish_blockers = [
                item for item in publish_analysis.get("prose", {}).get("findings", [])
                if item.get("blocking")
            ]
            if publish_blockers:
                self.db.add_run_event(
                    run_id, "error", "publish_local_gate_failed",
                    "发布前全文检查发现正文异常，已保留最佳稿但不会写入正式稿",
                    stage="quality", metadata={"findings": publish_blockers[:12]},
                )
                raise ValueError("发布前全文检查未通过，请先处理正文完整性问题")
            canon_text = await self._stage_with_role_fallback(
                run_id, run_path, project, "maintenance", constraints, polished,
                fallback_role="planning", allow_tools=False,
            )
            canon = self._convert_generated_object(
                canon_text, run_path, contract_name="maintenance_facts",
            )
            if not isinstance(canon.get("facts"), list):
                raise ValueError("Maintenance output must contain a facts array")
            polished = "\n\n".join(self._split_segments(polished))
            candidate = self.story_states.create_candidate(
                project.id, run_id, state.revision, "polish",
                hashlib.sha256(polished.encode("utf-8")).hexdigest(),
                {"artifact": "outputs/polish.md"},
            )
            candidate_id = candidate.id
            chapter_text = self._chapter_file(project, polished)
            canon_json = json.dumps(canon, ensure_ascii=False, indent=2)
            promotion_journal_path = (
                run_path / "outputs" / "formal-promotion-journal.json"
            )
            promotion_files = [
                (formal[0], polished),
                (formal[1], chapter_text),
                (formal[2], canon_json),
            ]
            promotion_payload_root = (
                run_path / "outputs" / "formal-promotion-payload"
            )
            promotion_file_records = []
            for index, (path, content) in enumerate(promotion_files):
                recovery_path = promotion_payload_root / f"{index:02d}-{path.name}"
                atomic_write(recovery_path, content)
                promotion_file_records.append({
                    "path": path.relative_to(project.path).as_posix(),
                    "new_sha256": hashlib.sha256(
                        content.encode("utf-8"),
                    ).hexdigest(),
                    "recovery_path": recovery_path.relative_to(
                        project.path,
                    ).as_posix(),
                })
            atomic_write(
                promotion_journal_path,
                json.dumps({
                    "version": 1,
                    "status": "prepared",
                    "run_id": run_id,
                    "candidate_id": candidate.id,
                    "base_revision": state.revision,
                    "target_revision": state.revision + 1,
                    "snapshot_path": snapshot.snapshot_root.relative_to(
                        project.path,
                    ).as_posix(),
                    "files": promotion_file_records,
                }, ensure_ascii=False, indent=2, sort_keys=True),
            )
            atomic_write(formal[0], polished)
            atomic_write(formal[1], chapter_text)
            atomic_write(formal[2], canon_json)
            self._set_formal_promotion_journal_status(
                promotion_journal_path, "files_written",
            )
            self._post_write_maintenance(run_id, project)
            confirmed = []
            for index, fact in enumerate(canon.get("facts", [])):
                if isinstance(fact, dict):
                    key = str(fact.get("fact_key") or fact.get("subject") or f"generated.{index}")
                    value = fact.get("value", fact.get("fact", ""))
                elif isinstance(fact, str):
                    key, value = f"generated.{index}", fact
                else:
                    continue
                confirmed.append({
                    "key": key,
                    "value": value,
                    "level": "confirmed",
                    "source": run_id,
                })
            next_data = {
                **state.data,
                "confirmed_facts": confirmed or state.data.get("confirmed_facts", []),
                "character_states": canon.get("state", state.data.get("character_states", {})),
                "world_rules": canon.get("world_rules", state.data.get("world_rules", [])),
                "timeline_events": canon.get("timeline", state.data.get("timeline_events", [])),
                "manuscript_revision": int(state.data.get("manuscript_revision", 0)) + 1,
            }
            committed = self.story_states.commit(candidate.id, state.revision, next_data)
            state_committed = True
            self._set_formal_promotion_journal_status(
                promotion_journal_path, "committed",
                committed_revision=committed.revision,
            )
            snapshot.discard()
            self.story_states.reject(draft_candidate.id, "superseded by accepted polish")
            self.db.add_run_event(
                run_id, "success", "story_state_committed", "正式稿与权威故事状态已提交",
                stage="archive", metadata={
                    "candidate_id": candidate.id,
                    "base_revision": state.revision,
                    "revision": committed.revision,
                },
            )
            self.db.update_run(run_id, "completed", "archive")
            return self.db.get_run(run_id) or {"id": run_id, "status": "completed"}
        except asyncio.CancelledError:
            if not state_committed:
                restored = self._restore_snapshot_after_failure(run_id, snapshot)
                if restored and promotion_journal_path is not None:
                    self._set_formal_promotion_journal_status(
                        promotion_journal_path, "rolled_back",
                    )
                    snapshot.discard()
            if candidate_id:
                self.story_states.reject(candidate_id, "cancelled")
            if draft_candidate_id:
                self.story_states.reject(draft_candidate_id, "cancelled")
            self.db.update_run(run_id, "cancelled", error="Cancelled by user")
            raise
        except Exception as exc:
            if not state_committed:
                restored = self._restore_snapshot_after_failure(run_id, snapshot)
                if restored and promotion_journal_path is not None:
                    self._set_formal_promotion_journal_status(
                        promotion_journal_path, "rolled_back",
                    )
                    snapshot.discard()
            if candidate_id:
                self.story_states.reject(candidate_id, str(exc))
            if draft_candidate_id:
                self.story_states.reject(draft_candidate_id, str(exc))
            self.db.update_run(run_id, "failed", error=str(exc))
            raise

    def _extract_short_causal_chain(
        self, run_id: str, plan: str,
    ) -> tuple[str, dict | None]:
        try:
            outline, chain = extract_short_causal_chain(plan)
        except (ValueError, json.JSONDecodeError) as exc:
            self.db.add_run_event(
                run_id, "warning", "causal_chain_parse_failed",
                "短篇因果链解析失败，规划稿将先进入本地修正",
                stage="planning", metadata={"error": str(exc)[:300]},
            )
            return plan, None
        if not chain:
            return plan, None

        return outline, chain

    def _short_plan_output_complete(
        self, project: Project, state: dict, value: str, segment_count: int,
    ) -> bool:
        try:
            outline, _chain = extract_short_causal_chain(value)
        except (ValueError, json.JSONDecodeError):
            return False
        return not self._short_plan_issues(project, state, outline, segment_count)

    def _route_requires_semantic_split(
        self, role: str, expected_output_characters: int,
    ) -> bool:
        binding = self.db.get_role_binding(role) or {}
        provider_id = str(binding.get("primary_provider_id") or "")
        model_id = str(binding.get("primary_model_id") or "")
        if not provider_id or not model_id:
            return False
        stable_limits = [
            profile["suspected_stable_output_tokens"]
            for profile in (
                self.db.latest_model_output_profile(provider_id, model_id, "plain"),
                self.db.latest_model_output_profile(
                    provider_id, model_id, "native_tool_round",
                ),
            )
            if isinstance(profile.get("suspected_stable_output_tokens"), int)
            and profile["suspected_stable_output_tokens"] > 0
        ]
        if not stable_limits:
            return False
        stable = min(stable_limits)
        return estimate_input_tokens("汉" * expected_output_characters) >= int(stable * 0.75)

    async def _plan_short_in_batches(
        self, run_id: str, run_path: Path, project: Project, constraints: str,
        brief: str, state: dict, segment_count: int,
    ) -> str:
        if segment_count < 2:
            raise ValueError("单段短篇规划超过供应商可完整返回的范围，无法安全拆分")
        batch_size = max(1, math.ceil(segment_count / 2))
        ranges = [
            (start, min(segment_count, start + batch_size - 1))
            for start in range(1, segment_count + 1, batch_size)
        ]
        self.db.add_run_event(
            run_id, "warning", "planning_task_split",
            "规划单次输出可能不完整，已按连续写作段拆成内部子任务",
            stage="planning", metadata={
                "subtasks": len(ranges), "segment_count": segment_count,
            },
        )
        blocks: list[str] = []
        checkpoint_root = run_path / "outputs" / "planning-checkpoints"
        authority = hashlib.sha256(
            (brief + constraints).encode("utf-8")
        ).hexdigest()
        for batch_number, (start, end) in enumerate(ranges, 1):
            previous = "\n\n".join(blocks)
            previous_hash = hashlib.sha256(previous.encode("utf-8")).hexdigest()
            checkpoint_path = checkpoint_root / f"batch-{batch_number:02d}.json"
            try:
                cached = json.loads(checkpoint_path.read_text(encoding="utf-8"))
            except (OSError, json.JSONDecodeError, AttributeError):
                cached = {}
            block = str(cached.get("text") or "")
            if not (
                cached.get("authority_sha256") == authority
                and cached.get("previous_sha256") == previous_hash
                and cached.get("range") == [start, end]
                and cached.get("text_sha256")
                == hashlib.sha256(block.encode("utf-8")).hexdigest()
                and self._short_plan_batch_complete(block, start, end)
            ):
                prompt = (
                    f"{brief}\n\nAUTOMATIC INTERNAL PLANNING SUBTASK {batch_number}/{len(ranges)}\n"
                    f"本次只返回第 {start} 段到第 {end} 段的完整规划块，标题必须使用"
                    f"“### 第 {start} 段：标题”到“### 第 {end} 段：标题”。"
                    "每段仍须包含事件ID、大纲依据、段首承接、本段事件、段末交接。"
                    "根据正式大纲顺序认领事件，不得重写前面批次，不得提前分配后续批次。"
                    + (f"\n\n前面已验收批次：\n{previous}" if previous else "")
                )
                block = await self._stage(
                    run_id, run_path, project, "planning", constraints, prompt,
                    suffix=f"-batch-{batch_number:02d}", allow_tools=False,
                    expected_output_characters=max(1800, (end - start + 1) * 1200),
                    completion_check=lambda value, first=start, last=end: (
                        self._short_plan_batch_complete(value, first, last)
                    ),
                )
                if not self._short_plan_batch_complete(block, start, end):
                    raise ValueError(
                        f"规划内部子任务 {batch_number} 未完整返回第 {start}-{end} 段"
                    )
                atomic_write(checkpoint_path, json.dumps({
                    "version": 1, "authority_sha256": authority,
                    "previous_sha256": previous_hash, "range": [start, end],
                    "text_sha256": hashlib.sha256(block.encode("utf-8")).hexdigest(),
                    "text": block,
                }, ensure_ascii=False, indent=2))
            blocks.append(block.strip())
        combined = "\n\n".join(blocks)
        if self._short_plan_issues(project, state, combined, segment_count):
            self.db.add_run_event(
                run_id, "warning", "planning_batches_need_repair",
                "规划内部子任务已合并，正在通过原有全篇检查定位事件分工问题",
                stage="planning",
            )
        return combined

    @classmethod
    def _short_plan_batch_complete(cls, value: str, start: int, end: int) -> bool:
        headings = {
            number for _match, number in cls._short_plan_headings(value)
            if number is not None
        }
        return headings == set(range(start, end + 1)) and all(
            cls._short_plan_field(block, "event")
            and cls._short_plan_field(block, "handoff")
            for block in cls._short_plan_segments_for_range(value, start, end)
        )

    @classmethod
    def _replace_short_plan_segment(
        cls, plan: str, segment_count: int, segment: int, replacement: str,
    ) -> str:
        headings = cls._short_plan_headings(plan)
        target = next((
            (index, match) for index, (match, number) in enumerate(headings)
            if number == segment
        ), None)
        if target is None:
            raise ValueError(f"规划稿缺少第 {segment} 段，无法执行定向修正")
        index, match = target
        end = headings[index + 1][0].start() if index + 1 < len(headings) else len(plan)
        prefix = plan[:match.start()].rstrip()
        suffix = plan[end:].lstrip()
        parts = [value for value in (prefix, replacement.strip(), suffix) if value]
        candidate = "\n\n".join(parts).strip()
        if len(cls._short_plan_segments(candidate, segment_count)) != segment_count:
            raise ValueError("定向修正破坏了规划稿的完整分段结构")
        return candidate

    @staticmethod
    def _short_plan_local_issue_records(issues: list[str]) -> list[dict]:
        """Turn deterministic local messages into stable monotonic identities."""
        records: list[dict] = []

        def add(code: str, message: str, *, segment: int = 0,
                event_id: str = "") -> None:
            records.append({
                "code": code,
                "segment": segment,
                "event_id": event_id,
                "message": message,
            })

        for value in issues:
            message = str(value or "").strip()
            if not message:
                continue
            if message.startswith("规划稿附带的因果链"):
                add("local_causal_chain_marker", message)
                continue
            if message.startswith("人物或地点与正式设定不一致"):
                detail = message.split("：", 1)[-1]
                labels = [
                    item.split("（", 1)[0].strip()
                    for item in re.split(r"[、,，]", detail)
                    if item.strip()
                ]
                if labels:
                    for label in labels:
                        add(f"local_canon_conflict:{label}", message)
                else:
                    add("local_canon_conflict", message)
                continue
            if "分段标题必须恰好" in message:
                add("local_segment_heading_format", message)
                continue
            if "需要明确列出第" in message and "各自负责的事件" in message:
                add("local_segment_coverage", message)
                continue
            if message.startswith("有分段没有写清"):
                add("local_segment_detail", message)
                continue
            if "段缺少事件ID" in message:
                prefix = message.split("段缺少", 1)[0]
                numbers = [int(item) for item in re.findall(r"\d+", prefix)]
                if numbers:
                    for number in numbers:
                        add("local_required_fields", message, segment=number)
                else:
                    add("local_required_fields", message)
                continue
            event_ids = planning_event_ids(message, formal_only=True)
            if "规划正式事件只在段首清单中出现" in message:
                segment_match = re.match(r"第\s*(\d+)\s*段", message)
                segment = int(segment_match.group(1)) if segment_match else 0
                for event_id in event_ids or [""]:
                    add(
                        "event_body_missing", message,
                        segment=segment, event_id=event_id,
                    )
                continue
            if "规划正式事件在本段事件正文中重复声明" in message:
                segment_match = re.match(r"第\s*(\d+)\s*段", message)
                segment = int(segment_match.group(1)) if segment_match else 0
                for event_id in event_ids or [""]:
                    add(
                        "event_body_duplicate", message,
                        segment=segment, event_id=event_id,
                    )
                continue
            if "规划正式事件正文过短" in message:
                segment_match = re.match(r"第\s*(\d+)\s*段", message)
                segment = int(segment_match.group(1)) if segment_match else 0
                for event_id in event_ids or [""]:
                    add(
                        "event_body_collapsed", message,
                        segment=segment, event_id=event_id,
                    )
                continue
            if message.startswith("规划稿使用了不存在的事件 ID"):
                for event_id in event_ids or [""]:
                    add("local_invalid_event_id", message, event_id=event_id)
                continue
            if message.startswith("这些正式大纲事件还没有分配到写作段"):
                for event_id in event_ids or [""]:
                    add("local_missing_event", message, event_id=event_id)
                continue
            if message.startswith("写作段认领的大纲事件顺序发生倒退"):
                identity = "->".join(event_ids) or "unknown"
                add(f"local_event_order:{identity}", message)
                continue
            if message.startswith("不同分段承担了过于相似的事件"):
                add("local_segment_duplication", message)
                continue
            digest = hashlib.sha256(message.encode("utf-8")).hexdigest()[:16]
            add(f"local_unknown:{digest}", message)
        return records

    @classmethod
    def _select_monotonic_short_plan_candidate(
        cls, project: Project, state: dict, best_plan: str, candidate: str,
        segment_count: int,
    ) -> tuple[str, list[str], dict]:
        """Keep the smallest changed segment set that strictly reduces issues."""
        best_issues = cls._short_plan_issues(
            project, state, best_plan, segment_count,
        )
        best_records = cls._short_plan_local_issue_records(best_issues)
        possibilities: list[tuple[tuple, str, list[str], dict]] = []

        def consider(value: str, selected_segments: list[int]) -> None:
            current_issues = cls._short_plan_issues(
                project, state, value, segment_count,
            )
            comparison = planning_candidate_comparison(
                best_records,
                cls._short_plan_local_issue_records(current_issues),
            )
            if not comparison["improved"]:
                return
            issue_count = len(comparison["candidate_issue_keys"])
            rank = (
                issue_count,
                len(selected_segments),
                tuple(selected_segments),
                hashlib.sha256(value.encode("utf-8")).hexdigest(),
            )
            possibilities.append((rank, value, current_issues, {
                **comparison,
                "selected_segments": selected_segments,
                "preserved_segments": [
                    number for number in range(1, segment_count + 1)
                    if number not in selected_segments
                ],
                "candidate_sha256": hashlib.sha256(
                    candidate.encode("utf-8"),
                ).hexdigest(),
                "selected_plan_sha256": hashlib.sha256(
                    value.encode("utf-8"),
                ).hexdigest(),
            }))

        best_segments = cls._short_plan_segments(best_plan, segment_count)
        candidate_segments = cls._short_plan_segments(candidate, segment_count)
        if (
            segment_count > 1
            and len(best_segments) == segment_count
            and len(candidate_segments) == segment_count
        ):
            changed = [
                number for number, (before, after) in enumerate(
                    zip(best_segments, candidate_segments, strict=True), 1,
                ) if before != after
            ]
            for size in range(1, len(changed) + 1):
                for selected in combinations(changed, size):
                    merged = best_plan
                    try:
                        for number in selected:
                            merged = cls._replace_short_plan_segment(
                                merged, segment_count, number,
                                candidate_segments[number - 1],
                            )
                    except ValueError:
                        continue
                    consider(merged, list(selected))
        else:
            consider(candidate, list(range(1, segment_count + 1)))

        if possibilities:
            _rank, selected, issues, comparison = min(
                possibilities, key=lambda item: item[0],
            )
            return selected, issues, comparison
        comparison = planning_candidate_comparison(
            best_records,
            cls._short_plan_local_issue_records(
                cls._short_plan_issues(project, state, candidate, segment_count),
            ),
        )
        return best_plan, best_issues, {
            **comparison,
            "selected_segments": [],
            "preserved_segments": list(range(1, segment_count + 1)),
            "candidate_sha256": hashlib.sha256(
                candidate.encode("utf-8"),
            ).hexdigest(),
            "selected_plan_sha256": hashlib.sha256(
                best_plan.encode("utf-8"),
            ).hexdigest(),
        }

    async def _repair_short_plan_local_event_segment(
        self, run_id: str, run_path: Path, project: Project, constraints: str,
        state: dict, plan: str, segment_count: int, segment: int,
        issues: list[dict], *, attempt: int,
    ) -> str:
        """Repair only event realization ownership for one complete segment."""
        plan_segments = self._short_plan_segments(plan, segment_count)
        if not 1 <= segment <= len(plan_segments):
            raise ValueError(f"规划稿缺少第 {segment} 段，无法修复事件归属")
        current = plan_segments[segment - 1]
        event_ids = self._short_plan_event_ids(current)
        if not event_ids:
            raise ValueError(f"规划第 {segment} 段没有可验证的正式事件归属")
        outline_content = str(((state.get("outline") or {}).get("content")) or "")
        formal_events = (
            outline_events(outline_content)
            if outline_content.strip() else
            list((state.get("outline") or {}).get("events") or [])
        )
        contracts = self._planning_adaptation_contracts(state, formal_events)
        contract_by_id = {
            str(item.get("id") or "").strip().upper(): item
            for item in contracts
        }
        owned_contracts = [
            contract_by_id[event_id] for event_id in event_ids
            if event_id in contract_by_id
        ]
        current_issues = [
            item for item in issues
            if int(item.get("segment") or 0) == segment
        ]
        authority = {
            "segment": segment,
            "event_ids": event_ids,
            "source_sha256": hashlib.sha256(
                current.encode("utf-8"),
            ).hexdigest(),
            "outline_basis": self._short_plan_field(current, "outline"),
            "opening": self._short_plan_field(current, "opening"),
            "handoff": self._short_plan_field(current, "handoff"),
        }
        structured_contract = StructuredArtifactContract(
            name="planning_event_realizations",
            schema={
                "$schema": "https://json-schema.org/draft/2020-12/schema",
                "type": "object",
                "properties": {
                    "events": {
                        "type": "array",
                        "minItems": len(event_ids),
                        "maxItems": len(event_ids),
                        "items": {
                            "type": "object",
                            "properties": {
                                "event_id": {"type": "string"},
                                "narrative": {"type": "string", "minLength": 12},
                            },
                            "required": ["event_id", "narrative"],
                            "additionalProperties": False,
                        },
                    },
                },
                "required": ["events"],
                "additionalProperties": False,
            },
            runtime_authority=authority,
        )
        prompt = (
            "SHORT_PLAN_EVENT_REALIZATION_RECOVERY_V3\n"
            "Return exactly one JSON object with only an events array. The Runtime owns "
            "the segment, event order, outline basis, opening, and handoff; do not return "
            "or change those controls. Return exactly one item for every EXPECTED EVENT ID "
            "in the same order. Each narrative must independently state the executable "
            "actor action, resistance or response, result/state change, and useful scene "
            "realization. Preserve valid dialogue intent, detail, pacing, and voice from the "
            "current segment. Do not invent a new plot function, move a later reveal early, "
            "change agency, chronology, knowledge, relationship state, viewpoint, promise, "
            "or ending. Multiple tightly coupled events may share one scene, but every item "
            "must still explain its own contribution. Do not include Markdown fences or "
            "commentary.\n"
            f"ATTEMPT: {attempt}\nEXPECTED SEGMENT: {segment}\n"
            "EXPECTED EVENT IDS:\n"
            + json.dumps(event_ids, ensure_ascii=False)
            + "\n\nRUNTIME AUTHORITY (IMMUTABLE):\n"
            + json.dumps(authority, ensure_ascii=False, indent=2)
            + "\n\nFORMAL EVENT CONTRACTS:\n"
            + json.dumps(owned_contracts, ensure_ascii=False, indent=2)
            + "\n\nCURRENT OWNERSHIP ISSUES:\n"
            + json.dumps(current_issues, ensure_ascii=False, indent=2)
            + "\n\nCURRENT COMPLETE SEGMENT (CREATIVE SOURCE):\n"
            + current
        )

        def normalized(value: str) -> str:
            try:
                artifact_ir = compile_planning_event_artifact(
                    value, expected_event_ids=event_ids,
                )
                event_body = "\n\n".join(
                    f"{index}. **正式事件**（{item.event_id}）："
                    + remove_planning_event_ids(
                        item.narrative, formal_only=True,
                    ).strip()
                    for index, item in enumerate(artifact_ir.events, 1)
                )
                return self._render_short_plan_repair_packet(
                    current,
                    segment=segment,
                    event_ids=event_ids,
                    event_body=event_body,
                    opening=self._short_plan_field(current, "opening"),
                    handoff=self._short_plan_field(current, "handoff"),
                )
            except (TypeError, ValueError):
                try:
                    return self._normalize_runtime_owned_short_plan_payload(
                        value,
                        segment=segment,
                        event_ids=event_ids,
                        current=current,
                        artifact="local planning event recovery",
                    )
                except GeneratedArtifactShapeError:
                    return self._normalize_generated_short_plan_segment(
                        value,
                        segment=segment,
                        event_ids=event_ids,
                        current=current,
                        artifact="local planning event recovery",
                    )

        def complete(value: str) -> bool:
            try:
                block = normalized(value)
            except GeneratedArtifactShapeError:
                return False
            return not planning_event_body_issues(block, event_ids)

        raw = await self._stage(
            run_id, run_path, project, "planning", constraints, prompt,
            suffix=f"-local-event-segment-{segment:02d}-attempt-{attempt}",
            allow_tools=False,
            expected_output_characters=max(1600, len(current)),
            completion_check=complete,
            compact_input=True,
            route_capacity_guard=True,
            story_skeleton_override=self._stage_story_skeleton(
                project, constraints, run_path,
                owner_event_ids=event_ids, index_only=True,
            ),
            bounded_protocol_output=True,
            structured_contract=structured_contract,
        )
        try:
            block = normalized(raw)
        except GeneratedArtifactShapeError:
            block = await self._normalize_generated_short_plan_segment_with_protocol_retry(
                run_id, run_path, project, constraints, raw,
                segment=segment,
                event_ids=event_ids,
                current=current,
                artifact="local planning event recovery",
                suffix=f"-local-event-segment-{segment:02d}-attempt-{attempt}",
            )
        remaining = planning_event_body_issues(block, event_ids)
        if remaining:
            raise GeneratedArtifactShapeError(
                f"规划第 {segment} 段事件正文仍不完整",
                issues=remaining,
            )
        return self._replace_short_plan_segment(
            plan, segment_count, segment, block,
        )

    async def _recover_short_plan_local_gate(
        self, run_id: str, run_path: Path, project: Project, constraints: str,
        brief: str, state: dict, plan: str, segment_count: int,
        expected_plan_characters: int, *, generation_context_sha256: str,
    ) -> str:
        """Resolve local plan defects without allowing repair regression."""
        best_plan = plan
        best_issues = self._short_plan_issues(
            project, state, best_plan, segment_count,
        )
        if not best_issues:
            return best_plan
        outline_content = str(((state.get("outline") or {}).get("content")) or "")
        outline_sha256 = hashlib.sha256(
            outline_content.encode("utf-8"),
        ).hexdigest()
        recovered = read_planning_recovery(run_path / "outputs")
        recovery_state = None
        if recovered is not None:
            stored_state, stored_plan = recovered
            if (
                stored_plan == best_plan
                and planning_recovery_state_matches(
                    stored_state,
                    outline_sha256=outline_sha256,
                    generation_context_sha256=generation_context_sha256,
                    segment_count=segment_count,
                )
                and str(stored_state.get("status") or "").startswith((
                    "local_", "recoverable_",
                ))
            ):
                recovery_state = stored_state
        if recovery_state is None:
            recovery_state = new_planning_recovery_state(
                outline_sha256=outline_sha256,
                generation_context_sha256=generation_context_sha256,
                segment_count=segment_count,
                plan=best_plan,
                issues=self._short_plan_local_issue_records(best_issues),
            )
        recovery_state["status"] = "local_repair"
        recovery_state["best_issues"] = self._short_plan_local_issue_records(
            best_issues,
        )
        recovery_state["best_issue_keys"] = sorted(planning_issue_keys(
            recovery_state["best_issues"],
        ))
        recovery_state["local_issue_messages"] = best_issues
        write_planning_recovery(run_path / "outputs", recovery_state, best_plan)

        # Event-realization ownership is a typed, independently promotable
        # unit. Repair it per complete segment before invoking the legacy
        # whole-plan compatibility fallback. This keeps already accepted
        # segments byte-identical and gives every remaining segment its own
        # bounded recovery budget.
        for granular_attempt in range(1, 3):
            issue_records = self._short_plan_local_issue_records(best_issues)
            ownership_records = [
                item for item in issue_records
                if str(item.get("code") or "").startswith("event_body_")
                and int(item.get("segment") or 0) > 0
            ]
            target_segments = sorted({
                int(item["segment"]) for item in ownership_records
            })
            if not target_segments:
                break
            round_progress = False
            self.db.add_run_event(
                run_id, "warning", "planning_event_ownership_recovery_started",
                "规划格式已经本地规范化，正在按分段补齐正式事件与可执行正文的绑定",
                stage="planning", metadata={
                    "attempt": granular_attempt,
                    "target_segments": target_segments,
                    "remaining_event_issues": len(ownership_records),
                },
            )
            for segment in target_segments:
                current_records = self._short_plan_local_issue_records(best_issues)
                segment_records = [
                    item for item in current_records
                    if int(item.get("segment") or 0) == segment
                    and str(item.get("code") or "").startswith("event_body_")
                ]
                if not segment_records:
                    continue
                source_segments = self._short_plan_segments(
                    best_plan, segment_count,
                )
                source_segment_sha256 = hashlib.sha256(
                    source_segments[segment - 1].encode("utf-8"),
                ).hexdigest()
                try:
                    candidate = await self._repair_short_plan_local_event_segment(
                        run_id, run_path, project, constraints, state,
                        best_plan, segment_count, segment, segment_records,
                        attempt=granular_attempt,
                    )
                except asyncio.CancelledError:
                    raise
                except Exception as exc:
                    recovery_state.setdefault("execution_failures", []).append({
                        "source": "local-event-segment",
                        "segment": segment,
                        "attempt": granular_attempt,
                        "error_type": type(exc).__name__,
                        "message": describe_error(exc),
                    })
                    write_planning_recovery(
                        run_path / "outputs", recovery_state, best_plan,
                    )
                    self.db.add_run_event(
                        run_id, "warning", "planning_event_segment_recovery_failed",
                        f"规划第 {segment} 段事件绑定修复未通过，已保留当前最佳段并继续处理其他分段",
                        stage="planning", metadata={
                            "segment": segment,
                            "attempt": granular_attempt,
                            "failure_class": type(exc).__name__,
                        },
                    )
                    continue
                selected, selected_issues, comparison = (
                    self._select_monotonic_short_plan_candidate(
                        project, state, best_plan, candidate, segment_count,
                    )
                )
                accepted = selected != best_plan and bool(comparison["improved"])
                recovery_state = record_planning_candidate(
                    recovery_state,
                    plan=selected if accepted else candidate,
                    issues=self._short_plan_local_issue_records(
                        selected_issues if accepted else self._short_plan_issues(
                            project, state, candidate, segment_count,
                        ),
                    ),
                    comparison=comparison,
                    source=(
                        f"local-event-segment-{segment:02d}-"
                        f"attempt-{granular_attempt}"
                    ),
                    accepted=accepted,
                )
                if not accepted:
                    write_planning_recovery(
                        run_path / "outputs", recovery_state, best_plan,
                    )
                    continue
                best_plan = selected
                best_issues = selected_issues
                round_progress = True
                recovery_state["local_issue_messages"] = best_issues
                selected_segments = self._short_plan_segments(
                    best_plan, segment_count,
                )
                if 1 <= segment <= len(selected_segments):
                    self.db.save_workflow_node_checkpoint(
                        run_id=run_id,
                        node_key=f"planning-segment-{segment:02d}",
                        authority_sha256=outline_sha256,
                        input_sha256=source_segment_sha256,
                        output_sha256=hashlib.sha256(
                            selected_segments[segment - 1].encode("utf-8"),
                        ).hexdigest(),
                        status="generated_complete",
                        validation_stage="local_semantics",
                        payload={
                            "segment": segment,
                            "event_ids": self._short_plan_event_ids(
                                selected_segments[segment - 1],
                            ),
                            "unchanged_scope": comparison.get(
                                "preserved_segments", [],
                            ),
                        },
                    )
                write_planning_recovery(
                    run_path / "outputs", recovery_state, best_plan,
                )
                self.db.add_run_event(
                    run_id, "success", "planning_event_segment_recovered",
                    f"规划第 {segment} 段正式事件正文已经补齐并保存，其他分段保持不变",
                    stage="planning", metadata={
                        "segment": segment,
                        "attempt": granular_attempt,
                        "comparison": comparison,
                        "remaining_issues": len(best_issues),
                    },
                )
                if not best_issues:
                    self.db.save_workflow_node_checkpoint(
                        run_id=run_id,
                        node_key="planning-local-gate",
                        authority_sha256=outline_sha256,
                        input_sha256=(
                            generation_context_sha256
                            if re.fullmatch(
                                r"[0-9a-f]{64}", generation_context_sha256,
                            )
                            else hashlib.sha256(
                                generation_context_sha256.encode("utf-8"),
                            ).hexdigest()
                        ),
                        output_sha256=hashlib.sha256(
                            best_plan.encode("utf-8"),
                        ).hexdigest(),
                        status="generated_complete",
                        validation_stage="local_semantics",
                        payload={"segment_count": segment_count},
                    )
                    recovery_state["status"] = "local_ready"
                    write_planning_recovery(
                        run_path / "outputs", recovery_state, best_plan,
                    )
                    return best_plan
            if not round_progress and granular_attempt >= 2:
                break

        unresolved_ownership = [
            item for item in self._short_plan_local_issue_records(best_issues)
            if str(item.get("code") or "").startswith("event_body_")
        ]
        if unresolved_ownership:
            recovery_state["status"] = "recoverable_event_ownership_failed"
            recovery_state["local_issue_messages"] = best_issues
            write_planning_recovery(
                run_path / "outputs", recovery_state, best_plan,
            )
            self.db.add_run_event(
                run_id, "error", "planning_event_ownership_recovery_exhausted",
                "受影响分段已分别使用完恢复预算；已保留最佳完整规划，未用整稿重写覆盖有效分段",
                stage="planning", metadata={
                    "issues": unresolved_ownership,
                    "protected_plan_sha256": hashlib.sha256(
                        best_plan.encode("utf-8"),
                    ).hexdigest(),
                    "whole_plan_fallback_used": False,
                },
            )
            raise GeneratedArtifactShapeError(
                "规划正式事件正文分段恢复尚未收敛，最佳完整规划已保留",
                issues=unresolved_ownership,
            )

        for attempt in range(1, 3):
            event_type = (
                "planning_gate_retry" if attempt == 1
                else "planning_gate_targeted_retry"
            )
            message = (
                "规划稿没有通过本地检查，正在只修正必要分段后再进入正文"
                if attempt == 1 else
                "规划本地问题尚未完全收敛，正在再次只处理剩余问题"
            )
            self.db.add_run_event(
                run_id, "warning", event_type, message,
                stage="planning", metadata={
                    "attempt": attempt,
                    "issues": best_issues,
                    "best_issue_keys": sorted(planning_issue_keys(
                        self._short_plan_local_issue_records(best_issues),
                    )),
                },
            )
            repair_prompt = (
                "SHORT_PLAN_LOCAL_RECOVERY_V2\n"
                f"LOCAL RECOVERY ATTEMPT: {attempt}\n"
                "请修正下面的规划稿。只允许修改解决所列问题所必需的完整分段；已经有效的分段必须逐字保留。"
                "不得改变正式大纲的故事方向、人物主动性、因果、视角、结局承诺或事件顺序。"
                f"必须恰好写 {segment_count} 个分段，标题依次使用“### 第 1 段：标题”"
                f"到“### 第 {segment_count} 段：标题”；每段写明事件ID、大纲依据、段首承接、"
                "本段事件和段末交接。每个正式大纲事件 ID 必须按原顺序覆盖，连续分段可以共同完成"
                "同一事件。段首和段末必须交代人物位置、当前行动、关系和已知信息。"
                "只返回完整规划稿，不要说明。\n\n"
                f"剩余问题：{json.dumps(best_issues, ensure_ascii=False)}\n\n"
                f"当前最佳规划稿：\n{best_plan}"
            )
            try:
                raw_candidate = await self._stage(
                    run_id, run_path, project, "planning", constraints,
                    repair_prompt,
                    suffix="-gate-repair" if attempt == 1 else f"-gate-repair-{attempt}",
                    allow_tools=False,
                    expected_output_characters=expected_plan_characters,
                    completion_check=lambda value: self._short_plan_output_complete(
                        project, state, value, segment_count,
                    ),
                )
            except IncompleteModelOutputError:
                raw_candidate = await self._plan_short_in_batches(
                    run_id, run_path, project, constraints,
                    brief + "\n\nLOCAL RECOVERY REQUIREMENTS:\n" + repair_prompt,
                    state, segment_count,
                )
            candidate, _candidate_chain = self._extract_short_causal_chain(
                run_id, raw_candidate,
            )
            selected, selected_issues, comparison = (
                self._select_monotonic_short_plan_candidate(
                    project, state, best_plan, candidate, segment_count,
                )
            )
            accepted = selected != best_plan and bool(comparison["improved"])
            recovery_state = record_planning_candidate(
                recovery_state,
                plan=selected if accepted else candidate,
                issues=self._short_plan_local_issue_records(
                    selected_issues if accepted else self._short_plan_issues(
                        project, state, candidate, segment_count,
                    ),
                ),
                comparison=comparison,
                source=f"local-{attempt}",
                accepted=accepted,
            )
            if accepted:
                best_plan = selected
                best_issues = selected_issues
                recovery_state["local_issue_messages"] = best_issues
                write_planning_recovery(
                    run_path / "outputs", recovery_state, best_plan,
                )
                self.db.add_run_event(
                    run_id, "success", "planning_gate_candidate_improved",
                    (
                        "规划本地问题已全部解决，未受影响分段保持不变"
                        if not best_issues else
                        "规划本地问题集合已严格缩小，未受影响分段保持不变"
                    ),
                    stage="planning", metadata=comparison,
                )
                if not best_issues:
                    recovery_state["status"] = "local_ready"
                    write_planning_recovery(
                        run_path / "outputs", recovery_state, best_plan,
                    )
                    return best_plan
            else:
                write_planning_recovery(
                    run_path / "outputs", recovery_state, best_plan,
                )
                self.db.add_run_event(
                    run_id, "warning", "planning_gate_candidate_rejected_regression",
                    "规划修复候选没有严格减少问题或引入了新问题，已恢复此前最佳规划",
                    stage="planning", metadata=comparison,
                )

        recovery_state["status"] = "recoverable_failed"
        recovery_state["local_issue_messages"] = best_issues
        write_planning_recovery(run_path / "outputs", recovery_state, best_plan)
        self.db.add_run_event(
            run_id, "error", "planning_gate_failed",
            "规划本地修正未能单调收敛，已保留问题最少的完整规划并在正文前停止",
            stage="planning", metadata={
                "issues": best_issues,
                "best_issue_keys": sorted(planning_issue_keys(
                    self._short_plan_local_issue_records(best_issues),
                )),
            },
        )
        raise ValueError("规划稿未通过设定和分段检查，尚未生成正文")

    @staticmethod
    def _planning_adaptation_contracts(
        state: dict, formal_outline_events: list[dict],
    ) -> list[dict]:
        outline = state.get("outline") if isinstance(state, dict) else {}
        outline = outline if isinstance(outline, dict) else {}
        outline_content = str(outline.get("content") or "")
        contracts = (
            narrative_outline_event_contracts(outline_content)
            if outline_content.strip() else []
        )
        if contracts:
            return contracts
        return [
            dict(item) for item in narrative_outline_events(formal_outline_events)
            if isinstance(item, dict) and str(item.get("id") or "").strip()
        ]

    @staticmethod
    def _stored_planning_adaptation_payloads(
        run_path: Path, *, segment: int | None = None, whole: bool = False,
    ) -> list[tuple[dict, str]]:
        """Return prior receipt payloads without trusting their old verdict."""
        outputs = run_path / "outputs"
        payloads: list[tuple[dict, str]] = []
        artifact_path = outputs / "planning-adaptations.json"
        try:
            artifact = json.loads(artifact_path.read_text(encoding="utf-8"))
        except (OSError, UnicodeError, json.JSONDecodeError):
            artifact = None
        if isinstance(artifact, dict):
            if whole:
                receipt = artifact.get("whole_story_receipt")
                if isinstance(receipt, dict) and receipt:
                    payloads.append((receipt, artifact_path.name))
            else:
                for receipt in artifact.get("segments", []):
                    if not isinstance(receipt, dict):
                        continue
                    try:
                        receipt_segment = int(receipt.get("segment") or 0)
                    except (TypeError, ValueError):
                        continue
                    if receipt_segment == segment:
                        payloads.append((receipt, artifact_path.name))
        pattern = (
            "review-plan-adaptation-whole-*.md"
            if whole else
            f"review-plan-adaptation-segment-{int(segment or 0):02d}-*.md"
        )
        try:
            paths = sorted(
                outputs.glob(pattern),
                key=lambda path: (path.stat().st_mtime_ns, path.name),
                reverse=True,
            )
        except OSError:
            paths = []
        for path in paths:
            try:
                raw = path.read_text(encoding="utf-8")
                payload = parse_json_object(
                    raw, label=f"Stored planning adaptation receipt {path.name}",
                )
            except (OSError, UnicodeError, TypeError, ValueError, json.JSONDecodeError):
                continue
            payloads.append((payload, path.name))
        return payloads

    def _resumable_current_planning_adaptation_plan(
        self, run_path: Path, project: Project, state: dict,
        segment_count: int, generation_context_sha256: str,
    ) -> tuple[str, dict | None, bool] | None:
        """Reuse the best hash-bound plan from this or a prior failed task."""
        outline_content = str(((state.get("outline") or {}).get("content")) or "")
        outline_sha256 = hashlib.sha256(outline_content.encode("utf-8")).hexdigest()
        candidates = [run_path / "outputs"]
        for run in self.db.list_runs(project.id):
            if run.get("id") == run_path.name or run.get("workflow") != "short-story" \
                    or run.get("status") not in {"failed", "cancelled"}:
                continue
            candidates.append(project.path / "runs" / run["id"] / "outputs")
        for outputs in candidates:
            recovered = read_planning_recovery(outputs)
            if recovered is not None:
                recovery_state, plan = recovered
                if planning_recovery_state_matches(
                    recovery_state,
                    outline_sha256=outline_sha256,
                    generation_context_sha256=generation_context_sha256,
                    segment_count=segment_count,
                ):
                    current_outputs = run_path / "outputs"
                    if outputs != current_outputs:
                        write_planning_recovery(
                            current_outputs, recovery_state, plan,
                        )
                    return plan, None, False

            artifact_path = outputs / "planning-adaptations.json"
            planning_path = outputs / "planning.md"
            try:
                artifact = json.loads(artifact_path.read_text(encoding="utf-8"))
                raw_plan = planning_path.read_text(encoding="utf-8")
            except (OSError, UnicodeError, json.JSONDecodeError):
                continue
            if not isinstance(artifact, dict) or artifact.get("status") != "failed" \
                    or artifact.get("version") not in \
                    SUPPORTED_PLANNING_ADAPTATION_VERSIONS \
                    or artifact.get("segment_count") != segment_count:
                continue
            stored_context = str(artifact.get("generation_context_sha256") or "")
            if artifact.get("version") in {
                PREVIOUS_PLANNING_ADAPTATION_VERSION,
                PLANNING_ADAPTATION_VERSION,
            } \
                    and stored_context != generation_context_sha256:
                continue
            if artifact.get("version") == LEGACY_PLANNING_ADAPTATION_VERSION \
                    and stored_context and stored_context != generation_context_sha256:
                continue
            try:
                plan, causal_chain = extract_short_causal_chain(raw_plan)
            except (TypeError, ValueError, json.JSONDecodeError):
                continue
            targeted = self._legacy_targeted_planning_candidate(
                outputs, project, state, plan, segment_count,
            )
            if targeted is not None:
                plan = targeted
                causal_chain = None
            if (
                artifact.get("outline_sha256") != outline_sha256
                or self._short_plan_issues(project, state, plan, segment_count)
            ):
                continue
            if targeted is None and artifact.get("planning_sha256") \
                    != hashlib.sha256(plan.encode("utf-8")).hexdigest():
                continue
            return plan, causal_chain, not bool(stored_context)
        return None

    def _legacy_targeted_planning_candidate(
        self, outputs: Path, project: Project, state: dict, plan: str,
        segment_count: int,
    ) -> str | None:
        """Reconstruct a pre-v2 targeted candidate as untrusted recovery input."""
        replacements: dict[int, str] = {}
        for path in sorted(outputs.glob("planning-adaptation-segment-*.md")):
            match = re.fullmatch(
                r"planning-adaptation-segment-(\d{2})\.md", path.name,
            )
            if not match:
                continue
            segment = int(match.group(1))
            try:
                value = path.read_text(encoding="utf-8")
            except (OSError, UnicodeError):
                continue
            blocks = self._short_plan_segments_for_range(value, segment, segment)
            if len(blocks) == 1:
                replacements[segment] = blocks[0]
        if not replacements:
            return None
        candidate = plan
        try:
            for segment, block in sorted(replacements.items()):
                candidate = self._replace_short_plan_segment(
                    candidate, segment_count, segment, block,
                )
        except ValueError:
            return None
        if self._short_plan_issues(project, state, candidate, segment_count):
            return None
        return candidate

    def _revalidate_stored_planning_adaptation_segment(
        self, run_path: Path, *, authority_sha256: str,
        planning_sha256: str, segment: int, expected_event_ids: list[str],
        evidence_candidates: dict[str, str],
        authority_version: int = PLANNING_ADAPTATION_VERSION,
        authority_event_ids: list[str] | None = None,
    ) -> tuple[dict, list[dict], str] | None:
        for payload, source in self._stored_planning_adaptation_payloads(
            run_path, segment=segment,
        ):
            normalized = normalize_planning_adaptation_receipt(
                payload, evidence_candidates=evidence_candidates,
            )
            issues = planning_adaptation_receipt_issues(
                normalized,
                authority_sha256=authority_sha256,
                planning_sha256=planning_sha256,
                segment=segment,
                expected_event_ids=expected_event_ids,
                evidence_candidates=evidence_candidates,
                authority_version=authority_version,
                authority_event_ids=authority_event_ids,
            )
            if any(
                str(item.get("code") or "") == "adaptation_receipt_conflict"
                for item in issues
            ):
                # A current-authority contradiction requires a fresh semantic
                # adjudication. Do not search backward for a more convenient
                # historical verdict about the same immutable plan.
                return None
            if not any(
                str(item.get("code") or "") in PLANNING_ADAPTATION_PROTOCOL_CODES
                for item in issues
            ):
                rebound = dict(normalized)
                previous_planning_sha256 = str(
                    rebound.get("planning_sha256") or ""
                )
                if (
                    authority_version >= PREVIOUS_PLANNING_ADAPTATION_VERSION
                    and previous_planning_sha256 != planning_sha256
                ):
                    rebound["revalidated_from_planning_sha256"] = (
                        previous_planning_sha256
                    )
                    rebound["planning_sha256"] = planning_sha256
                rebound["authority_version"] = authority_version
                return rebound, issues, source
        return None

    def _revalidate_stored_planning_adaptation_whole(
        self, run_path: Path, *, authority_sha256: str,
        planning_sha256: str, segment_count: int,
        expected_event_ids: list[str],
        authority_version: int = PLANNING_ADAPTATION_VERSION,
    ) -> tuple[dict, list[dict], str] | None:
        for payload, source in self._stored_planning_adaptation_payloads(
            run_path, whole=True,
        ):
            normalized = normalize_planning_adaptation_whole_receipt(payload)
            issues = planning_adaptation_whole_receipt_issues(
                normalized,
                authority_sha256=authority_sha256,
                planning_sha256=planning_sha256,
                segment_count=segment_count,
                expected_event_ids=expected_event_ids,
            )
            if not any(
                str(item.get("code") or "") in PLANNING_ADAPTATION_PROTOCOL_CODES
                for item in issues
            ):
                return dict(normalized), issues, source
        return None

    async def _review_short_plan_adaptation_segment(
        self, run_id: str, run_path: Path, project: Project, constraints: str,
        *, outline_sha256: str, planning_sha256: str, segment: int,
        event_contracts: list[dict], plan_segment: str, suffix: str,
        previous_handoff: str = "", next_entry: str = "",
        generation_context_sha256: str = "",
        authority_version: int = PLANNING_ADAPTATION_VERSION,
        authority_event_ids: list[str] | None = None,
        _capacity_split: bool = True,
        _authority_override: str | None = None,
        _prompt_plan_segment: str | None = None,
        _prompt_evidence_candidates: dict[str, str] | None = None,
        _story_skeleton_override: str | None = None,
    ) -> tuple[dict, list[dict], int]:
        event_ids = [str(item.get("id") or "").strip().upper() for item in event_contracts]
        candidates = planning_adaptation_evidence_candidates(plan_segment, segment)
        prompt_plan_segment = (
            _prompt_plan_segment
            if _prompt_plan_segment is not None else plan_segment
        )
        prompt_candidates = (
            dict(_prompt_evidence_candidates)
            if _prompt_evidence_candidates is not None else candidates
        )
        computed_authority_sha256 = planning_adaptation_segment_authority_sha256(
            outline_sha256=outline_sha256,
            planning_sha256=planning_sha256,
            segment=segment,
            event_contracts=event_contracts,
            plan_segment=plan_segment,
            previous_handoff=previous_handoff,
            next_entry=next_entry,
            generation_context_sha256=generation_context_sha256,
            version=authority_version,
        )
        authority_sha256 = _authority_override or computed_authority_sha256
        stored = self._revalidate_stored_planning_adaptation_segment(
            run_path,
            authority_sha256=authority_sha256,
            planning_sha256=planning_sha256,
            segment=segment,
            expected_event_ids=event_ids,
            evidence_candidates=candidates,
            authority_version=authority_version,
            authority_event_ids=authority_event_ids,
        )
        if stored is not None:
            receipt, issues, source = stored
            receipt = dict(receipt)
            receipt["segment_sha256"] = hashlib.sha256(
                plan_segment.encode("utf-8"),
            ).hexdigest()
            receipt["boundary_sha256"] = hashlib.sha256(json.dumps({
                "previous_handoff": previous_handoff,
                "next_entry": next_entry,
            }, ensure_ascii=False, sort_keys=True, separators=(",", ":")).encode(
                "utf-8",
            )).hexdigest()
            self.db.add_run_event(
                run_id, "info", "planning_adaptation_receipt_revalidated",
                "已有规划适配回执已按当前不变量规则完成本地重新验收",
                stage="review", metadata={
                    "segment": segment, "source": source, "issues": issues,
                },
            )
            return receipt, issues, 0
        last_issues: list[dict] = []
        protocol_retries = 0
        attempt_plan = self._protocol_receipt_attempt_plan(
            "review", same_route_attempts=3,
        )
        for attempt in attempt_plan:
            if attempt.use_configured_fallback:
                self._record_protocol_receipt_fallback(
                    run_id, stage="review",
                    boundary="planning_adaptation_segment",
                    unit_metadata={
                        "segment": segment,
                        "event_count": len(event_ids),
                        "authority_sha256": authority_sha256,
                    },
                    issues=last_issues,
                )
            prompt = (
                "SHORT_PLAN_ADAPTATION_REVIEW_V2\n"
                "只审核当前正式写作段，判断规划对正式大纲的实现是否属于允许的等价展开。"
                "不要要求逐字照搬，也不能以更好写、更有戏剧性为理由改变剧情功能。\n"
                "classification 建议使用 unchanged、equivalent 或 structural，但它只用于诊断；"
                "changed_dimensions 可以使用准确、简短的自然语言名称，不必猜固定词表。"
                "Runtime 最终只依据逐项不变量、原文证据、事件覆盖和顺序作出授权。"
                "presentation 只允许对话、描写、过渡、次要动作、次要道具和场景表现变化；"
                "equivalent 还允许触发方式、次要参与者、局部地点、证据取得方式和不影响依赖的局部顺序变化。"
                "任何主要执行者主动性、事件功能、因果依赖、入口/出口状态、知情状态、关系状态、"
                "视角、依赖性时间顺序、伏笔或结局变化都必须判为 structural。\n"
                "每个事件必须逐项返回 invariants：event_function、primary_actor_agency、"
                "causal_dependencies、entry_state、exit_state、knowledge_state、relationship_state、"
                "viewpoint、timeline_order、promise_ending。允许的分类中这些值必须全部为 true。\n"
                "若 timeline_order 为 false，必须额外返回 order_dependency（hard、soft 或 unknown）"
                "和 dependency_event_ids；soft 表示仅展示顺序变化，hard 必须绑定形成依赖的事件 ID。\n"
                "segment_order_preserved 只判断正式事件及其依赖顺序，不把同一事件内部的非依赖展示顺序变化判为 false。\n"
                "只返回一个 JSON 对象，字段为 authority_sha256、planning_sha256、authority_version、segment、"
                "event_reviews、segment_order_preserved、formal_direction_preserved、summary。"
                "event_reviews 每项包含 event_id、classification、changed_dimensions、invariants、"
                "plan_evidence_ids、plan_evidence_quote、reason。plan_evidence_ids 只能从 Runtime 候选中选择，"
                "不得复述、拼接或改写规划原文。\n"
                "NEGATIVE-EVIDENCE RULE: whenever any invariant is false, "
                "plan_evidence_quote must copy one exact problem phrase of at least six "
                "semantic characters from the selected current-plan evidence, and reason "
                "must include that exact phrase. A finding from an older or rejected plan "
                "is a receipt defect, not current semantic drift.\n"
                "UNKNOWN-AUTHORITY RULE: an empty actor, viewpoint, location, time, "
                "knowledge, or relationship field is unknown, not a second canonical fact. "
                "Judge only whether the plan contradicts explicit formal evidence; do not "
                "invent missing facts merely to produce a verdict.\n"
                "ROLE-SEPARATION RULE: executor, intermediary, investigator, witness, and "
                "hidden principal remain distinct unless the formal contract explicitly "
                "identifies them as the same entity.\n"
                "FUTURE-OWNERSHIP RULE: an earlier event must not complete a reveal, decision, "
                "confrontation, or state change assigned to a later formal event.\n"
                f"EXPECTED AUTHORITY SHA256: {authority_sha256}\n"
                f"EXPECTED PLANNING SHA256: {planning_sha256}\n"
                f"EXPECTED AUTHORITY VERSION: {authority_version}\n"
                f"CURRENT SEGMENT: {segment}\n"
                "EXPECTED EVENT IDS:\n"
                + json.dumps(event_ids, ensure_ascii=False)
                + "\n\nALLOWED DEPENDENCY EVENT IDS:\n"
                + json.dumps(authority_event_ids or event_ids, ensure_ascii=False)
                + "\n\nFORMAL EVENT CONTRACTS:\n"
                + json.dumps(event_contracts, ensure_ascii=False, indent=2)
                + "\n\nCURRENT ACCEPTED PLAN SEGMENT:\n" + prompt_plan_segment
                + "\n\nPREVIOUS ACCEPTED HANDOFF:\n" + previous_handoff
                + "\n\nNEXT SEGMENT ENTRY:\n" + next_entry
                + "\n\nPLAN EVIDENCE CANDIDATES:\n"
                + json.dumps(prompt_candidates, ensure_ascii=False, indent=2)
            )
            if last_issues:
                prompt += (
                    "\n\nRECEIPT PROTOCOL ISSUES:\n"
                    + json.dumps(last_issues, ensure_ascii=False, indent=2)
                    + "\n规划内容保持不变，只重新返回完整、准确绑定的审核回执。"
                )
            raw, route_failure = await self._execute_protocol_receipt_attempt(
                run_id, stage="review",
                boundary="planning_adaptation_segment",
                attempt=attempt,
                unit_metadata={
                    "segment": segment,
                    "event_count": len(event_ids),
                    "authority_sha256": authority_sha256,
                },
                operation=lambda: self._stage(
                run_id, run_path, project, "review", constraints, prompt,
                suffix=(
                    f"-plan-adaptation-segment-{segment:02d}-{suffix}-"
                    f"{attempt.attempt_index}"
                    + ("-fallback" if attempt.use_configured_fallback else "")
                ),
                allow_tools=False,
                prefer_configured_fallback=attempt.use_configured_fallback,
                primary_only=not attempt.use_configured_fallback,
                defer_route_failure_audit=True,
                protocol_system_contract=IMMUTABLE_RECEIPT_SYSTEM,
                expected_output_characters=max(1200, 520 * len(event_contracts)),
                completion_check=lambda value: (
                    self._planning_adaptation_segment_receipt_complete(
                        value,
                        authority_sha256=authority_sha256,
                        planning_sha256=planning_sha256,
                        authority_version=authority_version,
                        segment=segment,
                        expected_event_ids=event_ids,
                        evidence_candidates=candidates,
                        authority_event_ids=authority_event_ids,
                        plan_segment=plan_segment,
                        previous_handoff=previous_handoff,
                        next_entry=next_entry,
                    )
                ),
                route_capacity_guard=True,
                story_skeleton_override=_story_skeleton_override,
                bounded_protocol_output=True,
                capacity_splitter=(
                    (lambda details: self._review_short_plan_adaptation_capacity_split(
                        run_id, run_path, project, constraints,
                        outline_sha256=outline_sha256,
                        planning_sha256=planning_sha256,
                        segment=segment,
                        event_contracts=event_contracts,
                        plan_segment=plan_segment,
                        suffix=suffix,
                        previous_handoff=previous_handoff,
                        next_entry=next_entry,
                        generation_context_sha256=generation_context_sha256,
                        authority_version=authority_version,
                        authority_event_ids=authority_event_ids,
                        segment_authority_sha256=computed_authority_sha256,
                        details=details,
                    ))
                    if _capacity_split else None
                ),
                ),
            )
            if route_failure is not None:
                last_issues = [{
                    "code": route_failure.code,
                    "failure_class": route_failure.failure_class.value,
                }]
                if not attempt.is_last:
                    protocol_retries += 1
                    continue
                raise ProtocolReceiptRouteExhaustedError(route_failure)
            try:
                payload = self._convert_generated_object(
                    raw, run_path,
                    contract_name="planning_adaptation_segment",
                )
            except (TypeError, ValueError, json.JSONDecodeError) as exc:
                receipt: object = {}
                last_issues = [{
                    "code": "receipt_schema", "message": str(exc)[:500],
                }]
            else:
                receipt = normalize_planning_adaptation_receipt(
                    payload, evidence_candidates=candidates,
                )
                if isinstance(receipt, dict):
                    receipt["authority_version"] = authority_version
                    receipt["segment_sha256"] = hashlib.sha256(
                        plan_segment.encode("utf-8"),
                    ).hexdigest()
                    receipt["boundary_sha256"] = hashlib.sha256(json.dumps({
                        "previous_handoff": previous_handoff,
                        "next_entry": next_entry,
                    }, ensure_ascii=False, sort_keys=True, separators=(",", ":")).encode(
                        "utf-8",
                    )).hexdigest()
                last_issues = planning_adaptation_receipt_issues(
                    receipt,
                    authority_sha256=authority_sha256,
                    planning_sha256=planning_sha256,
                    segment=segment,
                    expected_event_ids=event_ids,
                    evidence_candidates=candidates,
                    authority_version=authority_version,
                    authority_event_ids=authority_event_ids,
                    plan_segment=plan_segment,
                )
                protocol_issues = [
                    item for item in last_issues
                    if str(item.get("code") or "") in PLANNING_ADAPTATION_PROTOCOL_CODES
                ]
                if not protocol_issues:
                    capacity_metadata = (
                        receipt.get("capacity_split")
                        if isinstance(receipt, dict) else None
                    )
                    packet_retry_count = (
                        capacity_metadata.get("protocol_retries")
                        if isinstance(capacity_metadata, dict) else None
                    )
                    if (
                        isinstance(raw, StageText)
                        and raw.receipt.get("execution_mode") == "capacity_split"
                        and isinstance(packet_retry_count, int)
                        and packet_retry_count >= 0
                    ):
                        protocol_retries += packet_retry_count
                    return dict(receipt), last_issues, protocol_retries
                last_issues = protocol_issues
            if not attempt.is_last:
                protocol_retries += 1
                self.db.add_run_event(
                    run_id, "info", "planning_adaptation_receipt_retry",
                    "规划内容保持不变，正在重新获取等价展开审核回执",
                    stage="review", metadata={
                        "segment": segment,
                        "attempt": attempt.attempt_index,
                        "route": attempt.route,
                        "next_route": attempt_plan[
                            attempt.attempt_index
                        ].route,
                        "issues": last_issues,
                    },
                )
                continue
            break
        return {}, last_issues, protocol_retries

    @staticmethod
    def _planning_adaptation_packet_checkpoint_path(
        run_path: Path, *, segment: int, packet_authority_sha256: str,
    ) -> Path:
        return (
            run_path / "outputs" / "pap"
            / f"segment-{segment:02d}-{packet_authority_sha256[:24]}.json"
        )

    @classmethod
    def _save_planning_adaptation_packet_checkpoint(
        cls, run_path: Path, *, segment_authority_sha256: str,
        packet_authority_sha256: str, segment: int,
        event_ids: list[str], receipt: dict,
    ) -> None:
        canonical = json.dumps(
            receipt, ensure_ascii=False, sort_keys=True, separators=(",", ":"),
        )
        atomic_write(
            cls._planning_adaptation_packet_checkpoint_path(
                run_path,
                segment=segment,
                packet_authority_sha256=packet_authority_sha256,
            ),
            json.dumps({
                "version": 1,
                "segment_authority_sha256": segment_authority_sha256,
                "packet_authority_sha256": packet_authority_sha256,
                "segment": segment,
                "event_ids": event_ids,
                "receipt_sha256": hashlib.sha256(
                    canonical.encode("utf-8"),
                ).hexdigest(),
                "receipt": receipt,
            }, ensure_ascii=False, indent=2, sort_keys=True),
        )

    def _load_planning_adaptation_packet_checkpoint(
        self, run_id: str, run_path: Path, project: Project, *,
        segment_authority_sha256: str, packet_authority_sha256: str,
        planning_sha256: str, authority_version: int, segment: int,
        event_ids: list[str], evidence_candidates: dict[str, str],
        authority_event_ids: list[str] | None,
    ) -> tuple[dict, list[dict]] | None:
        candidates: dict[str, tuple[dict, Path, list[dict]]] = {}
        for path in project.path.glob("runs/*/outputs/pap/*.json"):
            try:
                envelope = json.loads(path.read_text(encoding="utf-8"))
                if (
                    not isinstance(envelope, dict)
                    or envelope.get("version") != 1
                    or envelope.get("segment_authority_sha256")
                    != segment_authority_sha256
                    or envelope.get("packet_authority_sha256")
                    != packet_authority_sha256
                    or envelope.get("segment") != segment
                    or envelope.get("event_ids") != event_ids
                ):
                    continue
                raw_receipt = envelope.get("receipt")
                canonical = json.dumps(
                    raw_receipt, ensure_ascii=False, sort_keys=True,
                    separators=(",", ":"),
                )
                if envelope.get("receipt_sha256") != hashlib.sha256(
                    canonical.encode("utf-8"),
                ).hexdigest():
                    continue
                receipt = normalize_planning_adaptation_receipt(
                    raw_receipt, evidence_candidates=evidence_candidates,
                )
                if not isinstance(receipt, dict):
                    continue
                receipt["authority_version"] = authority_version
                issues = planning_adaptation_receipt_issues(
                    receipt,
                    authority_sha256=packet_authority_sha256,
                    planning_sha256=planning_sha256,
                    segment=segment,
                    expected_event_ids=event_ids,
                    evidence_candidates=evidence_candidates,
                    authority_version=authority_version,
                    authority_event_ids=authority_event_ids,
                )
                if any(
                    str(item.get("code") or "")
                    in PLANNING_ADAPTATION_PROTOCOL_CODES
                    for item in issues
                ):
                    continue
            except (OSError, UnicodeError, TypeError, ValueError, json.JSONDecodeError):
                continue
            digest = hashlib.sha256(canonical.encode("utf-8")).hexdigest()
            candidates.setdefault(digest, (receipt, path, issues))
        if len(candidates) > 1:
            self.db.add_run_event(
                run_id, "warning", "planning_adaptation_packet_checkpoint_ambiguous",
                "同一规划审核分包发现多份冲突回执，已放弃复用并重新审核",
                stage="review", metadata={
                    "segment": segment,
                    "event_ids": event_ids,
                    "candidate_count": len(candidates),
                },
            )
            return None
        if not candidates:
            return None
        receipt, source_path, issues = next(iter(candidates.values()))
        self._save_planning_adaptation_packet_checkpoint(
            run_path,
            segment_authority_sha256=segment_authority_sha256,
            packet_authority_sha256=packet_authority_sha256,
            segment=segment,
            event_ids=event_ids,
            receipt=receipt,
        )
        try:
            source_run = source_path.relative_to(project.path / "runs").parts[0]
        except (ValueError, IndexError):
            source_run = "unknown"
        self.db.add_run_event(
            run_id, "info", "planning_adaptation_packet_checkpoint_reused",
            "已复用哈希一致的规划事件审核分包，仅继续未完成范围",
            stage="review", metadata={
                "segment": segment,
                "event_ids": event_ids,
                "source_run": source_run,
            },
        )
        return receipt, issues

    @staticmethod
    def _planning_adaptation_facet_checkpoint_path(
        run_path: Path, *, segment: int, event_id: str, facet: str,
        facet_authority_sha256: str,
    ) -> Path:
        safe_event = re.sub(r"[^A-Z0-9_-]+", "-", event_id.upper()).strip("-")
        return (
            run_path / "outputs" / "pap"
            / f"facet-{segment:02d}-{safe_event}-{facet}-{facet_authority_sha256[:16]}.json"
        )

    @classmethod
    def _save_planning_adaptation_facet_checkpoint(
        cls, run_path: Path, *, packet_authority_sha256: str,
        facet_authority_sha256: str, segment: int, event_id: str,
        facet: str, invariant_fields: Sequence[str], receipt: dict,
    ) -> None:
        canonical = json.dumps(
            receipt, ensure_ascii=False, sort_keys=True, separators=(",", ":"),
        )
        atomic_write(
            cls._planning_adaptation_facet_checkpoint_path(
                run_path, segment=segment, event_id=event_id, facet=facet,
                facet_authority_sha256=facet_authority_sha256,
            ),
            json.dumps({
                "version": 1,
                "packet_authority_sha256": packet_authority_sha256,
                "facet_authority_sha256": facet_authority_sha256,
                "segment": segment,
                "event_id": event_id,
                "facet": facet,
                "invariant_fields": list(invariant_fields),
                "receipt": receipt,
                "receipt_sha256": hashlib.sha256(
                    canonical.encode("utf-8"),
                ).hexdigest(),
            }, ensure_ascii=False, indent=2),
        )

    @staticmethod
    def _planning_adaptation_facet_semantic_issues(
        value: object, *, invariant_fields: Sequence[str],
        evidence_candidates: dict[str, str],
    ) -> list[str]:
        """Validate only model-owned facet verdict fields.

        Request identity is owned by Runtime and is bound separately.  Keeping
        that envelope out of semantic validation prevents a model typo in a
        digest or range from being mistaken for narrative drift, while exact
        evidence IDs and negative quotes still bind the verdict to the current
        immutable plan scope.
        """
        if not isinstance(value, dict):
            return ["receipt_schema"]
        issues: list[str] = []
        invariants = value.get("invariants")
        if not isinstance(invariants, dict) or set(invariants) != set(
            invariant_fields,
        ) or any(
            not isinstance(invariants.get(field), bool)
            for field in invariant_fields
        ):
            issues.append("invariant_shape")
        evidence_ids = value.get("plan_evidence_ids")
        if not isinstance(evidence_ids, list) or not evidence_ids:
            issues.append("evidence_ids_missing")
        elif any(str(item) not in evidence_candidates for item in evidence_ids):
            issues.append("evidence_ids_out_of_scope")
        reason = value.get("reason")
        if not isinstance(reason, str) or not reason.strip():
            issues.append("reason_missing")
        if not issues and not planning_evidence_quote_valid(
            value, evidence_candidates,
        ):
            issues.append("evidence_quote_unbound")
        return issues

    def _converted_planning_adaptation_facet_semantic_issues(
        self, value: str, run_path: Path, *,
        invariant_fields: Sequence[str],
        evidence_candidates: dict[str, str],
    ) -> list[str]:
        """Run transport conversion and registered adapters before preflight."""

        converted = self._convert_generated_object(
            value, run_path,
            contract_name="planning_adaptation_facet",
        )
        adaptation = adapt_registered_contract(
            converted,
            contract_name="planning_adaptation_facet",
            context={
                "invariant_fields": tuple(invariant_fields),
                "evidence_candidates": evidence_candidates,
            },
        )
        return self._planning_adaptation_facet_semantic_issues(
            adaptation.payload,
            invariant_fields=invariant_fields,
            evidence_candidates=evidence_candidates,
        )

    @staticmethod
    def _reconcile_planning_adaptation_dimension_roles(
        dimensions: Sequence[object], *, invariants: dict[str, bool],
    ) -> tuple[list[str], list[str]]:
        """Separate narrative dimensions from authority deviations.

        Facet providers use ``changed_dimensions`` both for dimensions that
        progress inside the story and for differences from formal authority.
        Only the complete invariant map can distinguish those roles.  A known
        protected dimension whose invariant is true is therefore retained as
        reviewed-scope audit rather than a deviation.  Free-form dimensions
        and dimensions with a false invariant remain effective changes.
        """

        def protocol_key(value: object) -> str:
            normalized = unicodedata.normalize(
                "NFKC", str(value or ""),
            ).strip().casefold()
            return re.sub(r"[\s\-—_/\\:：]+", "_", normalized).strip("_")

        effective: list[str] = []
        reviewed: list[str] = []
        invariant_keys = {protocol_key(field): field for field in invariants}
        for value in dimensions:
            text = unicodedata.normalize("NFKC", str(value or "")).strip()
            if not text:
                continue
            field = invariant_keys.get(protocol_key(text))
            target = (
                reviewed
                if field is not None and invariants.get(field) is True
                else effective
            )
            if text not in target:
                target.append(text)
        return effective, reviewed

    @classmethod
    def _bind_current_planning_adaptation_facet_receipt(
        cls, value: object, *, expected_identity: dict[str, object],
        invariant_fields: Sequence[str],
        evidence_candidates: dict[str, str],
    ) -> tuple[dict | None, list[str], list[str], list[str], list[dict]]:
        """Wrap a fresh model verdict in a Runtime-owned identity envelope.

        This function is intentionally for the direct response to the current
        call.  Persisted checkpoints never pass through it and must continue to
        match every stored digest and range byte-for-byte.
        """
        if isinstance(value, dict):
            adaptation = adapt_registered_contract(
                value,
                contract_name="planning_adaptation_facet",
                context={
                    "invariant_fields": tuple(invariant_fields),
                    "evidence_candidates": evidence_candidates,
                },
            )
            normalized: object = adaptation.payload
            adapter_audits = [
                audit.model_dump(mode="json") for audit in adaptation.audits
            ]
            semantic_repairs = [
                transformation
                for audit in adaptation.audits
                for transformation in audit.transformations
            ]
        else:
            normalized = value
            adapter_audits = []
            semantic_repairs = []
        issues = cls._planning_adaptation_facet_semantic_issues(
            normalized,
            invariant_fields=invariant_fields,
            evidence_candidates=evidence_candidates,
        )
        if issues or not isinstance(normalized, dict):
            return None, issues, [], semantic_repairs, adapter_audits
        bound = dict(normalized)
        rebound_fields = [
            field for field, expected in expected_identity.items()
            if bound.get(field) != expected
        ]
        bound.update(expected_identity)
        return bound, [], rebound_fields, semantic_repairs, adapter_audits

    @classmethod
    def _planning_adaptation_facet_receipt_valid(
        cls, value: object, *, facet_authority_sha256: str,
        planning_sha256: str, authority_version: int, segment: int,
        event_id: str, facet: str, invariant_fields: Sequence[str],
        evidence_candidates: dict[str, str],
    ) -> bool:
        if not isinstance(value, dict):
            return False
        try:
            returned_segment = int(value.get("segment"))
            returned_version = int(value.get("authority_version"))
        except (TypeError, ValueError):
            return False
        if (
            value.get("authority_sha256") != facet_authority_sha256
            or value.get("planning_sha256") != planning_sha256
            or returned_version != authority_version
            or returned_segment != segment
            or str(value.get("event_id") or "").strip().upper() != event_id
            or str(value.get("facet") or "").strip() != facet
        ):
            return False
        return not cls._planning_adaptation_facet_semantic_issues(
            value,
            invariant_fields=invariant_fields,
            evidence_candidates=evidence_candidates,
        )

    def _load_planning_adaptation_facet_checkpoint(
        self, run_id: str, run_path: Path, project: Project, *,
        packet_authority_sha256: str, facet_authority_sha256: str,
        planning_sha256: str, authority_version: int, segment: int,
        event_id: str, facet: str, invariant_fields: Sequence[str],
        evidence_candidates: dict[str, str],
    ) -> dict | None:
        candidates: dict[str, tuple[dict, Path, list[str], str]] = {}
        for path in project.path.glob("runs/*/outputs/pap/facet-*.json"):
            try:
                envelope = json.loads(path.read_text(encoding="utf-8"))
                raw_receipt = (
                    envelope.get("receipt") if isinstance(envelope, dict) else None
                )
                raw_canonical = json.dumps(
                    raw_receipt, ensure_ascii=False, sort_keys=True,
                    separators=(",", ":"),
                )
                adaptation = adapt_registered_contract(
                    raw_receipt,
                    contract_name="planning_adaptation_facet",
                    context={
                        "invariant_fields": tuple(invariant_fields),
                        "evidence_candidates": evidence_candidates,
                    },
                ) if isinstance(raw_receipt, dict) else None
                receipt = (
                    adaptation.payload if adaptation is not None else raw_receipt
                )
                semantic_repairs = (
                    [
                        transformation
                        for audit in adaptation.audits
                        for transformation in audit.transformations
                    ]
                    if adaptation is not None else []
                )
                canonical = json.dumps(
                    receipt, ensure_ascii=False, sort_keys=True,
                    separators=(",", ":"),
                )
                if (
                    not isinstance(envelope, dict)
                    or envelope.get("version") != 1
                    or envelope.get("packet_authority_sha256") != packet_authority_sha256
                    or envelope.get("facet_authority_sha256") != facet_authority_sha256
                    or envelope.get("segment") != segment
                    or envelope.get("event_id") != event_id
                    or envelope.get("facet") != facet
                    or envelope.get("invariant_fields") != list(invariant_fields)
                    or envelope.get("receipt_sha256") != hashlib.sha256(
                        raw_canonical.encode("utf-8"),
                    ).hexdigest()
                    or not self._planning_adaptation_facet_receipt_valid(
                        receipt,
                        facet_authority_sha256=facet_authority_sha256,
                        planning_sha256=planning_sha256,
                        authority_version=authority_version,
                        segment=segment,
                        event_id=event_id,
                        facet=facet,
                        invariant_fields=invariant_fields,
                        evidence_candidates=evidence_candidates,
                    )
                ):
                    continue
            except (OSError, UnicodeError, TypeError, ValueError, json.JSONDecodeError):
                continue
            digest = hashlib.sha256(canonical.encode("utf-8")).hexdigest()
            candidates.setdefault(digest, (
                dict(receipt), path, semantic_repairs,
                hashlib.sha256(raw_canonical.encode("utf-8")).hexdigest(),
            ))
        if len(candidates) != 1:
            if len(candidates) > 1:
                self.db.add_run_event(
                    run_id, "warning", "planning_adaptation_facet_checkpoint_ambiguous",
                    "同一单事件审核维度发现冲突检查点，已放弃复用并重新审核",
                    stage="review", metadata={
                        "segment": segment, "event_id": event_id,
                        "facet": facet, "candidate_count": len(candidates),
                    },
                )
            return None
        receipt, source_path, semantic_repairs, source_receipt_sha256 = next(
            iter(candidates.values())
        )
        self._save_planning_adaptation_facet_checkpoint(
            run_path,
            packet_authority_sha256=packet_authority_sha256,
            facet_authority_sha256=facet_authority_sha256,
            segment=segment,
            event_id=event_id,
            facet=facet,
            invariant_fields=invariant_fields,
            receipt=receipt,
        )
        if semantic_repairs:
            self.db.add_run_event(
                run_id, "info",
                "planning_adaptation_checkpoint_protocol_normalized",
                "哈希完整的单事件审核检查点已完成确定性协议归一化",
                stage="review", metadata={
                    "segment": segment, "event_id": event_id, "facet": facet,
                    "semantic_repairs": semantic_repairs,
                    "source_receipt_sha256": source_receipt_sha256,
                    "receipt_sha256": hashlib.sha256(json.dumps(
                        receipt, ensure_ascii=False, sort_keys=True,
                        separators=(",", ":"),
                    ).encode("utf-8")).hexdigest(),
                },
            )
        self.db.add_run_event(
            run_id, "info", "planning_adaptation_facet_checkpoint_reused",
            "已复用哈希匹配的单事件审核维度，只继续未完成维度",
            stage="review", metadata={
                "segment": segment, "event_id": event_id, "facet": facet,
                "source_run": source_path.relative_to(
                    project.path / "runs",
                ).parts[0],
            },
        )
        return receipt

    @staticmethod
    def _planning_adaptation_facet_window_authority_sha256(
        *, facet_authority_sha256: str, window_index: int,
        start: int, end: int, text_sha256: str,
    ) -> str:
        return hashlib.sha256(json.dumps({
            "facet_authority_sha256": facet_authority_sha256,
            "window_index": int(window_index),
            "start": int(start),
            "end": int(end),
            "text_sha256": text_sha256,
        }, ensure_ascii=False, sort_keys=True, separators=(",", ":")).encode(
            "utf-8",
        )).hexdigest()

    @staticmethod
    def _planning_adaptation_facet_window_checkpoint_path(
        run_path: Path, *, segment: int, event_id: str, facet: str,
        window_index: int, window_authority_sha256: str,
    ) -> Path:
        safe_event = re.sub(r"[^A-Z0-9_-]+", "-", event_id.upper()).strip("-")
        return (
            run_path / "outputs" / "pap"
            / (
                f"facet-window-{segment:02d}-{safe_event}-{facet}-"
                f"{window_index:03d}-{window_authority_sha256[:16]}.json"
            )
        )

    @classmethod
    def _save_planning_adaptation_facet_window_checkpoint(
        cls, run_path: Path, *, facet_authority_sha256: str,
        window_authority_sha256: str, segment: int, event_id: str,
        facet: str, window_index: int, start: int, end: int,
        text_sha256: str, invariant_fields: Sequence[str], receipt: dict,
    ) -> None:
        canonical = json.dumps(
            receipt, ensure_ascii=False, sort_keys=True, separators=(",", ":"),
        )
        atomic_write(
            cls._planning_adaptation_facet_window_checkpoint_path(
                run_path, segment=segment, event_id=event_id, facet=facet,
                window_index=window_index,
                window_authority_sha256=window_authority_sha256,
            ),
            json.dumps({
                "version": 1,
                "facet_authority_sha256": facet_authority_sha256,
                "window_authority_sha256": window_authority_sha256,
                "segment": segment,
                "event_id": event_id,
                "facet": facet,
                "window_index": window_index,
                "start": start,
                "end": end,
                "text_sha256": text_sha256,
                "invariant_fields": list(invariant_fields),
                "receipt": receipt,
                "receipt_sha256": hashlib.sha256(
                    canonical.encode("utf-8"),
                ).hexdigest(),
            }, ensure_ascii=False, indent=2),
        )

    @classmethod
    def _planning_adaptation_facet_window_receipt_valid(
        cls, value: object, *, window_authority_sha256: str,
        planning_sha256: str, authority_version: int, segment: int,
        event_id: str, facet: str, window_index: int, start: int, end: int,
        text_sha256: str, invariant_fields: Sequence[str],
        evidence_candidates: dict[str, str],
    ) -> bool:
        if not isinstance(value, dict):
            return False
        try:
            returned_version = int(value.get("authority_version"))
            returned_segment = int(value.get("segment"))
            returned_window = int(value.get("window_index"))
            returned_start = int(value.get("start"))
            returned_end = int(value.get("end"))
        except (TypeError, ValueError):
            return False
        if (
            value.get("authority_sha256") != window_authority_sha256
            or value.get("planning_sha256") != planning_sha256
            or returned_version != authority_version
            or returned_segment != segment
            or str(value.get("event_id") or "").strip().upper() != event_id
            or str(value.get("facet") or "").strip() != facet
            or returned_window != window_index
            or returned_start != start
            or returned_end != end
            or value.get("text_sha256") != text_sha256
        ):
            return False
        return not cls._planning_adaptation_facet_semantic_issues(
            value,
            invariant_fields=invariant_fields,
            evidence_candidates=evidence_candidates,
        )

    def _load_planning_adaptation_facet_window_checkpoint(
        self, run_id: str, run_path: Path, project: Project, *,
        facet_authority_sha256: str, window_authority_sha256: str,
        planning_sha256: str, authority_version: int, segment: int,
        event_id: str, facet: str, window_index: int, start: int, end: int,
        text_sha256: str, invariant_fields: Sequence[str],
        evidence_candidates: dict[str, str],
    ) -> dict | None:
        candidates: dict[str, tuple[dict, Path, list[str], str]] = {}
        for path in project.path.glob("runs/*/outputs/pap/facet-window-*.json"):
            try:
                envelope = json.loads(path.read_text(encoding="utf-8"))
                raw_receipt = (
                    envelope.get("receipt") if isinstance(envelope, dict) else None
                )
                raw_canonical = json.dumps(
                    raw_receipt, ensure_ascii=False, sort_keys=True,
                    separators=(",", ":"),
                )
                adaptation = adapt_registered_contract(
                    raw_receipt,
                    contract_name="planning_adaptation_facet",
                    context={
                        "invariant_fields": tuple(invariant_fields),
                        "evidence_candidates": evidence_candidates,
                    },
                ) if isinstance(raw_receipt, dict) else None
                receipt = (
                    adaptation.payload if adaptation is not None else raw_receipt
                )
                semantic_repairs = (
                    [
                        transformation
                        for audit in adaptation.audits
                        for transformation in audit.transformations
                    ]
                    if adaptation is not None else []
                )
                canonical = json.dumps(
                    receipt, ensure_ascii=False, sort_keys=True,
                    separators=(",", ":"),
                )
                if (
                    not isinstance(envelope, dict)
                    or envelope.get("version") != 1
                    or envelope.get("facet_authority_sha256")
                    != facet_authority_sha256
                    or envelope.get("window_authority_sha256")
                    != window_authority_sha256
                    or envelope.get("segment") != segment
                    or envelope.get("event_id") != event_id
                    or envelope.get("facet") != facet
                    or envelope.get("window_index") != window_index
                    or envelope.get("start") != start
                    or envelope.get("end") != end
                    or envelope.get("text_sha256") != text_sha256
                    or envelope.get("invariant_fields") != list(invariant_fields)
                    or envelope.get("receipt_sha256") != hashlib.sha256(
                        raw_canonical.encode("utf-8"),
                    ).hexdigest()
                    or not self._planning_adaptation_facet_window_receipt_valid(
                        receipt,
                        window_authority_sha256=window_authority_sha256,
                        planning_sha256=planning_sha256,
                        authority_version=authority_version,
                        segment=segment,
                        event_id=event_id,
                        facet=facet,
                        window_index=window_index,
                        start=start,
                        end=end,
                        text_sha256=text_sha256,
                        invariant_fields=invariant_fields,
                        evidence_candidates=evidence_candidates,
                    )
                ):
                    continue
            except (OSError, UnicodeError, TypeError, ValueError, json.JSONDecodeError):
                continue
            digest = hashlib.sha256(canonical.encode("utf-8")).hexdigest()
            candidates.setdefault(digest, (
                dict(receipt), path, semantic_repairs,
                hashlib.sha256(raw_canonical.encode("utf-8")).hexdigest(),
            ))
        if len(candidates) != 1:
            if len(candidates) > 1:
                self.db.add_run_event(
                    run_id, "warning",
                    "planning_adaptation_facet_window_checkpoint_ambiguous",
                    "同一单事件审核窗口发现冲突检查点，已放弃复用并重新审核",
                    stage="review", metadata={
                        "segment": segment, "event_id": event_id,
                        "facet": facet, "window": window_index,
                        "candidate_count": len(candidates),
                    },
                )
            return None
        receipt, source_path, semantic_repairs, source_receipt_sha256 = next(
            iter(candidates.values())
        )
        self._save_planning_adaptation_facet_window_checkpoint(
            run_path,
            facet_authority_sha256=facet_authority_sha256,
            window_authority_sha256=window_authority_sha256,
            segment=segment,
            event_id=event_id,
            facet=facet,
            window_index=window_index,
            start=start,
            end=end,
            text_sha256=text_sha256,
            invariant_fields=invariant_fields,
            receipt=receipt,
        )
        if semantic_repairs:
            self.db.add_run_event(
                run_id, "info",
                "planning_adaptation_checkpoint_protocol_normalized",
                "哈希完整的单事件审核窗口检查点已完成确定性协议归一化",
                stage="review", metadata={
                    "segment": segment, "event_id": event_id, "facet": facet,
                    "window_index": window_index,
                    "semantic_repairs": semantic_repairs,
                    "source_receipt_sha256": source_receipt_sha256,
                    "receipt_sha256": hashlib.sha256(json.dumps(
                        receipt, ensure_ascii=False, sort_keys=True,
                        separators=(",", ":"),
                    ).encode("utf-8")).hexdigest(),
                },
            )
        self.db.add_run_event(
            run_id, "info", "planning_adaptation_facet_window_checkpoint_reused",
            "已复用哈希匹配的单事件审核窗口，只继续未完成窗口",
            stage="review", metadata={
                "segment": segment, "event_id": event_id, "facet": facet,
                "window": window_index,
                "source_run": source_path.relative_to(
                    project.path / "runs",
                ).parts[0],
            },
        )
        return receipt

    async def _review_short_plan_adaptation_facet_windows(
        self, run_id: str, run_path: Path, project: Project, constraints: str,
        *, planning_sha256: str, segment: int, event_contract: dict,
        plan_segment: str, evidence_candidates: dict[str, str],
        facet_authority_sha256: str, event_id: str, facet: str,
        invariant_fields: Sequence[str], authority_version: int,
    ) -> str:
        windows = review_windows(plan_segment, target=3600, overlap=500)
        if not windows or windows[0]["start"] != 0 or windows[-1]["end"] != len(
            plan_segment,
        ) or any(
            int(current["start"]) > int(previous["end"])
            for previous, current in zip(windows, windows[1:])
        ):
            raise ValueError("单事件审核窗口未完整覆盖当前事件原文")
        contract_sha256 = hashlib.sha256(json.dumps(
            event_contract, ensure_ascii=False, sort_keys=True,
            separators=(",", ":"),
        ).encode("utf-8")).hexdigest()
        receipts: list[dict] = []
        index_skeleton = self._stage_story_skeleton(
            project, constraints, run_path, owner_event_ids=[event_id],
            index_only=True,
        )
        for window in windows:
            window_index = int(window["index"])
            start = int(window["start"])
            end = int(window["end"])
            text = str(window["text"])
            text_sha256 = hashlib.sha256(text.encode("utf-8")).hexdigest()
            window_authority = self._planning_adaptation_facet_window_authority_sha256(
                facet_authority_sha256=facet_authority_sha256,
                window_index=window_index,
                start=start,
                end=end,
                text_sha256=text_sha256,
            )
            window_candidates: dict[str, str] = {}
            for evidence_id, evidence in evidence_candidates.items():
                position = plan_segment.find(evidence)
                if position < 0 or position >= end or position + len(evidence) <= start:
                    continue
                excerpt_start = max(start, position) - position
                excerpt_end = min(end, position + len(evidence)) - position
                excerpt = evidence[excerpt_start:excerpt_end]
                if excerpt:
                    window_candidates[evidence_id] = excerpt
            stored = self._load_planning_adaptation_facet_window_checkpoint(
                run_id, run_path, project,
                facet_authority_sha256=facet_authority_sha256,
                window_authority_sha256=window_authority,
                planning_sha256=planning_sha256,
                authority_version=authority_version,
                segment=segment,
                event_id=event_id,
                facet=facet,
                window_index=window_index,
                start=start,
                end=end,
                text_sha256=text_sha256,
                invariant_fields=invariant_fields,
                evidence_candidates=window_candidates,
            )
            if stored is not None:
                receipts.append(stored)
                continue
            expected_identity: dict[str, object] = {
                "authority_sha256": window_authority,
                "planning_sha256": planning_sha256,
                "authority_version": authority_version,
                "segment": segment,
                "event_id": event_id,
                "facet": facet,
                "window_index": window_index,
                "start": start,
                "end": end,
                "text_sha256": text_sha256,
            }
            base_prompt = (
                "SHORT_PLAN_ADAPTATION_EVENT_FACET_WINDOW_REVIEW_V1\n"
                "Review this complete overlapping evidence window for one indivisible event. "
                "Do not rewrite. For each requested invariant return false if this window contains "
                "a contradiction or unauthorized structural change; otherwise return true. The "
                "Runtime will AND every fully covered window before accepting the facet.\n"
                f"EXPECTED WINDOW AUTHORITY SHA256: {window_authority}\n"
                f"EXPECTED FACET AUTHORITY SHA256: {facet_authority_sha256}\n"
                f"FORMAL EVENT CONTRACT SHA256: {contract_sha256}\n"
                f"EXPECTED PLANNING SHA256: {planning_sha256}\n"
                f"EXPECTED AUTHORITY VERSION: {authority_version}\n"
                f"CURRENT SEGMENT: {segment}\n"
                f"EVENT ID: {event_id}\n"
                f"FACET: {facet}\n"
                f"WINDOW INDEX: {window_index}\n"
                f"WINDOW RANGE: {start}:{end}\n"
                f"WINDOW TEXT SHA256: {text_sha256}\n"
                "EXPECTED INVARIANTS:\n"
                + json.dumps(list(invariant_fields), ensure_ascii=False)
                + "\n\nFORMAL EVENT CONTRACT:\n"
                + json.dumps(event_contract, ensure_ascii=False, indent=2)
                + "\n\nWINDOW EVIDENCE CANDIDATES:\n"
                + json.dumps(window_candidates, ensure_ascii=False, indent=2)
                + "\n\nEXACT PLAN WINDOW:\n" + text
                + "\n\nRequired fields: invariants, changed_dimensions, plan_evidence_ids, "
                "plan_evidence_quote, reason. Runtime owns and injects authority, planning "
                "hash, version, segment, event, facet, window range, and text hash. "
                "If any invariant is false, quote one exact current-window problem "
                "phrase of at least six semantic characters and include it verbatim in reason."
            )
            last_issues: list[str] = []
            receipt: dict | None = None
            attempt_plan = self._protocol_receipt_attempt_plan(
                "review", same_route_attempts=2,
            )
            for attempt in attempt_plan:
                if attempt.use_configured_fallback:
                    self._record_protocol_receipt_fallback(
                        run_id, stage="review",
                        boundary="planning_adaptation_facet_window",
                        unit_metadata={
                            "segment": segment,
                            "event_id": event_id,
                            "facet": facet,
                            "window_index": window_index,
                            "authority_sha256": window_authority,
                        },
                        issues=last_issues,
                    )
                prompt = base_prompt
                if last_issues:
                    prompt += (
                        "\n\nSEMANTIC RECEIPT ISSUES TO CORRECT:\n"
                        + json.dumps(last_issues, ensure_ascii=False)
                        + "\nThe exact plan window is immutable. Return only a corrected verdict payload."
                    )
                raw, route_failure = await self._execute_protocol_receipt_attempt(
                    run_id, stage="review",
                    boundary="planning_adaptation_facet_window",
                    attempt=attempt,
                    unit_metadata={
                        "segment": segment,
                        "event_id": event_id,
                        "facet": facet,
                        "window_index": window_index,
                        "authority_sha256": window_authority,
                    },
                    operation=lambda: self._stage(
                    run_id, run_path, project, "review", constraints, prompt,
                    suffix=(
                        f"-plan-adaptation-facet-window-{segment:02d}-{event_id}-"
                        f"{facet}-{window_index:03d}"
                        + (
                            "-fallback" if attempt.use_configured_fallback
                            else "" if attempt.route_attempt == 1
                            else "-protocol-retry"
                        )
                    ),
                    allow_tools=False,
                    prefer_configured_fallback=attempt.use_configured_fallback,
                    primary_only=not attempt.use_configured_fallback,
                    defer_route_failure_audit=True,
                    protocol_system_contract=IMMUTABLE_RECEIPT_SYSTEM,
                    expected_output_characters=700,
                    completion_check=lambda value: not (
                        self._converted_planning_adaptation_facet_semantic_issues(
                            value, run_path,
                            invariant_fields=invariant_fields,
                            evidence_candidates=window_candidates,
                        )
                    ),
                    route_capacity_guard=True,
                    story_skeleton_override=index_skeleton,
                    bounded_protocol_output=True,
                    compact_input=True,
                    ),
                )
                if route_failure is not None:
                    last_issues = [route_failure.code]
                    receipt = None
                    if not attempt.is_last:
                        continue
                    raise ProtocolReceiptRouteExhaustedError(route_failure)
                try:
                    generated = self._convert_generated_object(
                        raw, run_path,
                        contract_name="planning_adaptation_facet",
                    )
                except (TypeError, ValueError, json.JSONDecodeError) as exc:
                    last_issues = ["receipt_schema:" + str(exc)[:300]]
                    rebound_fields: list[str] = []
                else:
                    (
                        receipt, last_issues, rebound_fields,
                        semantic_repairs, adapter_audits,
                    ) = (
                        self._bind_current_planning_adaptation_facet_receipt(
                            generated,
                            expected_identity=expected_identity,
                            invariant_fields=invariant_fields,
                            evidence_candidates=window_candidates,
                        )
                    )
                if receipt is not None:
                    if rebound_fields or semantic_repairs:
                        canonical = json.dumps(
                            receipt, ensure_ascii=False, sort_keys=True,
                            separators=(",", ":"),
                        )
                        self.db.add_run_event(
                            run_id, "info",
                            "planning_adaptation_runtime_identity_bound",
                            "单事件审核语义载荷已由运行时绑定到当前不可变窗口",
                            stage="review", metadata={
                                "segment": segment,
                                "event_id": event_id,
                                "facet": facet,
                                "window_index": window_index,
                                "rebound_fields": rebound_fields,
                                "semantic_repairs": semantic_repairs,
                                "contract_adapter_audits": adapter_audits,
                                "raw_sha256": hashlib.sha256(
                                    str(raw).encode("utf-8", errors="replace"),
                                ).hexdigest(),
                                "receipt_sha256": hashlib.sha256(
                                    canonical.encode("utf-8"),
                                ).hexdigest(),
                            },
                        )
                    break
                if not attempt.is_last:
                    self.db.add_run_event(
                        run_id, "info",
                        "planning_adaptation_facet_window_receipt_retry",
                        "规划原文保持不变，正在重取当前审核窗口的语义回执",
                        stage="review", metadata={
                            "segment": segment,
                            "event_id": event_id,
                            "facet": facet,
                            "window_index": window_index,
                            "attempt": attempt.attempt_index,
                            "route": attempt.route,
                            "next_route": attempt_plan[
                                attempt.attempt_index
                            ].route,
                            "issues": last_issues,
                        },
                    )
            if receipt is None:
                raise ValueError(
                    "单事件审核窗口语义回执无效："
                    + ",".join(last_issues or ["unknown_protocol_error"])
                )
            if not self._planning_adaptation_facet_window_receipt_valid(
                receipt,
                window_authority_sha256=window_authority,
                planning_sha256=planning_sha256,
                authority_version=authority_version,
                segment=segment,
                event_id=event_id,
                facet=facet,
                window_index=window_index,
                start=start,
                end=end,
                text_sha256=text_sha256,
                invariant_fields=invariant_fields,
                evidence_candidates=window_candidates,
            ):
                raise ValueError("单事件审核窗口回执未绑定完整范围或原文哈希")
            receipt = dict(receipt)
            receipts.append(receipt)
            self._save_planning_adaptation_facet_window_checkpoint(
                run_path,
                facet_authority_sha256=facet_authority_sha256,
                window_authority_sha256=window_authority,
                segment=segment,
                event_id=event_id,
                facet=facet,
                window_index=window_index,
                start=start,
                end=end,
                text_sha256=text_sha256,
                invariant_fields=invariant_fields,
                receipt=receipt,
            )
        invariants = {
            field: all(receipt["invariants"].get(field) is True for receipt in receipts)
            for field in invariant_fields
        }
        evidence_ids = list(dict.fromkeys(
            str(value)
            for receipt in receipts
            for value in receipt.get("plan_evidence_ids", [])
            if str(value) in evidence_candidates
        ))
        if not evidence_ids:
            raise ValueError("单事件审核窗口没有返回任何绑定到父级候选的原文证据")
        changed_dimensions = list(dict.fromkeys(
            str(value).strip()
            for receipt in receipts
            for value in receipt.get("changed_dimensions", [])
            if str(value).strip()
        ))
        reasons = list(dict.fromkeys(
            str(receipt.get("reason") or "").strip()
            for receipt in receipts
            if str(receipt.get("reason") or "").strip()
        ))
        evidence_quotes = list(dict.fromkeys(
            str(receipt.get("plan_evidence_quote") or "").strip()
            for receipt in receipts
            if any(
                value is False
                for value in (receipt.get("invariants") or {}).values()
            )
            and str(receipt.get("plan_evidence_quote") or "").strip()
        ))
        merged = {
            "authority_sha256": facet_authority_sha256,
            "planning_sha256": planning_sha256,
            "authority_version": authority_version,
            "segment": segment,
            "event_id": event_id,
            "facet": facet,
            "invariants": invariants,
            "changed_dimensions": changed_dimensions,
            "plan_evidence_ids": evidence_ids,
            "plan_evidence_quote": evidence_quotes[0] if evidence_quotes else "",
            "reason": (
                f"已审核 {len(receipts)} 个完整重叠窗口，范围 0:{len(plan_segment)}，"
                "所有窗口均绑定原文哈希并完成无遗漏归并。"
                + ("；" + "；".join(reasons) if reasons else "")
            ),
            "window_coverage": [{
                "window_index": int(receipt["window_index"]),
                "start": int(receipt["start"]),
                "end": int(receipt["end"]),
                "text_sha256": str(receipt["text_sha256"]),
            } for receipt in receipts],
        }
        if not self._planning_adaptation_facet_receipt_valid(
            merged,
            facet_authority_sha256=facet_authority_sha256,
            planning_sha256=planning_sha256,
            authority_version=authority_version,
            segment=segment,
            event_id=event_id,
            facet=facet,
            invariant_fields=invariant_fields,
            evidence_candidates=evidence_candidates,
        ):
            raise ValueError("单事件审核窗口归并后未形成完整维度回执")
        self.db.add_run_event(
            run_id, "success", "planning_adaptation_facet_windows_completed",
            "单个事件审核维度已按完整重叠原文窗口核对并无损归并",
            stage="review", metadata={
                "segment": segment, "event_id": event_id, "facet": facet,
                "window_count": len(receipts),
                "covered_characters": len(plan_segment),
            },
        )
        return json.dumps(merged, ensure_ascii=False)

    async def _review_short_plan_adaptation_event_facets(
        self, run_id: str, run_path: Path, project: Project, constraints: str,
        *, planning_sha256: str, segment: int, event_contract: dict,
        plan_segment: str, evidence_candidates: dict[str, str],
        packet_authority_sha256: str, previous_handoff: str,
        next_entry: str, authority_version: int,
        authority_event_ids: list[str] | None,
        story_skeleton_override: str,
    ) -> tuple[dict, list[dict], int]:
        event_id = str(event_contract.get("id") or "").strip().upper()
        facet_receipts: list[dict] = []
        retries = 0
        for facet, invariant_fields in PLANNING_ADAPTATION_EVENT_FACETS.items():
            facet_authority = planning_adaptation_event_facet_authority_sha256(
                packet_authority_sha256=packet_authority_sha256,
                segment=segment,
                event_id=event_id,
                facet=facet,
                invariant_fields=invariant_fields,
                version=authority_version,
            )
            expected_identity: dict[str, object] = {
                "authority_sha256": facet_authority,
                "planning_sha256": planning_sha256,
                "authority_version": authority_version,
                "segment": segment,
                "event_id": event_id,
                "facet": facet,
            }
            stored = self._load_planning_adaptation_facet_checkpoint(
                run_id, run_path, project,
                packet_authority_sha256=packet_authority_sha256,
                facet_authority_sha256=facet_authority,
                planning_sha256=planning_sha256,
                authority_version=authority_version,
                segment=segment,
                event_id=event_id,
                facet=facet,
                invariant_fields=invariant_fields,
                evidence_candidates=evidence_candidates,
            )
            if stored is not None:
                facet_receipts.append(stored)
                continue
            last_error = ""
            attempt_plan = self._protocol_receipt_attempt_plan(
                "review", same_route_attempts=2,
            )
            for attempt in attempt_plan:
                if attempt.use_configured_fallback:
                    self._record_protocol_receipt_fallback(
                        run_id, stage="review",
                        boundary="planning_adaptation_event_facet",
                        unit_metadata={
                            "segment": segment,
                            "event_id": event_id,
                            "facet": facet,
                            "authority_sha256": facet_authority,
                        },
                        issues=[last_error] if last_error else [],
                    )
                prompt = (
                    "SHORT_PLAN_ADAPTATION_EVENT_FACET_REVIEW_V1\n"
                    "Review one indivisible formal event without changing its narrative ownership. "
                    "Return one JSON object only. Judge only the requested invariant facet from the "
                    "exact event-owned plan evidence. Unknown formal fields are unknown, not invented facts.\n"
                    f"EXPECTED FACET AUTHORITY SHA256: {facet_authority}\n"
                    f"EXPECTED PLANNING SHA256: {planning_sha256}\n"
                    f"EXPECTED AUTHORITY VERSION: {authority_version}\n"
                    f"CURRENT SEGMENT: {segment}\n"
                    f"EVENT ID: {event_id}\n"
                    f"FACET: {facet}\n"
                    "EXPECTED INVARIANTS:\n"
                    + json.dumps(list(invariant_fields), ensure_ascii=False)
                    + "\n\nFORMAL EVENT CONTRACT:\n"
                    + json.dumps(event_contract, ensure_ascii=False, indent=2)
                    + "\n\nPREVIOUS ACCEPTED HANDOFF:\n" + previous_handoff
                    + "\n\nNEXT SEGMENT ENTRY:\n" + next_entry
                    + "\n\nALLOWED DEPENDENCY EVENT IDS:\n"
                    + json.dumps(authority_event_ids or [event_id], ensure_ascii=False)
                    + "\n\nCURRENT ACCEPTED EVENT PLAN EVIDENCE:\n" + plan_segment
                    + "\n\nPLAN EVIDENCE CANDIDATES:\n"
                    + json.dumps(evidence_candidates, ensure_ascii=False, indent=2)
                    + "\n\nRequired fields: invariants, changed_dimensions, plan_evidence_ids, "
                    "plan_evidence_quote, reason. Runtime owns and injects authority, planning "
                    "hash, version, segment, event, and facet. invariants must contain "
                    "exactly the requested names. If any invariant is false, quote one exact "
                    "current-plan problem phrase of at least six semantic characters and include "
                    "it verbatim in reason."
                )
                if last_error:
                    prompt += "\n\nPROTOCOL ERROR TO CORRECT:\n" + last_error[:800]
                raw, route_failure = await self._execute_protocol_receipt_attempt(
                    run_id, stage="review",
                    boundary="planning_adaptation_event_facet",
                    attempt=attempt,
                    unit_metadata={
                        "segment": segment,
                        "event_id": event_id,
                        "facet": facet,
                        "authority_sha256": facet_authority,
                    },
                    operation=lambda: self._stage(
                        run_id, run_path, project, "review", constraints, prompt,
                        suffix=(
                            f"-plan-adaptation-facet-{segment:02d}-{event_id}-{facet}-"
                            f"{attempt.attempt_index}"
                            + ("-fallback" if attempt.use_configured_fallback else "")
                        ),
                        allow_tools=False,
                        prefer_configured_fallback=attempt.use_configured_fallback,
                        primary_only=not attempt.use_configured_fallback,
                        defer_route_failure_audit=True,
                        protocol_system_contract=IMMUTABLE_RECEIPT_SYSTEM,
                        expected_output_characters=900,
                        completion_check=lambda value, fields=invariant_fields: not (
                            self._converted_planning_adaptation_facet_semantic_issues(
                                value, run_path,
                                invariant_fields=fields,
                                evidence_candidates=evidence_candidates,
                            )
                        ),
                        route_capacity_guard=True,
                        story_skeleton_override=story_skeleton_override,
                        bounded_protocol_output=True,
                        capacity_splitter=lambda _details: (
                            self._review_short_plan_adaptation_facet_windows(
                                run_id, run_path, project, constraints,
                                planning_sha256=planning_sha256,
                                segment=segment,
                                event_contract=event_contract,
                                plan_segment=plan_segment,
                                evidence_candidates=evidence_candidates,
                                facet_authority_sha256=facet_authority,
                                event_id=event_id,
                                facet=facet,
                                invariant_fields=invariant_fields,
                                authority_version=authority_version,
                            )
                        ),
                    ),
                )
                if route_failure is not None:
                    last_error = route_failure.code
                    retries += 1
                    if attempt.is_last:
                        raise ProtocolReceiptRouteExhaustedError(route_failure)
                    continue
                try:
                    generated = self._convert_generated_object(
                        raw, run_path,
                        contract_name="planning_adaptation_facet",
                    )
                except (TypeError, ValueError, json.JSONDecodeError) as exc:
                    last_error = str(exc)
                else:
                    (
                        receipt, semantic_issues, rebound_fields,
                        semantic_repairs, adapter_audits,
                    ) = (
                        self._bind_current_planning_adaptation_facet_receipt(
                            generated,
                            expected_identity=expected_identity,
                            invariant_fields=invariant_fields,
                            evidence_candidates=evidence_candidates,
                        )
                    )
                    if receipt is None:
                        last_error = json.dumps(
                            semantic_issues, ensure_ascii=False,
                        )
                        retries += 1
                        continue
                    if rebound_fields or semantic_repairs:
                        canonical = json.dumps(
                            receipt, ensure_ascii=False, sort_keys=True,
                            separators=(",", ":"),
                        )
                        self.db.add_run_event(
                            run_id, "info",
                            "planning_adaptation_runtime_identity_bound",
                            "单事件审核语义载荷已由运行时绑定到当前不可变事件范围",
                            stage="review", metadata={
                                "segment": segment,
                                "event_id": event_id,
                                "facet": facet,
                                "rebound_fields": rebound_fields,
                                "semantic_repairs": semantic_repairs,
                                "contract_adapter_audits": adapter_audits,
                                "raw_sha256": hashlib.sha256(
                                    str(raw).encode("utf-8", errors="replace"),
                                ).hexdigest(),
                                "receipt_sha256": hashlib.sha256(
                                    canonical.encode("utf-8"),
                                ).hexdigest(),
                            },
                        )
                    if self._planning_adaptation_facet_receipt_valid(
                        receipt,
                        facet_authority_sha256=facet_authority,
                        planning_sha256=planning_sha256,
                        authority_version=authority_version,
                        segment=segment,
                        event_id=event_id,
                        facet=facet,
                        invariant_fields=invariant_fields,
                        evidence_candidates=evidence_candidates,
                    ):
                        facet_receipts.append(dict(receipt))
                        self._save_planning_adaptation_facet_checkpoint(
                            run_path,
                            packet_authority_sha256=packet_authority_sha256,
                            facet_authority_sha256=facet_authority,
                            segment=segment,
                            event_id=event_id,
                            facet=facet,
                            invariant_fields=invariant_fields,
                            receipt=dict(receipt),
                        )
                        break
                    last_error = "facet receipt did not bind the requested invariant scope"
                retries += 1
            else:
                raise ValueError(
                    f"规划第 {segment} 段事件 {event_id} 的 {facet} 分层审核回执无效："
                    f"{last_error or 'unknown protocol error'}"
                )

        invariants: dict[str, bool] = {}
        changed_dimensions: list[str] = []
        evidence_ids: list[str] = []
        evidence_quotes: list[str] = []
        reasons: list[str] = []
        for receipt in facet_receipts:
            invariants.update(receipt["invariants"])
            for value in receipt.get("changed_dimensions", []):
                text = str(value or "").strip()
                if text and text not in changed_dimensions:
                    changed_dimensions.append(text)
            for value in receipt.get("plan_evidence_ids", []):
                text = str(value or "").strip()
                if text and text not in evidence_ids:
                    evidence_ids.append(text)
            quote = str(receipt.get("plan_evidence_quote") or "").strip()
            if (
                quote
                and any(
                    value is False
                    for value in (receipt.get("invariants") or {}).values()
                )
                and quote not in evidence_quotes
            ):
                evidence_quotes.append(quote)
            reason = str(receipt.get("reason") or "").strip()
            if reason:
                reasons.append(reason)
        reported_dimensions = list(changed_dimensions)
        changed_dimensions, reviewed_dimensions = (
            self._reconcile_planning_adaptation_dimension_roles(
                reported_dimensions, invariants=invariants,
            )
        )
        if reviewed_dimensions:
            self.db.add_run_event(
                run_id, "info",
                "planning_adaptation_dimension_roles_reconciled",
                "单事件分面已按完整不变量图分离叙事进展维度与正式权威偏离",
                stage="review", metadata={
                    "segment": segment,
                    "event_id": event_id,
                    "reviewed_dimensions": reviewed_dimensions,
                    "reported_dimensions_sha256": hashlib.sha256(json.dumps(
                        reported_dimensions, ensure_ascii=False,
                        separators=(",", ":"),
                    ).encode("utf-8")).hexdigest(),
                    "effective_dimensions_sha256": hashlib.sha256(json.dumps(
                        changed_dimensions, ensure_ascii=False,
                        separators=(",", ":"),
                    ).encode("utf-8")).hexdigest(),
                },
            )
        event_review = {
            "event_id": event_id,
            "classification": "equivalent" if changed_dimensions else "unchanged",
            "changed_dimensions": changed_dimensions,
            "invariants": invariants,
            "plan_evidence_ids": evidence_ids,
            "plan_evidence_quote": evidence_quotes[0] if evidence_quotes else "",
            "reason": "；".join(reasons),
        }
        merged = normalize_planning_adaptation_receipt({
            "authority_sha256": packet_authority_sha256,
            "planning_sha256": planning_sha256,
            "authority_version": authority_version,
            "segment": segment,
            "event_reviews": [event_review],
            "segment_order_preserved": invariants.get("timeline_order") is True,
            "formal_direction_preserved": all(
                invariants.get(field) is True
                for field in (
                    "event_function", "primary_actor_agency",
                    "causal_dependencies", "promise_ending",
                )
            ),
            "summary": f"事件 {event_id} 已完成全部审核维度并无损合并。",
        }, evidence_candidates=evidence_candidates)
        issues = planning_adaptation_receipt_issues(
            merged,
            authority_sha256=packet_authority_sha256,
            planning_sha256=planning_sha256,
            segment=segment,
            expected_event_ids=[event_id],
            evidence_candidates=evidence_candidates,
            authority_version=authority_version,
            authority_event_ids=authority_event_ids,
            plan_segment=plan_segment,
        )
        return dict(merged), issues, retries

    async def _review_short_plan_adaptation_capacity_split(
        self, run_id: str, run_path: Path, project: Project, constraints: str,
        *, outline_sha256: str, planning_sha256: str, segment: int,
        event_contracts: list[dict], plan_segment: str, suffix: str,
        previous_handoff: str, next_entry: str,
        generation_context_sha256: str,
        authority_version: int, authority_event_ids: list[str] | None,
        segment_authority_sha256: str, details: dict,
    ) -> str:
        """Review one segment in event-owned packets and merge losslessly.

        The segment remains the authority.  Only the transport topology changes;
        every packet is hash-bound to the complete segment authority and its
        ordered event subset, then the merged receipt is validated against the
        original full event list before it is returned to the caller.
        """
        packet_receipts: list[dict] = []
        packet_meta: list[dict] = []
        protocol_retries = 0
        singleton_facet_recoveries = 0

        async def review_group(group: list[dict]) -> None:
            nonlocal protocol_retries, singleton_facet_recoveries
            group_ids = [
                str(item.get("id") or "").strip().upper() for item in group
            ]
            projected_plan, projected_candidates = planning_adaptation_event_projection(
                plan_segment, segment, group_ids,
            )
            packet_story_skeleton = self._stage_story_skeleton(
                project, constraints, run_path, owner_event_ids=group_ids,
            )
            packet_authority = planning_adaptation_segment_packet_authority_sha256(
                segment_authority_sha256=segment_authority_sha256,
                segment=segment,
                event_ids=group_ids,
                version=authority_version,
            )
            stored = self._load_planning_adaptation_packet_checkpoint(
                run_id, run_path, project,
                segment_authority_sha256=segment_authority_sha256,
                packet_authority_sha256=packet_authority,
                planning_sha256=planning_sha256,
                authority_version=authority_version,
                segment=segment,
                event_ids=group_ids,
                evidence_candidates=planning_adaptation_evidence_candidates(
                    plan_segment, segment,
                ),
                authority_event_ids=authority_event_ids,
            )
            if stored is not None:
                receipt, issues = stored
                packet_receipts.append(receipt)
                packet_meta.append({
                    "authority_sha256": packet_authority,
                    "event_ids": group_ids,
                    "retries": 0,
                    "reused": True,
                })
                return
            try:
                receipt, issues, retries = (
                    await self._review_short_plan_adaptation_segment(
                        run_id, run_path, project, constraints,
                        outline_sha256=outline_sha256,
                        planning_sha256=planning_sha256,
                        segment=segment,
                        event_contracts=group,
                        plan_segment=plan_segment,
                        suffix=(
                            f"{suffix}-capacity-{packet_authority[:12]}"
                        ),
                        previous_handoff=previous_handoff,
                        next_entry=next_entry,
                        generation_context_sha256=generation_context_sha256,
                        authority_version=authority_version,
                        authority_event_ids=authority_event_ids,
                        _capacity_split=False,
                        _authority_override=packet_authority,
                        _prompt_plan_segment=projected_plan,
                        _prompt_evidence_candidates=projected_candidates,
                        _story_skeleton_override=packet_story_skeleton,
                    )
                )
            except Exception as exc:
                capacity_failure = (
                    isinstance(exc, ContextCapacityPreflightError)
                    or classify_model_failure(str(exc)) == "input_context_overflow"
                )
                if not capacity_failure:
                    raise
                if (
                    capacity_failure
                ) and len(group) > 1:
                    midpoint = max(1, len(group) // 2)
                    await review_group(group[:midpoint])
                    await review_group(group[midpoint:])
                    return
                if (
                    capacity_failure
                ) and len(group) == 1:
                    receipt, issues, retries = (
                        await self._review_short_plan_adaptation_event_facets(
                            run_id, run_path, project, constraints,
                            planning_sha256=planning_sha256,
                            segment=segment,
                            event_contract=group[0],
                            plan_segment=projected_plan,
                            evidence_candidates=projected_candidates,
                            packet_authority_sha256=packet_authority,
                            previous_handoff=previous_handoff,
                            next_entry=next_entry,
                            authority_version=authority_version,
                            authority_event_ids=authority_event_ids,
                            story_skeleton_override=packet_story_skeleton,
                        )
                    )
                    singleton_facet_recoveries += 1
                elif isinstance(exc, ContextCapacityPreflightError):
                    raise ValueError(
                        f"{exc}；规划第 {segment} 段单个事件不可再拆分，"
                        "已保留完整事件权威"
                    ) from exc
                else:
                    raise
            protocol_retries += retries
            protocol_issues = [
                item for item in issues
                if str(item.get("code") or "")
                in PLANNING_ADAPTATION_PROTOCOL_CODES
            ]
            if not receipt or protocol_issues:
                raise ValueError(
                    f"规划第 {segment} 段分包审核回执无效："
                    + json.dumps(protocol_issues, ensure_ascii=False)
                )
            packet_receipts.append(receipt)
            self._save_planning_adaptation_packet_checkpoint(
                run_path,
                segment_authority_sha256=segment_authority_sha256,
                packet_authority_sha256=packet_authority,
                segment=segment,
                event_ids=group_ids,
                receipt=receipt,
            )
            packet_meta.append({
                "authority_sha256": packet_authority,
                "event_ids": group_ids,
                "retries": retries,
            })

        await review_group(list(event_contracts))
        expected_event_ids = [
            str(item.get("id") or "").strip().upper()
            for item in event_contracts
        ]
        by_event: dict[str, dict] = {}
        for receipt in packet_receipts:
            for review in receipt.get("event_reviews", []):
                event_id = str(review.get("event_id") or "").strip().upper()
                if event_id in by_event:
                    raise ValueError(
                        f"规划第 {segment} 段分包审核重复覆盖事件 {event_id}"
                    )
                by_event[event_id] = dict(review)
        if list(by_event) != expected_event_ids:
            raise ValueError(
                f"规划第 {segment} 段分包审核未完整覆盖正式事件"
            )
        merged = {
            "authority_sha256": segment_authority_sha256,
            "planning_sha256": planning_sha256,
            "authority_version": authority_version,
            "segment": segment,
            "event_reviews": [by_event[event_id] for event_id in expected_event_ids],
            "segment_order_preserved": all(
                receipt.get("segment_order_preserved") is True
                for receipt in packet_receipts
            ),
            "formal_direction_preserved": all(
                receipt.get("formal_direction_preserved") is True
                for receipt in packet_receipts
            ),
            "summary": "；".join(
                str(receipt.get("summary") or "").strip()
                for receipt in packet_receipts
                if str(receipt.get("summary") or "").strip()
            ) or "容量分包审核已覆盖当前正式段全部事件",
            "capacity_split": {
                "pressure": details.get("pressure"),
                "packets": packet_meta,
                "protocol_retries": protocol_retries,
                "singleton_facet_recoveries": singleton_facet_recoveries,
            },
            "segment_sha256": hashlib.sha256(
                plan_segment.encode("utf-8"),
            ).hexdigest(),
            "boundary_sha256": hashlib.sha256(json.dumps({
                "previous_handoff": previous_handoff,
                "next_entry": next_entry,
            }, ensure_ascii=False, sort_keys=True, separators=(",", ":")).encode(
                "utf-8",
            )).hexdigest(),
        }
        merged_issues = planning_adaptation_receipt_issues(
            merged,
            authority_sha256=segment_authority_sha256,
            planning_sha256=planning_sha256,
            segment=segment,
            expected_event_ids=expected_event_ids,
            evidence_candidates=planning_adaptation_evidence_candidates(
                plan_segment, segment,
            ),
            authority_version=authority_version,
            authority_event_ids=authority_event_ids,
            plan_segment=plan_segment,
        )
        if any(
            str(item.get("code") or "") in PLANNING_ADAPTATION_PROTOCOL_CODES
            for item in merged_issues
        ):
            raise ValueError(
                "规划分包合并后的完整回执未通过协议校验："
                + json.dumps(merged_issues, ensure_ascii=False)
            )
        self.db.add_run_event(
            run_id, "success", "planning_adaptation_capacity_split_completed",
            f"规划第 {segment} 段已按事件所有权完成容量分包并无损合并",
            stage="review", metadata={
                "segment": segment,
                "packet_count": len(packet_meta),
                "packets": packet_meta,
                "pressure": details.get("pressure"),
                "estimated_input_tokens": details.get("estimated_input_tokens"),
                "output_reserve": details.get("output_reserve"),
                "singleton_facet_recoveries": singleton_facet_recoveries,
            },
        )
        return json.dumps(merged, ensure_ascii=False)

    def _planning_adaptation_whole_units(
        self, *, plan: str, formal_contracts: list[dict],
        segment_receipts: list[dict], segment_count: int,
    ) -> list[dict]:
        """Build ordered segment units with lossless local review authority."""
        segments = self._short_plan_segments(plan, segment_count)
        if len(segments) != segment_count or len(segment_receipts) != segment_count:
            return []
        contract_by_id = {
            str(item.get("id") or "").strip().upper(): item
            for item in formal_contracts if isinstance(item, dict)
        }
        result: list[dict] = []
        for number, (block, receipt) in enumerate(
            zip(segments, segment_receipts, strict=True), 1,
        ):
            event_ids = self._short_plan_event_ids(block)
            contracts = [contract_by_id.get(event_id) for event_id in event_ids]
            if not event_ids or any(item is None for item in contracts):
                return []
            reviews = receipt.get("event_reviews", []) \
                if isinstance(receipt, dict) else []
            result.append({
                "segment": number,
                "segment_sha256": hashlib.sha256(
                    block.encode("utf-8"),
                ).hexdigest(),
                "event_ids": event_ids,
                "formal_contracts": [dict(item) for item in contracts if item],
                "opening": self._short_plan_field(block, "opening"),
                "handoff": self._short_plan_handoff(block),
                "local_receipt_sha256": hashlib.sha256(json.dumps(
                    receipt, ensure_ascii=False, sort_keys=True,
                    separators=(",", ":"),
                ).encode("utf-8")).hexdigest(),
                "event_reviews": [{
                    "event_id": str(review.get("event_id") or ""),
                    "classification": str(review.get("classification") or ""),
                    "invariants": dict(review.get("invariants") or {}),
                    "changed_dimensions": list(
                        review.get("changed_dimensions") or []
                    ),
                    "plan_evidence_ids": list(
                        review.get("plan_evidence_ids") or []
                    ),
                    "plan_evidence": list(review.get("plan_evidence") or []),
                    "plan_evidence_quote": str(
                        review.get("plan_evidence_quote") or ""
                    ),
                    "reason": str(review.get("reason") or ""),
                } for review in reviews if isinstance(review, dict)],
            })
        return result

    def _planning_adaptation_whole_context(
        self, *, plan: str, formal_contracts: list[dict],
        segment_receipts: list[dict], segment_count: int,
        token_limit: int,
    ) -> tuple[str, str, int]:
        """Build a lossless direct context or require hierarchical review."""
        full = (
            "FORMAL EVENT CONTRACTS:\n"
            + json.dumps(formal_contracts, ensure_ascii=False, indent=2)
            + "\n\nVALIDATED SEGMENT ADAPTATION RECEIPTS:\n"
            + json.dumps(segment_receipts, ensure_ascii=False, indent=2)
            + "\n\nCOMPLETE ACCEPTED PLAN:\n" + plan
        )
        full_tokens = estimate_input_tokens(full)
        if full_tokens <= token_limit:
            return full, "full", full_tokens

        structural_segments = self._planning_adaptation_whole_units(
            plan=plan,
            formal_contracts=formal_contracts,
            segment_receipts=segment_receipts,
            segment_count=segment_count,
        )
        if not structural_segments:
            # The caller's structural gate owns malformed coverage. Do not
            # fabricate a compact substitute for an incomplete authority.
            return full, "full_uncompactable", full_tokens
        compact = (
            "HASH-BOUND COMPLETE STRUCTURAL PLAN MAP:\n"
            + json.dumps(structural_segments, ensure_ascii=False, indent=2)
        )
        compact_tokens = estimate_input_tokens(compact)
        if compact_tokens <= token_limit:
            return compact, "structural_map", compact_tokens

        # Hash-only representations are useful for coverage accounting but are
        # not sufficient narrative evidence for a whole-story verdict. Signal
        # the caller to perform bounded, overlapping regional reviews that each
        # retain the complete contracts and exact plan evidence in their scope.
        coverage_segments = [{
            "segment": item["segment"],
            "segment_sha256": item["segment_sha256"],
            "event_ids": item["event_ids"],
            "opening_sha256": hashlib.sha256(
                item["opening"].encode("utf-8"),
            ).hexdigest(),
            "handoff_sha256": hashlib.sha256(
                item["handoff"].encode("utf-8"),
            ).hexdigest(),
            "local_receipt_sha256": item["local_receipt_sha256"],
        } for item in structural_segments]
        manifest = (
            "HASH-BOUND COMPLETE COVERAGE MANIFEST:\n"
            + json.dumps(coverage_segments, ensure_ascii=False, indent=2)
        )
        return manifest, "hierarchical_required", estimate_input_tokens(manifest)

    @staticmethod
    def _planning_hierarchy_coverage(values: list[dict]) -> tuple[list[int], list[str]]:
        segments: list[int] = []
        event_ids: list[str] = []
        for item in values:
            for value in item.get("segment_numbers", [item.get("segment")]):
                if isinstance(value, int) and value not in segments:
                    segments.append(value)
            for value in item.get("event_ids", []):
                event_id = str(value or "").strip().upper()
                if event_id and event_id not in event_ids:
                    event_ids.append(event_id)
        return segments, event_ids

    @staticmethod
    def _planning_adaptation_segment_receipt_complete(
        value: str, *, authority_sha256: str, planning_sha256: str,
        authority_version: int, segment: int, expected_event_ids: list[str],
        evidence_candidates: dict[str, str], authority_event_ids: list[str] | None,
        plan_segment: str, previous_handoff: str, next_entry: str,
    ) -> bool:
        """Prove a segment receipt is closed even when the route reports a limit.

        Semantic ``false`` verdicts are complete receipts.  Only parser, binding,
        coverage, or protocol defects make the artifact incomplete.
        """
        try:
            payload = parse_json_object(
                value, label=f"Planning adaptation receipt segment {segment}",
            )
            receipt = normalize_planning_adaptation_receipt(
                payload, evidence_candidates=evidence_candidates,
            )
            if not isinstance(receipt, dict):
                return False
            receipt["authority_version"] = authority_version
            receipt["segment_sha256"] = hashlib.sha256(
                plan_segment.encode("utf-8"),
            ).hexdigest()
            receipt["boundary_sha256"] = hashlib.sha256(json.dumps({
                "previous_handoff": previous_handoff,
                "next_entry": next_entry,
            }, ensure_ascii=False, sort_keys=True, separators=(",", ":")).encode(
                "utf-8",
            )).hexdigest()
            issues = planning_adaptation_receipt_issues(
                receipt,
                authority_sha256=authority_sha256,
                planning_sha256=planning_sha256,
                segment=segment,
                expected_event_ids=expected_event_ids,
                evidence_candidates=evidence_candidates,
                authority_version=authority_version,
                authority_event_ids=authority_event_ids,
                plan_segment=plan_segment,
            )
        except (TypeError, ValueError, json.JSONDecodeError):
            return False
        return not any(
            str(item.get("code") or "") in PLANNING_ADAPTATION_PROTOCOL_CODES
            for item in issues
        )

    @classmethod
    def _planning_hierarchy_receipt_complete(
        cls, value: str, *, source_sha256: str,
        expected_segments: list[int], expected_event_ids: list[str],
        inherited: list[dict] | None = None,
    ) -> bool:
        try:
            payload = parse_json_object(
                value, label="Planning adaptation hierarchy receipt",
            )
            cls._normalize_planning_hierarchy_receipt(
                payload,
                source_sha256=source_sha256,
                expected_segments=expected_segments,
                expected_event_ids=expected_event_ids,
                inherited=inherited,
            )
        except (TypeError, ValueError, json.JSONDecodeError):
            return False
        return True

    @staticmethod
    def _planning_adaptation_whole_receipt_complete(
        value: str, *, authority_sha256: str, planning_sha256: str,
        authority_version: int, segment_count: int,
        expected_event_ids: list[str],
    ) -> bool:
        try:
            payload = parse_json_object(
                value, label="Whole planning adaptation receipt",
            )
            receipt = normalize_planning_adaptation_whole_receipt(payload)
            if not isinstance(receipt, dict):
                return False
            receipt["authority_version"] = authority_version
            issues = planning_adaptation_whole_receipt_issues(
                receipt,
                authority_sha256=authority_sha256,
                planning_sha256=planning_sha256,
                segment_count=segment_count,
                expected_event_ids=expected_event_ids,
            )
        except (TypeError, ValueError, json.JSONDecodeError):
            return False
        return not any(
            str(item.get("code") or "") in PLANNING_ADAPTATION_PROTOCOL_CODES
            for item in issues
        )

    @staticmethod
    def _planning_hierarchy_event_coverage_valid(
        owned_groups: list[list[str]], expected_event_ids: list[str],
    ) -> bool:
        """Accept complete formal order with adjacent shared-event continuation.

        A formal event may legitimately start in one segment and continue in
        the next.  Flattening those segment declarations therefore produces
        adjacent duplicate IDs.  Collapse only consecutive duplicates and
        require the resulting order to equal the formal event order exactly;
        this still rejects omissions, unknown IDs, order reversal, and a later
        re-entry after another event has already begun.
        """
        expected = [str(value or "").strip().upper() for value in expected_event_ids]
        if not expected or any(not value for value in expected):
            return False
        flattened: list[str] = []
        for group in owned_groups:
            normalized = [str(value or "").strip().upper() for value in group]
            if not normalized or any(not value for value in normalized):
                return False
            if len(normalized) != len(set(normalized)):
                return False
            flattened.extend(normalized)
        collapsed: list[str] = []
        for event_id in flattened:
            if not collapsed or event_id != collapsed[-1]:
                collapsed.append(event_id)
        return collapsed == expected

    @staticmethod
    def _planning_hierarchy_unit_key(item: dict) -> tuple:
        return (
            int(item.get("segment") or 0),
            tuple(str(value or "").strip().upper() for value in item.get("event_ids", [])),
            str(item.get("segment_sha256") or ""),
            str(item.get("local_receipt_sha256") or ""),
        )

    @staticmethod
    def _normalize_planning_hierarchy_receipt(
        value: object, *, source_sha256: str,
        expected_segments: list[int], expected_event_ids: list[str],
        inherited: list[dict] | None = None,
    ) -> dict:
        receipt = normalize_planning_adaptation_whole_receipt(value)
        if not isinstance(receipt, dict):
            raise ValueError("规划分层审核回执必须是一个 JSON 对象")
        if receipt.get("source_sha256") != source_sha256:
            raise ValueError("规划分层审核回执没有绑定当前完整输入包")
        if receipt.get("segment_numbers") != expected_segments:
            raise ValueError("规划分层审核回执没有覆盖当前全部分段")
        if receipt.get("event_ids") != expected_event_ids:
            raise ValueError("规划分层审核回执没有按顺序覆盖当前全部事件")
        for field in WHOLE_STORY_FIELDS:
            if not isinstance(receipt.get(field), bool):
                raise ValueError("规划分层审核回执缺少完整的整篇不变量")
        affected_segments = receipt.get("affected_segments")
        affected_event_ids = receipt.get("affected_event_ids")
        if not isinstance(affected_segments, list) or any(
            not isinstance(item, int) or item not in expected_segments
            for item in affected_segments
        ):
            raise ValueError("规划分层审核回执的受影响分段无效")
        if not isinstance(affected_event_ids, list) or any(
            str(item).upper() not in expected_event_ids
            for item in affected_event_ids
        ):
            raise ValueError("规划分层审核回执的受影响事件无效")
        invalid = [
            field for field in WHOLE_STORY_FIELDS if receipt.get(field) is False
        ]
        if invalid and (not affected_segments or not affected_event_ids):
            raise ValueError("规划分层审核发现问题但没有给出最小受影响范围")
        if not invalid and (affected_segments or affected_event_ids):
            raise ValueError("规划分层审核无问题时不得返回受影响范围")
        for field in (
            "entry_state", "exit_state", "knowledge_state",
            "relationship_state", "viewpoint_timeline", "summary",
        ):
            text = str(receipt.get(field) or "").strip()
            if not text:
                raise ValueError(f"规划分层审核回执缺少 {field}")
            receipt[field] = text[:800]
        for field in ("open_promises", "resolved_promises"):
            values = receipt.get(field)
            if not isinstance(values, list):
                raise ValueError(f"规划分层审核回执缺少 {field}")
            receipt[field] = [str(item or "").strip()[:300] for item in values]
        receipt["reason"] = str(receipt.get("reason") or "").strip()[:1200]

        # A higher-level reducer may discover additional cross-region issues,
        # but it may never erase a hard failure already established below.
        inherited = inherited or []
        inherited_invalid = {
            field for item in inherited for field in WHOLE_STORY_FIELDS
            if item.get(field) is False
        }
        if inherited_invalid:
            for field in inherited_invalid:
                receipt[field] = False
            receipt["affected_segments"] = sorted({
                *affected_segments,
                *(segment for item in inherited
                  for segment in item.get("affected_segments", [])
                  if isinstance(segment, int)),
            })
            inherited_event_ids = {
                str(event_id).upper() for item in inherited
                for event_id in item.get("affected_event_ids", [])
                if str(event_id).strip()
            }
            receipt["affected_event_ids"] = [
                event_id for event_id in expected_event_ids
                if event_id in inherited_event_ids
                or event_id in {
                    str(value).upper()
                    for value in affected_event_ids
                    if str(value).strip()
                }
            ]
            if not receipt["reason"]:
                receipt["reason"] = "下层完整审核已经确认存在跨段结构问题。"
        return receipt

    @staticmethod
    def _planning_hierarchy_checkpoint_path(
        run_path: Path, *, kind: str, source_sha256: str,
    ) -> Path:
        safe_kind = re.sub(r"[^a-z0-9-]+", "-", kind.lower()).strip("-")
        kind_code = (
            "r" if safe_kind == "regional" else
            "l" + safe_kind.rsplit("-", 1)[-1]
        )
        return (
            run_path / "outputs" / "pah"
            / f"{kind_code}-{source_sha256[:24]}.json"
        )

    @classmethod
    def _save_planning_hierarchy_checkpoint(
        cls, run_path: Path, *, kind: str, source_sha256: str,
        expected_segments: list[int], expected_event_ids: list[str], receipt: dict,
    ) -> None:
        normalized_json = json.dumps(
            receipt, ensure_ascii=False, sort_keys=True, separators=(",", ":"),
        )
        payload = {
            "version": 1,
            "kind": kind,
            "source_sha256": source_sha256,
            "expected_segments": expected_segments,
            "expected_event_ids": expected_event_ids,
            "receipt_sha256": hashlib.sha256(
                normalized_json.encode("utf-8"),
            ).hexdigest(),
            "receipt": receipt,
        }
        atomic_write(
            cls._planning_hierarchy_checkpoint_path(
                run_path, kind=kind, source_sha256=source_sha256,
            ),
            json.dumps(payload, ensure_ascii=False, indent=2, sort_keys=True),
        )

    def _load_planning_hierarchy_checkpoint(
        self, run_id: str, run_path: Path, project: Project, *, kind: str,
        source_sha256: str, expected_segments: list[int],
        expected_event_ids: list[str], inherited: list[dict] | None = None,
    ) -> dict | None:
        """Reuse only a unique, hash-bound completed hierarchy packet.

        New checkpoints use an explicit envelope.  Legacy stage outputs are
        also inspected so a task interrupted before this format existed can
        still resume without replaying already paid, fully validated packets.
        Conflicting valid receipts are treated as ambiguous and regenerated.
        """
        runs_root = project.path / "runs"
        json_paths = list(runs_root.glob(
            "*/outputs/pah/*.json",
        ))
        markdown_paths = list(runs_root.glob(
            "*/outputs/review-plan-adaptation-hierarchy-*.md",
        ))
        candidates: dict[str, tuple[dict, Path]] = {}

        for path in [*json_paths, *markdown_paths]:
            try:
                raw = path.read_text(encoding="utf-8")
                if path.suffix.lower() == ".json":
                    envelope = json.loads(raw)
                    if (
                        not isinstance(envelope, dict)
                        or envelope.get("version") != 1
                        or envelope.get("kind") != kind
                        or envelope.get("source_sha256") != source_sha256
                        or envelope.get("expected_segments") != expected_segments
                        or envelope.get("expected_event_ids") != expected_event_ids
                    ):
                        continue
                    payload = envelope.get("receipt")
                    normalized_json = json.dumps(
                        payload, ensure_ascii=False, sort_keys=True,
                        separators=(",", ":"),
                    )
                    if envelope.get("receipt_sha256") != hashlib.sha256(
                        normalized_json.encode("utf-8"),
                    ).hexdigest():
                        continue
                else:
                    payload = parse_json_object(
                        raw, label="Stored planning hierarchy receipt",
                    )
                receipt = self._normalize_planning_hierarchy_receipt(
                    payload,
                    source_sha256=source_sha256,
                    expected_segments=expected_segments,
                    expected_event_ids=expected_event_ids,
                    inherited=inherited,
                )
            except (OSError, UnicodeError, TypeError, ValueError, json.JSONDecodeError):
                continue
            canonical = json.dumps(
                receipt, ensure_ascii=False, sort_keys=True, separators=(",", ":"),
            )
            digest = hashlib.sha256(canonical.encode("utf-8")).hexdigest()
            candidates.setdefault(digest, (receipt, path))

        if len(candidates) > 1:
            self.db.add_run_event(
                run_id, "warning", "planning_adaptation_hierarchy_checkpoint_ambiguous",
                "发现同一规划审核输入的多份冲突回执，已放弃复用并重新审核",
                stage="review", metadata={
                    "kind": kind,
                    "source_sha256": source_sha256,
                    "candidate_count": len(candidates),
                },
            )
            return None
        if not candidates:
            return None
        receipt, source_path = next(iter(candidates.values()))
        self._save_planning_hierarchy_checkpoint(
            run_path,
            kind=kind,
            source_sha256=source_sha256,
            expected_segments=expected_segments,
            expected_event_ids=expected_event_ids,
            receipt=receipt,
        )
        try:
            source_run = source_path.relative_to(runs_root).parts[0]
        except (ValueError, IndexError):
            source_run = "unknown"
        self.db.add_run_event(
            run_id, "info", "planning_adaptation_hierarchy_checkpoint_reused",
            "已复用哈希一致的规划分层审核包，仅继续未完成范围",
            stage="review", metadata={
                "kind": kind,
                "source_sha256": source_sha256,
                "segments": expected_segments,
                "event_ids": expected_event_ids,
                "source_run": source_run,
            },
        )
        return receipt

    async def _planning_adaptation_hierarchical_context(
        self, run_id: str, run_path: Path, project: Project, constraints: str,
        *, plan: str, formal_contracts: list[dict],
        segment_receipts: list[dict], segment_count: int,
        token_limit: int, suffix: str,
    ) -> tuple[str, dict, int]:
        """Review lossless overlapping scopes, then reduce their bound receipts."""
        index_skeleton = self._stage_story_skeleton(
            project, constraints, run_path, index_only=True,
        )
        segment_units = self._planning_adaptation_whole_units(
            plan=plan,
            formal_contracts=formal_contracts,
            segment_receipts=segment_receipts,
            segment_count=segment_count,
        )
        if not segment_units:
            raise ValueError("整篇规划无法建立完整的分层审核输入")

        packet_limit = max(1_200, int(token_limit * 0.68))
        units: list[dict] = []
        for segment_unit in segment_units:
            if estimate_input_tokens(json.dumps(
                segment_unit, ensure_ascii=False, separators=(",", ":"),
            )) <= packet_limit:
                units.append(segment_unit)
                continue
            reviews_by_id = {
                str(item.get("event_id") or "").strip().upper(): item
                for item in segment_unit["event_reviews"]
            }
            contracts_by_id = {
                str(item.get("id") or "").strip().upper(): item
                for item in segment_unit["formal_contracts"]
            }
            for position, event_id in enumerate(segment_unit["event_ids"]):
                event_unit = {
                    "segment": segment_unit["segment"],
                    "segment_sha256": segment_unit["segment_sha256"],
                    "event_ids": [event_id],
                    "formal_contracts": [contracts_by_id[event_id]],
                    "opening": segment_unit["opening"] if position == 0 else "",
                    "handoff": (
                        segment_unit["handoff"]
                        if position == len(segment_unit["event_ids"]) - 1 else ""
                    ),
                    "local_receipt_sha256": segment_unit[
                        "local_receipt_sha256"
                    ],
                    "event_reviews": [reviews_by_id[event_id]],
                }
                if estimate_input_tokens(json.dumps(
                    event_unit, ensure_ascii=False, separators=(",", ":"),
                )) > packet_limit:
                    raise ValueError(
                        f"正式规划第 {segment_unit['segment']} 段的单个事件超过"
                        "当前审核模型可安全承载的上下文范围"
                    )
                units.append(event_unit)

        expected_event_ids = [
            str(item.get("id") or "").strip().upper()
            for item in formal_contracts
        ]
        owned_event_groups = [list(unit.get("event_ids") or []) for unit in units]
        covered_segments = sorted({
            int(unit.get("segment")) for unit in units
            if isinstance(unit.get("segment"), int)
        })
        if not self._planning_hierarchy_event_coverage_valid(
            owned_event_groups, expected_event_ids,
        ):
            raise ValueError(
                "规划分层审核的基础单元存在正式事件遗漏、非相邻重复归属或顺序变化"
            )
        if covered_segments != list(range(1, segment_count + 1)):
            raise ValueError("规划分层审核的基础单元没有覆盖全部正式分段")
        for unit in units:
            unit_event_ids = list(unit.get("event_ids") or [])
            contract_ids = [
                str(item.get("id") or "").strip().upper()
                for item in unit.get("formal_contracts", [])
                if isinstance(item, dict)
            ]
            review_ids = [
                str(item.get("event_id") or "").strip().upper()
                for item in unit.get("event_reviews", [])
                if isinstance(item, dict)
            ]
            if contract_ids != unit_event_ids or review_ids != unit_event_ids:
                raise ValueError(
                    "规划分层审核单元没有同时保留完整正式合同和局部审核回执"
                )
            if any(
                not isinstance(item.get("plan_evidence"), list)
                or not item.get("plan_evidence")
                for item in unit.get("event_reviews", [])
                if isinstance(item, dict)
            ):
                raise ValueError("规划分层审核单元缺少精确规划原文证据")

        batches = review_evidence_batches(
            units, token_limit=packet_limit, overlap=1,
        )
        expected_unit_keys = {
            self._planning_hierarchy_unit_key(unit) for unit in units
        }
        batch_unit_keys = {
            self._planning_hierarchy_unit_key(unit)
            for batch in batches
            for unit in batch
        }
        if batch_unit_keys != expected_unit_keys:
            raise ValueError("规划分层审核区域包没有完整覆盖全部正式分段与事件单元")
        regional: list[dict] = []
        protocol_retries = 0
        for batch_number, batch in enumerate(batches, 1):
            expected_segments, expected_event_ids = (
                self._planning_hierarchy_coverage(batch)
            )
            source = json.dumps(
                batch, ensure_ascii=False, separators=(",", ":"),
            )
            source_sha256 = hashlib.sha256(source.encode("utf-8")).hexdigest()
            stored_receipt = self._load_planning_hierarchy_checkpoint(
                run_id, run_path, project,
                kind="regional",
                source_sha256=source_sha256,
                expected_segments=expected_segments,
                expected_event_ids=expected_event_ids,
            )
            if stored_receipt is not None:
                regional.append(stored_receipt)
                continue
            last_error = ""
            attempt_plan = self._protocol_receipt_attempt_plan(
                "review", same_route_attempts=2,
            )
            for attempt in attempt_plan:
                if attempt.use_configured_fallback:
                    self._record_protocol_receipt_fallback(
                        run_id, stage="review",
                        boundary="planning_adaptation_regional_receipt",
                        unit_metadata={
                            "batch_number": batch_number,
                            "segment_count": len(expected_segments),
                            "event_count": len(expected_event_ids),
                            "source_sha256": source_sha256,
                        },
                        issues=[last_error] if last_error else [],
                    )
                prompt = (
                    "SHORT_PLAN_ADAPTATION_REGIONAL_REVIEW_V3\n"
                    "审核一个完整、连续且与相邻包重叠的规划范围。不得改写。输入包保留了"
                    "当前范围的正式事件合同、精确规划证据、段首入口、段末交接和局部审核"
                    "回执。返回一个 JSON 对象，字段为 source_sha256、segment_numbers、"
                    "event_ids、causal_order_preserved、adjacent_handoffs_preserved、"
                    "knowledge_progression_preserved、relationship_progression_preserved、"
                    "viewpoint_timeline_preserved、promises_ending_preserved、"
                    "formal_direction_preserved、affected_segments、affected_event_ids、"
                    "entry_state、exit_state、knowledge_state、relationship_state、"
                    "viewpoint_timeline、open_promises、resolved_promises、reason、summary。"
                    "所有状态摘要必须忠实反映输入范围，不得补造未知事实；若有问题必须给出"
                    "最小受影响分段和事件。\n"
                    f"SOURCE SHA256: {source_sha256}\n"
                    f"EXPECTED SEGMENTS: {json.dumps(expected_segments)}\n"
                    f"EXPECTED EVENT IDS: {json.dumps(expected_event_ids)}\n\n"
                    f"ORDERED LOSSLESS REVIEW UNITS:\n{source}"
                )
                if last_error:
                    prompt += (
                        "\n\n上一份回执仅存在协议错误，输入规划保持不变："
                        + last_error[:600]
                    )
                raw, route_failure = await self._execute_protocol_receipt_attempt(
                    run_id, stage="review",
                    boundary="planning_adaptation_regional_receipt",
                    attempt=attempt,
                    unit_metadata={
                        "batch_number": batch_number,
                        "segment_count": len(expected_segments),
                        "event_count": len(expected_event_ids),
                        "source_sha256": source_sha256,
                    },
                    operation=lambda: self._stage(
                        run_id, run_path, project, "review", constraints, prompt,
                        suffix=(
                            f"-plan-adaptation-hierarchy-{suffix}-regional-"
                            f"{batch_number:02d}-{attempt.attempt_index}"
                            + ("-fallback" if attempt.use_configured_fallback else "")
                        ),
                        allow_tools=False,
                        prefer_configured_fallback=attempt.use_configured_fallback,
                        primary_only=not attempt.use_configured_fallback,
                        defer_route_failure_audit=True,
                        protocol_system_contract=IMMUTABLE_RECEIPT_SYSTEM,
                        expected_output_characters=max(
                            1400, 180 * len(expected_event_ids),
                        ),
                        completion_check=lambda value: (
                            self._planning_hierarchy_receipt_complete(
                                value,
                                source_sha256=source_sha256,
                                expected_segments=expected_segments,
                                expected_event_ids=expected_event_ids,
                            )
                        ),
                        route_capacity_guard=True,
                        story_skeleton_override=index_skeleton,
                        bounded_protocol_output=True,
                    ),
                )
                if route_failure is not None:
                    last_error = route_failure.code
                    if not attempt.is_last:
                        protocol_retries += 1
                        continue
                    raise ProtocolReceiptRouteExhaustedError(route_failure)
                try:
                    payload = self._convert_generated_object(
                        raw, run_path,
                        contract_name="planning_adaptation_hierarchy",
                    )
                    receipt = self._normalize_planning_hierarchy_receipt(
                        payload,
                        source_sha256=source_sha256,
                        expected_segments=expected_segments,
                        expected_event_ids=expected_event_ids,
                    )
                except (TypeError, ValueError, json.JSONDecodeError) as exc:
                    last_error = str(exc)
                    if not attempt.is_last:
                        protocol_retries += 1
                        continue
                    raise ValueError(
                        "规划分层区域审核回执在重试后仍不完整："
                        + last_error[:500]
                    ) from exc
                self._save_planning_hierarchy_checkpoint(
                    run_path,
                    kind="regional",
                    source_sha256=source_sha256,
                    expected_segments=expected_segments,
                    expected_event_ids=expected_event_ids,
                    receipt=receipt,
                )
                regional.append(receipt)
                break

        levels: list[dict] = []
        current = regional
        for level in range(1, 6):
            evidence = json.dumps(
                current, ensure_ascii=False, separators=(",", ":"),
            )
            coverage = [{
                "segment": item["segment"],
                "segment_sha256": item["segment_sha256"],
                "event_ids": item["event_ids"],
                "opening_sha256": hashlib.sha256(
                    item["opening"].encode("utf-8"),
                ).hexdigest(),
                "handoff_sha256": hashlib.sha256(
                    item["handoff"].encode("utf-8"),
                ).hexdigest(),
                "local_receipt_sha256": item["local_receipt_sha256"],
            } for item in segment_units]
            final_context = (
                "HASH-BOUND HIERARCHICAL WHOLE-PLAN EVIDENCE:\n" + evidence
                + "\n\nCOMPLETE COVERAGE MANIFEST:\n"
                + json.dumps(coverage, ensure_ascii=False, separators=(",", ":"))
                + "\n\nFORMAL OPENING STATE:\n" + segment_units[0]["opening"]
                + "\n\nFORMAL FINAL HANDOFF:\n" + segment_units[-1]["handoff"]
            )
            if estimate_input_tokens(final_context) <= token_limit:
                inherited_invalid = sorted({
                    field for item in current for field in WHOLE_STORY_FIELDS
                    if item.get(field) is False
                })
                inherited_segments = sorted({
                    segment for item in current
                    for segment in item.get("affected_segments", [])
                    if isinstance(segment, int)
                })
                inherited_event_ids = {
                    str(event_id).upper() for item in current
                    for event_id in item.get("affected_event_ids", [])
                    if str(event_id).strip()
                }
                return final_context, {
                    "regional_packets": len(regional),
                    "levels": levels,
                    "covered_segments": list(range(1, segment_count + 1)),
                    "covered_event_ids": [
                        str(item.get("id") or "").strip().upper()
                        for item in formal_contracts
                    ],
                    "inherited_invalid_dimensions": inherited_invalid,
                    "inherited_affected_segments": inherited_segments,
                    "inherited_affected_event_ids": [
                        str(item.get("id") or "").strip().upper()
                        for item in formal_contracts
                        if str(item.get("id") or "").strip().upper()
                        in inherited_event_ids
                    ],
                }, protocol_retries
            reduction_batches = review_evidence_batches(
                current, token_limit=packet_limit, overlap=1,
            )
            if len(reduction_batches) >= len(current) and all(
                len(batch) == 1 for batch in reduction_batches
            ):
                raise ValueError("规划分层审核证据无法在安全上下文内继续归并")
            reduced: list[dict] = []
            for batch_number, batch in enumerate(reduction_batches, 1):
                expected_segments, expected_event_ids = (
                    self._planning_hierarchy_coverage(batch)
                )
                source = json.dumps(
                    batch, ensure_ascii=False, separators=(",", ":"),
                )
                source_sha256 = hashlib.sha256(
                    source.encode("utf-8"),
                ).hexdigest()
                checkpoint_kind = f"reduction-level-{level}"
                stored_receipt = self._load_planning_hierarchy_checkpoint(
                    run_id, run_path, project,
                    kind=checkpoint_kind,
                    source_sha256=source_sha256,
                    expected_segments=expected_segments,
                    expected_event_ids=expected_event_ids,
                    inherited=batch,
                )
                if stored_receipt is not None:
                    reduced.append(stored_receipt)
                    continue
                last_error = ""
                attempt_plan = self._protocol_receipt_attempt_plan(
                    "review", same_route_attempts=2,
                )
                for attempt in attempt_plan:
                    if attempt.use_configured_fallback:
                        self._record_protocol_receipt_fallback(
                            run_id, stage="review",
                            boundary="planning_adaptation_hierarchy_reduction",
                            unit_metadata={
                                "level": level,
                                "batch_number": batch_number,
                                "segment_count": len(expected_segments),
                                "event_count": len(expected_event_ids),
                                "source_sha256": source_sha256,
                            },
                            issues=[last_error] if last_error else [],
                        )
                    prompt = (
                        "SHORT_PLAN_ADAPTATION_HIERARCHY_REDUCTION_V3\n"
                        "合并相邻且有重叠的规划审核回执，不得改写规划、不得消除下层已确认的"
                        "结构问题。返回与区域审核相同字段的一个 JSON 对象，并准确回显"
                        "source_sha256、segment_numbers 和 event_ids。状态摘要必须覆盖整个输入包；"
                        "下层任一不变量为 false 时对应字段必须保持 false。\n"
                        f"SOURCE SHA256: {source_sha256}\n"
                        f"EXPECTED SEGMENTS: {json.dumps(expected_segments)}\n"
                        f"EXPECTED EVENT IDS: {json.dumps(expected_event_ids)}\n\n"
                        f"ORDERED HASH-BOUND RECEIPTS:\n{source}"
                    )
                    if last_error:
                        prompt += (
                            "\n\n上一份输出只有回执协议缺陷；保持不可变证据，"
                            "只返回完整修正后的回执：\n" + last_error[:600]
                        )
                    raw, route_failure = await self._execute_protocol_receipt_attempt(
                        run_id, stage="review",
                        boundary="planning_adaptation_hierarchy_reduction",
                        attempt=attempt,
                        unit_metadata={
                            "level": level,
                            "batch_number": batch_number,
                            "segment_count": len(expected_segments),
                            "event_count": len(expected_event_ids),
                            "source_sha256": source_sha256,
                        },
                        operation=lambda: self._stage(
                            run_id, run_path, project, "review", constraints, prompt,
                            suffix=(
                                f"-plan-adaptation-hierarchy-{suffix}-level-{level}-"
                                f"{batch_number:02d}-{attempt.attempt_index}"
                                + (
                                    "-fallback"
                                    if attempt.use_configured_fallback else ""
                                )
                            ),
                            allow_tools=False,
                            prefer_configured_fallback=(
                                attempt.use_configured_fallback
                            ),
                            primary_only=not attempt.use_configured_fallback,
                            defer_route_failure_audit=True,
                            protocol_system_contract=IMMUTABLE_RECEIPT_SYSTEM,
                            expected_output_characters=max(
                                1400, 160 * len(expected_event_ids),
                            ),
                            completion_check=lambda value: (
                                self._planning_hierarchy_receipt_complete(
                                    value,
                                    source_sha256=source_sha256,
                                    expected_segments=expected_segments,
                                    expected_event_ids=expected_event_ids,
                                    inherited=batch,
                                )
                            ),
                            route_capacity_guard=True,
                            story_skeleton_override=index_skeleton,
                            bounded_protocol_output=True,
                        ),
                    )
                    if route_failure is not None:
                        last_error = route_failure.code
                        if not attempt.is_last:
                            protocol_retries += 1
                            continue
                        raise ProtocolReceiptRouteExhaustedError(route_failure)
                    try:
                        payload = self._convert_generated_object(
                            raw, run_path,
                            contract_name="planning_adaptation_hierarchy",
                        )
                        receipt = self._normalize_planning_hierarchy_receipt(
                            payload,
                            source_sha256=source_sha256,
                            expected_segments=expected_segments,
                            expected_event_ids=expected_event_ids,
                            inherited=batch,
                        )
                    except (TypeError, ValueError, json.JSONDecodeError) as exc:
                        last_error = str(exc)
                        if not attempt.is_last:
                            protocol_retries += 1
                            continue
                        raise ValueError(
                            "规划分层归并回执在同路重试和备用模型后仍不完整"
                        ) from exc
                    self._save_planning_hierarchy_checkpoint(
                        run_path,
                        kind=checkpoint_kind,
                        source_sha256=source_sha256,
                        expected_segments=expected_segments,
                        expected_event_ids=expected_event_ids,
                        receipt=receipt,
                    )
                    reduced.append(receipt)
                    break
            levels.append({
                "level": level,
                "input_receipts": len(current),
                "output_receipts": len(reduced),
            })
            current = reduced
        raise ValueError("规划分层审核超过安全归并深度")

    async def _review_short_plan_adaptation_whole(
        self, run_id: str, run_path: Path, project: Project, constraints: str,
        *, outline_sha256: str, planning_sha256: str,
        formal_contracts: list[dict], plan: str,
        segment_receipts: list[dict], segment_count: int, suffix: str,
        authority_version: int = PLANNING_ADAPTATION_VERSION,
    ) -> tuple[dict, list[dict], int]:
        authority_sha256 = planning_adaptation_whole_authority_sha256(
            outline_sha256=outline_sha256,
            planning_sha256=planning_sha256,
            segment_receipts=segment_receipts,
            version=authority_version,
        )
        expected_event_ids = [
            str(item.get("id") or "").strip().upper()
            for item in formal_contracts
        ]
        stored = self._revalidate_stored_planning_adaptation_whole(
            run_path,
            authority_sha256=authority_sha256,
            planning_sha256=planning_sha256,
            segment_count=segment_count,
            expected_event_ids=expected_event_ids,
            authority_version=authority_version,
        )
        if stored is not None:
            receipt, issues, source = stored
            self.db.add_run_event(
                run_id, "info", "planning_adaptation_whole_receipt_revalidated",
                "已有整篇规划适配回执已按当前跨段不变量完成本地重新验收",
                stage="review", metadata={"source": source, "issues": issues},
            )
            return receipt, issues, 0
        last_issues: list[dict] = []
        protocol_retries = 0
        context_window = self._route_safe_context_window(
            "review", include_configured_fallback=True,
        )
        token_limit = max(2_000, int(context_window * 0.40))
        whole_context, context_mode, context_tokens = (
            self._planning_adaptation_whole_context(
                plan=plan,
                formal_contracts=formal_contracts,
                segment_receipts=segment_receipts,
                segment_count=segment_count,
                token_limit=token_limit,
            )
        )
        hierarchy_metadata: dict = {}
        if context_mode == "hierarchical_required":
            whole_context, hierarchy_metadata, retries = (
                await self._planning_adaptation_hierarchical_context(
                    run_id, run_path, project, constraints,
                    plan=plan,
                    formal_contracts=formal_contracts,
                    segment_receipts=segment_receipts,
                    segment_count=segment_count,
                    token_limit=token_limit,
                    suffix=suffix,
                )
            )
            protocol_retries += retries
            context_mode = "hierarchical"
            context_tokens = estimate_input_tokens(whole_context)
        elif context_tokens > token_limit:
            raise ValueError(
                "整篇规划审核的完整权威无法在当前模型上下文中安全表达"
            )
        if context_mode != "full":
            self.db.add_run_event(
                run_id, "info", "planning_adaptation_whole_context_reduced",
                "整篇规划审核输入接近模型上下文安全线，已按完整事件和交接权威生成哈希绑定结构图",
                stage="review", metadata={
                    "mode": context_mode,
                    "estimated_tokens": context_tokens,
                    "token_limit": token_limit,
                    "segment_count": segment_count,
                    **hierarchy_metadata,
                },
            )
        index_skeleton = self._stage_story_skeleton(
            project, constraints, run_path, index_only=True,
        )
        attempt_plan = self._protocol_receipt_attempt_plan(
            "review", same_route_attempts=3,
        )
        for attempt in attempt_plan:
            if attempt.use_configured_fallback:
                self._record_protocol_receipt_fallback(
                    run_id, stage="review",
                    boundary="planning_adaptation_whole_receipt",
                    unit_metadata={
                        "segment_count": segment_count,
                        "event_count": len(expected_event_ids),
                        "authority_sha256": authority_sha256,
                    },
                    issues=last_issues,
                )
            prompt = (
                "SHORT_PLAN_ADAPTATION_WHOLE_STORY_REVIEW_V2\n"
                "各正式段已经分别通过等价展开核对。现在只审核它们合并后的整篇关系，"
                "防止两个局部都合理的调整组合后破坏因果、相邻交接、人物知情、关系推进、"
                "视角/时间线、伏笔回收或确认结局。只返回一个 JSON 对象。\n"
                "字段：authority_sha256、planning_sha256、segment_numbers、event_ids、"
                "causal_order_preserved、adjacent_handoffs_preserved、knowledge_progression_preserved、"
                "relationship_progression_preserved、viewpoint_timeline_preserved、"
                "promises_ending_preserved、formal_direction_preserved、affected_segments、"
                "affected_event_ids、reason、summary。所有无问题布尔值必须为 true；"
                "若有问题，affected_segments 和 affected_event_ids 必须准确指出最小修正范围。\n"
                "Review adjacent handoffs separately from local event realization. A changed "
                "neighbor boundary does not invalidate an otherwise byte-identical local "
                "receipt, but any cross-segment causal or state mismatch must be reported here.\n"
                "Unknown formal actor, viewpoint, time, location, knowledge, or relationship "
                "fields must remain unknown; do not invent a canon fact to force agreement.\n"
                f"EXPECTED AUTHORITY SHA256: {authority_sha256}\n"
                f"EXPECTED PLANNING SHA256: {planning_sha256}\n"
                f"EXPECTED AUTHORITY VERSION: {authority_version}\n"
                "EXPECTED SEGMENTS:\n"
                + json.dumps(list(range(1, segment_count + 1)), ensure_ascii=False)
                + "\n\nEXPECTED EVENT IDS:\n"
                + json.dumps(expected_event_ids, ensure_ascii=False)
                + "\n\n" + whole_context
            )
            if last_issues:
                prompt += (
                    "\n\nRECEIPT PROTOCOL ISSUES:\n"
                    + json.dumps(last_issues, ensure_ascii=False, indent=2)
                    + "\n规划与分段回执保持不变，只重新返回完整整篇审核回执。"
                )
            raw, route_failure = await self._execute_protocol_receipt_attempt(
                run_id, stage="review",
                boundary="planning_adaptation_whole_receipt",
                attempt=attempt,
                unit_metadata={
                    "segment_count": segment_count,
                    "event_count": len(expected_event_ids),
                    "authority_sha256": authority_sha256,
                },
                operation=lambda: self._stage(
                    run_id, run_path, project, "review", constraints, prompt,
                    suffix=(
                        f"-plan-adaptation-whole-{suffix}-{attempt.attempt_index}"
                        + ("-fallback" if attempt.use_configured_fallback else "")
                    ),
                    allow_tools=False,
                    prefer_configured_fallback=attempt.use_configured_fallback,
                    primary_only=not attempt.use_configured_fallback,
                    defer_route_failure_audit=True,
                    protocol_system_contract=IMMUTABLE_RECEIPT_SYSTEM,
                    expected_output_characters=max(1200, 110 * len(expected_event_ids)),
                    completion_check=lambda value: (
                        self._planning_adaptation_whole_receipt_complete(
                            value,
                            authority_sha256=authority_sha256,
                            planning_sha256=planning_sha256,
                            authority_version=authority_version,
                            segment_count=segment_count,
                            expected_event_ids=expected_event_ids,
                        )
                    ),
                    route_capacity_guard=True,
                    story_skeleton_override=index_skeleton,
                    bounded_protocol_output=True,
                ),
            )
            if route_failure is not None:
                last_issues = [{
                    "code": route_failure.code,
                    "failure_class": route_failure.failure_class.value,
                }]
                if not attempt.is_last:
                    protocol_retries += 1
                    continue
                raise ProtocolReceiptRouteExhaustedError(route_failure)
            try:
                payload = self._convert_generated_object(
                    raw, run_path,
                    contract_name="planning_adaptation_whole",
                )
            except (TypeError, ValueError, json.JSONDecodeError) as exc:
                receipt: object = {}
                last_issues = [{
                    "code": "whole_receipt_schema", "message": str(exc)[:500],
                }]
            else:
                receipt = normalize_planning_adaptation_whole_receipt(payload)
                if isinstance(receipt, dict):
                    receipt["authority_version"] = authority_version
                    inherited_invalid = hierarchy_metadata.get(
                        "inherited_invalid_dimensions", [],
                    )
                    if inherited_invalid:
                        for field in inherited_invalid:
                            if field in WHOLE_STORY_FIELDS:
                                receipt[field] = False
                        receipt["affected_segments"] = sorted({
                            *(receipt.get("affected_segments") or []),
                            *hierarchy_metadata.get(
                                "inherited_affected_segments", [],
                            ),
                        })
                        affected_ids = {
                            str(value).upper()
                            for value in (receipt.get("affected_event_ids") or [])
                            if str(value).strip()
                        } | {
                            str(value).upper()
                            for value in hierarchy_metadata.get(
                                "inherited_affected_event_ids", []
                            )
                            if str(value).strip()
                        }
                        receipt["affected_event_ids"] = [
                            event_id for event_id in expected_event_ids
                            if event_id in affected_ids
                        ]
                        if not str(receipt.get("reason") or "").strip():
                            receipt["reason"] = (
                                "分层区域审核已经确认存在跨段结构问题。"
                            )
                last_issues = planning_adaptation_whole_receipt_issues(
                    receipt,
                    authority_sha256=authority_sha256,
                    planning_sha256=planning_sha256,
                    segment_count=segment_count,
                    expected_event_ids=expected_event_ids,
                )
                protocol_issues = [
                    item for item in last_issues
                    if str(item.get("code") or "") in PLANNING_ADAPTATION_PROTOCOL_CODES
                ]
                if not protocol_issues:
                    return dict(receipt), last_issues, protocol_retries
                last_issues = protocol_issues
            if not attempt.is_last:
                protocol_retries += 1
                self.db.add_run_event(
                    run_id, "info", "planning_adaptation_whole_receipt_retry",
                    "整篇规划保持不变，正在重新获取跨段因果与结局审核回执",
                    stage="review", metadata={
                        "attempt": attempt.attempt_index,
                        "route": attempt.route,
                        "next_route": attempt_plan[
                            attempt.attempt_index
                        ].route,
                        "issues": last_issues,
                    },
                )
                continue
            break
        return {}, last_issues, protocol_retries

    async def _review_short_plan_adaptations(
        self, run_id: str, run_path: Path, project: Project, constraints: str,
        state: dict, plan: str, formal_outline_events: list[dict],
        segment_count: int, *, suffix: str,
        generation_context_sha256: str = "",
        authority_version: int = PLANNING_ADAPTATION_VERSION,
    ) -> tuple[list[dict], dict, list[dict], int]:
        formal_contracts = self._planning_adaptation_contracts(
            state, formal_outline_events,
        )
        if not formal_contracts:
            return [], {}, [], 0
        contract_by_id = {
            str(item.get("id") or "").strip().upper(): item
            for item in formal_contracts
        }
        outline_content = str(((state.get("outline") or {}).get("content")) or "")
        outline_sha256 = hashlib.sha256(outline_content.encode("utf-8")).hexdigest()
        planning_sha256 = hashlib.sha256(plan.encode("utf-8")).hexdigest()
        authority_event_ids = [
            str(item.get("id") or "").strip().upper()
            for item in formal_contracts
        ]
        plan_segments = self._short_plan_segments(plan, segment_count)
        receipts: list[dict] = []
        whole_receipt: dict = {}
        all_issues: list[dict] = []
        protocol_retries = 0
        for segment, plan_segment in enumerate(plan_segments, 1):
            event_ids = self._short_plan_event_ids(plan_segment)
            contracts = [
                contract_by_id[event_id] for event_id in event_ids
                if event_id in contract_by_id
            ]
            if len(contracts) != len(event_ids) or not contracts:
                all_issues.append({
                    "code": "planning_event_authority",
                    "segment": segment,
                    "message": "规划段没有完整绑定正式大纲事件合同",
                })
                continue
            receipt, issues, retries = await self._review_short_plan_adaptation_segment(
                run_id, run_path, project, constraints,
                outline_sha256=outline_sha256,
                planning_sha256=planning_sha256,
                segment=segment,
                event_contracts=contracts,
                plan_segment=plan_segment,
                suffix=suffix,
                previous_handoff=(
                    self._short_plan_handoff(plan_segments[segment - 2])
                    if segment > 1 else "opening"
                ),
                next_entry=(
                    self._short_plan_field(plan_segments[segment], "opening")
                    if segment < len(plan_segments) else "ending"
                ),
                generation_context_sha256=generation_context_sha256,
                authority_version=authority_version,
                authority_event_ids=authority_event_ids,
            )
            protocol_retries += retries
            if receipt:
                receipts.append(receipt)
            all_issues.extend({**item, "segment": segment} for item in issues)
            if any(
                str(item.get("code") or "") in PLANNING_ADAPTATION_PROTOCOL_CODES
                for item in issues
            ):
                break
        if not all_issues and len(receipts) == len(plan_segments):
            whole_receipt, whole_issues, retries = (
                await self._review_short_plan_adaptation_whole(
                    run_id, run_path, project, constraints,
                    outline_sha256=outline_sha256,
                    planning_sha256=planning_sha256,
                    formal_contracts=formal_contracts,
                    plan=plan,
                    segment_receipts=receipts,
                    segment_count=segment_count,
                    suffix=suffix,
                    authority_version=authority_version,
                )
            )
            protocol_retries += retries
            all_issues.extend(whole_issues)
        return receipts, whole_receipt, all_issues, protocol_retries

    def _planning_adaptation_artifact_valid(
        self, artifact: object, state: dict, plan: str,
        formal_outline_events: list[dict], segment_count: int,
        generation_context_sha256: str | None = None,
    ) -> bool:
        if not isinstance(artifact, dict) or artifact.get("version") not in \
                SUPPORTED_PLANNING_ADAPTATION_VERSIONS \
                or artifact.get("status") != "ready":
            return False
        authority_version = int(artifact.get("version") or 0)
        if artifact.get("issues") not in (None, []):
            return False
        outline_content = str(((state.get("outline") or {}).get("content")) or "")
        outline_sha256 = hashlib.sha256(outline_content.encode("utf-8")).hexdigest()
        planning_sha256 = hashlib.sha256(plan.encode("utf-8")).hexdigest()
        stored_generation_context = artifact.get("generation_context_sha256")
        if (
            artifact.get("outline_sha256") != outline_sha256
            or artifact.get("planning_sha256") != planning_sha256
            or artifact.get("segment_count") != segment_count
        ):
            return False
        if generation_context_sha256 is not None:
            if authority_version >= PREVIOUS_PLANNING_ADAPTATION_VERSION \
                    and stored_generation_context != generation_context_sha256:
                return False
            if authority_version == LEGACY_PLANNING_ADAPTATION_VERSION \
                    and stored_generation_context not in {
                        None, "", generation_context_sha256,
                    }:
                return False
        formal_contracts = self._planning_adaptation_contracts(
            state, formal_outline_events,
        )
        contract_by_id = {
            str(item.get("id") or "").strip().upper(): item
            for item in formal_contracts
        }
        plan_segments = self._short_plan_segments(plan, segment_count)
        receipts = artifact.get("segments")
        if not isinstance(receipts, list) or len(receipts) != len(plan_segments):
            return False
        for segment, (plan_segment, receipt) in enumerate(
            zip(plan_segments, receipts), 1,
        ):
            event_ids = self._short_plan_event_ids(plan_segment)
            contracts = [contract_by_id.get(event_id) for event_id in event_ids]
            if not event_ids or any(item is None for item in contracts):
                return False
            candidates = planning_adaptation_evidence_candidates(plan_segment, segment)
            authority_sha256 = planning_adaptation_segment_authority_sha256(
                outline_sha256=outline_sha256,
                planning_sha256=planning_sha256,
                segment=segment,
                event_contracts=[dict(item) for item in contracts if item],
                plan_segment=plan_segment,
                previous_handoff=(
                    self._short_plan_handoff(plan_segments[segment - 2])
                    if segment > 1 else "opening"
                ),
                next_entry=(
                    self._short_plan_field(plan_segments[segment], "opening")
                    if segment < len(plan_segments) else "ending"
                ),
                generation_context_sha256=str(
                    artifact.get("generation_context_sha256") or ""
                ),
                version=authority_version,
            )
            normalized = normalize_planning_adaptation_receipt(
                receipt, evidence_candidates=candidates,
            )
            if authority_version >= PLANNING_ADAPTATION_VERSION:
                expected_segment_sha256 = hashlib.sha256(
                    plan_segment.encode("utf-8"),
                ).hexdigest()
                expected_boundary_sha256 = hashlib.sha256(json.dumps({
                    "previous_handoff": (
                        self._short_plan_handoff(plan_segments[segment - 2])
                        if segment > 1 else "opening"
                    ),
                    "next_entry": (
                        self._short_plan_field(plan_segments[segment], "opening")
                        if segment < len(plan_segments) else "ending"
                    ),
                }, ensure_ascii=False, sort_keys=True, separators=(",", ":")).encode(
                    "utf-8",
                )).hexdigest()
                if (
                    not isinstance(normalized, dict)
                    or normalized.get("segment_sha256") != expected_segment_sha256
                    or normalized.get("boundary_sha256") != expected_boundary_sha256
                ):
                    return False
            if planning_adaptation_receipt_issues(
                normalized,
                authority_sha256=authority_sha256,
                planning_sha256=planning_sha256,
                segment=segment,
                expected_event_ids=event_ids,
                evidence_candidates=candidates,
                authority_version=authority_version,
                authority_event_ids=[
                    str(item.get("id") or "").strip().upper()
                    for item in formal_contracts
                ],
                plan_segment=plan_segments[segment - 1],
            ):
                return False
        whole_receipt = normalize_planning_adaptation_whole_receipt(
            artifact.get("whole_story_receipt"),
        )
        whole_authority_sha256 = planning_adaptation_whole_authority_sha256(
            outline_sha256=outline_sha256,
            planning_sha256=planning_sha256,
            segment_receipts=receipts,
            version=authority_version,
        )
        if planning_adaptation_whole_receipt_issues(
            whole_receipt,
            authority_sha256=whole_authority_sha256,
            planning_sha256=planning_sha256,
            segment_count=segment_count,
            expected_event_ids=[
                str(item.get("id") or "").strip().upper()
                for item in formal_contracts
            ],
        ):
            return False
        return True

    def _planning_recovery_feedback_token_budget(
        self, *, constraints: str, fixed_prompt: str,
        expected_output_characters: int,
    ) -> int:
        """Derive feedback capacity from the smallest configured planning route.

        The layered request includes the current contract both in Runtime's
        system envelope and in the user message.  Budget for that duplication,
        compacted constraints, Skill/system overhead, and the full output
        reserve before assigning any room to rejected-candidate evidence.
        Larger routes may therefore carry more evidence; a small or unknown
        route receives a deterministic hash-bound projection instead.
        """
        context_window = self._route_safe_context_window(
            "planning", include_configured_fallback=True,
        )
        prompt_tokens = estimate_input_tokens(fixed_prompt)
        compact_constraint_allowance = min(
            estimate_input_tokens(constraints), 5_000,
        )
        output_reserve = adaptive_output_budget(
            "planning",
            expected_output_characters=expected_output_characters,
            input_tokens=0,
            context_window=context_window,
            declared_output_ceiling=min(filter(None, (
                self._provider_output_ceiling("planning", False),
                self._provider_output_ceiling("planning", True),
            )), default=None),
        ) or 0
        safe_total = int(context_window * 0.74)
        fixed_request = (
            prompt_tokens * 2
            + compact_constraint_allowance
            + 2_048
        )
        # Feedback is also represented in the layered system packet and the
        # user prompt, so every token consumes roughly two context tokens.
        return max(256, (safe_total - output_reserve - fixed_request) // 2)

    @staticmethod
    def _planning_recovery_candidate_feedback(
        recovery_state: dict,
    ) -> list[dict]:
        """Retain actionable generation failures without making them canon."""
        result: list[dict] = []
        for item in recovery_state.get("candidates", []):
            if not isinstance(item, dict) or item.get("accepted"):
                continue
            comparison = dict(item.get("comparison") or {})
            repair_feedback = [
                dict(issue) for issue in comparison.get("repair_feedback") or []
                if isinstance(issue, dict)
            ]
            if (
                str(comparison.get("reason") or "")
                == "candidate_generation_failed"
                and not repair_feedback
            ):
                continue
            result.append({
                "source": str(item.get("source") or ""),
                "planning_sha256": str(item.get("planning_sha256") or ""),
                "issue_keys": list(item.get("issue_keys") or []),
                "introduced_issue_keys": list(
                    item.get("introduced_issue_keys") or []
                ),
                "issues": list(repair_feedback or item.get("issues") or []),
                "introduced_issues": list(
                    repair_feedback or item.get("introduced_issues") or []
                ),
                "comparison": comparison,
            })
        return result

    @staticmethod
    def _planning_recovery_feedback_for_segment(
        feedback: list[dict] | None, *, segment: int,
        segment_event_ids: dict[int, list[str]], token_budget: int = 6000,
    ) -> list[dict]:
        """Project a lossless recovery ledger into bounded actionable feedback.

        The persisted ledger remains the complete audit source. The model sees
        every stable issue key relevant to its current segment plus the useful
        structured evidence for those keys; unrelated candidate prose is never
        repeated into the prompt. If raw evidence would exceed the packet
        budget, it is replaced deterministically by hashes while semantic
        fields and issue identities remain complete.
        """
        if not feedback:
            return []
        result: list[dict] = []
        for record in feedback:
            if not isinstance(record, dict):
                continue
            records = record.get("introduced_issues") or record.get("issues")
            if not isinstance(records, list):
                records = []
            relevant: list[dict] = []
            seen_keys: set[str] = set()
            for issue in records:
                if not isinstance(issue, dict) or segment not in \
                        planning_issue_segments([issue], segment_event_ids):
                    continue
                keys = sorted(planning_issue_keys([issue]))
                identity = "|".join(keys) or hashlib.sha256(json.dumps(
                    issue, ensure_ascii=False, sort_keys=True,
                    separators=(",", ":"),
                ).encode("utf-8")).hexdigest()
                if identity in seen_keys:
                    continue
                seen_keys.add(identity)
                relevant.append(dict(issue))
            if not relevant:
                continue
            full_record = json.dumps(
                record, ensure_ascii=False, sort_keys=True,
                separators=(",", ":"),
            )
            result.append({
                "source": str(record.get("source") or ""),
                "planning_sha256": str(record.get("planning_sha256") or ""),
                "full_record_sha256": hashlib.sha256(
                    full_record.encode("utf-8"),
                ).hexdigest(),
                "relevant_issue_keys": sorted({
                    key for issue in relevant
                    for key in planning_issue_keys([issue])
                }),
                "issues": relevant,
                "comparison_reason": str(
                    (record.get("comparison") or {}).get("reason") or ""
                ),
            })

        serialized = json.dumps(result, ensure_ascii=False, separators=(",", ":"))
        if estimate_input_tokens(serialized) <= token_budget:
            return result

        # Raw rejected-plan excerpts are the largest repeated material. Their
        # hashes retain audit identity while the current best-plan anchors in
        # the repair prompt remain the only writable prose authority.
        for packet in result:
            for issue in packet.get("issues", []):
                evidence = issue.pop("plan_evidence", None)
                if evidence:
                    encoded = json.dumps(
                        evidence, ensure_ascii=False, sort_keys=True,
                        separators=(",", ":"),
                    )
                    issue["plan_evidence_sha256"] = hashlib.sha256(
                        encoded.encode("utf-8"),
                    ).hexdigest()
            packet["projection"] = "hash_bound_no_regression"
        serialized = json.dumps(result, ensure_ascii=False, separators=(",", ":"))
        if estimate_input_tokens(serialized) <= token_budget:
            return result

        # Preserve all issue identities and invariant dimensions even under a
        # pathological ledger. Descriptive messages remain in the full
        # persisted record addressed by full_record_sha256.
        compact_fields = {
            "code", "segment", "event_id", "invalid_invariants",
            "invalid_dimensions", "affected_segments", "affected_event_ids",
            "plan_evidence_ids", "classification", "changed_dimensions",
            "plan_evidence_quote",
        }
        for packet in result:
            packet["issues"] = [{
                key: value for key, value in issue.items()
                if key in compact_fields
            } for issue in packet.get("issues", [])]
            packet["projection"] = "structured_issue_manifest"
        serialized = json.dumps(result, ensure_ascii=False, separators=(",", ":"))
        if estimate_input_tokens(serialized) <= token_budget:
            return result

        # Collapse repeated candidate wrappers without losing any stable issue
        # identity. The complete records remain persisted under a ledger hash;
        # the repair model receives one canonical structured manifestation per
        # issue key plus the complete ordered key set.
        issue_by_key: dict[str, dict] = {}
        for packet in result:
            for issue in packet.get("issues", []):
                keys = sorted(planning_issue_keys([issue]))
                for key in keys:
                    issue_by_key.setdefault(key, dict(issue))
        ledger_json = json.dumps(
            result, ensure_ascii=False, sort_keys=True, separators=(",", ":"),
        )
        aggregate = [{
            "projection": "structured_issue_manifest",
            "aggregation": "deduplicated_issue_identity_manifest",
            "rejected_candidate_count": len(result),
            "ledger_sha256": hashlib.sha256(
                ledger_json.encode("utf-8"),
            ).hexdigest(),
            "full_record_sha256": hashlib.sha256(
                ledger_json.encode("utf-8"),
            ).hexdigest(),
            "relevant_issue_keys": sorted(issue_by_key),
            "issues": [issue_by_key[key] for key in sorted(issue_by_key)],
        }]
        return aggregate

    @classmethod
    def _render_short_plan_repair_packet(
        cls, current: str, *, segment: int, event_ids: list[str],
        event_body: str, opening: str | None = None,
        handoff: str | None = None,
    ) -> str:
        heading = next((
            current[match.start():current.find("\n", match.start())].strip()
            if current.find("\n", match.start()) >= 0 else current[match.start():].strip()
            for match, number in cls._short_plan_headings(current)
            if number == segment
        ), f"### 第 {segment} 段：规划修复")
        outline = cls._short_plan_field(current, "outline")
        opening_value = (
            str(opening).strip() if opening is not None
            else cls._short_plan_field(current, "opening")
        )
        handoff_value = (
            str(handoff).strip() if handoff is not None
            else cls._short_plan_field(current, "handoff")
        )
        return (
            f"{heading}\n\n"
            f"事件ID：{'、'.join(event_ids)}\n\n"
            f"大纲依据：{outline}\n\n"
            f"段首承接：{opening_value}\n\n"
            f"本段事件：\n{str(event_body or '').strip()}\n\n"
            f"段末交接：{handoff_value}"
        ).strip()

    @classmethod
    def _short_plan_event_owned_body(
        cls, current: str, event_ids: list[str],
    ) -> str:
        body = cls._short_plan_field(current, "event")
        if not body:
            return ""
        comparison = cls._short_plan_comparison_view(body)
        owned_spans: dict[str, tuple[int, int]] = {}
        event_lines: list[tuple[int, list[str]]] = []
        offset = 0
        for line in comparison.splitlines(keepends=True):
            ids = planning_event_ids(line, formal_only=True)
            if ids:
                event_lines.append((offset, ids))
            offset += len(line)
        for index, (start, ids) in enumerate(event_lines):
            if index == 0:
                start = 0
            end = event_lines[index + 1][0] if index + 1 < len(event_lines) else len(body)
            for event_id in ids:
                if event_id in owned_spans:
                    owned_spans[event_id] = (-1, -1)
                else:
                    owned_spans[event_id] = (start, end)
        selected: list[str] = []
        selected_spans: set[tuple[int, int]] = set()
        for event_id in event_ids:
            span = owned_spans.get(event_id)
            if span and span != (-1, -1) and span not in selected_spans:
                selected.append(body[span[0]:span[1]].strip())
                selected_spans.add(span)
                continue
            selected.append(
                f"（{event_id}）当前最佳规划没有可独立投影的事件正文；"
                "请只依据正式事件合同与完成清单重建本事件。"
            )
        return "\n\n".join(value for value in selected if value).strip()

    @classmethod
    def _short_plan_repair_event_projection(
        cls, current: str, *, segment: int, event_ids: list[str],
    ) -> str:
        event_body = cls._short_plan_event_owned_body(current, event_ids)
        if not event_body:
            projected, _candidates = planning_adaptation_event_projection(
                current, segment, event_ids,
            )
            event_body = cls._short_plan_field(projected, "event")
        return cls._render_short_plan_repair_packet(
            current,
            segment=segment,
            event_ids=event_ids,
            event_body=event_body,
        )

    @staticmethod
    def _renumber_short_plan_event_body(body: str) -> str:
        number = 0

        def replace(match: re.Match) -> str:
            nonlocal number
            number += 1
            return f"{match.group('indent')}{number}{match.group('separator')} "

        return re.sub(
            r"(?m)^(?P<indent>[ \t]{0,3})\d+(?P<separator>[.、．)])[ \t]*",
            replace,
            str(body or "").strip(),
        )

    @classmethod
    def _merge_short_plan_repair_packets(
        cls, current: str, *, segment: int, event_ids: list[str],
        packets: list[str],
    ) -> str:
        expected = [str(value or "").strip().upper() for value in event_ids]
        # Ownership comes from the packet's explicit declaration, never from
        # incidental IDs mentioned in its narrative body (for example a
        # forward reference to the next event).  Falling back to a single
        # unambiguous ID keeps legacy packets compatible; multiple IDs without
        # a declaration fail closed instead of guessing ownership.
        packet_ids = [cls._short_plan_declared_event_ids(packet) for packet in packets]
        flattened = [event_id for values in packet_ids for event_id in values]
        if flattened != expected or len(flattened) != len(set(flattened)):
            raise ValueError(
                f"规划第 {segment} 段容量分包没有无损覆盖原有正式事件顺序"
            )
        bodies: list[str] = []
        for packet, owned_ids in zip(packets, packet_ids):
            body = cls._canonical_short_plan_packet_event_body(
                packet, owned_ids, segment=segment,
            )
            if not body:
                raise ValueError(f"规划第 {segment} 段容量分包缺少可合并的事件正文")
            bodies.append(body)
        opening = cls._short_plan_field(packets[0], "opening")
        handoff = cls._short_plan_field(packets[-1], "handoff")
        return cls._render_short_plan_repair_packet(
            current,
            segment=segment,
            event_ids=expected,
            event_body=cls._renumber_short_plan_event_body("\n\n".join(bodies)),
            opening=opening,
            handoff=handoff,
        )

    @classmethod
    def _canonical_short_plan_packet_event_body(
        cls, packet: str, event_ids: list[str], *, segment: int,
    ) -> str:
        """Make packet ownership explicit before combining independent bodies.

        A singleton packet may omit a repeated event ID because its envelope
        already binds the complete body to one event. That representation is
        not closed under parent merge: the multi-event validator needs an
        in-body owner marker to partition siblings. Add a Runtime-owned marker
        while preserving all narrative text. Multi-event packets must already
        be independently partitionable; ambiguous bodies fail closed.
        """
        expected = [str(value or "").strip().upper() for value in event_ids]
        body = cls._short_plan_field(packet, "event").strip()
        if not body or not expected:
            return ""

        def clean(value: str) -> str:
            return remove_planning_event_ids(
                value, formal_only=True,
            ).strip()

        if len(expected) == 1:
            narrative = clean(body)
            meaningful = re.sub(r"[^0-9A-Za-z\u3400-\u9fff]+", "", narrative)
            if len(meaningful) < 8:
                return ""
            return f"1. **正式事件**（{expected[0]}）：{narrative}"

        body_issues = planning_event_body_issues(packet, expected)
        if body_issues:
            raise GeneratedArtifactShapeError(
                f"planning segment {segment} packet merge has ambiguous event body ownership",
                issues=body_issues,
            )
        parts: list[str] = []
        for event_id in expected:
            owned = cls._short_plan_event_owned_body(packet, [event_id]).strip()
            narrative = clean(owned)
            meaningful = re.sub(
                r"[^0-9A-Za-z\u3400-\u9fff]+", "", narrative,
            )
            if len(meaningful) < 8:
                raise GeneratedArtifactShapeError(
                    f"planning segment {segment} packet merge lost event {event_id} narrative body",
                    issues=[{
                        "code": "event_body_missing",
                        "event_id": event_id,
                        "segment": segment,
                        "blocking": True,
                    }],
                )
            parts.append(
                f"{len(parts) + 1}. **正式事件**（{event_id}）：{narrative}"
            )
        return "\n\n".join(parts).strip()

    @staticmethod
    def _planning_repair_packet_checkpoint_path(
        run_path: Path, *, segment: int, packet_authority_sha256: str,
    ) -> Path:
        return (
            run_path / "outputs" / "prp"
            / f"segment-{segment:02d}-{packet_authority_sha256[:24]}.json"
        )

    @classmethod
    def _save_planning_repair_packet_checkpoint(
        cls, run_path: Path, *, parent_authority_sha256: str,
        packet_authority_sha256: str, segment: int,
        event_ids: list[str], predecessor_sha256: str, block: str,
    ) -> None:
        atomic_write(
            cls._planning_repair_packet_checkpoint_path(
                run_path,
                segment=segment,
                packet_authority_sha256=packet_authority_sha256,
            ),
            json.dumps({
                "version": 1,
                "parent_authority_sha256": parent_authority_sha256,
                "packet_authority_sha256": packet_authority_sha256,
                "segment": segment,
                "event_ids": event_ids,
                "predecessor_sha256": predecessor_sha256,
                "block_sha256": hashlib.sha256(block.encode("utf-8")).hexdigest(),
                "block": block,
            }, ensure_ascii=False, indent=2, sort_keys=True),
        )

    def _load_planning_repair_packet_checkpoint(
        self, run_id: str, run_path: Path, project: Project, *,
        parent_authority_sha256: str, packet_authority_sha256: str,
        segment: int, event_ids: list[str], predecessor_sha256: str,
        completion_check: Callable[[str], bool],
    ) -> str | None:
        candidates: dict[str, tuple[str, Path]] = {}
        for path in project.path.glob("runs/*/outputs/prp/*.json"):
            try:
                envelope = json.loads(path.read_text(encoding="utf-8"))
            except (OSError, UnicodeError, json.JSONDecodeError):
                continue
            if (
                not isinstance(envelope, dict)
                or envelope.get("version") != 1
                or envelope.get("parent_authority_sha256")
                != parent_authority_sha256
                or envelope.get("packet_authority_sha256")
                != packet_authority_sha256
                or envelope.get("segment") != segment
                or envelope.get("event_ids") != event_ids
                or envelope.get("predecessor_sha256") != predecessor_sha256
            ):
                continue
            block = str(envelope.get("block") or "")
            block_sha256 = hashlib.sha256(block.encode("utf-8")).hexdigest()
            if (
                envelope.get("block_sha256") != block_sha256
                or not completion_check(block)
            ):
                continue
            candidates.setdefault(block_sha256, (block, path))
        if len(candidates) > 1:
            self.db.add_run_event(
                run_id, "warning", "planning_repair_packet_checkpoint_conflict",
                f"规划第 {segment} 段同一容量分包存在多份不同候选，已放弃复用并重新生成",
                stage="planning", metadata={
                    "segment": segment,
                    "event_ids": event_ids,
                    "candidate_count": len(candidates),
                },
            )
            return None
        if not candidates:
            return None
        block, source = next(iter(candidates.values()))
        self.db.add_run_event(
            run_id, "info", "planning_repair_packet_checkpoint_reused",
            f"已复用哈希一致的规划第 {segment} 段事件重建分包",
            stage="planning", metadata={
                "segment": segment,
                "event_ids": event_ids,
                "source_run_id": source.parents[2].name,
            },
        )
        return block

    @classmethod
    def _normalize_runtime_owned_short_plan_payload(
        cls, value: str, *, segment: int, event_ids: list[str],
        current: str, artifact: str,
    ) -> str:
        """Bind machine control to Runtime and retain only creative payload.

        This is the canonical write path for a protocol retry.  The model may
        serialize narrative for the exact events it was given, but it cannot
        choose the segment, ownership, outline basis, or entry/exit boundary.
        Unknown keys and ambiguous identities fail closed.
        """

        expected = [str(item or "").strip().upper() for item in event_ids]
        try:
            payload = GeneratedArtifactGateway().convert_object(
                value, contract_name="short_plan_packet",
            ).payload
        except (TypeError, ValueError, json.JSONDecodeError) as exc:
            raise GeneratedArtifactShapeError(
                f"{artifact} did not return one structured narrative payload",
            ) from exc
        if set(payload) != {"events"} or not isinstance(payload["events"], list):
            raise GeneratedArtifactShapeError(
                f"{artifact} changed the Runtime-owned structured contract",
                issues=[{
                    "code": "planning_packet_unknown_control_field",
                    "segment": segment,
                    "event_ids": expected,
                    "fields": sorted(set(payload) - {"events"}),
                    "blocking": True,
                }],
            )
        normalized_events: list[tuple[str, str]] = []
        for item in payload["events"]:
            if not isinstance(item, dict) or set(item) != {"event_id", "narrative"}:
                raise GeneratedArtifactShapeError(
                    f"{artifact} contains a malformed event narrative",
                )
            item_ids = planning_event_ids(
                str(item.get("event_id") or ""), formal_only=True,
            )
            event_id = (
                item_ids[0]
                if len(item_ids) == 1
                and planning_protocol_comparison_view(
                    item.get("event_id") or "",
                ).strip().upper() == item_ids[0]
                else ""
            )
            narrative = str(item.get("narrative") or "").strip()
            meaningful = re.sub(
                r"[^0-9A-Za-z\u3400-\u9fff]+", "", narrative,
            )
            if not event_id or len(meaningful) < 12:
                raise GeneratedArtifactShapeError(
                    f"{artifact} contains incomplete event narrative",
                )
            normalized_events.append((event_id, narrative))
        received = [item[0] for item in normalized_events]
        if received != expected or len(received) != len(set(received)):
            raise GeneratedArtifactShapeError(
                f"{artifact} changed ordered event ownership "
                f"(expected={expected}, received={received})",
            )
        body = "\n\n".join(
            f"{index}. **正式事件**（{event_id}）："
            + remove_planning_event_ids(narrative, formal_only=True).strip()
            for index, (event_id, narrative) in enumerate(normalized_events, 1)
        )
        normalized = cls._render_short_plan_repair_packet(
            current,
            segment=segment,
            event_ids=expected,
            event_body=body,
            opening=cls._short_plan_field(current, "opening"),
            handoff=cls._short_plan_field(current, "handoff"),
        )
        return cls._require_short_plan_segment(
            normalized, segment, artifact=f"Runtime-bound {artifact}",
        )

    async def _normalize_generated_short_plan_segment_with_protocol_retry(
        self, run_id: str, run_path: Path, project: Project, constraints: str,
        value: str, *, segment: int, event_ids: list[str], current: str,
        artifact: str, suffix: str,
    ) -> str:
        """Normalize one generated segment, retrying only its wire protocol.

        A normally finished model response can contain a complete narrative
        repair while using a previously unseen Markdown, JSON, XML, or
        provider wrapper.  That is not evidence that the story repair itself
        failed.  First apply every deterministic presentation adapter.  Only
        when those adapters cannot establish one unambiguous segment identity
        do we ask the same planning route to rewrap the already generated
        packet.  The formal scope and retained source boundaries stay fixed,
        and the returned block still re-enters the ordinary packet contract.
        """
        expected = [str(value).strip().upper() for value in event_ids]
        first_error: GeneratedArtifactShapeError | None = None
        try:
            return self._normalize_generated_short_plan_segment(
                value,
                segment=segment,
                event_ids=expected,
                current=current,
                artifact=artifact,
            )
        except GeneratedArtifactShapeError as error:
            first_error = error
            first_issues = [
                dict(item) for item in error.issues
                if isinstance(item, dict)
            ]
        assert first_error is not None

        self.db.add_run_event(
            run_id, "warning", "planning_packet_protocol_retry",
            "规划修复内容保持原范围，正在把模型返回重新封装为可校验的标准规划段",
            stage="planning", metadata={
                "segment": segment,
                "event_ids": expected,
                "artifact": artifact,
                "parser_error": str(first_error)[:500],
                "issues": first_issues,
            },
        )
        authority = {
            "segment": segment,
            "event_ids": expected,
            "outline_basis": self._short_plan_field(current, "outline"),
            "opening": self._short_plan_field(current, "opening"),
            "handoff": self._short_plan_field(current, "handoff"),
            "source_sha256": hashlib.sha256(
                current.encode("utf-8"),
            ).hexdigest(),
            "generated_packet_sha256": hashlib.sha256(
                str(value).encode("utf-8"),
            ).hexdigest(),
        }
        structured_contract = StructuredArtifactContract(
            name="planning_packet",
            schema={
                "type": "object",
                "properties": {
                    "events": {
                        "type": "array",
                        "items": {
                            "type": "object",
                            "properties": {
                                "event_id": {"type": "string"},
                                "narrative": {"type": "string"},
                            },
                            "required": ["event_id", "narrative"],
                            "additionalProperties": False,
                        },
                    },
                },
                "required": ["events"],
                "additionalProperties": False,
            },
            runtime_authority=authority,
        )
        prompt = (
            "SHORT_PLAN_CANONICAL_REWRAP_V1\n"
            "This is a presentation-protocol repair, not a story rewrite. "
            "Return exactly one JSON object with one field named events. Each "
            "events item must contain only event_id and narrative. Preserve "
            "the generated packet's narrative actions, "
            "reactions, results, dialogue intent, and creative detail. Do not "
            "invent, delete, summarize, or move story facts. The Runtime-owned "
            "segment identity, exact ordered event ownership, outline basis, "
            "entry state, and exit state below may not change and must not be "
            "returned by the model; Runtime binds them after validation. Descriptive "
            "references to later events may remain prose but must not become "
            "owned event IDs. Use ordinary ASCII hyphens inside event IDs. If "
            "the source packet cannot support complete narrative without "
            "invention, return an empty narrative; never fabricate authority.\n"
            f"EXPECTED SEGMENT: {segment}\n"
            "EXPECTED EVENT IDS:\n"
            + json.dumps(expected, ensure_ascii=False)
            + "\n\nCURRENT AUTHORITY (IMMUTABLE):\n"
            + json.dumps(authority, ensure_ascii=False, indent=2)
            + "\n\nFIRST PARSER FAILURE (DIAGNOSTIC ONLY):\n"
            + json.dumps({
                "message": str(first_error),
                "issues": first_issues,
            }, ensure_ascii=False, indent=2)
            + "\n\nRAW GENERATED PACKET TO REWRAP:\n"
            + str(value)
        )

        def normalize_protocol_candidate(candidate: str) -> str:
            try:
                return self._normalize_runtime_owned_short_plan_payload(
                    candidate,
                    segment=segment,
                    event_ids=expected,
                    current=current,
                    artifact=f"Runtime-owned {artifact}",
                )
            except GeneratedArtifactShapeError:
                return self._normalize_generated_short_plan_segment(
                    candidate,
                    segment=segment,
                    event_ids=expected,
                    current=current,
                    artifact=f"legacy canonical {artifact}",
                )

        def protocol_complete(candidate: str) -> bool:
            try:
                normalize_protocol_candidate(candidate)
            except GeneratedArtifactShapeError:
                return False
            return True

        rewrapped = await self._stage(
            run_id, run_path, project, "planning", constraints, prompt,
            suffix=f"{suffix}-protocol-rewrap",
            allow_tools=False,
            expected_output_characters=max(
                1200, len(str(value)) + 600,
            ),
            completion_check=protocol_complete,
            compact_input=True,
            route_capacity_guard=True,
            story_skeleton_override=self._stage_story_skeleton(
                project, constraints, run_path,
                owner_event_ids=expected, index_only=True,
            ),
            bounded_protocol_output=True,
            structured_contract=structured_contract,
        )
        try:
            normalized = normalize_protocol_candidate(rewrapped)
        except GeneratedArtifactShapeError as retry_error:
            retry_issues = [
                dict(item) for item in retry_error.issues
                if isinstance(item, dict)
            ]
            issue = {
                "code": "planning_packet_protocol_exhausted",
                "message": (
                    "planning packet protocol recovery exhausted without one "
                    "unambiguous canonical segment"
                ),
                "segment": segment,
                "event_ids": expected,
                "first_error": str(first_error)[:500],
                "retry_error": str(retry_error)[:500],
                "blocking": True,
            }
            self.db.add_run_event(
                run_id, "error", "planning_packet_protocol_exhausted",
                "规划修复内容未被改写，但同范围协议重封装仍无法形成唯一可校验规划段",
                stage="planning", metadata={
                    **issue,
                    "first_issues": first_issues,
                    "retry_issues": retry_issues,
                },
            )
            raise GeneratedArtifactShapeError(
                issue["message"], issues=[issue],
            ) from retry_error
        # Protocol recovery may reorganize presentation but never receives
        # authority to alter the retained formal shell.  Rebind every
        # Runtime-owned field deterministically and carry forward only the
        # normalized event realization from the provider result.
        normalized = self._render_short_plan_repair_packet(
            current,
            segment=segment,
            event_ids=expected,
            event_body=self._short_plan_field(normalized, "event"),
            opening=self._short_plan_field(current, "opening"),
            handoff=self._short_plan_field(current, "handoff"),
        )
        normalized = self._require_short_plan_segment(
            normalized, segment, artifact=f"authority-bound {artifact}",
        )
        self.db.add_run_event(
            run_id, "success", "planning_packet_protocol_recovered",
            "规划修复内容已在原事件范围内完成协议重封装并重新进入完整校验",
            stage="planning", metadata={
                "segment": segment,
                "event_ids": expected,
                "artifact": artifact,
                "source_sha256": authority["source_sha256"],
                "generated_packet_sha256": authority[
                    "generated_packet_sha256"
                ],
                "normalized_sha256": hashlib.sha256(
                    normalized.encode("utf-8"),
                ).hexdigest(),
            },
        )
        return normalized

    async def _repair_short_plan_adaptation_capacity_split(
        self, run_id: str, run_path: Path, project: Project, constraints: str,
        *, segment: int, current: str, event_ids: list[str],
        contract_by_id: dict[str, dict], obligation_by_id: dict[str, dict],
        current_issues: list[dict], segment_feedback: list[dict],
        previous_handoff: str, next_entry: str, attempt: int,
        details: dict,
    ) -> str:
        """Rebuild one formal segment in event-owned packets without losing authority."""
        leaf_packets: list[dict] = []
        parent_authority_sha256 = hashlib.sha256(json.dumps({
            "version": 1,
            "segment": segment,
            "segment_sha256": hashlib.sha256(current.encode("utf-8")).hexdigest(),
            "event_ids": event_ids,
            "contracts": [
                contract_by_id[event_id] for event_id in event_ids
                if event_id in contract_by_id
            ],
            "obligations": [
                obligation_by_id[event_id] for event_id in event_ids
                if event_id in obligation_by_id
            ],
            "issue_keys": sorted(planning_issue_keys(current_issues)),
            "feedback_sha256": hashlib.sha256(json.dumps(
                segment_feedback, ensure_ascii=False, sort_keys=True,
                separators=(",", ":"),
            ).encode("utf-8")).hexdigest(),
            "previous_handoff": previous_handoff,
            "next_entry": next_entry,
        }, ensure_ascii=False, sort_keys=True, separators=(",", ":")).encode(
            "utf-8"
        )).hexdigest()

        def issue_event_ids(item: dict) -> set[str]:
            values = [item.get("event_id")]
            for key in ("event_ids", "affected_event_ids"):
                raw = item.get(key)
                if isinstance(raw, list):
                    values.extend(raw)
            return {
                str(value or "").strip().upper()
                for value in values if str(value or "").strip()
            }

        def project_issues(values: list[dict], owned: list[str]) -> list[dict]:
            owned_set = set(owned)
            return [
                dict(item) for item in values
                if not issue_event_ids(item) or issue_event_ids(item) & owned_set
            ]

        def project_feedback(values: list[dict], owned: list[str]) -> list[dict]:
            result: list[dict] = []
            for raw in values:
                if not isinstance(raw, dict):
                    continue
                item = dict(raw)
                raw_issues = item.get("issues")
                if isinstance(raw_issues, list):
                    filtered = project_issues(
                        [issue for issue in raw_issues if isinstance(issue, dict)],
                        owned,
                    )
                    if not filtered:
                        continue
                    item["issues"] = filtered
                    item["relevant_issue_keys"] = sorted(
                        planning_issue_keys(filtered)
                    )
                result.append(item)
            return result

        def packet_complete(value: str, owned: list[str], source: str) -> bool:
            packet_checklists = {
                event_id: obligation_by_id[event_id]
                for event_id in owned if event_id in obligation_by_id
            }
            try:
                normalized = self._normalize_generated_short_plan_segment(
                    value,
                    segment=segment,
                    event_ids=owned,
                    current=source,
                    artifact="planning repair packet",
                )
            except GeneratedArtifactShapeError:
                return False
            return not self._short_plan_packet_contract_issues(
                normalized,
                segment=segment,
                event_ids=owned,
                source=source,
                obligation_checklists=packet_checklists,
            )

        async def repair_group(
            owned: list[str], predecessor: str | None,
        ) -> str:
            source = self._short_plan_repair_event_projection(
                current, segment=segment, event_ids=owned,
            )
            contracts = [
                contract_by_id[event_id] for event_id in owned
                if event_id in contract_by_id
            ]
            obligations = [
                obligation_by_id[event_id] for event_id in owned
                if event_id in obligation_by_id
            ]
            owned_issues = project_issues(current_issues, owned)
            owned_feedback = project_feedback(segment_feedback, owned)
            predecessor_projection = "opening"
            predecessor_sha256 = ""
            if predecessor:
                predecessor_ids = self._short_plan_event_ids(predecessor)
                predecessor_projection = self._short_plan_repair_event_projection(
                    predecessor,
                    segment=segment,
                    event_ids=predecessor_ids[-1:],
                )
                predecessor_sha256 = hashlib.sha256(
                    predecessor.encode("utf-8")
                ).hexdigest()
            packet_authority_sha256 = hashlib.sha256(json.dumps({
                "version": 1,
                "parent_authority_sha256": parent_authority_sha256,
                "segment": segment,
                "event_ids": owned,
                "predecessor_sha256": predecessor_sha256,
            }, ensure_ascii=False, sort_keys=True, separators=(",", ":")).encode(
                "utf-8"
            )).hexdigest()
            packet_prompt = (
                "SHORT_PLAN_EQUIVALENCE_SEGMENT_REBUILD_PACKET_V1\n"
                "This is one event-owned transport packet of a complete formal segment rebuild. "
                "Return only one complete segment-shaped planning block for the packet event IDs. "
                "Do not write any parent or sibling event. The Runtime will merge every packet in "
                "the original formal order and then repeat complete-segment, adjacent-boundary, "
                "and whole-plan validation.\n"
                f"EXPECTED SEGMENT: {segment}\n"
                "EXPECTED PACKET EVENT IDS:\n"
                + json.dumps(owned, ensure_ascii=False)
                + "\n\nPARENT SEGMENT EVENT IDS:\n"
                + json.dumps(event_ids, ensure_ascii=False)
                + "\n\nFORMAL EVENT CONTRACTS:\n"
                + json.dumps(contracts, ensure_ascii=False, indent=2)
                + "\n\nFORMAL EVENT COMPLETION CHECKLIST:\n"
                + json.dumps(obligations, ensure_ascii=False, indent=2)
                + "\n\nSTRUCTURAL DRIFT ISSUES FOR THIS PACKET:\n"
                + json.dumps(owned_issues, ensure_ascii=False, indent=2)
                + "\n\nREJECTED CANDIDATE NO-REGRESSION FEEDBACK:\n"
                + json.dumps(owned_feedback, ensure_ascii=False, indent=2)
                + "\n\nPARENT PREVIOUS HANDOFF:\n" + previous_handoff
                + "\n\nPARENT NEXT SEGMENT ENTRY TO PRESERVE:\n" + next_entry
                + "\n\nPREVIOUS ACCEPTED PACKET SHA256:\n" + predecessor_sha256
                + "\n\nPREVIOUS ACCEPTED PACKET EVENT PROJECTION:\n"
                + predecessor_projection
                + "\n\nCURRENT EVENT-OWNED PLAN PROJECTION:\n" + source
                + "\n\nPreserve event function, primary agency, causal dependencies, entry/exit "
                "state, knowledge and relationship progression, viewpoint, dependency-sensitive "
                "order, promises, and ending. Dialogue, description, emotion, rhythm, minor "
                "participants, local setting, and non-dependent micro-order remain creative space."
            )

            async def split_again(split_details: dict) -> str:
                return await split_group(owned, predecessor, split_details)

            stored = self._load_planning_repair_packet_checkpoint(
                run_id, run_path, project,
                parent_authority_sha256=parent_authority_sha256,
                packet_authority_sha256=packet_authority_sha256,
                segment=segment,
                event_ids=owned,
                predecessor_sha256=predecessor_sha256,
                completion_check=lambda value: packet_complete(
                    value, owned, source,
                ),
            )
            if stored is not None:
                leaf_packets.append({
                    "event_ids": list(owned),
                    "text_sha256": hashlib.sha256(
                        stored.encode("utf-8")
                    ).hexdigest(),
                    "reused": True,
                })
                return stored

            try:
                repaired = await self._stage(
                    run_id, run_path, project, "planning", constraints,
                    packet_prompt,
                    suffix=(
                        f"-adaptation-segment-rebuild-{segment:02d}-attempt-{attempt}"
                        f"-packet-{owned[0]}-{owned[-1]}"
                    ),
                    allow_tools=False,
                    expected_output_characters=max(1000, len(source) + 400),
                    completion_check=lambda value: packet_complete(
                        value, owned, source,
                    ),
                    route_capacity_guard=True,
                    capacity_splitter=split_again if len(owned) > 1 else None,
                    compact_input=True,
                    story_skeleton_override=self._stage_story_skeleton(
                        project, constraints, run_path,
                        owner_event_ids=owned, index_only=True,
                    ),
                    scoped_creative_output=True,
                )
            except Exception as exc:
                capacity_failure = (
                    isinstance(exc, ContextCapacityPreflightError)
                    or classify_model_failure(str(exc)) == "input_context_overflow"
                )
                if capacity_failure and len(owned) > 1:
                    failure_details = (
                        {
                            "pressure": exc.pressure,
                            "estimated_input_tokens": exc.estimated_input_tokens,
                            "authority_input_tokens": exc.authority_input_tokens,
                            "output_reserve": exc.output_reserve,
                            "context_window": exc.context_window,
                        }
                        if isinstance(exc, ContextCapacityPreflightError)
                        else details
                    )
                    return await split_group(
                        owned, predecessor, failure_details,
                    )
                if capacity_failure:
                    raise ValueError(
                        f"{exc}；规划第 {segment} 段事件 {owned[0]} 已是不可再拆分的"
                        "正式事件，完整事件权威已保留"
                    ) from exc
                raise
            block = await self._normalize_generated_short_plan_segment_with_protocol_retry(
                run_id, run_path, project, constraints, repaired,
                segment=segment,
                event_ids=owned,
                current=source,
                artifact="planning repair packet",
                suffix=(
                    f"-adaptation-segment-rebuild-{segment:02d}-attempt-{attempt}"
                    f"-packet-{owned[0]}-{owned[-1]}"
                ),
            )
            packet_checklists = {
                event_id: obligation_by_id[event_id]
                for event_id in owned if event_id in obligation_by_id
            }
            contract_issues = self._short_plan_packet_contract_issues(
                block,
                segment=segment,
                event_ids=owned,
                source=source,
                obligation_checklists=packet_checklists,
            )
            if contract_issues:
                raise GeneratedArtifactShapeError(
                    f"planning repair packet failed its complete event contract "
                    f"(segment={segment}, event_ids={owned}): "
                    + "; ".join(
                        str(item.get("message") or item.get("code"))
                        for item in contract_issues
                    ),
                    issues=contract_issues,
                )
            receipt = getattr(repaired, "receipt", {})
            if not isinstance(receipt, dict) or receipt.get("execution_mode") != "capacity_split":
                self._save_planning_repair_packet_checkpoint(
                    run_path,
                    parent_authority_sha256=parent_authority_sha256,
                    packet_authority_sha256=packet_authority_sha256,
                    segment=segment,
                    event_ids=owned,
                    predecessor_sha256=predecessor_sha256,
                    block=block,
                )
                leaf_packets.append({
                    "event_ids": list(owned),
                    "text_sha256": hashlib.sha256(block.encode("utf-8")).hexdigest(),
                })
            return block

        async def split_group(
            owned: list[str], predecessor: str | None, split_details: dict,
        ) -> str:
            if len(owned) <= 1:
                return await repair_group(owned, predecessor)
            left_owned, right_owned = semantic_bisect(owned)
            left_ids = list(left_owned)
            right_ids = list(right_owned)
            left = await repair_group(left_ids, predecessor)
            right = await repair_group(right_ids, left)
            return self._merge_short_plan_repair_packets(
                current,
                segment=segment,
                event_ids=owned,
                packets=[left, right],
            )

        rebuilt = (
            await split_group(event_ids, None, details)
            if len(event_ids) > 1 else
            await repair_group(event_ids, None)
        )
        self.db.add_run_event(
            run_id, "success", "planning_repair_capacity_split_completed",
            f"规划第 {segment} 段已按正式事件所有权完成重建分包并无损合并",
            stage="planning", metadata={
                "segment": segment,
                "event_ids": event_ids,
                "packet_count": len(leaf_packets),
                "packets": leaf_packets,
                "pressure": details.get("pressure"),
                "estimated_input_tokens": details.get("estimated_input_tokens"),
                "output_reserve": details.get("output_reserve"),
            },
        )
        return rebuilt

    async def _repair_short_plan_adaptation_segments(
        self, run_id: str, run_path: Path, project: Project, constraints: str,
        state: dict, plan: str, formal_outline_events: list[dict],
        segment_count: int, issues: list[dict], *, mode: str = "targeted",
        attempt: int = 1, recovery_feedback: list[dict] | None = None,
        target_segments: list[int] | None = None,
    ) -> str:
        formal_contracts = self._planning_adaptation_contracts(
            state, formal_outline_events,
        )
        outline_content = str(((state.get("outline") or {}).get("content")) or "")
        obligation_checklists = bind_planning_participant_realizations(
            narrative_outline_event_obligations(outline_content),
            narrative_participant_realizations(
                resolve_narrative_contract(project),
            ),
        )
        contract_by_id = {
            str(item.get("id") or "").strip().upper(): item
            for item in formal_contracts
        }
        obligation_by_id = {
            str(event_id or "").strip().upper(): checklist
            for event_id, checklist in obligation_checklists.items()
            if isinstance(checklist, dict)
        }
        candidate = plan
        original_segments = self._short_plan_segments(plan, segment_count)
        segment_event_ids = {
            number: self._short_plan_event_ids(block)
            for number, block in enumerate(original_segments, 1)
        }
        issue_segments = planning_issue_segments(issues, segment_event_ids)
        affected = sorted(
            segment for segment in (
                target_segments if target_segments is not None else issue_segments
            )
            if segment in issue_segments
        )
        if issues and not affected:
            raise ValueError("规划适配问题没有提供可执行的受影响分段范围")
        for segment in affected:
            plan_segments = self._short_plan_segments(candidate, segment_count)
            if not 1 <= segment <= len(plan_segments):
                continue
            current = plan_segments[segment - 1]
            event_ids = self._short_plan_event_ids(current)
            contracts = [
                contract_by_id[event_id] for event_id in event_ids
                if event_id in contract_by_id
            ]
            obligations = [
                obligation_by_id[event_id] for event_id in event_ids
                if event_id in obligation_by_id
            ]
            current_issues = [
                item for item in issues
                if segment in planning_issue_segments([item], segment_event_ids)
            ]
            previous_handoff = (
                self._short_plan_handoff(plan_segments[segment - 2])
                if segment > 1 else "opening"
            )
            next_entry = (
                self._short_plan_field(plan_segments[segment], "opening")
                if segment < len(plan_segments) else "ending"
            )
            protocol = (
                "SHORT_PLAN_EQUIVALENCE_SEGMENT_REBUILD_V2"
                if mode == "rebuild" else
                "SHORT_PLAN_EQUIVALENCE_TARGETED_REPAIR_V2"
            )
            evidence_candidates = planning_adaptation_evidence_candidates(
                current, segment,
            )
            anchor_ids = (
                planning_repair_anchor_ids(current_issues, evidence_candidates)
                if mode == "targeted" else []
            )
            issue_keys = sorted(planning_issue_keys(current_issues))
            segment_feedback: list[dict] = []
            patch_authority = ""
            repair_expected_output_characters = max(1600, len(current))
            if anchor_ids:
                patch_authority = planning_repair_patch_authority_sha256(
                    planning_sha256=hashlib.sha256(
                        candidate.encode("utf-8"),
                    ).hexdigest(),
                    segment=segment,
                    issue_keys=issue_keys,
                    anchor_ids=anchor_ids,
                )
            instruction = (
                "从正式事件合同重新构建当前完整段。当前段只作为可保留素材，不能继承其中被指出的"
                "推断、顺序、口供、视角或关系因果。先逐项落实正式事件，再补充不改变不变量的创作细节。"
                if mode == "rebuild" else
                "保留当前段已经有效的对话、细节、节奏和可写性，只修正回执指出的最小范围。"
            )
            prompt = (
                protocol + "\n"
                f"只返回完整的“### 第 {segment} 段：标题”规划块，不要返回其他段、说明或因果链。"
                + instruction
                + "不得改变主要执行者、剧情功能、因果依赖、入口/出口、知情、关系、视角、"
                "依赖性时间顺序、伏笔或结局。允许等价的触发方式、次要参与者、局部地点、"
                "对话、描写和不影响依赖的展示顺序。事件 ID 必须保持原集合和原顺序，"
                "不能提前消费后续事件。\n"
                f"EXPECTED SEGMENT: {segment}\nEXPECTED EVENT IDS:\n"
                + json.dumps(event_ids, ensure_ascii=False)
                + "\n\nFORMAL EVENT CONTRACTS:\n"
                + json.dumps(contracts, ensure_ascii=False, indent=2)
                + "\n\nFORMAL EVENT COMPLETION CHECKLIST:\n"
                + json.dumps(obligations, ensure_ascii=False, indent=2)
                + "\n\nPREVIOUS ACCEPTED HANDOFF:\n" + previous_handoff
                + "\n\nNEXT SEGMENT ENTRY TO PRESERVE:\n" + next_entry
                + "\n\nSTRUCTURAL DRIFT ISSUES:\n"
                + json.dumps(current_issues, ensure_ascii=False, indent=2)
                + "\n\nCURRENT PLAN SEGMENT:\n" + current
            )

            guardrails = (
                "\n\nGENERAL NO-REGRESSION RULES:\n"
                "- Preserve formal event function, primary agency, causal dependencies, "
                "entry/exit state, knowledge and relationship progression, viewpoint, hard "
                "timeline dependencies, promises, and ending.\n"
                "- Do not merge an executor, intermediary, investigator, witness, or hidden "
                "principal unless the formal contract explicitly says they are the same entity.\n"
                "- Do not let an earlier event complete a reveal, decision, confrontation, or "
                "state change owned by a later formal event.\n"
                "- Empty actor, viewpoint, time, location, knowledge, or relationship fields mean "
                "unknown authority. Do not invent a canonical fact and do not treat an unstated "
                "detail as a contradiction unless the formal evidence contradicts it.\n"
                "- Do not rewrite an event or passage outside the authorized issue scope.\n"
                "- Dialogue, description, emotional texture, scene rhythm, trigger method, minor "
                "participants, local setting, and non-dependent micro-order remain creative space.\n"
            )
            prompt += guardrails
            if mode == "rebuild":
                prompt += (
                    "\nREBUILD SELF-CHECK BEFORE RETURNING:\n"
                    "- For every listed structural issue, remove or rewrite the exact semantic "
                    "claim described by its reason; do not merely add a disclaimer, move the "
                    "same claim to another event, or leave it as an assumed backstory.\n"
                    "- Re-read the formal contracts in event order and verify that each event's "
                    "function, primary actor, causal dependency, entry/exit state, knowledge, "
                    "relationship, viewpoint, timeline dependency, promise, and ending role is "
                    "performed at its own event and not completed early or transferred to a "
                    "neighbor.\n"
                    "- Before returning, compare the rebuilt segment with the rejected-candidate "
                    "feedback and ensure no previously rejected invariant or newly introduced "
                    "hard issue remains in this changed segment or its formal boundary.\n"
                )
            if patch_authority:
                anchors = [{
                    "evidence_id": evidence_id,
                    "source_sha256": hashlib.sha256(
                        evidence_candidates[evidence_id].encode("utf-8"),
                    ).hexdigest(),
                    "text": evidence_candidates[evidence_id],
                } for evidence_id in anchor_ids]
                repair_expected_output_characters = max(
                    1200,
                    sum(len(anchor["text"]) for anchor in anchors) + 800,
                )
                prompt = (
                    protocol + "\nSHORT_PLAN_EVIDENCE_PATCH_V3\n"
                    "Return only one JSON object with authority_sha256, segment, replacements, "
                    "and summary. Each replacement must contain exactly one authorized "
                    "evidence_id, its source_sha256, and replacement text. Replace only the "
                    "smallest quoted anchor needed to resolve the listed issues; do not return "
                    "the full segment.\n"
                    f"EXPECTED PATCH AUTHORITY SHA256: {patch_authority}\n"
                    f"EXPECTED SEGMENT: {segment}\n"
                    "EXPECTED ISSUE KEYS:\n"
                    + json.dumps(issue_keys, ensure_ascii=False)
                    + "\n\nAUTHORIZED ORIGINAL ANCHORS:\n"
                    + json.dumps(anchors, ensure_ascii=False, indent=2)
                    + "\n\nFORMAL EVENT CONTRACTS:\n"
                    + json.dumps(contracts, ensure_ascii=False, indent=2)
                    + "\n\nFORMAL EVENT COMPLETION CHECKLIST:\n"
                    + json.dumps(obligations, ensure_ascii=False, indent=2)
                    + "\n\nPREVIOUS ACCEPTED HANDOFF:\n" + previous_handoff
                    + "\n\nNEXT SEGMENT ENTRY TO PRESERVE:\n" + next_entry
                    + "\n\nSTRUCTURAL DRIFT ISSUES:\n"
                    + json.dumps(current_issues, ensure_ascii=False, indent=2)
                    + guardrails
                )
                prompt += "\n\nCURRENT PLAN SEGMENT:\n" + current

            feedback_budget = self._planning_recovery_feedback_token_budget(
                constraints=constraints,
                fixed_prompt=prompt,
                expected_output_characters=repair_expected_output_characters,
            )
            segment_feedback = self._planning_recovery_feedback_for_segment(
                recovery_feedback,
                segment=segment,
                segment_event_ids=segment_event_ids,
                token_budget=feedback_budget,
            )
            current_authority = "\n\nCURRENT PLAN SEGMENT:\n" + current
            if current_authority in prompt:
                prompt = prompt.replace(current_authority, "", 1)
            if segment_feedback:
                prompt += (
                    "\n\nREJECTED CANDIDATE NO-REGRESSION FEEDBACK:\n"
                    + json.dumps(segment_feedback, ensure_ascii=False, indent=2)
                    + "\nThese records are failure evidence only, never story canon. "
                    "Start from the current best-plan authority in this prompt; do not inherit "
                    "wording or facts from a rejected candidate, and do not reintroduce its "
                    "issue keys.\n"
                )
            # Keep the current best segment last. Rejected-candidate evidence is
            # diagnostic only and must never be parsed as writable story text.
            prompt += current_authority

            def complete_segment(
                value: str, expected=event_ids, number=segment,
            ) -> bool:
                candidate_value = value
                if not patch_authority:
                    try:
                        candidate_value = (
                            self._normalize_generated_short_plan_segment(
                                value,
                                segment=number,
                                event_ids=expected,
                                current=current,
                                artifact="planning repair candidate",
                            )
                        )
                    except GeneratedArtifactShapeError:
                        return False
                return not self._short_plan_packet_contract_issues(
                    candidate_value,
                    segment=number,
                    event_ids=expected,
                    source=current,
                    obligation_checklists=obligation_checklists,
                )

            def normalized_patch(value: str) -> dict | None:
                if not patch_authority:
                    return None
                try:
                    payload = self._convert_generated_object(
                        value, run_path,
                        contract_name="planning_repair_patch",
                    )
                    return normalize_planning_repair_patch(
                        payload,
                        authority_sha256=patch_authority,
                        segment=segment,
                        evidence_candidates=evidence_candidates,
                        allowed_anchor_ids=anchor_ids,
                        current_segment=current,
                    )
                except (TypeError, ValueError, json.JSONDecodeError):
                    if not complete_segment(value):
                        return None
                    try:
                        full_segment = self._short_plan_segments_for_range(
                            value, segment, segment,
                        )[0]
                        return planning_repair_patch_from_segment(
                            full_segment,
                            authority_sha256=patch_authority,
                            segment=segment,
                            evidence_candidates=evidence_candidates,
                            allowed_anchor_ids=anchor_ids,
                            current_segment=current,
                        )
                    except (IndexError, ValueError):
                        return None

            def complete(value: str) -> bool:
                if patch_authority:
                    return normalized_patch(value) is not None
                return complete_segment(value)

            repaired = await self._stage(
                run_id, run_path, project, "planning", constraints, prompt,
                suffix=(
                    f"-adaptation-segment-{segment:02d}-attempt-{attempt}"
                    if mode == "targeted" else
                    f"-adaptation-segment-rebuild-{segment:02d}-attempt-{attempt}"
                ),
                allow_tools=False,
                expected_output_characters=repair_expected_output_characters,
                completion_check=complete,
                route_capacity_guard=True,
                compact_input=True,
                story_skeleton_override=self._stage_story_skeleton(
                    project, constraints, run_path,
                    owner_event_ids=event_ids, index_only=True,
                ),
                bounded_protocol_output=bool(patch_authority),
                scoped_creative_output=not bool(patch_authority),
                capacity_splitter=(
                    (lambda details: self._repair_short_plan_adaptation_capacity_split(
                        run_id, run_path, project, constraints,
                        segment=segment,
                        current=current,
                        event_ids=event_ids,
                        contract_by_id=contract_by_id,
                        obligation_by_id=obligation_by_id,
                        current_issues=current_issues,
                        segment_feedback=segment_feedback,
                        previous_handoff=previous_handoff,
                        next_entry=next_entry,
                        attempt=attempt,
                        details=details,
                    ))
                    if not patch_authority else None
                ),
            )
            if patch_authority and not complete(repaired):
                raise ValueError(f"规划第 {segment} 段定向修正没有完整返回")
            patch = normalized_patch(repaired)
            if patch is not None:
                block = apply_planning_repair_patch(
                    current, patch, evidence_candidates,
                )
                if not complete_segment(block):
                    raise ValueError(
                        f"Planning repair patch for segment {segment} changed its "
                        "formal event set or required segment fields"
                    )
            else:
                if patch_authority:
                    raise ValueError(
                        f"规划第 {segment} 段已经具备精确证据锚点，"
                        "不能退回整段改写扩大修改范围"
                    )
                block = await self._normalize_generated_short_plan_segment_with_protocol_retry(
                    run_id, run_path, project, constraints, repaired,
                    segment=segment,
                    event_ids=event_ids,
                    current=current,
                    artifact="planning repair candidate",
                    suffix=(
                        f"-adaptation-segment-{segment:02d}-attempt-{attempt}"
                        if mode == "targeted" else
                        f"-adaptation-segment-rebuild-{segment:02d}-attempt-{attempt}"
                    ),
                )
                contract_issues = self._short_plan_packet_contract_issues(
                    block,
                    segment=segment,
                    event_ids=event_ids,
                    source=current,
                    obligation_checklists=obligation_checklists,
                )
                if contract_issues:
                    raise GeneratedArtifactShapeError(
                        f"planning repair candidate failed its complete segment "
                        f"contract (segment={segment}, event_ids={event_ids}): "
                        + "; ".join(
                            str(item.get("message") or item.get("code"))
                            for item in contract_issues
                        ),
                        issues=contract_issues,
                    )
            candidate = self._replace_short_plan_segment(
                candidate, segment_count, segment, block,
            )
        return candidate

    async def _ensure_short_plan_adaptations(
        self, run_id: str, run_path: Path, project: Project, constraints: str,
        state: dict, plan: str, formal_outline_events: list[dict],
        segment_count: int, *, generation_context_sha256: str | None = None,
    ) -> tuple[str, dict | None, bool]:
        contracts = self._planning_adaptation_contracts(state, formal_outline_events)
        if not contracts or not all(str(item.get("evidence") or "").strip() for item in contracts):
            return plan, None, False
        outputs = run_path / "outputs"
        artifact_path = outputs / "planning-adaptations.json"
        try:
            cached = json.loads(artifact_path.read_text(encoding="utf-8"))
        except (OSError, UnicodeError, json.JSONDecodeError):
            cached = None
        if self._planning_adaptation_artifact_valid(
            cached, state, plan, formal_outline_events, segment_count,
            generation_context_sha256,
        ):
            self.db.add_run_event(
                run_id, "success", "planning_adaptation_reused",
                "已复用与当前大纲和规划哈希一致的等价展开回执",
                stage="planning",
            )
            return plan, dict(cached), False

        original_plan = plan
        protocol_repairs = 0
        current_route_failures: list[dict] = []
        current_protocol_failures: list[dict] = []
        current_semantic_candidates = 0
        last_protocol_exception: GeneratedArtifactShapeError | None = None
        outline_content = str(((state.get("outline") or {}).get("content")) or "")
        obligation_checklists = bind_planning_participant_realizations(
            narrative_outline_event_obligations(outline_content),
            narrative_participant_realizations(
                resolve_narrative_contract(project),
            ),
        )
        outline_sha256 = hashlib.sha256(outline_content.encode("utf-8")).hexdigest()
        context_sha256 = generation_context_sha256 or ""

        def auto_repair_event_obligations(
            candidate: str,
            allowed_segments: set[int] | None = None,
        ) -> tuple[str, list[dict]]:
            """Apply only deterministic, event-owned obligation repairs.

            Existing unlabelled continuations may be rebound to their unique
            owner, and a missing obligation may be appended only from one exact
            hash-bound formal excerpt. Ambiguous content remains untouched for
            model repair; sibling events and segment boundaries never change.
            """
            current = candidate
            repairs: list[dict] = []
            segments = self._short_plan_segments(current, segment_count)
            if len(segments) != segment_count:
                return candidate, repairs
            for segment in range(1, segment_count + 1):
                if allowed_segments is not None and segment not in allowed_segments:
                    continue
                block = segments[segment - 1]
                event_ids = self._short_plan_event_ids(block)
                if not event_ids:
                    continue
                repaired, segment_repairs = repair_planning_event_obligation_ownership(
                    block, event_ids, obligation_checklists,
                )
                completed, completion_repairs = (
                    repair_planning_event_obligation_coverage(
                        repaired, event_ids, obligation_checklists,
                    )
                )
                segment_repairs = [*segment_repairs, *completion_repairs]
                if completed == block or not segment_repairs:
                    continue
                current = self._replace_short_plan_segment(
                    current, segment_count, segment, completed,
                )
                segments = self._short_plan_segments(current, segment_count)
                repairs.extend({"segment": segment, **item} for item in segment_repairs)
            return current, repairs

        seeded_recovery = read_planning_recovery(outputs)
        seeded_state = seeded_recovery[0] if seeded_recovery is not None else None
        if not planning_recovery_state_matches(
            seeded_state,
            outline_sha256=outline_sha256,
            generation_context_sha256=context_sha256,
            segment_count=segment_count,
        ) or seeded_recovery is None or seeded_recovery[1] != plan:
            seeded_state = None

        def protocol_failure(values: list[dict]) -> bool:
            return any(
                str(item.get("code") or "") in PLANNING_ADAPTATION_PROTOCOL_CODES
                for item in values
            )

        def deterministic_obligation_issues(candidate: str) -> list[dict]:
            values: list[dict] = []
            for segment, block in enumerate(
                self._short_plan_segments(candidate, segment_count), 1,
            ):
                event_ids = self._short_plan_event_ids(block)
                for issue in planning_event_obligation_issues(
                    block, event_ids, obligation_checklists,
                ):
                    values.append({**issue, "segment": segment})
            return values

        def merge_initial_issue_evidence(values: list[dict]) -> list[dict]:
            combined: list[dict] = []
            seen: set[str] = set()
            seeded_issues = (
                list(seeded_state.get("best_issues") or [])
                if isinstance(seeded_state, dict) else []
            )
            for issue in [*seeded_issues, *values]:
                if not isinstance(issue, dict):
                    continue
                if str(issue.get("code") or "") in PLANNING_ADAPTATION_PROTOCOL_CODES:
                    continue
                identity = json.dumps(
                    issue, ensure_ascii=False, sort_keys=True,
                    separators=(",", ":"),
                )
                if identity in seen:
                    continue
                seen.add(identity)
                combined.append(dict(issue))
            return combined

        async def evaluate(candidate: str, suffix: str) -> tuple[list[dict], dict, list[dict]]:
            nonlocal protocol_repairs
            obligation_issues = deterministic_obligation_issues(candidate)
            if obligation_issues:
                issues_value = (
                    merge_initial_issue_evidence(obligation_issues)
                    if suffix == "initial" else obligation_issues
                )
                self.db.add_run_event(
                    run_id, "warning", "planning_event_obligation_precheck_failed",
                    "规划正式复合事件尚未覆盖全部必需参与者与回应，正在直接重建所属完整正式段",
                    stage="planning", metadata={
                        "issues": obligation_issues,
                        "review_deferred": True,
                    },
                )
                return [], {}, issues_value
            receipts_value, whole_value, issues_value, retries = (
                await self._review_short_plan_adaptations(
                    run_id, run_path, project, constraints, state, candidate,
                    formal_outline_events, segment_count, suffix=suffix,
                    generation_context_sha256=context_sha256,
                    authority_version=PLANNING_ADAPTATION_VERSION,
                )
            )
            protocol_repairs += retries
            return receipts_value, whole_value, issues_value

        def recovery_scope(candidate: str, values: list[dict]) -> dict[str, list[int]]:
            segments = self._short_plan_segments(candidate, segment_count)
            event_ids = {
                number: self._short_plan_event_ids(block)
                for number, block in enumerate(segments, 1)
            }
            affected = sorted(planning_issue_segments(values, event_ids))
            return {
                "affected_segments": affected,
                "preserved_segments": [
                    number for number in range(1, segment_count + 1)
                    if number not in affected
                ],
            }

        def recovery_units(candidate: str, values: list[dict]) -> list[tuple[int, ...]]:
            segments = self._short_plan_segments(candidate, segment_count)
            event_ids = {
                number: self._short_plan_event_ids(block)
                for number, block in enumerate(segments, 1)
            }
            components: list[set[int]] = []
            for issue in values:
                owned = set(planning_issue_segments([issue], event_ids))
                if not owned:
                    continue
                overlapping = [
                    component for component in components
                    if component.intersection(owned)
                ]
                merged = set(owned)
                for component in overlapping:
                    merged.update(component)
                    components.remove(component)
                components.append(merged)
            all_affected = planning_issue_segments(values, event_ids)
            claimed = set().union(*components) if components else set()
            components.extend(
                {segment} for segment in sorted(all_affected - claimed)
            )
            return sorted(
                (tuple(sorted(component)) for component in components),
                key=lambda unit: (unit[0], len(unit), unit),
            )

        self.db.add_run_event(
            run_id, "info", "planning_adaptation_review_started",
            "正在核对规划中的等价展开、跨段因果和结局承诺",
            stage="planning", metadata={
                "segment_count": segment_count,
                "event_count": len(contracts),
            },
        )
        best_plan = plan
        best_plan, initial_obligation_repairs = auto_repair_event_obligations(
            best_plan,
        )
        if initial_obligation_repairs:
            # The old checkpoint is bound to the pre-repair plan. Start a fresh
            # review ledger; historical run events remain the audit trail.
            seeded_state = None
            self.db.add_run_event(
                run_id, "success", "planning_event_obligation_completed_locally",
                "已从正式大纲的唯一哈希义务补全缺失回应，并保持其他事件与段落边界不变",
                stage="planning", metadata={
                    "repairs": initial_obligation_repairs,
                    "planning_sha256": hashlib.sha256(
                        best_plan.encode("utf-8"),
                    ).hexdigest(),
                },
            )
        pending_state = new_planning_recovery_state(
            outline_sha256=outline_sha256,
            generation_context_sha256=context_sha256,
            segment_count=segment_count,
            plan=best_plan,
            issues=[],
        )
        if seeded_state is not None:
            pending_state["candidates"] = list(
                seeded_state.get("candidates") or []
            )
            pending_state["execution_failures"] = list(
                seeded_state.get("execution_failures") or []
            )
            pending_state["semantic_attempts"] = int(
                seeded_state.get("semantic_attempts") or 0
            )
            pending_state["candidate_generation_attempts"] = int(
                seeded_state.get("candidate_generation_attempts") or 0
            )
            pending_state["resumed_recovery_sha256"] = hashlib.sha256(
                json.dumps(
                    seeded_state, ensure_ascii=False, sort_keys=True,
                    separators=(",", ":"),
                ).encode("utf-8"),
            ).hexdigest()
        pending_state["status"] = "review_pending"
        write_planning_recovery(outputs, pending_state, best_plan)
        best_receipts, best_whole_receipt, best_issues = await evaluate(
            best_plan, "initial",
        )
        recovery_state = new_planning_recovery_state(
            outline_sha256=outline_sha256,
            generation_context_sha256=context_sha256,
            segment_count=segment_count,
            plan=best_plan,
            issues=best_issues,
        )
        if seeded_state is not None:
            recovery_state["candidates"] = list(
                seeded_state.get("candidates") or []
            )
            recovery_state["execution_failures"] = list(
                seeded_state.get("execution_failures") or []
            )
            recovery_state["semantic_attempts"] = int(
                seeded_state.get("semantic_attempts") or 0
            )
            recovery_state["candidate_generation_attempts"] = int(
                seeded_state.get("candidate_generation_attempts") or 0
            )
            recovery_state["resumed_recovery_sha256"] = (
                pending_state["resumed_recovery_sha256"]
            )
        write_planning_recovery(outputs, recovery_state, best_plan)

        targeted_attempts: dict[tuple[int, ...], int] = {}
        rebuild_attempts: dict[tuple[int, ...], int] = {}
        targeted_dispatches: dict[tuple[int, ...], int] = {}
        rebuild_dispatches: dict[tuple[int, ...], int] = {}
        targeted_generation_failures: dict[tuple[int, ...], int] = {}
        rebuild_generation_failures: dict[tuple[int, ...], int] = {}
        while best_issues and not protocol_failure(best_issues):
            scope = recovery_scope(best_plan, best_issues)
            units = recovery_units(best_plan, best_issues)
            current_segments = self._short_plan_segments(
                best_plan, segment_count,
            )
            current_event_ids = {
                number: self._short_plan_event_ids(block)
                for number, block in enumerate(current_segments, 1)
            }
            forced_rebuild = {
                unit for unit in units
                if any(
                    str(issue.get("code") or "")
                    == "planning_required_participant_missing"
                    and set(unit).intersection(
                        planning_issue_segments([issue], current_event_ids)
                    )
                    for issue in best_issues if isinstance(issue, dict)
                )
            }
            targetable = [
                unit for unit in units
                if unit not in forced_rebuild
                if targeted_attempts.get(unit, 0) < 2
                if targeted_generation_failures.get(unit, 0) < 2
            ]
            rebuildable = [
                unit for unit in units
                if rebuild_attempts.get(unit, 0) < 2
                if rebuild_generation_failures.get(unit, 0) < 2
            ]
            if targetable:
                minimum_attempts = min(
                    targeted_attempts.get(unit, 0)
                    for unit in targetable
                )
                target_unit = min(
                    unit for unit in targetable
                    if targeted_attempts.get(unit, 0) == minimum_attempts
                )
                mode = "targeted"
                attempt = targeted_dispatches.get(target_unit, 0) + 1
                targeted_dispatches[target_unit] = attempt
                event_type = "planning_adaptation_targeted_repair"
                message = "规划存在结构性偏移，正在只修正受影响的正式段"
            elif rebuildable:
                target_unit = min(rebuildable)
                mode = "rebuild"
                attempt = rebuild_dispatches.get(target_unit, 0) + 1
                rebuild_dispatches[target_unit] = attempt
                event_type = "planning_adaptation_segment_rebuild"
                message = "局部修正未继续收敛，正在依据正式事件合同重建受影响的完整段"
            else:
                break
            target_segment = target_unit[0] if len(target_unit) == 1 else None
            unit_label = "-".join(f"{segment:02d}" for segment in target_unit)
            self.db.add_run_event(
                run_id, "warning", event_type, message,
                stage="planning", metadata={
                    "attempt": attempt,
                    "mode": mode,
                    "candidate_segment": target_segment,
                    "candidate_segments": list(target_unit),
                    "issues": best_issues,
                    "best_issue_keys": sorted(planning_issue_keys(best_issues)),
                    **scope,
                },
            )
            try:
                recovery_feedback = self._planning_recovery_candidate_feedback(
                    recovery_state,
                )
                candidate = await self._repair_short_plan_adaptation_segments(
                    run_id, run_path, project, constraints, state, best_plan,
                    formal_outline_events, segment_count, best_issues,
                    mode=mode, attempt=attempt,
                    recovery_feedback=recovery_feedback,
                    target_segments=list(target_unit),
                )
            except (
                ContextCapacityPreflightError,
                IncompleteModelOutputError,
                ModelRoutesExhaustedError,
                ValueError,
            ) as exc:
                generation_failures = (
                    targeted_generation_failures
                    if mode == "targeted" else rebuild_generation_failures
                )
                generation_failures[target_unit] = (
                    generation_failures.get(target_unit, 0) + 1
                )
                failure_class = classify_model_failure(exc)
                repair_feedback = [
                    dict(item) for item in getattr(exc, "issues", [])
                    if isinstance(item, dict)
                ]
                protocol_exhausted = any(
                    str(item.get("code") or "")
                    == "planning_packet_protocol_exhausted"
                    for item in repair_feedback
                )
                comparison = {
                    "improved": False,
                    "previous_issue_keys": sorted(planning_issue_keys(best_issues)),
                    "candidate_issue_keys": sorted(planning_issue_keys(best_issues)),
                    "introduced_issue_keys": [],
                    "resolved_issue_keys": [],
                    "retained_issue_keys": sorted(planning_issue_keys(best_issues)),
                    "reason": "candidate_generation_failed",
                    "error": str(exc)[:500],
                    "failure_class": failure_class,
                    "candidate_segment": target_segment,
                    "candidate_segments": list(target_unit),
                    "repair_feedback": repair_feedback,
                    **scope,
                }
                recovery_state = record_planning_candidate(
                    recovery_state, plan=best_plan, issues=best_issues,
                    comparison=comparison,
                    source=f"{mode}-{attempt}-segments-{unit_label}",
                    accepted=False,
                    counts_as_semantic=False,
                )
                if protocol_exhausted:
                    current_protocol_failures.append({
                        "error": str(exc)[:500],
                        "mode": mode,
                        "attempt": attempt,
                        "candidate_segments": list(target_unit),
                        "issues": repair_feedback,
                    })
                    if isinstance(exc, GeneratedArtifactShapeError):
                        last_protocol_exception = exc
                if failure_class != "normal_invalid_output":
                    failure_record = {
                        "failure_class": failure_class,
                        "error": str(exc)[:500],
                        "attempt": attempt,
                        "mode": mode,
                        "candidate_segment": target_segment,
                        "candidate_segments": list(target_unit),
                    }
                    recovery_state.setdefault("execution_failures", []).append({
                        **failure_record,
                    })
                    if failure_class in {
                        "provider_rejection", "transport_interrupted",
                    }:
                        current_route_failures.append(failure_record)
                write_planning_recovery(outputs, recovery_state, best_plan)
                self.db.add_run_event(
                    run_id, "warning", "planning_candidate_rejected",
                    (
                        "规划修复候选的内容保持隔离，但协议重封装已耗尽；"
                        "已保留此前问题更少的最佳规划"
                        if protocol_exhausted else
                        "规划修复候选没有完整生成，已保留此前问题更少的最佳规划"
                    ),
                    stage="planning", metadata=comparison,
                )
                continue

            candidate, ownership_repairs = auto_repair_event_obligations(
                candidate, set(target_unit),
            )
            if ownership_repairs:
                self.db.add_run_event(
                    run_id, "info", "planning_event_obligation_auto_repaired",
                    "已在修复候选中完成确定性的事件义务归属或正式摘录补全，再做结构核对",
                    stage="planning", metadata={"repairs": ownership_repairs},
                )
            best_segments_before = self._short_plan_segments(
                best_plan, segment_count,
            )
            candidate_segments_after = self._short_plan_segments(
                candidate, segment_count,
            )
            if (
                len(best_segments_before) == segment_count
                and len(candidate_segments_after) == segment_count
            ):
                changed_segments = [
                    number for number, (before, after) in enumerate(
                        zip(
                            best_segments_before,
                            candidate_segments_after,
                            strict=True,
                        ), 1,
                    ) if before != after
                ]
            else:
                changed_segments = list(target_unit)
            segment_event_ids = {
                number: self._short_plan_event_ids(block)
                for number, block in enumerate(best_segments_before, 1)
            }
            unauthorized_changes = sorted(
                set(changed_segments) - set(target_unit)
            )
            local_issues = self._short_plan_issues(
                project, state, candidate, segment_count,
            )
            if unauthorized_changes:
                candidate_receipts = []
                candidate_whole_receipt = {}
                candidate_issues = [{
                    "code": "planning_unauthorized_segment_change",
                    "segment": segment,
                    "message": (
                        f"规划修复候选改动了未授权的第 {segment} 段"
                    ),
                } for segment in unauthorized_changes]
            elif local_issues:
                candidate_receipts: list[dict] = []
                candidate_whole_receipt: dict = {}
                candidate_issues = [{
                    "code": "planning_local_gate",
                    "message": value,
                } for value in local_issues]
            else:
                candidate_receipts, candidate_whole_receipt, candidate_issues = (
                    await evaluate(candidate, f"{mode}-{attempt}")
                )
            if protocol_failure(candidate_issues):
                generation_failures = (
                    targeted_generation_failures
                    if mode == "targeted" else rebuild_generation_failures
                )
                generation_failures[target_unit] = (
                    generation_failures.get(target_unit, 0) + 1
                )
                comparison = {
                    "improved": False,
                    "previous_issue_keys": sorted(planning_issue_keys(best_issues)),
                    "candidate_issue_keys": sorted(planning_issue_keys(candidate_issues)),
                    "introduced_issue_keys": sorted(
                        planning_issue_keys(candidate_issues)
                        - planning_issue_keys(best_issues)
                    ),
                    "resolved_issue_keys": [],
                    "retained_issue_keys": sorted(planning_issue_keys(best_issues)),
                    "reason": "candidate_receipt_failed",
                    "candidate_segment": target_segment,
                    "candidate_segments": list(target_unit),
                    **scope,
                }
                recovery_state = record_planning_candidate(
                    recovery_state, plan=best_plan, issues=best_issues,
                    comparison=comparison,
                    source=f"{mode}-{attempt}-segments-{unit_label}",
                    accepted=False,
                    counts_as_semantic=False,
                )
                current_protocol_failures.append({
                    "error": "planning candidate receipt protocol failed",
                    "mode": mode,
                    "attempt": attempt,
                    "candidate_segments": list(target_unit),
                    "issues": [dict(item) for item in candidate_issues],
                })
                write_planning_recovery(outputs, recovery_state, best_plan)
                self.db.add_run_event(
                    run_id, "error", "planning_candidate_receipt_failed",
                    "候选规划保持隔离，但其审核回执未能完成，已保留最佳规划",
                    stage="planning", metadata={
                        "issues": candidate_issues,
                        **comparison,
                    },
                )
                continue
            semantic_attempts = (
                targeted_attempts if mode == "targeted" else rebuild_attempts
            )
            semantic_attempts[target_unit] = (
                semantic_attempts.get(target_unit, 0) + 1
            )
            current_semantic_candidates += 1
            comparison = planning_candidate_comparison(
                best_issues, candidate_issues,
                changed_segments=set(changed_segments),
                segment_event_ids=segment_event_ids,
            )
            latent_keys = set(comparison["latent_baseline_issue_keys"])
            latent_segments = sorted({
                segment
                for issue in candidate_issues
                if planning_issue_keys([issue]).intersection(latent_keys)
                for segment in planning_issue_segments(
                    [issue], segment_event_ids,
                )
                if segment not in changed_segments
            })
            merged_candidate_issues = merge_planning_issue_ledgers(
                best_issues, candidate_issues,
                changed_segments=set(changed_segments),
                segment_event_ids=segment_event_ids,
            )
            comparison = {
                **comparison,
                **scope,
                "candidate_segment": target_segment,
                "candidate_segments": list(target_unit),
                "changed_segments": changed_segments,
                "changed_segment_sha256": {
                    str(segment): {
                        "previous": hashlib.sha256(
                            best_segments_before[segment - 1].encode("utf-8"),
                        ).hexdigest(),
                        "candidate": hashlib.sha256(
                            candidate_segments_after[segment - 1].encode("utf-8"),
                        ).hexdigest(),
                    }
                    for segment in changed_segments
                    if (
                        1 <= segment <= len(best_segments_before)
                        and segment <= len(candidate_segments_after)
                    )
                },
                "latent_baseline_segments": latent_segments,
                "latent_baseline_segment_sha256": {
                    str(segment): hashlib.sha256(
                        best_segments_before[segment - 1].encode("utf-8"),
                    ).hexdigest()
                    for segment in latent_segments
                    if 1 <= segment <= len(best_segments_before)
                },
                "merged_candidate_issue_keys": sorted(
                    planning_issue_keys(merged_candidate_issues)
            ),
        }

            accepted = not merged_candidate_issues or bool(comparison["improved"])
            recovery_state = record_planning_candidate(
                recovery_state, plan=candidate, issues=merged_candidate_issues,
                comparison=comparison,
                source=f"{mode}-{attempt}-segments-{unit_label}",
                accepted=accepted,
            )
            if accepted:
                best_plan = candidate
                best_receipts = candidate_receipts
                best_whole_receipt = candidate_whole_receipt
                best_issues = merged_candidate_issues
                targeted_attempts = {}
                rebuild_attempts = {}
                targeted_dispatches = {}
                rebuild_dispatches = {}
                targeted_generation_failures = {}
                rebuild_generation_failures = {}
                write_planning_recovery(outputs, recovery_state, best_plan)
                if comparison["newly_discovered_latent_issue_keys"]:
                    self.db.add_run_event(
                        run_id, "info", "planning_latent_issues_discovered",
                        "已保留当前段的有效修复，并将未修改段中新发现的旧问题转入独立修复",
                        stage="planning", metadata={
                            "changed_segments": changed_segments,
                            "latent_baseline_segments": latent_segments,
                            "latent_baseline_issue_keys": comparison[
                                "latent_baseline_issue_keys"
                            ],
                            "newly_discovered_latent_issue_keys": comparison[
                                "newly_discovered_latent_issue_keys"
                            ],
                            "latent_baseline_segment_sha256": comparison[
                                "latent_baseline_segment_sha256"
                            ],
                        },
                    )
                self.db.add_run_event(
                    run_id, "success", "planning_candidate_improved",
                    (
                        "规划修复候选已解决全部结构问题"
                        if not best_issues else
                        "规划修复候选的问题集合已严格缩小，已更新最佳规划"
                    ),
                    stage="planning", metadata=comparison,
                )
            else:
                write_planning_recovery(outputs, recovery_state, best_plan)
                self.db.add_run_event(
                    run_id, "warning", "planning_candidate_rejected_regression",
                    "规划修复候选没有取得严格进展或引入了新问题，已恢复最佳规划",
                    stage="planning", metadata=comparison,
                )

        issues = best_issues
        receipts = best_receipts
        whole_receipt = best_whole_receipt
        recovery_state["status"] = "ready" if not issues else "recoverable_failed"
        recovery_state["best_issues"] = best_issues
        recovery_state["best_issue_keys"] = sorted(planning_issue_keys(best_issues))
        write_planning_recovery(outputs, recovery_state, best_plan)
        semantic_repairs = int(recovery_state.get("semantic_attempts") or 0)
        candidate_generation_attempts = int(
            recovery_state.get("candidate_generation_attempts") or 0
        )
        artifact = {
            "version": PLANNING_ADAPTATION_VERSION,
            "status": "failed" if issues else "ready",
            "outline_sha256": outline_sha256,
            "planning_sha256": hashlib.sha256(best_plan.encode("utf-8")).hexdigest(),
            "segment_count": segment_count,
            "generation_context_sha256": generation_context_sha256,
            "segments": receipts,
            "whole_story_receipt": whole_receipt,
            "protocol_repairs": protocol_repairs,
            "semantic_repairs": semantic_repairs,
            "candidate_generation_attempts": candidate_generation_attempts,
            "execution_failures": list(
                recovery_state.get("execution_failures") or []
            ),
            "best_issue_keys": sorted(planning_issue_keys(best_issues)),
            "recovery_state": "planning-recovery-state.json",
            "issues": issues,
        }
        atomic_write(
            artifact_path, json.dumps(artifact, ensure_ascii=False, indent=2),
        )
        if issues:
            execution_failures = [
                item for item in (recovery_state.get("execution_failures") or [])
                if isinstance(item, dict)
            ]
            if current_route_failures:
                self.db.add_run_event(
                    run_id, "error", "planning_adaptation_unavailable",
                    "规划语义问题尚未解决，当前模型路由不可用；已保留最佳规划和有效上游进度",
                    stage="planning", metadata={
                        "issues": issues,
                        "execution_failures": current_route_failures,
                        "historical_execution_failures": execution_failures,
                        "semantic_repairs": semantic_repairs,
                    },
                )
                raise PlanningRecoveryUnavailableError(
                    issues, current_route_failures,
                )
            if current_protocol_failures and current_semantic_candidates == 0:
                self.db.add_run_event(
                    run_id, "error", "planning_adaptation_receipt_failed",
                    "本轮规划候选均在协议层失败；已保留最佳规划，语义修复预算未被消耗",
                    stage="planning", metadata={
                        "issues": issues,
                        "protocol_failures": current_protocol_failures,
                        "protocol_repairs": protocol_repairs,
                        "semantic_repairs": semantic_repairs,
                        "candidate_generation_attempts": (
                            candidate_generation_attempts
                        ),
                    },
                )
                if last_protocol_exception is not None:
                    raise last_protocol_exception
                raise GeneratedArtifactShapeError(
                    "planning packet protocol recovery exhausted",
                    issues=[{
                        "code": "planning_packet_protocol_exhausted",
                        "message": "planning packet protocol recovery exhausted",
                        "blocking": True,
                    }],
                )
            is_protocol = protocol_failure(issues)
            self.db.add_run_event(
                run_id, "error", (
                    "planning_adaptation_receipt_failed"
                    if is_protocol else "planning_adaptation_failed"
                ),
                (
                    "规划内容未被改动，但等价展开审核回执仍不完整，已停止后续生成"
                    if is_protocol else
                    "规划经过局部修正和完整段重建后仍有结构问题，已保留最佳规划并停止后续生成"
                ),
                stage="planning", metadata={
                    "issues": issues,
                    "protocol_repairs": protocol_repairs,
                    "semantic_repairs": semantic_repairs,
                },
            )
            raise ValueError(
                "规划等价展开审核回执未通过，规划内容保持不变"
                if is_protocol else
                "规划恢复尚未收敛，最佳候选和有效上游进度已保留"
            )
        counts: dict[str, int] = {}
        for receipt in receipts:
            for review in receipt.get("event_reviews", []):
                classification = str(review.get("classification") or "unknown")
                counts[classification] = counts.get(classification, 0) + 1
        self.db.add_run_event(
            run_id, "success", "planning_adaptation_ready",
            "规划中的等价展开已通过剧情功能、因果和状态核对",
            stage="planning", metadata={
                "classifications": counts,
                "protocol_repairs": protocol_repairs,
                "semantic_repairs": semantic_repairs,
            },
        )
        return best_plan, artifact, best_plan != original_plan

    @classmethod
    def _short_plan_segments_for_range(
        cls, value: str, start: int, end: int,
    ) -> list[str]:
        headings = cls._short_plan_headings(value)
        blocks: list[str] = []
        for position, (match, number) in enumerate(headings):
            if number is None or not start <= number <= end:
                continue
            boundary = headings[position + 1][0].start() if position + 1 < len(headings) else len(value)
            blocks.append(value[match.start():boundary].strip())
        return blocks

    @classmethod
    def _require_short_plan_segment(
        cls, value: str, segment: int, *, artifact: str,
    ) -> str:
        """Return one parsed segment or raise a recoverable contract error.

        Generated output is never indexed before its presentation syntax has
        been normalized and its cardinality has been checked.  Callers in the
        planning recovery loop catch ``ValueError`` and retry only the current
        repair scope from the retained best plan.
        """
        conflicts = [
            identities
            for _match, identities in cls._short_plan_heading_identities(value)
            if len(identities) > 1
        ]
        if conflicts:
            raise GeneratedArtifactShapeError(
                f"{artifact} has conflicting segment identity "
                f"(expected={segment}, declared={conflicts})",
                issues=[{
                    "code": "planning_packet_segment_identity",
                    "message": (
                        f"{artifact} declares multiple distinct segment identities"
                    ),
                    "segment": segment,
                    "declared_segments": conflicts,
                    "blocking": True,
                }],
            )
        blocks = cls._short_plan_segments_for_range(value, segment, segment)
        if len(blocks) != 1:
            headings = [
                number for _match, number in cls._short_plan_headings(value)
                if number is not None
            ]
            raise GeneratedArtifactShapeError(
                f"{artifact} missing exactly one recognizable segment heading "
                f"(expected={segment}, parsed={headings})"
            )
        return blocks[0]

    @classmethod
    def _short_plan_structural_event_spans(
        cls, value: str,
    ) -> list[tuple[str, int, int]]:
        """Find event-owned title/list lines while excluding diagnostic prose."""
        comparison = cls._short_plan_comparison_view(value)
        matches: list[tuple[str, int, int]] = []
        line_pattern = re.compile(
            r"(?im)^[ \t]{0,3}(?:#{1,6}[ \t]+|[-+*][ \t]+|"
            r"\d{1,3}[.)、）][ \t]+|(?:\*\*|__)[ \t]*)"
            r"(?P<body>[^\r\n]+)$"
        )
        diagnostic_prefixes = (
            "后续事件", "下一事件", "不得", "禁止", "未执行", "自检", "检查清单",
            "核验要求", "核验清单", "约束", "later", "nextevent", "mustnot",
            "forbid", "selfcheck", "checklist", "validationrule",
        )
        for match in line_pattern.finditer(comparison):
            line = match.group("body").casefold()
            compact = re.sub(r"\s+", "", line)
            if compact.startswith(diagnostic_prefixes):
                continue
            occurrences = planning_event_id_occurrences(
                comparison[match.start():match.end()], formal_only=True,
            )
            event_ids = list(dict.fromkeys(item[0] for item in occurrences))
            if len(event_ids) != 1:
                continue
            matches.append((event_ids[0], match.start(), match.end()))
        return matches

    @classmethod
    def _short_plan_structural_event_sequence(cls, value: str) -> list[str]:
        sequence = [event_id for event_id, _start, _end in (
            cls._short_plan_structural_event_spans(value)
        )]
        collapsed: list[str] = []
        for event_id in sequence:
            if not collapsed or collapsed[-1] != event_id:
                collapsed.append(event_id)
        return collapsed if len(collapsed) == len(set(collapsed)) else []

    @classmethod
    def _short_plan_structural_owned_event_ids(cls, segment: str) -> list[str]:
        sequences = [
            cls._short_plan_structural_event_sequence(value)
            for value in planning_field_sections(segment, "event")
        ]
        sequences = [value for value in sequences if value]
        if not sequences:
            return []
        longest = max(sequences, key=len)

        def subsequence(candidate: list[str], authority: list[str]) -> bool:
            iterator = iter(authority)
            return all(any(value == item for item in iterator) for value in candidate)

        if any(not subsequence(candidate, longest) for candidate in sequences):
            return []
        equally_long = [candidate for candidate in sequences if len(candidate) == len(longest)]
        return longest if all(candidate == longest for candidate in equally_long) else []

    @classmethod
    def _short_plan_structural_event_body(
        cls, value: str, expected: list[str],
    ) -> str:
        spans = cls._short_plan_structural_event_spans(value)
        sequence = cls._short_plan_structural_event_sequence(value)
        if sequence != expected:
            if len(expected) == 1 and not spans and value.strip():
                body = remove_planning_event_ids(value, formal_only=True).strip()
                return f"1. **正式事件**（{expected[0]}）：{body}"
            return ""
        grouped: dict[str, list[str]] = {event_id: [] for event_id in expected}
        for index, (event_id, start, _line_end) in enumerate(spans):
            if event_id not in grouped:
                continue
            end = spans[index + 1][1] if index + 1 < len(spans) else len(value)
            piece = remove_planning_event_ids(
                value[start:end], formal_only=True,
            )
            piece = re.sub(
                r"(?m)^[ \t]{0,3}(?:#{1,6}[ \t]+|[-+*][ \t]+|"
                r"\d{1,3}[.)、）][ \t]+|(?:\*\*|__)[ \t]*)",
                "", piece,
            ).strip(" \t\r\n*_`：:（）()")
            if piece:
                grouped[event_id].append(piece)
        if any(not grouped[event_id] for event_id in expected):
            return ""
        return "\n\n".join(
            f"{index}. **正式事件**（{event_id}）："
            + "\n\n".join(grouped[event_id])
            for index, event_id in enumerate(expected, 1)
        )

    @classmethod
    def _short_plan_variant_label_matches(
        cls, value: str, aliases: tuple[str, ...],
    ) -> list[re.Match[str]]:
        labels = "|".join(
            re.escape(unicodedata.normalize("NFKC", label))
            for label in aliases
        )
        pattern = re.compile(
            rf"(?im)^[ \t]{{0,3}}"
            rf"(?:#{{1,6}}[ \t]+)?(?:[-+*][ \t]+)?"
            rf"(?:\*{{1,2}}|_{{1,2}}|`)?[ \t]*"
            rf"(?:{labels})(?=[ \t（(\*_`:：]|$)"
            rf"(?:[ \t]*[（(][^\r\n（）(){{}}]{{0,120}}[）)])?"
            rf"[ \t]*(?:\*{{1,2}}|_{{1,2}}|`)?[ \t]*"
            rf"(?:[:：][ \t]*)?(?P<inline>[^\r\n]*)$"
        )
        return list(pattern.finditer(cls._short_plan_comparison_view(value)))

    @classmethod
    def _short_plan_variant_label_value(
        cls, value: str, aliases: tuple[str, ...], *,
        boundary_aliases: tuple[str, ...] = (),
        inline_only: bool = False,
        stop_at_next_heading: bool = False,
    ) -> tuple[str, int]:
        matches = cls._short_plan_variant_label_matches(value, aliases)
        if len(matches) != 1:
            return "", len(matches)
        match = matches[0]
        inline_start, inline_end = match.span("inline")
        inline = value[inline_start:inline_end].strip()
        if inline_only:
            return inline, 1
        start = match.end()
        if value[start:start + 2] == "\r\n":
            start += 2
        elif start < len(value) and value[start] in "\r\n":
            start += 1
        comparison = cls._short_plan_comparison_view(value)
        boundaries: list[int] = []
        if boundary_aliases:
            for boundary in cls._short_plan_variant_label_matches(
                value, boundary_aliases,
            ):
                if boundary.start() > match.start():
                    boundaries.append(boundary.start())
        if stop_at_next_heading:
            heading = re.search(
                r"(?im)^[ \t]{0,3}(?:#{1,6}[ \t]+\S.*|"
                r"(?:\*{2}|__)[^\r\n*]{1,160}(?:\*{2}|__)[ \t]*"
                r"(?:[:：][ \t]*)?)$",
                comparison[start:],
            )
            if heading:
                boundaries.append(start + heading.start())
        end = min(boundaries) if boundaries else len(value)
        body = value[start:end].strip()
        return "\n".join(part for part in (inline, body) if part).strip(), 1

    @classmethod
    def _normalize_generated_short_plan_markdown_packet(
        cls, value: str, *, segment: int, event_ids: list[str],
        current: str, artifact: str,
    ) -> str:
        """Normalize a provider's explicit segment-only Markdown packet."""
        marker_matches = cls._short_plan_variant_label_matches(
            value, ("segment-only plan", "segment only plan", "segment-only", "segment only"),
        )
        identity_aliases = ("段标识", "段标签", "segment identity", "segment label")
        identity_matches = cls._short_plan_variant_label_matches(
            value, identity_aliases,
        )
        declared_segment: int | None = None
        if len(identity_matches) == 1:
            identity_value, _ = cls._short_plan_variant_label_value(
                value, identity_aliases, inline_only=False,
                boundary_aliases=("事件ID", "正式事件ID", "段首承接", "开场承接",
                                  "本段事件", "核心事件", "负责事件", "段末交接",
                                  "交接状态", "段末状态"),
            )
            declared_segment = parse_segment_number(
                identity_value, allow_scene=False,
            )
        if declared_segment != segment:
            issue = {
                "code": "planning_packet_segment_identity",
                "message": (
                    f"{artifact} has no unambiguous segment identity: "
                    f"expected {segment}, received {declared_segment}"
                ),
                "segment": segment,
                "event_ids": [str(item).upper() for item in event_ids],
                "blocking": True,
            }
            raise GeneratedArtifactShapeError(issue["message"], issues=[issue])

        expected = [str(item).strip().upper() for item in event_ids]
        opening_aliases = (
            cls.SHORT_PLAN_FIELD_ALIASES["opening"]
            + ("段前接续", "段前承接")
        )
        event_aliases = (
            cls.SHORT_PLAN_FIELD_ALIASES["event"]
            + ("本包事件", "段内事件", "本包内事件")
        )
        handoff_aliases = cls.SHORT_PLAN_FIELD_ALIASES["handoff"]
        declared_value, declared_count = cls._short_plan_variant_label_value(
            value, cls.SHORT_PLAN_FIELD_ALIASES["event_id"], inline_only=True,
        )
        declared_ids = planning_event_ids(
            declared_value, formal_only=True,
        )
        if declared_count != 1 or declared_ids != expected:
            issue = {
                "code": "planning_packet_event_ownership",
                "message": (
                    f"{artifact} changed explicit ordered event ownership: "
                    f"expected {expected}, received {declared_ids}"
                ),
                "segment": segment,
                "event_ids": expected,
                "expected_event_ids": expected,
                "actual_event_ids": declared_ids,
                "blocking": True,
            }
            raise GeneratedArtifactShapeError(issue["message"], issues=[issue])

        opening, opening_count = cls._short_plan_variant_label_value(
            value, opening_aliases,
            boundary_aliases=event_aliases + handoff_aliases,
        )
        event_body, event_count = cls._short_plan_variant_label_value(
            value, event_aliases, boundary_aliases=handoff_aliases,
        )
        handoff, handoff_count = cls._short_plan_variant_label_value(
            value, handoff_aliases,
            stop_at_next_heading=True,
        )
        missing = []
        if opening_count != 1 or not opening:
            missing.append("opening")
        if event_count != 1 or not event_body:
            missing.append("event")
        if handoff_count != 1 or not handoff:
            missing.append("handoff")
        if missing:
            issue = {
                "code": "planning_packet_field_missing",
                "message": f"{artifact} lacks complete packet fields: {missing}",
                "segment": segment,
                "event_ids": expected,
                "fields": missing,
                "blocking": True,
            }
            raise GeneratedArtifactShapeError(issue["message"], issues=[issue])

        # References to adjacent formal events are allowed in packet prose;
        # only the explicit ownership line controls packet identity. Remove
        # those references from the body before adding exactly one owner ID.
        clean_body = remove_planning_event_ids(
            event_body, formal_only=True,
        )
        clean_body = re.sub(
            r"(?m)^[ \t]{0,3}#{1,6}[ \t]+", "", clean_body,
        ).strip()
        event_body = (
            f"1. **正式事件**（{expected[0]}）：{clean_body}"
        )
        normalized = cls._render_short_plan_repair_packet(
            current,
            segment=segment,
            event_ids=expected,
            event_body=event_body,
            opening=opening,
            handoff=handoff,
        )
        return cls._require_short_plan_segment(
            normalized, segment, artifact=f"normalized {artifact}",
        )

    @classmethod
    def _generated_short_plan_markdown_projection(
        cls, block: str, *, segment: int, event_ids: list[str],
        current: str, artifact: str,
    ) -> str:
        """Project harmless Markdown field variants into the canonical block."""
        expected = [str(event_id).strip().upper() for event_id in event_ids]
        received = cls._short_plan_declared_event_ids(block)
        if received != expected or len(received) != len(set(received)):
            issue = {
                "code": "planning_packet_event_ownership",
                "message": (
                    f"{artifact} changed ordered event ownership: "
                    f"expected {expected}, received {received}"
                ),
                "segment": segment,
                "event_ids": expected,
                "blocking": True,
            }
            raise GeneratedArtifactShapeError(issue["message"], issues=[issue])

        canonical = {
            field: cls._short_plan_field(block, field)
            for field in cls.SHORT_PLAN_FIELD_ALIASES
        }
        if all(canonical.values()):
            return block

        heading_counts: dict[str, int] = {}
        for field in ("opening", "event", "handoff"):
            semantic_values = list(planning_field_sections(block, field))
            if field == "event" and semantic_values:
                projected = [
                    cls._short_plan_structural_event_body(value, expected)
                    for value in semantic_values
                ]
                projected = [value for value in projected if value]
                if projected:
                    canonical[field] = max(
                        projected,
                        key=lambda value: len(re.sub(r"\s+", "", value)),
                    )
                    heading_counts[field] = 1
                    continue
            if semantic_values:
                normalized_values = {
                    re.sub(r"\s+", " ", value).strip(): value
                    for value in semantic_values
                }
                heading_counts[field] = len(normalized_values)
                if len(normalized_values) == 1:
                    canonical[field] = next(iter(normalized_values.values()))
                    continue
            if canonical[field]:
                continue
            heading_counts[field] = len(planning_field_sections(block, field))

        # Event IDs and outline evidence are Runtime-owned authority.  A
        # generated packet may vary their presentation or omit the redundant
        # outline field, but it may not replace either value.
        canonical["event_id"] = "、".join(expected)
        canonical["outline"] = (
            canonical["outline"]
            or cls._short_plan_field(current, "outline")
        )
        missing = [
            field for field in cls.SHORT_PLAN_FIELD_ALIASES
            if not canonical.get(field)
        ]
        ambiguous = [
            field for field, count in heading_counts.items() if count > 1
        ]
        if missing or ambiguous:
            issues: list[dict] = []
            if missing:
                issues.append({
                    "code": "planning_packet_field_missing",
                    "message": (
                        f"{artifact} lacks complete plan fields: {missing}"
                    ),
                    "segment": segment,
                    "event_ids": expected,
                    "fields": missing,
                    "blocking": True,
                })
            if ambiguous:
                issues.append({
                    "code": "planning_packet_field_ambiguous",
                    "message": (
                        f"{artifact} repeats heading-owned plan fields: "
                        f"{ambiguous}"
                    ),
                    "segment": segment,
                    "event_ids": expected,
                    "fields": ambiguous,
                    "blocking": True,
                })
            raise GeneratedArtifactShapeError(
                "; ".join(str(item["message"]) for item in issues),
                issues=issues,
            )

        normalized = cls._render_short_plan_repair_packet(
            current,
            segment=segment,
            event_ids=expected,
            event_body=canonical["event"],
            opening=canonical["opening"],
            handoff=canonical["handoff"],
        )
        return cls._require_short_plan_segment(
            normalized, segment, artifact=f"normalized {artifact}",
        )

    @staticmethod
    def _parse_short_plan_event_array(value: str, *, artifact: str) -> list[dict]:
        """Read exactly one JSON event array from a provider presentation wrapper.

        This is deliberately narrower than the object parser: an array packet
        is accepted only when the whole payload is one array (optionally inside
        one fenced block or HTML comment).  We never scan prose and pick the
        first array because that would make ownership ambiguous.
        """
        source = str(value or "").lstrip("\ufeff").strip()
        if source.startswith("<!--") and source.endswith("-->"):
            source = source[4:-3].strip()
        if source.startswith("```") and source.endswith("```"):
            lines = source.splitlines()
            if len(lines) < 3 or not lines[-1].strip().startswith("```"):
                raise ValueError(f"{artifact} JSON array fence is incomplete")
            source = "\n".join(lines[1:-1]).strip()
        try:
            payload = json.loads(source)
        except (TypeError, json.JSONDecodeError) as exc:
            raise ValueError(f"{artifact} is not one JSON event array") from exc
        if not isinstance(payload, list):
            raise ValueError(f"{artifact} JSON packet must be an event array")
        if not payload or not all(isinstance(item, dict) for item in payload):
            raise ValueError(f"{artifact} JSON event array contains invalid items")
        return payload

    @staticmethod
    def _short_plan_json_key(value: object) -> str:
        return re.sub(
            r"[^0-9a-z_]+", "_",
            unicodedata.normalize("NFKC", str(value or ""))
            .strip().casefold().replace("-", "_").replace(" ", "_"),
        ).strip("_")

    @classmethod
    def _short_plan_json_unknown_control_fields(
        cls, payload: object,
    ) -> list[str]:
        """Return unsafe machine-control fields from an open JSON wrapper.

        Container names are deliberately open. Machine operations are not:
        this parser may project narrative evidence, but it must never infer a
        patch, mutation, command, or review decision from an unknown schema.
        Such packets re-enter the existing canonical-contract retry path.
        """
        control_fields = {
            "command", "commands", "control", "control_action", "mutation",
            "op", "operation", "operations", "patch", "patch_operation",
            "patches", "repair_kind", "repair_operation", "review_decision",
        }
        control_values = {
            "accept", "append", "apply", "delete", "discard", "insert",
            "merge", "move", "preserve", "reject", "remove", "replace",
            "restore", "retry", "rewrite", "skip", "stop",
        }
        found: list[str] = []

        def looks_like_control(value: object) -> bool:
            if isinstance(value, dict):
                keys = {
                    cls._short_plan_json_key(key) for key in value
                }
                return bool(keys & control_values) or any(
                    looks_like_control(child) for child in value.values()
                    if isinstance(child, (dict, list))
                )
            if isinstance(value, list):
                return any(looks_like_control(child) for child in value)
            if isinstance(value, str):
                return cls._short_plan_json_key(value) in control_values
            return False

        def walk(node: object, path: tuple[str, ...]) -> None:
            if isinstance(node, dict):
                for raw_key, child in node.items():
                    key = cls._short_plan_json_key(raw_key)
                    child_path = path + (str(raw_key),)
                    if key in control_fields and looks_like_control(child):
                        found.append(".".join(child_path))
                    walk(child, child_path)
            elif isinstance(node, list):
                for index, child in enumerate(node):
                    walk(child, path + (str(index),))

        walk(payload, ())
        return found

    @classmethod
    def _short_plan_json_declared_segments(
        cls, payload: object,
    ) -> set[int | None]:
        numeric_fields = {
            "segment", "segment_id", "segment_index", "segment_number",
            "segment_order",
        }
        label_fields = {
            "segment_identity", "segment_label", "segment_title",
        }
        declared: set[int | None] = set()

        def walk(node: object) -> None:
            if isinstance(node, dict):
                for raw_key, child in node.items():
                    key = cls._short_plan_json_key(raw_key)
                    if key in numeric_fields | label_fields:
                        number = parse_segment_number(
                            str(child), allow_scene=False,
                        )
                        if number is None and key in numeric_fields:
                            try:
                                number = int(unicodedata.normalize(
                                    "NFKC", str(child),
                                ))
                            except (TypeError, ValueError):
                                number = None
                        # A free-form segment label is descriptive metadata.
                        # It may reinforce a numeric Runtime identity, but an
                        # unnumbered creative title must not create a blocking
                        # ``None`` identity. Numeric control fields remain
                        # closed and therefore retain invalid declarations.
                        if number is not None or key in numeric_fields:
                            declared.add(number)
                    walk(child)
            elif isinstance(node, list):
                for child in node:
                    walk(child)

        walk(payload)
        return declared

    @classmethod
    def _short_plan_json_explicit_event_sequences(
        cls, payload: object,
    ) -> list[list[str]]:
        ownership_fields = {"event_ids", "packet_event_ids"}
        sequences: list[list[str]] = []

        def walk(node: object) -> None:
            if isinstance(node, dict):
                for raw_key, child in node.items():
                    key = cls._short_plan_json_key(raw_key)
                    if key in ownership_fields:
                        if isinstance(child, str):
                            raw_items = planning_event_ids(
                                child, formal_only=True,
                            )
                        elif isinstance(child, list):
                            raw_items = []
                            for item in child:
                                if not isinstance(item, str):
                                    continue
                                item_ids = planning_event_ids(
                                    item, formal_only=True,
                                )
                                if len(item_ids) == 1:
                                    raw_items.extend(item_ids)
                        else:
                            raw_items = []
                        sequences.append(list(raw_items))
                    walk(child)
            elif isinstance(node, list):
                for child in node:
                    walk(child)

        walk(payload)
        return sequences

    @classmethod
    def _short_plan_json_event_narrative(cls, item: dict) -> str:
        """Project schema-independent descriptive evidence into one body.

        Stable ownership comes from the event ID, not a provider-selected
        wrapper or field name. Known concise fields are retained first for
        readability, then nested human-readable evidence is appended without
        identifiers, hashes, boundary state, or machine-control metadata.
        """
        pieces: list[str] = []
        preferred_fields = (
            "narrative_summary", "event_body", "description", "summary",
            "causal_plan", "resolution", "causal_trigger", "approach",
        )
        for key in preferred_fields:
            value = item.get(key)
            if isinstance(value, str) and value.strip():
                pieces.append(value.strip())
                break

        identity_fields = {
            "block_id", "event_id", "event_ids", "id", "obligation_id",
            "obligation_ids", "packet_event_ids", "segment", "segment_id",
            "segment_identity", "segment_index", "segment_label",
            "segment_number", "segment_order", "segment_title", "source_sha256",
        }
        boundary_fields = {
            "entry_conditions", "entry_handoff", "entry_state", "exit_conditions",
            "entry_boundary", "exit_boundary", "exit_handoff", "exit_state",
            "handoff", "handoff_in",
            "handoff_out", "handoff_to_next_segment", "opening",
            "segment_entry_condition", "segment_exit_condition",
        }
        descriptor_only_fields = {
            "event_label", "kind", "kinds", "label", "participants_used",
            "required_participants", "identity_stable_participants",
        }

        def collect(node: object, path: tuple[str, ...]) -> None:
            if isinstance(node, dict):
                for raw_key, child in node.items():
                    key = cls._short_plan_json_key(raw_key)
                    if (
                        key in identity_fields
                        or key in boundary_fields
                        or key.endswith("_sha256")
                        or key.endswith("_hash")
                    ):
                        continue
                    collect(child, path + (key,))
            elif isinstance(node, list):
                for child in node:
                    collect(child, path)
            elif isinstance(node, str):
                value = node.strip()
                if not value or (path and path[-1] in descriptor_only_fields):
                    return
                if (
                    planning_event_ids(value, formal_only=True)
                    and planning_protocol_comparison_view(value).strip().upper()
                    == planning_event_ids(value, formal_only=True)[0]
                ):
                    return
                if re.fullmatch(r"[0-9a-f]{32,64}", value, re.IGNORECASE):
                    return
                meaningful = re.sub(r"[^0-9A-Za-z\u3400-\u9fff]+", "", value)
                if len(meaningful) >= 6:
                    pieces.append(value)

        collect(item, ())
        unique: list[str] = []
        seen: set[str] = set()
        for piece in pieces:
            normalized = re.sub(r"\s+", " ", piece).strip()
            if normalized and normalized not in seen:
                seen.add(normalized)
                unique.append(piece.strip())
        narrative = remove_planning_event_ids(
            "\n".join(unique).strip(), formal_only=True,
        )
        return re.sub(r"\n{3,}", "\n\n", narrative).strip()

    @classmethod
    def _short_plan_json_embedded_markdown_candidate(
        cls, payload: object, *, segment: int, event_ids: list[str],
        current: str, artifact: str,
    ) -> str | None:
        """Extract one complete Markdown segment nested in an open JSON wrapper.

        Providers sometimes return a protocol envelope whose narrative artifact
        is stored as a string under an arbitrary container key. The wrapper
        controls identity, while the embedded Markdown remains subject to the
        canonical segment parser. Distinct valid candidates are ambiguous and
        are rejected instead of choosing one by traversal order.
        """
        expected = [str(value or "").strip().upper() for value in event_ids]
        candidates: dict[str, str] = {}

        def unwrap(value: str) -> str:
            source = str(value or "").lstrip("\ufeff").strip()
            if source.startswith("<!--") and source.endswith("-->"):
                source = source[4:-3].strip()
            lines = source.splitlines()
            if len(lines) >= 3:
                opening = lines[0].strip()
                closing = lines[-1].strip()
                is_fenced = (
                    opening.startswith("~~~")
                    or opening.startswith(chr(96) * 3)
                ) and (
                    closing.startswith("~~~")
                    or closing.startswith(chr(96) * 3)
                )
                if is_fenced:
                    source = "\n".join(lines[1:-1]).strip()
            return source

        def visit(node: object) -> None:
            if isinstance(node, str):
                source = unwrap(node)
                if len(source) < 80 or not cls._short_plan_headings(source):
                    return
                try:
                    block = cls._require_short_plan_segment(
                        source, segment, artifact=f"{artifact} embedded Markdown",
                    )
                    normalized = cls._generated_short_plan_markdown_projection(
                        block,
                        segment=segment,
                        event_ids=expected,
                        current=current,
                        artifact=f"{artifact} embedded Markdown",
                    )
                except GeneratedArtifactShapeError:
                    return
                if (
                    cls._short_plan_declared_event_ids(normalized) == expected
                    and all(
                        cls._short_plan_field(normalized, field)
                        for field in cls.SHORT_PLAN_FIELD_ALIASES
                    )
                ):
                    digest = hashlib.sha256(
                        normalized.encode("utf-8"),
                    ).hexdigest()
                    candidates.setdefault(digest, normalized)
                return
            if isinstance(node, dict):
                for child in node.values():
                    visit(child)
            elif isinstance(node, list):
                for child in node:
                    visit(child)

        visit(payload)
        if len(candidates) > 1:
            raise GeneratedArtifactShapeError(
                f"{artifact} JSON packet contains multiple distinct embedded Markdown segments",
                issues=[{
                    "code": "planning_packet_embedded_markdown_ambiguous",
                    "segment": segment,
                    "event_ids": expected,
                    "candidate_count": len(candidates),
                    "blocking": True,
                }],
            )
        return next(iter(candidates.values()), None)

    @classmethod
    def _short_plan_json_event_candidates(
        cls, payload: object, *, artifact: str,
    ) -> list[tuple[str, str, str, dict]]:
        """Discover leaf-most event records by identity, not container name."""

        def exact_event_id(value: object) -> str:
            candidate = planning_protocol_comparison_view(value).strip().upper()
            event_ids = planning_event_ids(candidate, formal_only=True)
            return event_ids[0] if len(event_ids) == 1 and candidate == event_ids[0] else ""

        def visit(
            node: object, *, inherited_id: str = "",
        ) -> list[tuple[str, str, str, dict]]:
            if isinstance(node, list):
                records: list[tuple[str, str, str, dict]] = []
                for child in node:
                    records.extend(visit(child))
                return records
            if not isinstance(node, dict):
                return []

            direct_ids = {
                exact_event_id(node.get(key))
                for key in ("event_id", "id") if node.get(key) is not None
            } - {""}
            if len(direct_ids) > 1:
                raise GeneratedArtifactShapeError(
                    f"{artifact} JSON event object has conflicting identities"
                )
            direct_id = next(iter(direct_ids), "")
            if inherited_id and direct_id and inherited_id != direct_id:
                raise GeneratedArtifactShapeError(
                    f"{artifact} JSON event mapping conflicts with its child identity"
                )
            owner_id = inherited_id or direct_id
            descendants: list[tuple[str, str, str, dict]] = []
            for raw_key, child in node.items():
                mapped_id = exact_event_id(raw_key)
                descendants.extend(visit(
                    child, inherited_id=mapped_id,
                ))

            narrative = cls._short_plan_json_event_narrative(node)
            meaningful = re.sub(
                r"[^0-9A-Za-z\u3400-\u9fff]+", "", narrative,
            )
            descendant_ids = {record[0] for record in descendants}
            if owner_id and len(meaningful) >= 12 and owner_id not in descendant_ids:
                label = str(
                    node.get("label") or node.get("event_label") or owner_id
                ).strip()
                return [(owner_id, label, narrative, node)] + descendants
            return descendants

        return visit(payload)

    @classmethod
    def _short_plan_json_boundary_value(
        cls, payload: object, event_items: list[dict], *, role: str,
        artifact: str,
    ) -> str:
        if role == "opening":
            aliases = {
                "entry_boundary": 0, "entry_handoff": 0, "handoff_in": 0,
                "segment_entry_condition": 0, "opening": 0,
                "entry_state": 1, "entry_conditions": 1,
            }
            preferred = event_items[:1]
        else:
            aliases = {
                "exit_boundary": 0, "exit_handoff": 0, "handoff_out": 0,
                "handoff_to_next_segment": 0, "segment_exit_condition": 0,
                "handoff": 0, "exit_state": 1, "exit_conditions": 1,
            }
            preferred = event_items[-1:]

        def boundary_text(value: object) -> str:
            """Project a complete boundary value without discarding structure.

            Providers legitimately return entry/exit state as a mapping of
            character, location, knowledge, or promise state.  The state is
            narrative authority, not a free-form label, so preserve the full
            value in a deterministic JSON representation.  Scalars other than
            non-empty strings are not accepted as state evidence.
            """
            if isinstance(value, str):
                return value.strip()
            if isinstance(value, (dict, list)) and value:
                return json.dumps(
                    value,
                    ensure_ascii=False,
                    sort_keys=True,
                    separators=(",", ":"),
                )
            return ""

        def candidates(node: object) -> list[tuple[int, str]]:
            found: list[tuple[int, str]] = []

            def walk(current: object) -> None:
                if isinstance(current, dict):
                    for raw_key, child in current.items():
                        key = cls._short_plan_json_key(raw_key)
                        if key in aliases:
                            text = boundary_text(child)
                            if text:
                                found.append((aliases[key], text))
                        walk(child)
                elif isinstance(current, list):
                    for child in current:
                        walk(child)

            walk(node)
            return found

        preferred_found: list[tuple[int, str]] = []
        for item in preferred:
            preferred_found.extend(candidates(item))
        found = preferred_found
        if not preferred_found or min(
            rank for rank, _value in preferred_found
        ) > 0:
            global_found = candidates(payload)
            if global_found and (
                not preferred_found
                or min(rank for rank, _value in global_found)
                < min(rank for rank, _value in preferred_found)
            ):
                found = global_found
        if not found:
            return ""
        best_rank = min(rank for rank, _value in found)
        values: list[str] = []
        for rank, value in found:
            if rank == best_rank and value not in values:
                values.append(value)
        if len(values) != 1:
            raise GeneratedArtifactShapeError(
                f"{artifact} JSON packet has ambiguous {role} state"
            )
        return values[0]

    @classmethod
    def _short_plan_beam_summary_event_body(
        cls, current: str, normalized_events: list[tuple[str, str, str]],
        expected: list[str], *, artifact: str,
    ) -> str:
        """Apply a structured beam summary without replacing accepted prose.

        Some providers answer a complete-segment rebuild request with a
        ``beam_plan`` object that contains only obligations and boundary
        decisions.  Those values are useful repair instructions, but they are
        not a complete narrative realization.  Treating them as the event body
        collapses the current best plan.  The accepted event-owned body remains
        authority; the provider summary is appended only to its matching event
        as an explicit obligation/boundary amendment.  The caller still runs
        retention, obligation, handoff, and whole-plan validation afterwards.
        """
        source_body = cls._short_plan_field(current, "event")
        current_ids = cls._short_plan_event_ids(current)
        source_issues = planning_event_body_issues(current, expected)
        if not source_body or current_ids != expected or source_issues:
            issue = {
                "code": "planning_packet_summary_authority_missing",
                "message": (
                    f"{artifact} is a structured summary but the retained "
                    "event body cannot be projected without ambiguity"
                ),
                "event_ids": expected,
                "actual_event_ids": current_ids,
                "source_issues": source_issues,
                "blocking": True,
            }
            raise GeneratedArtifactShapeError(issue["message"], issues=[issue])

        body_ids = planning_event_ids(source_body, formal_only=True)
        pieces: list[str] = []
        for event_id, _label, narrative in normalized_events:
            if len(expected) == 1 and not body_ids:
                source_piece = (
                    f"1. **正式事件**（{event_id}）：{source_body}"
                )
            else:
                source_piece = cls._short_plan_event_owned_body(
                    current, [event_id],
                )
                owned_ids = planning_event_ids(source_piece, formal_only=True)
                if owned_ids != [event_id]:
                    issue = {
                        "code": "planning_packet_summary_authority_missing",
                        "message": (
                            f"{artifact} cannot bind its structured summary "
                            f"to exactly one retained event body ({event_id})"
                        ),
                        "event_id": event_id,
                        "event_ids": expected,
                        "actual_event_ids": owned_ids,
                        "blocking": True,
                    }
                    raise GeneratedArtifactShapeError(
                        issue["message"], issues=[issue],
                    )
            pieces.append(
                f"{source_piece.rstrip()}\n\n"
                f"   - **结构化义务与边界**：{narrative}"
            )
        return cls._renumber_short_plan_event_body("\n\n".join(pieces))

    @classmethod
    def _short_plan_retention_source(
        cls, current: str, *, segment: int, event_ids: list[str],
    ) -> str:
        """Compare packet retention against the same event-owned authority.

        A capacity packet may own one event while ``current`` is still the
        complete multi-event segment. Comparing those two bodies directly
        makes every legitimate packet look like it deleted its siblings. Only
        project when the requested IDs form the same exact ordered subset and
        the resulting packet retains a complete independently owned body.
        """
        expected = [str(item).strip().upper() for item in event_ids]
        current_ids = cls._short_plan_event_ids(current)
        if current_ids == expected:
            return current
        requested = set(expected)
        if [item for item in current_ids if item in requested] != expected:
            return current
        projected = cls._short_plan_repair_event_projection(
            current, segment=segment, event_ids=expected,
        )
        if (
            cls._short_plan_event_ids(projected) != expected
            or planning_event_body_issues(projected, expected)
        ):
            return current
        return projected

    @classmethod
    def _normalize_generated_short_plan_segment(
        cls, value: str, *, segment: int, event_ids: list[str],
        current: str, artifact: str,
    ) -> str:
        """Normalize one unambiguous generated planning packet.

        Markdown remains canonical. A single JSON object may be accepted as a
        presentation variant only when it declares the same segment and exact
        ordered event ownership and provides complete event bodies plus entry
        and exit state. The normalized block still re-enters every existing
        semantic validator and never becomes a second narrative authority.
        """
        try:
            canonical_block = cls._require_short_plan_segment(
                value, segment, artifact=artifact,
            )
            expected = [
                str(event_id).strip().upper() for event_id in event_ids
            ]
            if (
                cls._short_plan_declared_event_ids(canonical_block) == expected
                and all(
                    cls._short_plan_field(canonical_block, field)
                    for field in cls.SHORT_PLAN_FIELD_ALIASES
                )
            ):
                return canonical_block
            numbered_headings = [
                (match, number)
                for match, number in cls._short_plan_headings(value)
                if number is not None
            ]
            position = next(
                index for index, (_match, number) in enumerate(numbered_headings)
                if number == segment
            )
            start = numbered_headings[position][0].start()
            end = (
                numbered_headings[position + 1][0].start()
                if position + 1 < len(numbered_headings) else len(value)
            )
            block = value[start:end].strip() or canonical_block
            return cls._generated_short_plan_markdown_projection(
                block,
                segment=segment,
                event_ids=event_ids,
                current=current,
                artifact=artifact,
            )
        except GeneratedArtifactShapeError as markdown_error:
            marker_present = bool(cls._short_plan_variant_label_matches(
                value,
                ("segment-only plan", "segment only plan", "segment-only", "segment only"),
            ))
            identity_present = bool(cls._short_plan_variant_label_matches(
                value, ("段标识", "段标签", "segment identity", "segment label"),
            ))
            if marker_present or identity_present:
                return cls._normalize_generated_short_plan_markdown_packet(
                    value,
                    segment=segment,
                    event_ids=event_ids,
                    current=current,
                    artifact=artifact,
                )
            try:
                payload = GeneratedArtifactGateway().convert_object(
                    value, contract_name="short_plan_packet",
                ).payload
            except (TypeError, ValueError, json.JSONDecodeError):
                try:
                    payload = cls._parse_short_plan_event_array(
                        value, artifact=artifact,
                    )
                except ValueError:
                    raise markdown_error

        expected = [str(event_id).strip().upper() for event_id in event_ids]
        unsafe_controls = cls._short_plan_json_unknown_control_fields(payload)
        if unsafe_controls:
            issue = {
                "code": "planning_packet_unknown_control_field",
                "message": (
                    f"{artifact} JSON packet contains unknown machine-control "
                    f"fields: {unsafe_controls}"
                ),
                "segment": segment,
                "event_ids": expected,
                "fields": unsafe_controls,
                "blocking": True,
            }
            raise GeneratedArtifactShapeError(issue["message"], issues=[issue])

        declared_numbers = cls._short_plan_json_declared_segments(payload)
        if isinstance(payload, list) and any(
            cls._short_plan_json_declared_segments(item) != {segment}
            for item in payload
        ):
            declared_numbers = {None}
        if not declared_numbers or declared_numbers != {segment}:
            raise GeneratedArtifactShapeError(
                f"{artifact} JSON packet has ambiguous segment identity "
                f"(expected={segment}, declared={sorted(map(str, declared_numbers))})"
            )

        for declared_ids in cls._short_plan_json_explicit_event_sequences(payload):
            if declared_ids != expected:
                raise GeneratedArtifactShapeError(
                    f"{artifact} JSON packet changed explicit event ownership "
                    f"(expected={expected}, received={declared_ids})"
                )

        event_records = cls._short_plan_json_event_candidates(
            payload, artifact=artifact,
        )
        if not event_records:
            embedded = cls._short_plan_json_embedded_markdown_candidate(
                payload,
                segment=segment,
                event_ids=expected,
                current=current,
                artifact=artifact,
            )
            if embedded is not None:
                return embedded
            raise GeneratedArtifactShapeError(
                f"{artifact} JSON packet has no owned events with narrative evidence"
            )
        normalized_events = [
            (event_id, label, narrative)
            for event_id, label, narrative, _item in event_records
        ]
        owned = [item[0] for item in normalized_events]
        if owned != expected or len(owned) != len(set(owned)):
            raise GeneratedArtifactShapeError(
                f"{artifact} JSON packet changed ordered event ownership "
                f"(expected={expected}, received={owned})"
            )

        event_items = [item for _id, _label, _narrative, item in event_records]
        opening = cls._short_plan_json_boundary_value(
            payload, event_items, role="opening", artifact=artifact,
        )
        handoff = cls._short_plan_json_boundary_value(
            payload, event_items, role="handoff", artifact=artifact,
        )
        if not opening or not handoff:
            raise GeneratedArtifactShapeError(
                f"{artifact} JSON packet lacks complete entry or exit state"
            )
        projected_event_body = "\n\n".join(
            f"{index}. **{label_value if label_value.upper() != event_id else '正式事件'}**"
            f"（{event_id}）：{narrative}"
            for index, (event_id, label_value, narrative) in enumerate(
                normalized_events, 1,
            )
        )
        event_body = projected_event_body
        retention_source = cls._short_plan_retention_source(
            current, segment=segment, event_ids=expected,
        )
        provisional = cls._render_short_plan_repair_packet(
            current,
            segment=segment,
            event_ids=expected,
            event_body=projected_event_body,
            opening=opening,
            handoff=handoff,
        )
        collapsed = any(
            item.get("code") == "event_body_collapsed"
            for item in planning_event_body_retention_issues(
                retention_source, provisional, expected,
            )
        )
        if collapsed:
            event_body = cls._short_plan_beam_summary_event_body(
                retention_source, normalized_events, expected,
                artifact=artifact,
            )
        normalized = cls._render_short_plan_repair_packet(
            current,
            segment=segment,
            event_ids=expected,
            event_body=event_body,
            opening=opening,
            handoff=handoff,
        )
        return cls._require_short_plan_segment(
            normalized, segment, artifact=f"normalized {artifact}",
        )

    @classmethod
    def _short_plan_packet_contract_issues(
        cls, value: str, *, segment: int, event_ids: list[str],
        source: str, obligation_checklists: dict[str, dict] | None = None,
    ) -> list[dict]:
        """Return actionable protocol and semantic issues for one packet."""
        expected = [str(event_id).strip().upper() for event_id in event_ids]
        issues: list[dict] = []

        def add(item: dict) -> None:
            bound = dict(item)
            bound.setdefault("segment", segment)
            if not bound.get("event_id") and not bound.get("event_ids"):
                bound["event_ids"] = expected
            bound.setdefault("blocking", True)
            issues.append(bound)

        headings = [
            number for _match, number in cls._short_plan_headings(value)
            if number is not None
        ]
        blocks = cls._short_plan_segments_for_range(value, segment, segment)
        if headings != [segment] or len(blocks) != 1:
            add({
                "code": "planning_packet_segment_shape",
                "message": (
                    "规划修复分包必须只包含当前正式段；"
                    f"expected={[segment]}, received={headings}"
                ),
            })
            return issues
        block = blocks[0]
        received = cls._short_plan_declared_event_ids(block)
        if received != expected or len(received) != len(set(received)):
            add({
                "code": "planning_packet_event_ownership",
                "message": (
                    "规划修复分包改变了正式事件所有权或顺序；"
                    f"expected={expected}, received={received}"
                ),
                "expected_event_ids": expected,
                "actual_event_ids": received,
            })
        missing = [
            field for field in cls.SHORT_PLAN_FIELD_ALIASES
            if not cls._short_plan_field(block, field)
        ]
        if missing:
            add({
                "code": "planning_packet_field_missing",
                "message": f"规划修复分包缺少完整字段：{missing}",
                "fields": missing,
            })
        for item in planning_event_body_issues(block, expected):
            add(item)
        for item in planning_event_obligation_issues(
            block, expected, obligation_checklists,
        ):
            add(item)
        retention_source = cls._short_plan_retention_source(
            source, segment=segment, event_ids=expected,
        )
        for item in planning_event_body_retention_issues(
            retention_source, block, expected,
        ):
            add(item)
        return issues

    def _save_short_causal_chain(
        self, run_id: str, project: Project, chain: dict,
    ) -> None:
        LearningSystem(self.db, self.references, self.projects, self.gateway).build_short_causal_chain(
            project.id, chain,
        )
        self.db.add_run_event(
            run_id, "success", "causal_chain_saved",
            "短篇整篇因果链已保存为项目资料",
            stage="planning", metadata={"cycles": len(chain.get("cycles") or [])},
        )

    async def _split_short_causal_chain_packets(
        self, run_id: str, run_path: Path, project: Project, constraints: str,
        plan: str, required_events: list[dict], target_words: int, details: dict,
    ) -> str:
        """Execute a hash-bound, recursively divisible causal Map/Reduce tree."""
        if not required_events:
            raise ValueError("causal chain has no formal events to split")
        required_ids = [
            str(item.get("id") or "").strip().upper()
            for item in required_events
        ]
        if any(not event_id for event_id in required_ids):
            raise ValueError("causal chain formal events require stable IDs")
        if len(required_ids) != len(set(required_ids)):
            raise ValueError("causal chain formal event IDs must be unique")

        event_by_id = dict(zip(required_ids, required_events))
        event_position = {
            event_id: index for index, event_id in enumerate(required_ids)
        }
        plan_sha256 = hashlib.sha256(plan.encode("utf-8")).hexdigest()
        authority_sha256 = canonical_sha256({
            "version": 1,
            "task_kind": "short_causal_chain",
            "plan_sha256": plan_sha256,
            "formal_events": required_events,
            "target_words": target_words,
        })
        detected_segments = [
            number for _heading, number in self._short_plan_headings(plan)
            if number is not None
        ]
        segment_count = max(
            self._short_segment_count(target_words),
            max(detected_segments, default=0),
        )
        plan_segments = self._short_plan_segments(plan, segment_count)
        plan_by_segment = {
            number: block for number, block in enumerate(plan_segments, 1)
        }
        segment_by_event: dict[str, int] = {}
        for number, block in plan_by_segment.items():
            for event_id in self._short_plan_event_ids(block):
                previous = segment_by_event.get(event_id)
                if previous is not None and previous != number:
                    raise ValueError(
                        f"causal chain event {event_id} belongs to multiple plan segments"
                    )
                segment_by_event[event_id] = number
        packet_dir = run_path / "outputs" / "causal-chain-packets"
        packet_dir.mkdir(parents=True, exist_ok=True)

        def has_value(value: object) -> bool:
            if value is None:
                return False
            if isinstance(value, str):
                return bool(value.strip())
            if isinstance(value, (list, dict, tuple, set)):
                return bool(value)
            return True

        def contract_for(
            owned_ids: Sequence[str], *, parent_packet_id: str,
            depth: int, predecessor_sha256: str,
        ) -> SemanticPacketContract:
            normalized = tuple(
                str(event_id or "").strip().upper() for event_id in owned_ids
            )
            start = event_position.get(normalized[0], -1)
            end = event_position.get(normalized[-1], -1)
            if (
                start < 0 or end < start
                or tuple(required_ids[start:end + 1]) != normalized
            ):
                raise ValueError(
                    "causal packet ownership must be one contiguous event range"
                )
            context_ids = tuple(
                event_id for event_id in (
                    required_ids[start - 1] if start else "",
                    required_ids[end + 1] if end + 1 < len(required_ids) else "",
                ) if event_id
            )
            segment_numbers = tuple(dict.fromkeys(
                segment_by_event[event_id]
                for event_id in normalized if event_id in segment_by_event
            ))
            return SemanticPacketContract(
                task_kind="short_causal_chain",
                authority_sha256=authority_sha256,
                parent_packet_id=parent_packet_id,
                depth=depth,
                owned_event_ids=normalized,
                context_event_ids=context_ids,
                segment_numbers=segment_numbers,
                predecessor_sha256=predecessor_sha256,
            )

        def normalize_packet(
            value: object, contract: SemanticPacketContract,
        ) -> dict | None:
            return normalize_causal_packet_payload(
                value,
                expected_event_ids=contract.owned_event_ids,
                owns_opening=required_ids[0] in contract.owned_event_ids,
                owns_ending=required_ids[-1] in contract.owned_event_ids,
            )

        def parse_packet(
            text: str, contract: SemanticPacketContract,
        ) -> dict | None:
            try:
                return self._convert_generated_object(
                    text, run_path, contract_name="short_causal_chain",
                    semantic_normalizer=lambda value: normalize_packet(
                        value, contract,
                    ),
                    expected_event_ids=contract.owned_event_ids,
                    owns_opening=required_ids[0] in contract.owned_event_ids,
                    owns_ending=required_ids[-1] in contract.owned_event_ids,
                )
            except (TypeError, ValueError, json.JSONDecodeError):
                return None

        def plan_projection(contract: SemanticPacketContract) -> str:
            projections: list[str] = []
            for number in contract.segment_numbers:
                block = plan_by_segment.get(number, "")
                owned = [
                    event_id for event_id in contract.owned_event_ids
                    if segment_by_event.get(event_id) == number
                ]
                if block and owned:
                    projections.append(
                        self._short_plan_repair_event_projection(
                            block, segment=number, event_ids=owned,
                        )
                    )
            return "\n\n".join(projections) or json.dumps(
                [event_by_id[event_id] for event_id in contract.owned_event_ids],
                ensure_ascii=False, indent=2,
            )

        def context_projection(contract: SemanticPacketContract) -> str:
            return json.dumps(
                [event_by_id[event_id] for event_id in contract.context_event_ids],
                ensure_ascii=False, indent=2,
            )

        def merge_packets(
            contract: SemanticPacketContract, packets: Sequence[dict],
        ) -> dict:
            children = [
                tuple(str(value).upper() for value in packet.get(
                    "covered_event_ids", []
                ))
                for packet in packets
            ]
            if not exact_ordered_partition(contract.owned_event_ids, children):
                raise ValueError(
                    "causal packet reduction has duplicate, missing, or reordered ownership"
                )
            merged: dict[str, object] = {
                "core_goal": "",
                "opening": {},
                "cycles": [],
                "accidents": [],
                "reversal": {},
                "ending": "",
                "question_chain": [],
                "relationship_arc": [],
                "covered_event_ids": [],
            }
            for packet in packets:
                covered = packet.get("covered_event_ids") or []
                if required_ids[0] in covered:
                    merged["core_goal"] = packet.get("core_goal") or ""
                    merged["opening"] = packet.get("opening") or {}
                if isinstance(packet.get("cycles"), list):
                    merged["cycles"].extend(packet["cycles"])
                if isinstance(packet.get("accidents"), list):
                    merged["accidents"].extend(packet["accidents"])
                if has_value(packet.get("reversal")):
                    merged["reversal"] = packet.get("reversal")
                if required_ids[-1] in covered:
                    merged["ending"] = packet.get("ending") or ""
                for field in ("question_chain", "relationship_arc"):
                    value = packet.get(field)
                    values = value if isinstance(value, list) else (
                        [value] if has_value(value) else []
                    )
                    known = {
                        canonical_sha256(item) for item in merged[field]
                    }
                    for item in values:
                        digest = canonical_sha256(item)
                        if digest not in known:
                            merged[field].append(item)
                            known.add(digest)
                merged["covered_event_ids"].extend(covered)
            normalized = normalize_packet(merged, contract)
            if normalized is None:
                raise ValueError(
                    "causal packet reduction failed its owned-range contract"
                )
            return normalized

        def save_packet(
            contract: SemanticPacketContract, packet: dict,
        ) -> None:
            path = write_validated_packet(packet_dir, contract, packet)
            self.db.save_workflow_node_checkpoint(
                run_id=run_id,
                node_key=f"causal-packet-authority-{contract.packet_id[:24]}",
                authority_sha256=authority_sha256,
                input_sha256=contract.packet_id,
                output_sha256=canonical_sha256(packet),
                status="validated",
                validation_stage="local_semantics",
                payload={
                    "packet_id": contract.packet_id,
                    "event_ids": list(contract.owned_event_ids),
                    "depth": contract.depth,
                    "checkpoint": path.name,
                    "packet": packet,
                },
            )

        async def execute_group(contract: SemanticPacketContract) -> dict:
            checkpoint_source = "artifact"
            stored = load_validated_packet(
                packet_dir, contract,
                payload_validator=lambda value: normalize_packet(
                    value, contract,
                ) is not None,
            )
            if stored is None:
                database_checkpoint = self.db.load_workflow_node_checkpoint(
                    run_id=run_id,
                    node_key=f"causal-packet-authority-{contract.packet_id[:24]}",
                    authority_sha256=authority_sha256,
                    input_sha256=contract.packet_id,
                    statuses=("validated",),
                    min_validation_stage="local_semantics",
                )
                database_packet = (
                    (database_checkpoint.get("payload") or {}).get("packet")
                    if isinstance(database_checkpoint, dict) else None
                )
                normalized_database_packet = normalize_packet(
                    database_packet, contract,
                )
                if (
                    normalized_database_packet is not None
                    and database_checkpoint.get("output_sha256")
                    == canonical_sha256(normalized_database_packet)
                ):
                    write_validated_packet(
                        packet_dir, contract, normalized_database_packet,
                    )
                    stored = normalized_database_packet
                    checkpoint_source = "database_mirror"
            if stored is not None:
                self.db.add_run_event(
                    run_id, "success", "causal_chain_packet_reused",
                    "已复用通过校验的因果链语义分包",
                    stage="planning", metadata={
                        "packet_id": contract.packet_id,
                        "depth": contract.depth,
                        "event_ids": list(contract.owned_event_ids),
                        "source": checkpoint_source,
                    },
                )
                return stored

            async def split_again(split_details: dict) -> str:
                return json.dumps(
                    await split_group(contract, split_details),
                    ensure_ascii=False,
                )

            owned_events = [
                event_by_id[event_id] for event_id in contract.owned_event_ids
            ]
            owned_plan = plan_projection(contract)

            def render_prompt(protocol_error: str = "") -> str:
                prompt_value = (
                    "SHORT_CAUSAL_CHAIN_EVENT_PACKET_V2\n"
                    "Generate one causal-chain packet for exactly the owned contiguous formal "
                    "events. Return one JSON object only. Context events are read-only and MUST "
                    "NOT appear in covered_event_ids. Preserve formal agency, dependencies, entry "
                    "and exit state, knowledge, relationships, timeline, promises, and ending.\n"
                    "Every cycle requires obstacle, effort, result, and state_change. Only the "
                    "packet owning the first formal event may fill core_goal/opening; only the "
                    "packet owning the last formal event may fill ending. Other global fields "
                    "must use their empty JSON form.\n"
                    f"PACKET CONTRACT:\n{contract.model_dump_json()}\n"
                    f"PLAN SHA256: {plan_sha256}\n"
                    "EXPECTED EVENT IDS:\n"
                    + json.dumps(list(contract.owned_event_ids), ensure_ascii=False)
                    + "\n\nFORMAL EVENTS:\n"
                    + json.dumps(owned_events, ensure_ascii=False, indent=2)
                    + "\n\nOWNED PLAN PROJECTION:\n" + owned_plan
                    + "\n\nREAD-ONLY NEIGHBOR CONTEXT:\n"
                    + context_projection(contract)
                )
                if protocol_error:
                    prompt_value += (
                        "\n\nPROTOCOL ERROR TO CORRECT WITHOUT CHANGING OWNERSHIP:\n"
                        + protocol_error[:800]
                    )
                return prompt_value

            async def call_route(
                *, fallback: bool, protocol_error: str = "",
            ) -> dict | None:
                raw_packet = await self._stage(
                    run_id, run_path, project, "planning", constraints,
                    render_prompt(protocol_error),
                    suffix=(
                        f"-causal-chain-packet-{contract.packet_id[:16]}"
                        + ("-fallback" if fallback else "")
                        + ("-protocol-retry" if protocol_error else "")
                    ),
                    allow_tools=False,
                    prefer_configured_fallback=fallback,
                    primary_only=not fallback,
                    expected_output_characters=max(
                        1200, 650 * len(contract.owned_event_ids),
                    ),
                    completion_check=lambda value: parse_packet(
                        value, contract,
                    ) is not None,
                    route_capacity_guard=True,
                    capacity_splitter=(
                        split_again if len(contract.owned_event_ids) > 1 else None
                    ),
                    bounded_protocol_output=True,
                    compact_input=True,
                    story_skeleton_override=self._stage_story_skeleton(
                        project, constraints, run_path,
                        owner_event_ids=list(contract.owned_event_ids),
                        index_only=True,
                    ),
                )
                return parse_packet(raw_packet, contract)

            primary_error: Exception | None = None
            try:
                packet = await call_route(fallback=False)
            except asyncio.CancelledError:
                raise
            except Exception as exc:
                primary_error = exc
                packet = None
            if packet is not None:
                save_packet(contract, packet)
                return packet

            if primary_error is None:
                self.db.add_run_event(
                    run_id, "warning", "causal_chain_packet_protocol_retry",
                    "因果链分包返回完整但未通过所有权或结构校验，正在仅重试该协议包",
                    stage="planning", metadata={
                        "packet_id": contract.packet_id,
                        "event_ids": list(contract.owned_event_ids),
                    },
                )
                try:
                    packet = await call_route(
                        fallback=False,
                        protocol_error=(
                            "Return exactly the expected ordered covered_event_ids, at least one "
                            "closed causal cycle, and no first/last global field outside this "
                            "packet's ownership."
                        ),
                    )
                except asyncio.CancelledError:
                    raise
                except Exception as exc:
                    primary_error = exc
                    packet = None
                if packet is not None:
                    save_packet(contract, packet)
                    return packet

            if len(contract.owned_event_ids) > 1 and (
                primary_error is None
                or isinstance(primary_error, IncompleteModelOutputError)
                or classify_model_failure(primary_error) == "input_context_overflow"
            ):
                packet = await split_group(contract, {
                    "trigger": "output_or_protocol",
                    "pressure": "split",
                    "provider_error": (
                        str(primary_error)[:500] if primary_error else "protocol_invalid"
                    ),
                })
                save_packet(contract, packet)
                return packet

            self.db.add_run_event(
                run_id, "warning", "causal_chain_packet_model_fallback",
                "因果链失败分包正在切换到 planning 角色的已配置备用模型",
                stage="planning", metadata={
                    "packet_id": contract.packet_id,
                    "event_ids": list(contract.owned_event_ids),
                    "error_type": (
                        type(primary_error).__name__
                        if primary_error else "protocol_invalid"
                    ),
                },
            )
            try:
                packet = await call_route(
                    fallback=True,
                    protocol_error=(
                        "The primary route did not produce a complete valid packet."
                    ),
                )
            except asyncio.CancelledError:
                raise
            except Exception as fallback_error:
                if len(contract.owned_event_ids) > 1:
                    packet = await split_group(contract, {
                        "trigger": "fallback_failure",
                        "pressure": "split",
                        "provider_error": str(fallback_error)[:500],
                    })
                else:
                    primary_route_error = primary_error or GeneratedArtifactShapeError(
                        "indivisible causal packet remained invalid on the primary route"
                    )
                    raise ModelRoutesExhaustedError(
                        primary_route_error, fallback_error,
                    ) from fallback_error
            if packet is None:
                if len(contract.owned_event_ids) > 1:
                    packet = await split_group(contract, {
                        "trigger": "fallback_protocol",
                        "pressure": "split",
                    })
                else:
                    fallback_protocol_error = GeneratedArtifactShapeError(
                        "indivisible causal packet remained invalid after fallback"
                    )
                    if primary_error is not None:
                        raise ModelRoutesExhaustedError(
                            primary_error, fallback_protocol_error,
                        )
                    raise fallback_protocol_error
            save_packet(contract, packet)
            return packet

        async def split_group(
            contract: SemanticPacketContract, split_details: dict,
        ) -> dict:
            if len(contract.owned_event_ids) <= 1:
                return await execute_group(contract)
            boundary_keys = [
                segment_by_event.get(event_id, f"event:{event_id}")
                for event_id in contract.owned_event_ids
            ]
            left_ids, right_ids = semantic_bisect(
                contract.owned_event_ids, boundary_keys=boundary_keys,
            )
            if not exact_ordered_partition(
                contract.owned_event_ids, (left_ids, right_ids),
            ):
                raise ValueError("causal semantic split changed event ownership")
            left_contract = contract_for(
                left_ids,
                parent_packet_id=contract.packet_id,
                depth=contract.depth + 1,
                predecessor_sha256=contract.predecessor_sha256,
            )
            left = await execute_group(left_contract)
            right_contract = contract_for(
                right_ids,
                parent_packet_id=contract.packet_id,
                depth=contract.depth + 1,
                predecessor_sha256=canonical_sha256(left),
            )
            right = await execute_group(right_contract)
            merged = merge_packets(contract, (left, right))
            self.db.add_run_event(
                run_id, "success", "causal_chain_packet_reduced",
                "因果链子包已按正式事件顺序完成确定性合并",
                stage="planning", metadata={
                    "packet_id": contract.packet_id,
                    "left_packet_id": left_contract.packet_id,
                    "right_packet_id": right_contract.packet_id,
                    "event_ids": list(contract.owned_event_ids),
                    "trigger": split_details.get("trigger"),
                },
            )
            return merged

        root_contract = contract_for(
            required_ids,
            parent_packet_id="root-causal-chain",
            depth=0,
            predecessor_sha256="",
        )
        merged = await split_group(root_contract, details)
        required_coverage = [
            str(item).upper() for item in merged.get("covered_event_ids", [])
            if str(item).strip()
        ]
        if (
            analyze_short_causal_chain(merged, target_words)["status"] == "invalid"
            or required_coverage != required_ids
        ):
            raise ValueError(
                "causal-chain semantic packets merged but failed whole-chain validation"
            )
        save_packet(root_contract, merged)
        return json.dumps(merged, ensure_ascii=False)

    async def _ensure_short_causal_chain(
        self, run_id: str, run_path: Path, project: Project, constraints: str,
        plan: str, formal_outline_events: list[dict], candidate: dict | None,
    ) -> dict:
        target_words = int(project.metadata["target_words"])

        def valid(value: dict | None, *, require_coverage: bool) -> bool:
            if not isinstance(value, dict):
                return False
            if analyze_short_causal_chain(value, target_words)["status"] == "invalid":
                return False
            required_ids = [
                str(item.get("id") or "").upper()
                for item in narrative_outline_events(formal_outline_events)
                if str(item.get("id") or "").strip()
            ]
            covered = [
                str(item).upper() for item in value.get("covered_event_ids", [])
                if str(item).strip()
            ]
            return not require_coverage or not required_ids or covered == required_ids

        if valid(candidate, require_coverage=False):
            # Compatibility: older combined plans did not declare coverage, but a
            # validated embedded chain is still a required checkpoint artifact.
            atomic_write(
                run_path / "outputs" / "short-causal-chain.json",
                json.dumps(candidate, ensure_ascii=False, indent=2),
            )
            return candidate

        required_events = narrative_outline_events(formal_outline_events)
        required_ids = [
            str(item.get("id") or "").strip().upper()
            for item in required_events if str(item.get("id") or "").strip()
        ]

        def parse_chain(text: str) -> dict | None:
            try:
                return self._convert_generated_object(
                    text, run_path, contract_name="short_causal_chain",
                    semantic_normalizer=lambda value: (
                        value if isinstance(value, dict)
                        and valid(value, require_coverage=True) else None
                    ),
                    expected_event_ids=required_ids,
                )
            except (TypeError, ValueError, json.JSONDecodeError):
                return None

        atomic_write(
            run_path / "outputs" / "short-execution-index.json",
            json.dumps({
                "version": 4,
                "status": "causal_pending",
                "planning_sha256": hashlib.sha256(plan.encode("utf-8")).hexdigest(),
                "state_revision": self.story_states.ensure(
                    project.id, project.path,
                ).revision,
                "segment_count": self._short_segment_count(target_words),
                "beats": [], "segments": [], "semantic_receipt": {},
                "repair_attempts": 0,
            }, ensure_ascii=False, indent=2),
        )
        prompt = (
            "SHORT_CAUSAL_CHAIN_STANDALONE\n"
            "根据已经通过检查的正式规划，单独生成整篇短篇因果链。只返回一个 JSON 对象，"
            "不要 Markdown 围栏或说明。必须包含 core_goal、opening、cycles、accidents、"
            "reversal、ending、question_chain、relationship_arc、covered_event_ids。"
            "covered_event_ids 必须逐项、按原顺序覆盖正式大纲事件 ID；不得补写规划中没有的事实。\n\n"
            f"正式大纲事件：\n{json.dumps(required_events, ensure_ascii=False)}\n\n"
            f"已验收规划：\n{plan}"
        )

        def complete(text: str) -> bool:
            return parse_chain(text) is not None

        async def split_causal_chain(details: dict) -> str:
            return await self._split_short_causal_chain_packets(
                run_id, run_path, project, constraints, plan,
                required_events, target_words, details,
            )

        raw = await self._stage(
            run_id, run_path, project, "planning", constraints, prompt,
            suffix="-causal-chain", allow_tools=False,
            expected_output_characters=max(2500, len(plan) // 2),
            completion_check=complete,
            route_capacity_guard=True,
            capacity_splitter=split_causal_chain,
            bounded_protocol_output=True,
            compact_input=True,
        )
        try:
            chain = parse_chain(raw)
        except (TypeError, ValueError, json.JSONDecodeError) as exc:
            chain = None
            last_error = str(exc)
        else:
            last_error = (
                "" if chain is not None
                else "semantic causal-chain validation failed"
            )
        for repair_attempt in range(1, 3):
            if valid(chain, require_coverage=True):
                break
            self.db.add_run_event(
                run_id, "warning", "causal_chain_repair",
                "因果链未覆盖全部正式事件，正在单独修正该资料",
                stage="planning", metadata={
                    "attempt": repair_attempt, "error": last_error[:300],
                },
            )
            if repair_attempt == 2 and required_events:
                repaired = await split_causal_chain({
                    "trigger": "protocol_invalid",
                    "pressure": "split",
                    "provider_error": last_error[:500],
                })
            else:
                repaired = await self._stage(
                    run_id, run_path, project, "planning", constraints,
                    prompt + (
                        f"\n\n第 {repair_attempt} 次输出没有通过完整性检查："
                        f"{last_error[:500]}\n重新返回完整 JSON，尤其确保"
                        "covered_event_ids 与正式大纲事件 ID 完全同序、无缺失。"
                    ),
                    suffix=f"-causal-chain-repair-{repair_attempt}", allow_tools=False,
                    expected_output_characters=max(2500, len(plan) // 2),
                    completion_check=complete,
                    route_capacity_guard=True,
                    capacity_splitter=split_causal_chain,
                    bounded_protocol_output=True,
                    compact_input=True,
                )
            try:
                chain = parse_chain(repaired)
            except (TypeError, ValueError, json.JSONDecodeError) as exc:
                chain = None
                last_error = str(exc)
            else:
                last_error = (
                    "" if chain is not None
                    else "semantic causal-chain validation failed"
                )
        if not valid(chain, require_coverage=True):
            self.db.add_run_event(
                run_id, "error", "causal_chain_not_ready",
                "因果链尚未完整生成，已在正文开始前停止",
                stage="planning", metadata={"error": last_error[:500]},
            )
            raise ValueError("短篇因果链未通过事件覆盖和因果完整性检查，尚未生成正文")
        atomic_write(
            run_path / "outputs" / "short-causal-chain.json",
            json.dumps(chain, ensure_ascii=False, indent=2),
        )
        return chain

    def _short_execution_authority(
        self, project: Project, state_revision: int, state: dict, constraints: str,
        plan: str, causal_chain: dict, formal_outline_events: list[dict],
        segment_count: int, planning_adaptation: dict | None = None,
    ) -> tuple[dict[str, str], str, list[dict]]:
        if planning_adaptation is not None and not self._planning_adaptation_artifact_valid(
            planning_adaptation, state, plan, formal_outline_events, segment_count,
        ):
            raise ValueError("规划等价展开回执与当前大纲、规划或分段不一致")
        outline = state.get("outline") if isinstance(state, dict) else {}
        outline = outline if isinstance(outline, dict) else {}
        outline_content = str(outline.get("content") or "")
        events = (
            narrative_outline_event_contracts(outline_content)
            if outline_content.strip() else []
        )
        if not events:
            events = narrative_outline_events(formal_outline_events)
        normalized_events: list[dict] = []
        for order, item in enumerate(events, 1):
            event = dict(item)
            event_id = str(event.get("id") or "").strip().upper()
            if not event_id:
                continue
            evidence = str(event.get("evidence") or "").strip()
            if not evidence:
                label = str(event.get("label") or "").strip()
                evidence = label if label and label in outline_content else outline_content
                evidence = evidence.strip() or label or event_id
            normalized_events.append({
                **event,
                "id": event_id,
                "order": order,
                "presentation_order": order,
                "source_order": int(event.get("source_order") or event.get("order") or order),
                "kind": "narrative",
                "source": str(event.get("source") or "formal_outline"),
                "evidence": evidence,
                "story_time": str(event.get("story_time") or "").strip(),
                "timeline": str(event.get("timeline") or "").strip(),
                "actor": str(event.get("actor") or "").strip(),
                "location": str(event.get("location") or "").strip(),
                "viewpoint": str(event.get("viewpoint") or "").strip(),
                "knowledge_delta": list(event.get("knowledge_delta") or []),
                "relationship_delta": list(event.get("relationship_delta") or []),
            })
        events = effective_event_contracts(normalized_events, planning_adaptation)
        if not events:
            plan_segments = WorkflowService._short_plan_segments(plan, segment_count)
            if not plan_segments:
                plan_segments = [plan]
            fallback_blocks: dict[str, list[str]] = {}
            fallback_order: list[str] = []
            for index, block in enumerate(plan_segments, 1):
                event_ids = WorkflowService._short_plan_event_ids(block)
                if not event_ids:
                    event_ids = ["EV-" + hashlib.sha1(
                        f"{project.id}|{index}|{block}".encode("utf-8"),
                    ).hexdigest()[:8].upper()]
                for event_id in event_ids:
                    if event_id not in fallback_blocks:
                        fallback_blocks[event_id] = []
                        fallback_order.append(event_id)
                    fallback_blocks[event_id].append(block)
            events = [{
                "id": event_id,
                "order": index,
                "label": f"已验收规划事件 {event_id}",
                "section": "已验收规划",
                "kind": "narrative",
                "source": "accepted_plan_fallback",
                "evidence": "\n\n".join(fallback_blocks[event_id]),
                "presentation_order": index,
                "source_order": index,
                "story_time": "",
                "timeline": "",
                "actor": "",
                "location": "",
                "viewpoint": "",
                "knowledge_delta": [],
                "relationship_delta": [],
            } for index, event_id in enumerate(fallback_order, 1)]
        outline_sha = hashlib.sha256(outline_content.encode("utf-8")).hexdigest()
        planning_sha = hashlib.sha256(plan.encode("utf-8")).hexdigest()
        causal_json = json.dumps(
            causal_chain, ensure_ascii=False, sort_keys=True, separators=(",", ":"),
        )
        causal_sha = hashlib.sha256(causal_json.encode("utf-8")).hexdigest()
        authority_payload = {
            "project_id": project.id,
            "state_revision": state_revision,
            "constraints_sha256": hashlib.sha256(
                constraints.encode("utf-8"),
            ).hexdigest(),
            "outline_sha256": outline_sha,
            "planning_sha256": planning_sha,
            "causal_chain_sha256": causal_sha,
            "segment_count": segment_count,
        }
        adaptation_sha = ""
        if isinstance(planning_adaptation, dict) \
                and planning_adaptation.get("status") == "ready":
            adaptation_sha = planning_adaptation_artifact_sha256(planning_adaptation)
            authority_payload["planning_adaptation_sha256"] = adaptation_sha
        authority_sha = hashlib.sha256(json.dumps(
            authority_payload, ensure_ascii=False, sort_keys=True,
            separators=(",", ":"),
        ).encode("utf-8")).hexdigest()
        hashes = {
            "authority_sha256": authority_sha,
            "outline_sha256": outline_sha,
            "planning_sha256": planning_sha,
            "causal_chain_sha256": causal_sha,
        }
        authority_text = (
            "FORMAL OUTLINE:\n" + outline_content
            + "\n\nNARRATIVE EVENT CONTRACTS:\n"
            + json.dumps(events, ensure_ascii=False, indent=2)
            + "\n\nACCEPTED PLAN:\n" + plan
            + ("\n\nAUTHORIZED PLAN ADAPTATIONS:\n"
               + json.dumps(planning_adaptation, ensure_ascii=False, indent=2)
               if adaptation_sha else "")
            + "\n\nCAUSAL CHAIN:\n"
            + json.dumps(causal_chain, ensure_ascii=False, indent=2)
        )
        return hashes, authority_text, events

    @staticmethod
    def _short_manifest_fragment_authority(
        event_contracts: list[dict], plan_segment: str, causal_chain: dict,
        previous_exit: tuple[StateAssertion, ...], narrative_authority: dict,
    ) -> str:
        return (
            "CURRENT EVENT CONTRACTS:\n"
            + json.dumps(event_contracts, ensure_ascii=False, indent=2)
            + "\n\nCURRENT ACCEPTED PLAN SEGMENT:\n" + plan_segment
            + "\n\nWHOLE-STORY CAUSAL AUTHORITY:\n"
            + json.dumps(causal_chain, ensure_ascii=False, indent=2)
            + "\n\nPREVIOUS ACCEPTED EXIT STATE:\n"
            + json.dumps(
                [asdict(item) for item in previous_exit],
                ensure_ascii=False, indent=2,
            )
            + "\n\nVIEWPOINT AND TIMELINE AUTHORITY:\n"
            + json.dumps(narrative_authority, ensure_ascii=False, indent=2)
        )

    @staticmethod
    def _short_manifest_fragment_schema(segment: int) -> dict:
        return {
            "beats": [{
                "beat_id": "EV-XXXXXXXX/NN",
                "source_event_id": "EV-XXXXXXXX",
                "order": 1,
                "presentation_order": 1,
                "actor": "人物、群体、环境、制度、系统或未知",
                "location": "正式资料明确的地点；没有则为空字符串",
                "action": "不改变执行者的一个原子动作",
                "preconditions": ["动作发生前已经成立的状态"],
                "postconditions": ["该动作直接产生的状态"],
                "owner_segment": segment,
                "source_evidence": "逐字摘自对应 CURRENT EVENT CONTRACT 的 evidence",
                "story_time": "仅在正式资料明确时填写；倒叙不得改成顺叙",
                "timeline": "多时间线标识；没有则为空字符串",
                "viewpoint": "正式资料明确的视角；没有则为空字符串",
                "knowledge_delta": ["本节拍明确造成的知情变化"],
                "relationship_delta": ["本节拍明确造成的关系变化"],
            }],
            "segments": [{
                "segment": segment,
                "beat_ids": ["当前段按展示顺序拥有的全部节拍 ID"],
                "entry_state": [{
                    "state": "进入当前段前已经成立的状态",
                    "inherited_from": "opening 或上一正式段",
                }],
                "exit_state": [{
                    "state": "当前段结束时成立的状态",
                    "produced_by": ["当前段拥有的一个或多个 EV-XXXXXXXX/NN"],
                }],
                "previous_exit_sha256": "由 Runtime 绑定，返回空字符串即可",
                "prohibited_future_beat_ids": [],
            }],
        }

    @staticmethod
    def _bind_short_execution_fragment_handoff(
        body: dict, *, previous_exit: tuple[StateAssertion, ...],
    ) -> tuple[dict, int]:
        """Bind accepted adjacent state without asking a model to echo authority."""
        raw_segments = body.get("segments")
        if (
            not isinstance(raw_segments, list)
            or len(raw_segments) != 1
            or not isinstance(raw_segments[0], dict)
        ):
            return body, 0

        segment_body = dict(raw_segments[0])
        segment_body["previous_exit_sha256"] = (
            state_assertions_sha256(previous_exit, version=4)
            if previous_exit else ""
        )
        entry_state = segment_body.get("entry_state")
        added = 0
        if isinstance(entry_state, list) and all(
            isinstance(item, dict) for item in entry_state
        ):
            bound_entry_state = [dict(item) for item in entry_state]
            present_states = {
                str(item.get("state") or "").strip()
                for item in bound_entry_state
                if str(item.get("state") or "").strip()
            }
            inherited = []
            for assertion in previous_exit:
                if assertion.state in present_states:
                    continue
                inherited.append({
                    "state": assertion.state,
                    "produced_by": [],
                    "inherited_from": "previous-segment-exit",
                })
                present_states.add(assertion.state)
                added += 1
            if inherited:
                segment_body["entry_state"] = inherited + bound_entry_state

        return {**body, "segments": [segment_body]}, added

    async def _generate_short_execution_fragment(
        self, run_id: str, run_path: Path, project: Project, constraints: str,
        hashes: dict[str, str], segment: int, event_contracts: list[dict],
        plan_segment: str, causal_chain: dict,
        previous_exit: tuple[StateAssertion, ...],
        previous_fragment_sha256: str, future_event_ids: list[str],
        narrative_authority: dict, *, semantic_directive: str = "",
        previous_body: dict | None = None,
        max_schema_repairs: int = 2, max_integrity_repairs: int = 2,
        output_label: str = "initial",
    ) -> tuple[ShortExecutionManifest | None, dict, list[dict], dict]:
        expected_event_ids = [
            str(item.get("id") or "").strip().upper()
            for item in event_contracts
        ]
        fragment_authority = self._short_manifest_fragment_authority(
            event_contracts, plan_segment, causal_chain, previous_exit,
            narrative_authority,
        )
        base_prompt = (
            "SHORT_EXECUTION_MANIFEST_FRAGMENT_V4\n"
            "这是 Runtime 拆出的单一正式写作段子任务，只返回一个 JSON 对象。"
            "不得改写正式大纲、规划、因果链或上一段出口；不得提前消费后续事件。\n"
            "CURRENT EVENT CONTRACT 中 evidence 是经过独立核对后生效的当前规划实现；"
            "若同时存在 formal_evidence 和 adaptation，只能执行 evidence 中已授权的等价展开，"
            "不得把旧实现与当前实现混合，也不得借等价展开改变 adaptation 声明保留的不变量。\n"
            "原子节拍必须保持正式资料的展示顺序。倒叙、多时间线和多视角作品也按展示顺序执行，"
            "story_time 与 timeline 只记录故事内时间，不得据此重排。"
            "actor 可以是人物、群体、环境、制度、系统或未知；有原文依据才填写可选状态变化。\n"
            "exit_state.produced_by 必须是数组，列出共同产生该状态的全部当前段节拍 ID；"
            "不得把多个 ID 拼成一个字符串。段前已经成立的状态应放入 entry_state，"
            "并通过 inherited_from 继承；不得使用 narrative_overview 等非节拍标签冒充来源。\n"
            f"AUTHORITY SHA256: {hashes['authority_sha256']}\n"
            f"TASK ID: manifest-segment-{segment:02d}\n"
            f"PARENT TASK ID: {run_id}\nDEPTH: 1\n"
            f"CURRENT SEGMENT: {segment}\n"
            f"PREVIOUS ACCEPTED FRAGMENT SHA256: {previous_fragment_sha256}\n"
            "EXPECTED EVENT IDS:\n"
            + json.dumps(expected_event_ids, ensure_ascii=False)
            + "\n\nFUTURE EVENT IDS (FORBIDDEN IN THIS TASK):\n"
            + json.dumps(future_event_ids, ensure_ascii=False)
            + "\n\nREQUIRED EXIT FROM ACCEPTED PLAN:\n"
            + self._short_plan_handoff(plan_segment)
            + "\n\nOUTPUT BODY SCHEMA:\n"
            + json.dumps(
                self._short_manifest_fragment_schema(segment),
                ensure_ascii=False, indent=2,
            )
            + "\n\nFRAGMENT AUTHORITY TEXT:\n" + fragment_authority
        )
        if semantic_directive:
            base_prompt += "\n\nSEMANTIC REPAIR DIRECTIVE:\n" + semantic_directive
        if previous_body:
            base_prompt += (
                "\n\nPREVIOUS VALID-SCHEMA FRAGMENT:\n"
                + json.dumps(previous_body, ensure_ascii=False, indent=2)
            )

        schema_repairs = 0
        integrity_repairs = 0
        call_number = 0
        last_issues: list[dict] = []
        last_body: dict = dict(previous_body or {})
        while True:
            call_number += 1
            prompt = base_prompt
            if last_issues:
                prompt += (
                    "\n\nLOCAL REPAIR ISSUES (fix every item):\n"
                    + json.dumps(last_issues, ensure_ascii=False, indent=2)
                    + "\n\nLAST RETURNED BODY:\n"
                    + json.dumps(last_body, ensure_ascii=False, indent=2)
                )
            raw = await self._stage(
                run_id, run_path, project, "planning", constraints, prompt,
                suffix=(
                    f"-execution-segment-{segment:02d}-{output_label}-{call_number}"
                ),
                allow_tools=False,
                expected_output_characters=max(1800, 850 * len(event_contracts)),
            )
            try:
                body = self._convert_generated_object(
                    raw, run_path, contract_name="execution_manifest",
                )
            except (TypeError, ValueError, json.JSONDecodeError) as exc:
                last_issues = [{
                    "code": "invalid_manifest_json", "message": str(exc)[:500],
                }]
                if schema_repairs >= max_schema_repairs:
                    break
                schema_repairs += 1
            else:
                source_body_sha256 = canonical_sha256(body)
                body, handoff_count = self._bind_short_execution_fragment_handoff(
                    body, previous_exit=previous_exit,
                )
                last_body = body
                if handoff_count:
                    self.db.add_run_event(
                        run_id, "info",
                        "planning_manifest_runtime_handoff_bound",
                        "Runtime 已绑定上一正式段的验收出口，模型当前段内容保持不变",
                        stage="planning", metadata={
                            "segment": segment,
                            "added_state_count": handoff_count,
                            "previous_exit_sha256": state_assertions_sha256(
                                previous_exit, version=4,
                            ),
                            "source_body_sha256": source_body_sha256,
                            "bound_body_sha256": canonical_sha256(body),
                        },
                    )
                payload = {
                    **body, "version": 4, "status": "fragment_ready", **hashes,
                    "semantic_receipt": {},
                    "repair_attempts": schema_repairs + integrity_repairs,
                }
                try:
                    fragment = parse_execution_manifest(payload)
                except (TypeError, ValueError) as exc:
                    last_issues = [{
                        "code": "invalid_manifest_schema", "message": str(exc)[:500],
                    }]
                    if schema_repairs >= max_schema_repairs:
                        break
                    schema_repairs += 1
                else:
                    last_issues = execution_manifest_fragment_issues(
                        fragment,
                        owner_segment=segment,
                        expected_event_ids=expected_event_ids,
                        authority_hashes=hashes,
                        expected_events=event_contracts,
                        previous_exit_state=previous_exit,
                    )
                    if not last_issues:
                        return fragment, {
                            "schema_repairs": schema_repairs,
                            "integrity_repairs": integrity_repairs,
                        }, [], last_body
                    if integrity_repairs >= max_integrity_repairs:
                        break
                    integrity_repairs += 1
            self.db.add_run_event(
                run_id, "info", "planning_manifest_fragment_repair",
                f"正在修正规划执行索引第 {segment} 段，正式大纲保持不变",
                stage="planning", metadata={
                    "segment": segment,
                    "repair_mode": output_label,
                    "schema_repairs": schema_repairs,
                    "integrity_repairs": integrity_repairs,
                    "issues": last_issues,
                },
            )
        return None, {
            "schema_repairs": schema_repairs,
            "integrity_repairs": integrity_repairs,
        }, last_issues, last_body

    @staticmethod
    def _execution_manifest_boundary_evidence_candidates(
        plan_segment: str, segment: int,
    ) -> dict[str, str]:
        """Return bounded exact plan excerpts that may prove segment boundaries."""
        lines = [line.strip() for line in plan_segment.splitlines() if line.strip()]
        if not lines:
            return {}
        selected: list[str] = []
        boundary_markers = ("段首", "段末", "交接", "入口", "出口", "承接")
        for index, line in enumerate(lines):
            if any(marker in line for marker in boundary_markers):
                selected.extend(lines[max(0, index - 1):index + 7])
        if not selected:
            selected.extend(lines[:8])
            selected.extend(lines[-16:])
        unique = list(dict.fromkeys(selected))
        return {
            f"SEG-{segment:02d}-E{index:03d}": evidence
            for index, evidence in enumerate(unique, 1)
        }

    async def _review_short_execution_fragment(
        self, run_id: str, run_path: Path, project: Project, constraints: str,
        fragment: ShortExecutionManifest, fragment_authority: str,
        plan_segment: str, segment: int, *, suffix: str,
    ) -> tuple[dict, list[dict]]:
        expected_manifest_hash = execution_manifest_sha256(fragment)
        boundary_candidates = self._execution_manifest_boundary_evidence_candidates(
            plan_segment, segment,
        )
        last_issues: list[dict] = []
        for receipt_attempt in range(3):
            prompt = (
                "SHORT_EXECUTION_MANIFEST_FRAGMENT_SEMANTIC_VALIDATION_V4\n"
                "只核对当前正式段，只返回一个 JSON 语义回执。逐项检查人物/非人物执行者、动作、"
                "视角、地点、展示顺序、故事时间、知情与关系变化、入口/出口状态。"
                "不能因为题材不同而猜测未写明的规则；倒叙不得按故事时间重排。\n"
                "若事件合同包含 adaptation，它已经由独立规划审核授权；应以 evidence 中的当前实现"
                "核对节拍，同时确认 event_function、primary_actor_agency、causal_dependencies、"
                "entry_state、exit_state、knowledge_state、relationship_state、viewpoint、timeline_order、"
                "promise_ending 仍保持。formal_plot_unchanged 表示这些结构不变量未改变，"
                "不表示对话、描写或等价触发方式必须逐字等同原大纲。\n"
                "下面两个哈希由 Runtime 准确计算，必须原样回填，不要自行计算：\n"
                f"EXPECTED AUTHORITY SHA256: {fragment.authority_sha256}\n"
                f"EXPECTED MANIFEST SHA256: {expected_manifest_hash}\n"
                "字段：authority_sha256、manifest_sha256、beat_receipts"
                "[{beat_id,actor_action_valid,field_verdicts,invalid_fields,reason}]、"
                "segment_receipts[{segment,boundary_valid,evidence_id}]、"
                "formal_plot_unchanged、summary。field_verdicts 可逐项核对 actor、action、"
                "location、preconditions、postconditions、viewpoint、story_time、timeline、"
                "knowledge_delta、relationship_delta；失败时必须填写 invalid_fields 和 reason。"
                "节拍 evidence 由 Runtime 直接绑定，不要复述。分段 evidence_id 必须从下面候选"
                "中选择，不得改写或拼接原文。\n\nBOUNDARY EVIDENCE CANDIDATES:\n"
                + json.dumps(boundary_candidates, ensure_ascii=False, indent=2)
                + "\n\nEXECUTION MANIFEST:\n"
                + json.dumps(
                    execution_manifest_payload(fragment), ensure_ascii=False, indent=2,
                )
                + "\n\nAUTHORITY TEXT:\n" + fragment_authority
            )
            if last_issues:
                prompt += (
                    "\n\nRECEIPT PROTOCOL ISSUES:\n"
                    + json.dumps(last_issues, ensure_ascii=False, indent=2)
                )
            raw = await self._stage(
                run_id, run_path, project, "review", constraints, prompt,
                suffix=f"-execution-segment-{segment:02d}-{suffix}-{receipt_attempt + 1}",
                allow_tools=False,
                expected_output_characters=max(1000, 260 * len(fragment.beats)),
            )
            try:
                receipt_payload = self._convert_generated_object(
                    raw, run_path,
                    contract_name="execution_manifest_receipt",
                )
            except (TypeError, ValueError, json.JSONDecodeError) as exc:
                receipt_payload = {}
                last_issues = [{
                    "code": "receipt_schema", "message": str(exc)[:500],
                }]
            else:
                receipt_payload = bind_execution_manifest_receipt_evidence(
                    fragment, fragment_authority, receipt_payload,
                    segment_evidence_candidates={segment: boundary_candidates},
                )
                last_issues = execution_manifest_receipt_issues(
                    fragment, fragment_authority, receipt_payload,
                )
                if not last_issues:
                    return validate_execution_manifest_receipt(
                        fragment, fragment_authority, receipt_payload,
                    ), []
                if not execution_manifest_receipt_issues_are_protocol_only(
                    last_issues,
                ):
                    review_summary = str(receipt_payload.get("summary") or "").strip()
                    if review_summary:
                        last_issues = [
                            {**item, "review_summary": review_summary[:800]}
                            for item in last_issues
                        ]
            if (
                receipt_attempt < 2
                and execution_manifest_receipt_issues_are_protocol_only(last_issues)
            ):
                self.db.add_run_event(
                    run_id, "info", "planning_manifest_receipt_protocol_retry",
                    "规划执行索引内容保持不变，正在仅重新获取原文绑定回执",
                    stage="review", metadata={
                        "segment": segment,
                        "attempt": receipt_attempt + 1,
                        "issues": last_issues,
                    },
                )
                continue
            break
        return {}, last_issues

    async def _ensure_short_execution_manifest(
        self, run_id: str, run_path: Path, project: Project, constraints: str,
        state_revision: int, state: dict, plan: str, causal_chain: dict,
        formal_outline_events: list[dict], segment_count: int,
        planning_adaptation: dict | None = None,
    ) -> ShortExecutionManifest:
        hashes, authority_text, expected_events = self._short_execution_authority(
            project, state_revision, state, constraints, plan, causal_chain,
            formal_outline_events, segment_count, planning_adaptation,
        )
        expected_event_ids = [str(item["id"]).upper() for item in expected_events]
        event_by_id = {str(item["id"]).upper(): item for item in expected_events}
        plan_segments = self._short_plan_segments(plan, segment_count)
        if len(plan_segments) != segment_count:
            raise ValueError("规划分段不完整，无法派生逐段执行索引")
        owned_event_ids = [self._short_plan_event_ids(block) for block in plan_segments]
        if segment_count == 1 and not owned_event_ids[0]:
            owned_event_ids[0] = list(expected_event_ids)
        elif len(expected_event_ids) == 1 and all(not group for group in owned_event_ids):
            owned_event_ids = [list(expected_event_ids) for _block in plan_segments]
        invalid_ids = sorted({
            event_id for group in owned_event_ids for event_id in group
            if event_id not in event_by_id
        })
        if invalid_ids or any(not group for group in owned_event_ids):
            raise ValueError(
                "规划事件归属不完整，无法派生逐段执行索引："
                + ("、".join(invalid_ids) if invalid_ids else "存在没有事件 ID 的正式段")
            )

        index_path = run_path / "outputs" / "short-execution-index.json"
        try:
            existing_payload = json.loads(index_path.read_text(encoding="utf-8"))
        except (OSError, UnicodeError, json.JSONDecodeError):
            existing_payload = None
        if not legacy_execution_index_requires_rebuild(existing_payload):
            try:
                existing = parse_execution_manifest(existing_payload)
                issues = execution_manifest_issues(
                    existing, expected_event_ids=expected_event_ids,
                    segment_count=segment_count, authority_hashes=hashes,
                    expected_events=expected_events,
                )
                receipt = validate_execution_manifest_receipt(
                    existing, authority_text, existing.semantic_receipt,
                )
            except (TypeError, ValueError):
                pass
            else:
                if not issues and existing.status == "ready":
                    return replace(existing, semantic_receipt=receipt)

        atomic_write(index_path, json.dumps({
            "version": 4, "status": "manifest_pending", **hashes,
            "beats": [], "segments": [], "semantic_receipt": {},
            "repair_attempts": 0,
        }, ensure_ascii=False, indent=2))
        checkpoints = run_path / "outputs" / "execution-manifest-fragments"
        narrative_authority = {
            "presentation_order": expected_event_ids,
            "timeline_events": state.get("timeline_events", []),
            "viewpoint_rule": str(
                state.get("viewpoint") or state.get("narrative_viewpoint") or ""
            ),
            "nonlinear_rule": (
                "展示顺序是执行顺序；story_time/timeline 只描述故事内时间，"
                "不得把倒叙、插叙、双时间线改成时间顺序。"
            ),
            "planning_adaptation": planning_adaptation or {},
        }
        fragments: list[ShortExecutionManifest] = []
        fragment_receipts: list[dict] = []
        repair_totals = {
            "schema_repairs": 0, "integrity_repairs": 0, "semantic_repairs": 0,
        }
        previous_exit: tuple[StateAssertion, ...] = ()
        previous_fragment_hash = ""
        failure_issues: list[dict] = []
        last_body: dict = {}
        try:
            for segment, (plan_segment, event_ids) in enumerate(
                zip(plan_segments, owned_event_ids), 1,
            ):
                contracts = [event_by_id[event_id] for event_id in event_ids]
                future_event_ids = list(dict.fromkeys(
                    event_id
                    for later in owned_event_ids[segment:]
                    for event_id in later
                ))
                fragment_authority = self._short_manifest_fragment_authority(
                    contracts, plan_segment, causal_chain, previous_exit,
                    narrative_authority,
                )
                fragment_authority_hash = hashlib.sha256(
                    fragment_authority.encode("utf-8"),
                ).hexdigest()
                checkpoint_path = checkpoints / f"segment-{segment:02d}.json"
                fragment = None
                receipt: dict = {}
                try:
                    cached_payload = json.loads(
                        checkpoint_path.read_text(encoding="utf-8"),
                    )
                    if (
                        cached_payload.get("checkpoint_version") != 1
                        or cached_payload.get("previous_fragment_sha256")
                        != previous_fragment_hash
                        or cached_payload.get("fragment_authority_sha256")
                        != fragment_authority_hash
                    ):
                        raise ValueError("execution manifest fragment checkpoint is stale")
                    cached = parse_execution_manifest(cached_payload.get("manifest"))
                    if cached_payload.get("manifest_sha256") != execution_manifest_sha256(
                        cached,
                    ):
                        raise ValueError("execution manifest fragment checkpoint is corrupt")
                    cached_issues = execution_manifest_fragment_issues(
                        cached, owner_segment=segment,
                        expected_event_ids=event_ids,
                        authority_hashes=hashes,
                        expected_events=contracts,
                        previous_exit_state=previous_exit,
                    )
                    cached_receipt = validate_execution_manifest_receipt(
                        cached, fragment_authority, cached.semantic_receipt,
                    )
                except (OSError, UnicodeError, json.JSONDecodeError, TypeError, ValueError):
                    pass
                else:
                    if not cached_issues and cached.status == "fragment_ready":
                        fragment = replace(cached, semantic_receipt=cached_receipt)
                        receipt = cached_receipt

                if fragment is None:
                    fragment, stats, failure_issues, last_body = (
                        await self._generate_short_execution_fragment(
                            run_id, run_path, project, constraints, hashes,
                            segment, contracts, plan_segment, causal_chain,
                            previous_exit, previous_fragment_hash,
                            future_event_ids, narrative_authority,
                        )
                    )
                    for key in ("schema_repairs", "integrity_repairs"):
                        repair_totals[key] += stats[key]
                    if fragment is None:
                        raise ValueError(
                            f"规划执行索引第 {segment} 段未通过结构、覆盖或边界检查"
                        )
                    receipt, semantic_issues = await self._review_short_execution_fragment(
                        run_id, run_path, project, constraints, fragment,
                        fragment_authority, plan_segment, segment, suffix="initial",
                    )
                    if execution_manifest_receipt_issues_are_protocol_only(
                        semantic_issues,
                    ):
                        failure_issues = semantic_issues
                        raise ValueError(
                            f"规划执行索引第 {segment} 段内容已保留，但审核回执未能绑定原文"
                        )
                    for semantic_repair in range(2):
                        if not semantic_issues:
                            break
                        repair_totals["semantic_repairs"] += 1
                        mode = "minimal_patch" if semantic_repair == 0 else "segment_rebuild"
                        directive = (
                            "只修正下列语义问题，保留所有已通过节拍、执行者、展示顺序和边界。"
                            if semantic_repair == 0 else
                            "前一次最小修正仍未通过。重新构建当前完整正式段 fragment，"
                            "但事件范围、展示顺序、入口和要求出口不得改变。"
                        ) + "\n" + json.dumps(
                            semantic_issues, ensure_ascii=False, indent=2,
                        )
                        seed = None if semantic_repair else {
                            "beats": execution_manifest_payload(fragment)["beats"],
                            "segments": execution_manifest_payload(fragment)["segments"],
                        }
                        repaired, stats, failure_issues, last_body = (
                            await self._generate_short_execution_fragment(
                                run_id, run_path, project, constraints, hashes,
                                segment, contracts, plan_segment, causal_chain,
                                previous_exit, previous_fragment_hash,
                                future_event_ids, narrative_authority,
                                semantic_directive=directive, previous_body=seed,
                                max_schema_repairs=2, max_integrity_repairs=2,
                                output_label=mode,
                            )
                        )
                        for key in ("schema_repairs", "integrity_repairs"):
                            repair_totals[key] += stats[key]
                        if repaired is None:
                            semantic_issues = failure_issues
                            continue
                        fragment = repaired
                        receipt, semantic_issues = (
                            await self._review_short_execution_fragment(
                                run_id, run_path, project, constraints, fragment,
                                fragment_authority, plan_segment, segment, suffix=mode,
                            )
                        )
                        if execution_manifest_receipt_issues_are_protocol_only(
                            semantic_issues,
                        ):
                            failure_issues = semantic_issues
                            raise ValueError(
                                f"规划执行索引第 {segment} 段返修内容已保留，"
                                "但审核回执未能绑定原文"
                            )
                    if semantic_issues:
                        failure_issues = semantic_issues
                        raise ValueError(
                            f"规划执行索引第 {segment} 段语义核对仍未通过"
                        )
                    fragment = replace(fragment, semantic_receipt=receipt)
                    atomic_write(checkpoint_path, json.dumps({
                        "checkpoint_version": 1,
                        "authority_sha256": hashes["authority_sha256"],
                        "previous_fragment_sha256": previous_fragment_hash,
                        "fragment_authority_sha256": fragment_authority_hash,
                        "manifest_sha256": execution_manifest_sha256(fragment),
                        "manifest": execution_manifest_payload(fragment),
                    }, ensure_ascii=False, indent=2))
                    self.db.add_run_event(
                        run_id, "success", "planning_manifest_fragment_ready",
                        f"规划执行索引第 {segment} 段已通过独立核对",
                        stage="planning", metadata={
                            "segment": segment, "beat_count": len(fragment.beats),
                        },
                    )

                fragments.append(fragment)
                fragment_receipts.append(receipt)
                previous_exit = fragment.segments[0].exit_state
                previous_fragment_hash = execution_manifest_sha256(fragment)

            manifest = merge_execution_manifest_fragments(
                fragments, authority_hashes=hashes,
                segment_count=segment_count,
                repair_attempts=sum(repair_totals.values()),
            )
            failure_issues = execution_manifest_issues(
                manifest, expected_event_ids=expected_event_ids,
                segment_count=segment_count, authority_hashes=hashes,
                expected_events=expected_events,
            )
            if failure_issues:
                raise ValueError("合并后的规划执行索引未通过整篇检查")

            merged_beat_receipts: list[dict] = []
            merged_segment_receipts: list[dict] = []
            final_beats_by_segment = {
                number: [
                    beat for beat in manifest.beats if beat.owner_segment == number
                ] for number in range(1, segment_count + 1)
            }
            fragment_audit = []
            for number, (fragment, receipt, plan_segment) in enumerate(
                zip(fragments, fragment_receipts, plan_segments), 1,
            ):
                local_beats = sorted(fragment.beats, key=lambda item: item.order)
                final_beats = final_beats_by_segment[number]
                local_receipts = {
                    str(item.get("beat_id") or "").upper(): item
                    for item in receipt.get("beat_receipts", [])
                }
                if len(local_beats) != len(final_beats):
                    raise ValueError("合并后的节拍数量与已审核 fragment 不一致")
                for local, final in zip(local_beats, final_beats):
                    if local.source_event_id != final.source_event_id:
                        raise ValueError("合并后的节拍事件归属发生变化")
                    item = local_receipts[local.beat_id]
                    merged_beat_receipts.append({
                        "beat_id": final.beat_id,
                        "evidence": final.source_evidence,
                        "actor_action_valid": item.get("actor_action_valid") is True,
                    })
                segment_receipt = receipt["segment_receipts"][0]
                evidence = str(segment_receipt.get("evidence") or "").strip()
                if not evidence or evidence not in authority_text:
                    evidence = next(
                        (line.strip() for line in plan_segment.splitlines()
                         if line.strip() and line.strip() in authority_text),
                        plan_segment.strip(),
                    )
                merged_segment_receipts.append({
                    "segment": number,
                    "boundary_valid": segment_receipt.get("boundary_valid") is True,
                    "evidence": evidence,
                })
                fragment_audit.append({
                    "segment": number,
                    "fragment_sha256": execution_manifest_sha256(fragment),
                    "summary": str(receipt.get("summary") or "")[:300],
                })
            aggregate_receipt = {
                "authority_sha256": manifest.authority_sha256,
                "manifest_sha256": execution_manifest_sha256(manifest),
                "beat_receipts": merged_beat_receipts,
                "segment_receipts": merged_segment_receipts,
                "formal_plot_unchanged": all(
                    item.get("formal_plot_unchanged") is True
                    for item in fragment_receipts
                ),
                "summary": "全部正式段已独立审核，并通过 Runtime 合并后的整篇覆盖、顺序与边界核验。",
                "fragment_receipts": fragment_audit,
            }
            receipt = validate_execution_manifest_receipt(
                manifest, authority_text, aggregate_receipt,
            )
            manifest = replace(manifest, semantic_receipt=receipt)
            atomic_write(index_path, json.dumps(
                execution_manifest_payload(manifest), ensure_ascii=False, indent=2,
            ))
        except ValueError as exc:
            protocol_failure = execution_manifest_receipt_issues_are_protocol_only(
                failure_issues,
            )
            failed_beats = [
                asdict(beat) for fragment in fragments for beat in fragment.beats
            ]
            failed_segments = [
                asdict(segment_row)
                for fragment in fragments for segment_row in fragment.segments
            ]
            if isinstance(last_body, dict):
                last_beats = list(last_body.get("beats") or [])
                last_segments = list(last_body.get("segments") or [])
                if protocol_failure:
                    failed_beats.extend(last_beats)
                    failed_segments.extend(last_segments)
                elif not failed_beats:
                    failed_beats = last_beats
                    failed_segments = last_segments
            atomic_write(index_path, json.dumps({
                "version": 4, "status": "failed", **hashes,
                "beats": failed_beats, "segments": failed_segments,
                "semantic_receipt": {},
                "repair_attempts": sum(repair_totals.values()),
                "repair_budgets": repair_totals,
                "content_status": "content_valid" if protocol_failure else "invalid",
                "receipt_status": "failed" if protocol_failure else "not_ready",
                "issues": failure_issues or [{
                    "code": "manifest_failure", "message": str(exc)[:500],
                }],
            }, ensure_ascii=False, indent=2))
            self.db.add_run_event(
                run_id, "error", (
                    "planning_manifest_receipt_failed"
                    if protocol_failure else "planning_manifest_failed"
                ),
                (
                    "规划执行索引内容已保留，但审核回执未能绑定原文，已停止正文生成"
                    if protocol_failure else
                    "规划执行索引仍有事件、执行者、顺序或边界问题，已在正文开始前停止"
                ),
                stage="planning", metadata={
                    "issues": failure_issues, "repair_budgets": repair_totals,
                },
            )
            issue_codes = sorted({
                str(item.get("code") or "").strip()
                for item in failure_issues
                if isinstance(item, dict) and str(item.get("code") or "").strip()
            })
            issue_suffix = (
                f"（issue_codes={','.join(issue_codes)}）" if issue_codes else ""
            )
            failure_message = (
                "规划执行索引审核回执未通过，内容已保留且尚未生成正文"
                if protocol_failure else
                "规划执行索引未通过分段与整篇语义检查，尚未生成正文"
            )
            raise ValueError(
                failure_message + issue_suffix
            ) from exc

        self.db.add_run_event(
            run_id, "success", "planning_manifest_ready",
            "规划执行索引已按正式段生成，并通过整篇结构与语义核对",
            stage="planning", metadata={
                "beat_count": len(manifest.beats),
                "segment_count": len(manifest.segments),
                "repair_budgets": repair_totals,
                "manifest_version": manifest.version,
            },
        )
        return manifest

    async def _quality_polish(self, run_id: str, run_path: Path, project: Project,
                              constraints: str, draft: str, review: dict,
                              chapter_number: int | None = None,
                              chapter_goal: str = "", volume_end: bool = False) -> tuple[str, dict]:
        route = select_route(
            project.mode, chapter_number, chapter_goal, volume_end, review,
        )
        previous_best = self._previous_quality_best(run_path)
        report = {
            "route": route,
            "initial_review": review,
            "reader_review": None,
            "final_attempts": [],
            "status": "running",
            "failure_reasons": [],
            "best_attempt": previous_best["best_attempt"] if previous_best else None,
            "best_score": previous_best["score"] if previous_best else None,
        }
        self._write_quality_report(run_path, report)
        if previous_best:
            self.db.add_run_event(
                run_id, "success", "quality_best_restored",
                "已保留上次运行的最高分稿，本轮只有更高分版本才会替换它",
                stage="quality", metadata={"best_score": previous_best["score"]},
            )
        self.db.add_run_event(
            run_id, "info", "quality_route",
            "已选择重点质量流程" if route["enhanced"] else "已选择标准质量流程",
            stage="quality", metadata=route,
        )
        self._quality_assessed_event(run_id, "editorial", review)

        reader_review = None
        if route["enhanced"]:
            reader_role = ("reader_review"
                           if self.db.get_role_binding("reader_review") else "review")
            fallback_used = reader_role == "review"
            self.db.add_run_event(
                run_id, "info", "quality_escalated",
                "正在使用审核模型回退执行目标读者模拟" if fallback_used
                else "正在使用独立读者模型执行目标读者模拟",
                stage="review", metadata={
                    "reasons": route["reasons"],
                    "model_role": reader_role,
                    "fallback_used": fallback_used,
                },
            )
            try:
                reader_review = await self._reader_review(
                    run_id, run_path, project, constraints, draft,
                    model_role=reader_role,
                )
            except asyncio.CancelledError:
                raise
            except Exception as exc:
                if reader_role == "review":
                    raise
                self.db.add_run_event(
                    run_id, "warning", "reader_fallback",
                    "独立读者模型调用失败，已回退到审核模型",
                    stage="review", metadata={
                        "failed_role": reader_role,
                        "fallback_role": "review",
                        "error": str(exc),
                    },
                )
                reader_review = {
                    **review,
                    "reader_signals": {"unavailable": True, "fallback": "editorial_review"},
                }
            report["reader_review"] = reader_review
            self._quality_assessed_event(run_id, "target_reader", reader_review)
            self._write_quality_report(run_path, report)

        findings = {"editorial": review, "target_reader": reader_review}
        try:
            polished = await self._polish_short_segments(
                run_id, run_path, project, constraints, draft,
                json.dumps(findings, ensure_ascii=False),
            )
        except (RevisionPlanError, PolishTokenBudgetError) as exc:
            self._halt_quality_revision(
                run_id, run_path, report,
                previous_best["text"] if previous_best else draft, exc,
            )
        review_text = "\n\n".join(self._split_segments(polished))
        current_analysis = self._analyze_manuscript(
            review_text, run_path, project, "polish",
        )
        baseline: dict | None = None
        revision_source_hash: str | None = None
        applied_patch_groups: tuple[dict, ...] = ()
        active_profile = profile_for_project(project)

        reasons: list[str] = []
        best_polished = previous_best["text"] if previous_best else polished
        best_review: dict | None = (
            previous_best.get("review") or {"score": previous_best["score"]}
            if previous_best else None
        )
        best_attempt: int | None = (
            previous_best["best_attempt"] if previous_best else None
        )
        best_outcome = str(previous_best.get("outcome") or "") if previous_best else ""
        for attempt in range(route["max_corrections"] + 1):
            reviewed_polished = polished
            review_text = "\n\n".join(self._split_segments(polished))
            final_input = review_text
            if attempt:
                checks_path = run_path / "outputs" / f"revision-checks-{attempt + 1}.json"
                if checks_path.is_file():
                    failures = json.loads(checks_path.read_text(encoding="utf-8")).get("failures", [])
                    if failures:
                        final_input += (
                            "\n\nRUNTIME STRUCTURAL CHECK FAILURES. Treat unresolved failures as hard "
                            f"evidence:\n{json.dumps(failures, ensure_ascii=False)}"
                        )
            try:
                optimized = bool(project.metadata.get("optimized_local_review_enabled", False))
                if attempt and optimized and baseline is not None:
                    final_review, evidence_audit = await self._incremental_manuscript_review(
                        run_id, run_path, project, constraints, review_text,
                        current_analysis, baseline, review,
                        suffix=f"-{attempt + 1}",
                        revision_source_hash=revision_source_hash,
                        patch_groups=applied_patch_groups,
                    )
                    report["final_review_evidence"] = evidence_audit
                    if evidence_audit.get("final_review_recovery"):
                        report["final_review_recovery"] = evidence_audit["final_review_recovery"]
                elif project.mode == "short" and len(final_input) > 6000:
                    final_review, evidence_audit = await self._full_manuscript_review(
                        run_id, run_path, project, constraints, final_input, review,
                        suffix=f"-{attempt + 1}" if attempt else "",
                        analysis=current_analysis,
                    )
                    report["final_review_evidence"] = evidence_audit
                    if evidence_audit.get("final_review_recovery"):
                        report["final_review_recovery"] = evidence_audit["final_review_recovery"]
                else:
                    ledger = issue_ledger(review.get("issues", []))
                    final_input = (
                        quality_profile_prompt(active_profile)
                        + self._causal_chain_review_checks(constraints)
                        + "SINGLE-REQUEST COMPLETE MANUSCRIPT REVIEW. Return strict quality-review "
                        "JSON plus reconciliations. Every prior issue must appear exactly once with "
                        "issue_id, status (resolved, partially_resolved, unresolved, uncertain, or "
                        "preserved), severity, and current-manuscript evidence. Omission never means "
                        "resolved. Do not rewrite the manuscript.\n\n"
                        f"INITIAL ISSUE LEDGER:\n{json.dumps(ledger, ensure_ascii=False)}\n\n"
                        f"COMPLETE MANUSCRIPT:\n{final_input}"
                    )
                    raw_final_review, final_payload = await self._final_review_json(
                        run_id, run_path, project, constraints, final_input,
                        suffix=f"-{attempt + 1}" if attempt else "",
                    )
                    final_review = self._review_for_project(
                        final_payload, project,
                        getattr(raw_final_review, "receipt", {}),
                    )
                    prior_issue_ids = [item["issue_id"] for item in ledger]
                    prior_issue_id_set = set(prior_issue_ids)
                    raw_reconciliations = final_payload.get("reconciliations", [])
                    reconciliations = (
                        raw_reconciliations
                        if (
                            isinstance(raw_reconciliations, list)
                            and all(isinstance(item, dict) for item in raw_reconciliations)
                        )
                        else [
                            item for item in final_payload.get("issues", [])
                            if isinstance(item, dict)
                            and item.get("issue_id") in prior_issue_id_set
                        ]
                    )
                    manuscript_sha256 = hashlib.sha256(
                        review_text.encode("utf-8")
                    ).hexdigest()
                    evidence_audit = {
                        "coverage": 1.0, "window_count": 1, "reviewed_windows": 1,
                        "evidence_count": 1,
                        "prior_issue_ids": prior_issue_ids,
                        "prior_issues": ledger,
                        "reconciliations": reconciliations,
                        "windows": [{
                            "index": 1, "start": 0, "end": len(review_text),
                            "summary": "single-request complete review",
                            "manuscript_sha256": manuscript_sha256,
                            "window_sha256": manuscript_sha256,
                        }],
                        "adjudication_receipt": getattr(raw_final_review, "receipt", {}),
                        "review_mode": "full",
                    }
                    final_review, gate_reasons = apply_evidence_gate(
                        final_review, evidence_audit,
                    )
                    final_review = reconcile_review_issues(
                        final_review, ledger, reconciliations,
                        reviewed_at=datetime.now(timezone.utc).isoformat(),
                    )
                    evidence_audit["gate_reasons"] = gate_reasons
                    if final_payload.get("_recovery_mode"):
                        evidence_audit["final_review_recovery"] = {
                            "attempted": True,
                            "succeeded": True,
                            "mode": "compact_recovery",
                            "count": 1,
                            "message": "终审原始报告不完整，系统已用精简格式恢复报告",
                        }
                        report["final_review_recovery"] = evidence_audit[
                            "final_review_recovery"
                        ]
                report["final_review_evidence"] = evidence_audit
                if attempt == 0:
                    # Full and direct terminal reviews already reconcile every
                    # prior issue. Re-appending the initial ledger here would
                    # manufacture duplicate identities in incremental baselines.
                    baseline_review = final_review
                    baseline = build_review_baseline(
                        review_text, current_analysis,
                        evidence_audit.get("windows", []), baseline_review,
                    )
                    atomic_write(
                        run_path / "outputs" / "final-review-baseline.json",
                        json.dumps(baseline, ensure_ascii=False, indent=2),
                    )
                report.setdefault("review_scope_history", []).append({
                    "attempt": attempt + 1,
                    "mode": evidence_audit.get("review_mode", "full"),
                    "reviewed_windows": evidence_audit.get("reviewed_windows", 1),
                    "window_count": evidence_audit.get("window_count", 1),
                    "selection_reasons": evidence_audit.get("selection_reasons", {}),
                    "fallback_reasons": evidence_audit.get("fallback_reasons", []),
                    "estimated_saved_input_characters": evidence_audit.get(
                        "estimated_saved_input_characters", 0,
                    ),
                })
            except asyncio.CancelledError:
                raise
            except Exception as exc:
                validation_failed = isinstance(exc, ValueError)
                if validation_failed:
                    report_status = "final_review_rejected"
                    event_type = "final_review_result_rejected"
                    message = "终审模型已返回，但结果未通过系统校验，已保留最佳稿"
                else:
                    report_status = "final_review_incomplete"
                    event_type = "final_review_model_failed"
                    message = "终审模型调用失败，已保留最佳稿"
                report["status"] = report_status
                report["terminal_review_complete"] = False
                report["failure_reasons"] = [message]
                if isinstance(exc, FinalReviewJSONError):
                    report["status"] = "final_review_incomplete"
                    report["failure_reasons"] = [str(exc)]
                    report["failure_detail"] = exc.detail
                    report["final_review_recovery"] = {
                        "attempted": True, "succeeded": False,
                        "mode": "compact_recovery",
                        "message": "终审原始返回不完整，精简报告恢复也未完成；最佳稿已保留",
                    }
                    report_status = "final_review_incomplete"
                    event_type = "final_review_model_failed"
                    message = str(exc)
                atomic_write(run_path / "outputs" / "best-candidate.md", best_polished)
                self._write_quality_report(run_path, report)
                self.db.add_run_event(
                    run_id, "error", event_type, message,
                    stage="final_review", metadata={"error": str(exc)},
                )
                raise RuntimeError(message) from exc
            final_review["issues"] = issue_ledger(final_review.get("issues", []))
            outcome, reasons = quality_outcome_for_profile(final_review, active_profile)
            passed = (
                outcome == "passed"
                if active_profile == "zhihu-short-v2"
                else outcome != "failed"
            )
            report["final_attempts"].append({
                "attempt": attempt + 1,
                "review": final_review,
                "passed": passed,
                "outcome": outcome,
                "reasons": reasons,
            })
            report["terminal_review_complete"] = True
            comparison = None
            if best_review is not None and active_profile == "zhihu-short-v2":
                comparison = compare_quality_candidates(best_review, final_review)
            promote = (
                best_review is None
                or (
                    active_profile != "zhihu-short-v2"
                    and final_review["score"] > best_review["score"]
                )
                or bool(comparison and comparison["promote"])
                or bool(
                    comparison and not comparison["comparable"]
                    and outcome == "passed"
                    and final_review.get("scoring_profile_id") == active_profile
                )
            )
            if promote:
                best_review = final_review
                best_polished = reviewed_polished
                best_attempt = attempt + 1
                best_outcome = outcome
                report["best_attempt"] = best_attempt
                report["best_score"] = final_review["score"]
            elif final_review["score"] < best_review["score"]:
                self.db.add_run_event(
                    run_id, "warning", "quality_regression",
                    "本轮评分下降，下一轮将恢复当前最高分版本",
                    stage="quality", metadata={
                        "attempt": attempt + 1,
                        "score": final_review["score"],
                        "best_attempt": best_attempt,
                        "best_score": best_review["score"],
                    },
                )
            self._quality_assessed_event(run_id, "chief_editor", final_review, attempt + 1)
            self._write_quality_report(run_path, report)
            if passed:
                retained_previous = bool(
                    previous_best
                    and final_review["score"] < float(previous_best["score"])
                )
                selected = best_polished if retained_previous else polished
                selected_review = best_review if retained_previous else final_review
                selected_outcome = (
                    str(previous_best.get("outcome") or "passed")
                    if retained_previous else outcome
                )
                if selected_outcome not in {"passed", "conditional_pass"}:
                    selected_outcome = "passed" if float(
                        (selected_review or {}).get("score", 0)
                    ) >= 80 else "conditional_pass"
                selected_review_text = "\n\n".join(self._split_segments(selected))
                report["status"] = selected_outcome
                report["failure_reasons"] = []
                report["terminal_reviewed_hash"] = hashlib.sha256(
                    selected_review_text.encode("utf-8")
                ).hexdigest()
                if retained_previous:
                    self.db.add_run_event(
                        run_id, "success", "quality_best_retained",
                        "本轮候选达到最低门槛，但没有超过受保护最佳稿，已继续保留最佳稿",
                        stage="quality", metadata={
                            "candidate_score": final_review["score"],
                            "best_score": previous_best["score"],
                        },
                    )
                report["scoring_profile_id"] = str(
                    (selected_review or {}).get("scoring_profile_id") or "legacy-v1"
                )
                report["judge_signature"] = str(
                    (selected_review or {}).get("judge_signature") or "legacy-unknown"
                )
                report["terminal_review"] = selected_review
                if not retained_previous and selected_review:
                    self._save_quality_checkpoint(
                        run_path, selected_review_text, selected_review,
                        best_attempt, selected_outcome,
                    )
                self._write_quality_report(run_path, report)
                self.db.add_run_event(
                    run_id, "success", "quality_gate",
                    "质量审核通过" if outcome == "passed" else "质量条件通过，建议小修",
                    stage="quality", metadata={
                        "attempt": attempt + 1,
                        "outcome": outcome,
                        "score": final_review["score"],
                        "dimensions": final_review["dimensions"],
                    },
                )
                return selected, report
            if attempt < route["max_corrections"]:
                self.db.add_run_event(
                    run_id, "warning", "quality_revision",
                    f"质量未达标，开始第 {attempt + 1} 次定向返工",
                    stage="polish", metadata={
                        "attempt": attempt + 1, "reasons": reasons,
                    },
                )
                try:
                    revision_source_hash = hashlib.sha256(
                        best_polished.encode("utf-8")
                    ).hexdigest()
                    polished = await self._polish_short_segments(
                        run_id, run_path, project, constraints, best_polished,
                        json.dumps(final_review, ensure_ascii=False),
                        suffix=f"-{attempt + 2}", structural=True,
                    )
                    current_analysis = self._analyze_manuscript(
                        "\n\n".join(self._split_segments(polished)),
                        run_path, project, f"polish-{attempt + 2}",
                    )
                    applied_patch_groups = ()
                except (RevisionPlanError, PolishTokenBudgetError) as exc:
                    self._halt_quality_revision(
                        run_id, run_path, report, best_polished, exc,
                    )

        if (active_profile == "zhihu-short-v2"
                and best_outcome == "conditional_pass" and best_review):
            clean_best = "\n\n".join(self._split_segments(best_polished))
            report["status"] = "conditional_pass"
            report["failure_reasons"] = []
            report["terminal_review"] = best_review
            report["scoring_profile_id"] = "zhihu-short-v2"
            report["judge_signature"] = str(
                best_review.get("judge_signature") or "legacy-unknown"
            )
            report["terminal_reviewed_hash"] = hashlib.sha256(
                clean_best.encode("utf-8")
            ).hexdigest()
            self._save_quality_checkpoint(
                run_path, clean_best, best_review, best_attempt, "conditional_pass",
            )
            self._write_quality_report(run_path, report)
            self.db.add_run_event(
                run_id, "warning", "quality_conditional_pass",
                "候选稿达到条件通过，但还不能设为正式稿",
                stage="quality", metadata={
                    "score": best_review["score"],
                    "dimensions": best_review["dimensions"],
                },
            )
            raise RuntimeError(
                "Editorial quality gate requires a full pass; preserved conditional candidate"
            )
        report["status"] = "failed"
        report["failure_reasons"] = reasons
        atomic_write(run_path / "outputs" / "best-candidate.md", best_polished)
        self._write_quality_report(run_path, report)
        self.db.add_run_event(
            run_id, "error", "quality_gate", "达到返工上限后仍未通过质量门槛",
            stage="quality", metadata={"reasons": reasons},
        )
        raise RuntimeError("Editorial quality gate did not pass within the correction limit")

    @classmethod
    def _integrity_publication_segments(
        cls, run_path: Path, integrity: dict, publication: str,
    ) -> tuple[list[str], str] | None:
        """Resolve internal semantic segments for a marker-free publication.

        Published prose intentionally omits Runtime's segment sentinel. New
        integrity artifacts carry exact character lengths; older artifacts can
        still be rebound through their hash-matching segmented draft or polish
        file. In either case every recovered segment must match its stored text
        hash and rejoin byte-for-byte to the protected publication text.
        """
        segment_records = integrity.get("segments")
        if not isinstance(segment_records, list) or not segment_records:
            return None
        expected_count = len(segment_records)
        draft_sha256 = str(integrity.get("draft_sha256") or "")

        def valid(parts: list[str], source_text: str) -> bool:
            publication_sha256 = integrity.get("publication_sha256")
            return bool(
                len(parts) == expected_count
                and "\n\n".join(parts) == publication
                and (
                    not isinstance(publication_sha256, str)
                    or publication_sha256
                    == hashlib.sha256(publication.encode("utf-8")).hexdigest()
                )
                and hashlib.sha256(source_text.encode("utf-8")).hexdigest()
                == draft_sha256
                and all(
                    isinstance(record, dict)
                    and record.get("text_sha256") == hashlib.sha256(
                        part.encode("utf-8"),
                    ).hexdigest()
                    for record, part in zip(
                        segment_records, parts, strict=True,
                    )
                )
            )

        lengths = integrity.get("publication_segment_lengths")
        if (
            isinstance(lengths, list)
            and len(lengths) == expected_count
            and all(isinstance(value, int) and value > 0 for value in lengths)
        ):
            parts = []
            cursor = 0
            valid_boundaries = True
            for index, length in enumerate(lengths):
                end = cursor + length
                parts.append(publication[cursor:end])
                cursor = end
                if index < expected_count - 1:
                    if publication[cursor:cursor + 2] != "\n\n":
                        valid_boundaries = False
                        break
                    cursor += 2
            if valid_boundaries and cursor == len(publication):
                for source_text in (
                    publication,
                    cls.SHORT_SEGMENT_SEPARATOR.join(parts),
                ):
                    if valid(parts, source_text):
                        return parts, source_text

        outputs = run_path / "outputs"
        candidates = [
            outputs / "best-candidate.md",
            outputs / "draft.md",
            *sorted(outputs.glob("polish*.md")),
        ]
        seen: set[Path] = set()
        for path in candidates:
            if path in seen:
                continue
            seen.add(path)
            try:
                source_text = path.read_text(encoding="utf-8")
            except (OSError, UnicodeError):
                continue
            parts = cls._split_segments(source_text)
            if valid(parts, source_text):
                return parts, source_text
        return None

    @classmethod
    def _save_quality_checkpoint(
        cls, run_path: Path, manuscript: str, review: dict,
        attempt: int | None, outcome: str,
    ) -> None:
        with QUALITY_CHECKPOINT_LOCK:
            atomic_write(run_path / "outputs" / "best-candidate.md", manuscript)
            digest = hashlib.sha256(manuscript.encode("utf-8")).hexdigest()
            narrative_integrity = None
            for path in sorted(
                (run_path / "outputs").glob("polish-integrity*.json"),
                key=lambda item: item.stat().st_mtime,
                reverse=True,
            ):
                try:
                    candidate = json.loads(path.read_text(encoding="utf-8"))
                except (OSError, UnicodeError, json.JSONDecodeError):
                    continue
                if candidate.get("status") == "passed" and (
                    candidate.get("draft_sha256") == digest
                    or candidate.get("publication_sha256") == digest
                    or cls._integrity_publication_segments(
                        run_path, candidate, manuscript,
                    ) is not None
                ):
                    narrative_integrity = {
                        "path": f"outputs/{path.name}",
                        "sha256": hashlib.sha256(
                            path.read_bytes(),
                        ).hexdigest(),
                    }
                    break
            write_quality_checkpoint(run_path, {
                "manuscript_path": "outputs/best-candidate.md",
                "manuscript_hash": digest,
                "score": float(review["score"]),
                "scoring_profile_id": str(
                    review.get("scoring_profile_id") or "legacy-v1"
                ),
                "judge_signature": str(
                    review.get("judge_signature") or "legacy-unknown"
                ),
                "best_attempt": attempt,
                "review": review,
                "issue_ledger": issue_ledger(review.get("issues", [])),
                "outcome": outcome,
                "terminal_reviewed_hash": digest,
                **({"narrative_integrity": narrative_integrity}
                   if narrative_integrity else {}),
            })

    async def _final_review_json(
        self, run_id: str, run_path: Path, project: Project, constraints: str,
        prompt: str, suffix: str, recovery_kind: str = "review",
    ) -> tuple[str, dict]:
        stage_error: RuntimeError | None = None
        index_skeleton = self._stage_story_skeleton(
            project, constraints, run_path, index_only=True,
        )
        try:
            raw = await self._stage(
                run_id, run_path, project, "final_review", constraints, prompt,
                suffix=suffix, allow_tools=False,
                route_capacity_guard=True,
                story_skeleton_override=index_skeleton,
                bounded_protocol_output=True,
            )
        except RuntimeError as exc:
            if not str(exc).startswith("final_review model returned empty output"):
                raise
            stage_error = exc
            raw = ""
        try:
            if stage_error is not None:
                raise stage_error
            return raw, self._convert_generated_object(
                raw, run_path, contract_name="final_review",
            )
        except (json.JSONDecodeError, ValueError, RuntimeError) as primary_error:
            binding = self.db.get_role_binding("final_review") or {}
            configured_fallback = bool(
                binding.get("fallback_provider_id") and binding.get("fallback_model_id")
                and hasattr(self.gateway, "complete_configured_fallback")
            )
            fallback_error: Exception | None = None
            if configured_fallback:
                self.db.add_run_event(
                    run_id, "warning", "final_review_json_fallback",
                    "终审模型返回内容不完整，正在用备用模型重做当前检查",
                    stage="final_review", metadata={
                        "suffix": suffix, "error": str(primary_error)[:300],
                    },
                )
                try:
                    fallback_raw = await self._stage(
                        run_id, run_path, project, "final_review", constraints, prompt,
                        suffix=f"{suffix}-json-fallback", allow_tools=False,
                        prefer_configured_fallback=True,
                        route_capacity_guard=True,
                        story_skeleton_override=index_skeleton,
                        bounded_protocol_output=True,
                    )
                    return fallback_raw, self._convert_generated_object(
                        fallback_raw, run_path, contract_name="final_review",
                    )
                except (json.JSONDecodeError, ValueError, RuntimeError) as exc:
                    fallback_error = exc

            compact_prompt = self._final_review_compact_prompt(prompt, recovery_kind)
            self.db.add_run_event(
                run_id, "warning", "final_review_compact_recovery_started",
                "终审报告不完整，正在改用精简格式重新检查",
                stage="final_review", metadata={
                    "suffix": suffix, "kind": recovery_kind,
                    "primary_error": str(primary_error)[:300],
                    "fallback_error": str(fallback_error)[:300] if fallback_error else None,
                },
            )
            try:
                compact_raw = await self._stage(
                    run_id, run_path, project, "final_review", constraints,
                    compact_prompt, suffix=f"{suffix}-compact-recovery", allow_tools=False,
                    route_capacity_guard=True,
                    story_skeleton_override=index_skeleton,
                    bounded_protocol_output=True,
                )
                compact_payload = self._convert_generated_object(
                    compact_raw, run_path, contract_name="final_review",
                )
            except (json.JSONDecodeError, ValueError, RuntimeError) as compact_error:
                detail = self._final_review_error_detail(
                    primary_error, fallback_error, compact_error, suffix, recovery_kind,
                )
                raise FinalReviewJSONError(
                    "终审模型返回内容不完整，精简报告恢复也未完成；已保留最佳稿",
                    detail,
                ) from compact_error
            if isinstance(compact_raw, StageText):
                compact_raw.receipt = {
                    **getattr(compact_raw, "receipt", {}),
                    "recovery_mode": "compact_recovery",
                }
            self.db.add_run_event(
                run_id, "warning", "final_review_compact_recovery",
                "终审原始报告不完整，系统已用精简格式恢复报告",
                stage="final_review", metadata={
                    "suffix": suffix, "kind": recovery_kind,
                },
            )
            compact_payload["_recovery_mode"] = "compact_recovery"
            return compact_raw, compact_payload

    @staticmethod
    def _final_review_compact_prompt(prompt: str, kind: str) -> str:
        if kind == "window":
            return (
                "终审窗口精简恢复。请重新阅读当前窗口，只返回一个 JSON 对象，不要解释。"
                "只允许两个字段：summary（不超过240字的窗口摘要）和 issues（最多4条，"
                "每条只含 category、severity、evidence、location、action）。"
                "不要返回 events、character_states、timeline、promises，不要评分，不要复述全文。\n\n"
                + prompt
            )
        if kind == "detail":
            return (
                "终审详细事件和伏笔单独分析。请只返回一个 JSON 对象，字段为 events、promises、"
                "character_states、timeline；每个数组最多8条，每条只保留必要的短句。"
                "不要评分，不要重写正文，不要返回其它字段。\n\n" + prompt
            )
        return (
            "终审结果精简恢复。请只返回一个 JSON 对象，必须包含 dimensions（commercial、story、"
            "prose，0-100）、hard_fail、decision（pass、revise 或 rewrite）和 issues（最多4条，"
            "每条只含 category、severity、evidence、action），可以省略其它字段。不要解释。\n\n"
            + prompt
        )

    @staticmethod
    def _bound_final_review_window_item(item: dict) -> dict:
        """Keep evidence small enough for the cross-window adjudication request."""
        result = dict(item)
        summary = str(result.get("summary") or "").strip()
        result["summary"] = summary[:240]
        for key in ("events", "character_states", "timeline", "promises"):
            result[key] = []
        issues = result.get("issues")
        bounded_issues = []
        for issue in issues[:4] if isinstance(issues, list) else []:
            if not isinstance(issue, dict):
                continue
            bounded_issues.append({
                **issue,
                "evidence": str(issue.get("evidence") or "")[:160],
                "location": str(issue.get("location") or "")[:120],
                "action": str(issue.get("action") or "")[:160],
            })
        result["issues"] = bounded_issues
        return result

    @staticmethod
    def _final_review_detail_plan(
        project: Project, analysis: dict | None, initial_review: dict,
        windows: list[dict],
    ) -> tuple[set[int], str]:
        all_windows = {int(window["index"]) for window in windows}
        if project.metadata.get("final_review_detail_analysis"):
            return all_windows, "已按作品设置单独复核详细事件、人物状态、时间线和伏笔"

        issue_text = json.dumps(
            initial_review.get("issues", []), ensure_ascii=False,
        ).lower()
        issue_markers = (
            "logic_continuity", "timeline", "character_state", "knowledge_state",
            "causal", "promise", "payoff", "setup", "foreshadow",
            "前后矛盾", "连续性", "时间线", "人物状态", "知情", "因果",
            "伏笔", "承诺", "兑现",
        )
        if any(marker in issue_text for marker in issue_markers):
            return all_windows, "已有终审问题涉及跨段关系，已单独复核详细事件和伏笔"

        selected: set[int] = set()
        ledger = (analysis or {}).get("narrative_ledger", {})
        for item in ledger.get("important_uncertainties", []):
            position = item.get("start") if isinstance(item, dict) else None
            if not isinstance(position, int):
                continue
            for window in windows:
                if int(window["start"]) <= position < int(window["end"]):
                    selected.add(int(window["index"]))
        if selected:
            return selected, "本地检查发现需要确认的伏笔或承诺"
        return set(), "未发现需要单独复核的跨段伏笔、人物状态或时间线问题"

    @staticmethod
    def _final_review_error_detail(
        primary: Exception, fallback: Exception | None, compact: Exception,
        suffix: str, kind: str,
    ) -> dict:
        def error_info(error: Exception | None) -> dict | None:
            if error is None:
                return None
            info = {"type": type(error).__name__, "message": str(error)[:500]}
            if isinstance(error, json.JSONDecodeError):
                info.update({"line": error.lineno, "column": error.colno})
            return info
        return {
            "kind": "malformed_json", "stage": "final_review", "suffix": suffix,
            "recovery_kind": kind, "primary": error_info(primary),
            "fallback": error_info(fallback), "compact": error_info(compact),
        }

    def _final_review_adjudication_token_limit(self) -> int:
        context_window = self._provider_context_window("final_review", False)
        effective_window = context_window or 32_768
        return max(4_000, int(effective_window * 0.45))

    @staticmethod
    def _coalesce_hierarchical_issue_evidence(items: list[dict]) -> list[dict]:
        """Keep one stable issue identity while retaining every window occurrence."""
        result = [{**item, "issues": []} for item in items]
        merged_by_id: dict[str, dict] = {}
        first_item_by_id: dict[str, int] = {}
        for item_index, item in enumerate(items):
            item_windows = (
                item.get("covered_windows")
                if isinstance(item.get("covered_windows"), list)
                else [item.get("window")]
            )
            item_windows = [
                int(window) for window in item_windows if isinstance(window, int)
            ]
            for issue in item.get("issues", []):
                if not isinstance(issue, dict) or not issue.get("issue_id"):
                    continue
                issue_id = str(issue["issue_id"])
                merged = merged_by_id.setdefault(issue_id, {
                    **issue,
                    "evidence_records": [],
                })
                first_item_by_id.setdefault(issue_id, item_index)
                records = issue.get("evidence_records")
                if not isinstance(records, list) or not records:
                    records = [{
                        "evidence": issue.get("evidence"),
                        "location": issue.get("location"),
                        "action": issue.get("action"),
                        "severity": issue.get("severity"),
                        "covered_windows": item_windows,
                    }]
                for record in records:
                    if not isinstance(record, dict):
                        continue
                    normalized = {
                        "evidence": str(record.get("evidence") or ""),
                        "location": str(record.get("location") or ""),
                        "action": str(record.get("action") or issue.get("action") or ""),
                        "severity": str(
                            record.get("severity") or issue.get("severity") or ""
                        ),
                        "covered_windows": sorted({
                            int(window)
                            for window in (
                                record.get("covered_windows")
                                if isinstance(record.get("covered_windows"), list)
                                else item_windows
                            )
                            if isinstance(window, int)
                        }),
                    }
                    if normalized not in merged["evidence_records"]:
                        merged["evidence_records"].append(normalized)
        for issue_id, issue in merged_by_id.items():
            item_index = first_item_by_id[issue_id]
            result[item_index]["issues"].append(issue)
            evidence_windows = {
                window
                for record in issue["evidence_records"]
                for window in record["covered_windows"]
            }
            if evidence_windows and isinstance(result[item_index].get("covered_windows"), list):
                result[item_index]["covered_windows"] = sorted({
                    *result[item_index]["covered_windows"], *evidence_windows,
                })
        return result

    async def _hierarchical_final_review_evidence(
        self,
        run_id: str,
        run_path: Path,
        project: Project,
        constraints: str,
        evidence: list[dict],
        suffix: str,
    ) -> tuple[list[dict], dict]:
        token_limit = self._final_review_adjudication_token_limit()
        original_windows = sorted(int(item["window"]) for item in evidence)
        current = [
            {
                **item,
                "issues": issue_ledger(
                    item.get("issues", []) if isinstance(item.get("issues"), list) else [],
                    source=f"final-review-window-{item.get('window', 'unknown')}",
                ),
            }
            for item in evidence
        ]
        levels = []
        for level in range(1, 6):
            current_tokens = estimate_input_tokens(json.dumps(current, ensure_ascii=False))
            if current_tokens <= token_limit:
                current = self._coalesce_hierarchical_issue_evidence(current)
                current_tokens = estimate_input_tokens(json.dumps(current, ensure_ascii=False))
                return current, {
                    "performed": bool(levels),
                    "token_limit": token_limit,
                    "original_evidence_tokens": estimate_input_tokens(
                        json.dumps(evidence, ensure_ascii=False)
                    ),
                    "final_evidence_tokens": current_tokens,
                    "covered_windows": original_windows,
                    "levels": levels,
                }
            batches = review_evidence_batches(
                current, token_limit=max(512, int(token_limit * 0.75)), overlap=1,
            )
            reduced = []
            for batch_index, batch in enumerate(batches, 1):
                covered_windows = sorted({
                    int(window)
                    for item in batch
                    for window in (
                        item.get("covered_windows")
                        if isinstance(item.get("covered_windows"), list)
                        else [item.get("window")]
                    )
                    if isinstance(window, int)
                })
                source_json = json.dumps(
                    batch, ensure_ascii=False, separators=(",", ":"),
                )
                source_sha256 = hashlib.sha256(source_json.encode("utf-8")).hexdigest()
                source_issues_by_id: dict[str, dict] = {}
                for batch_item in batch:
                    issue_windows = (
                        batch_item.get("covered_windows")
                        if isinstance(batch_item.get("covered_windows"), list)
                        else [batch_item.get("window")]
                    )
                    issue_windows = [
                        int(window) for window in issue_windows
                        if isinstance(window, int)
                    ]
                    for issue in batch_item.get("issues", []):
                        if not isinstance(issue, dict) or not issue.get("issue_id"):
                            continue
                        issue_id = str(issue["issue_id"])
                        merged_issue = source_issues_by_id.setdefault(issue_id, {
                            **issue,
                            "evidence_records": [],
                        })
                        records = issue.get("evidence_records")
                        if not isinstance(records, list) or not records:
                            records = [{
                                "evidence": str(issue.get("evidence") or ""),
                                "location": str(issue.get("location") or ""),
                                "action": str(issue.get("action") or ""),
                                "severity": str(issue.get("severity") or ""),
                                "covered_windows": issue_windows,
                            }]
                        for record in records:
                            if not isinstance(record, dict):
                                continue
                            normalized_record = {
                                "evidence": str(record.get("evidence") or ""),
                                "location": str(record.get("location") or ""),
                                "action": str(record.get("action") or issue.get("action") or ""),
                                "severity": str(
                                    record.get("severity") or issue.get("severity") or ""
                                ),
                                "covered_windows": sorted({
                                    int(window)
                                    for window in (
                                        record.get("covered_windows")
                                        if isinstance(record.get("covered_windows"), list)
                                        else issue_windows
                                    )
                                    if isinstance(window, int)
                                }),
                            }
                            if normalized_record not in merged_issue["evidence_records"]:
                                merged_issue["evidence_records"].append(normalized_record)
                source_issues = list(source_issues_by_id.values())
                source_issue_ids = [str(issue["issue_id"]) for issue in source_issues]
                regional_prompt = (
                    "REGIONAL EVIDENCE REDUCTION. Do not score and do not rewrite. Preserve every "
                    "covered window and reconcile cross-window timeline, character/knowledge state, "
                    "relationships, causality, setup/payoff, and ending obligations. Return one JSON "
                    "object with summary (under 400 Chinese characters), issues (at most 4 new "
                    "cross-window issues), covered_windows, source_sha256, and source_issue_ids. "
                    "Echo the exact manifest values to prove this complete source batch was used; "
                    "the runtime carries every source issue losslessly. Do not resolve conflicts "
                    "between evidence_records; report them for global adjudication.\n\n"
                    f"LEVEL {level} BATCH {batch_index}/{len(batches)}\n"
                    f"COVERED WINDOWS: {json.dumps(covered_windows)}\n"
                    f"SOURCE SHA256: {source_sha256}\n"
                    f"SOURCE ISSUE IDS: {json.dumps(source_issue_ids)}\n"
                    f"ORDERED EVIDENCE:\n{source_json}"
                )
                raw, item = await self._final_review_json(
                    run_id, run_path, project, constraints, regional_prompt,
                    suffix=f"{suffix}-hierarchy-{level}-{batch_index}",
                    recovery_kind="window",
                )
                summary = item.get("summary")
                if not isinstance(summary, str) or not summary.strip():
                    raise ValueError("Hierarchical final review evidence has no summary")
                if item.get("covered_windows") != covered_windows:
                    raise ValueError("Hierarchical final review returned stale window coverage")
                if item.get("source_sha256") != source_sha256:
                    raise ValueError("Hierarchical final review returned a stale source hash")
                if item.get("source_issue_ids") != source_issue_ids:
                    raise ValueError("Hierarchical final review omitted source issue identities")
                new_issues = issue_ledger(
                    self._bound_final_review_window_item(item).get("issues", []),
                    source=f"final-review-hierarchy-{level}-{batch_index}",
                )
                carried_issue_ids = set(source_issue_ids)
                reduced.append({
                    "level": level,
                    "batch": batch_index,
                    "covered_windows": covered_windows,
                    "summary": summary.strip()[:400],
                    "issues": [
                        *source_issues,
                        *(issue for issue in new_issues
                          if str(issue["issue_id"]) not in carried_issue_ids),
                    ],
                    "source_issue_ids": source_issue_ids,
                    "source_sha256": source_sha256,
                    "receipt": getattr(raw, "receipt", {}),
                })
            reduced = self._coalesce_hierarchical_issue_evidence(reduced)
            covered = sorted({
                window for item in reduced for window in item["covered_windows"]
            })
            if covered != original_windows:
                raise ValueError("Hierarchical final review omitted manuscript windows")
            reduced_tokens = estimate_input_tokens(json.dumps(reduced, ensure_ascii=False))
            levels.append({
                "level": level,
                "input_items": len(current),
                "batches": len(batches),
                "input_tokens": current_tokens,
                "output_tokens": reduced_tokens,
                "covered_windows": covered,
            })
            if reduced_tokens >= current_tokens and len(reduced) >= len(current):
                raise ValueError("Hierarchical final review could not reduce complete evidence")
            current = reduced
        raise ValueError("Hierarchical final review exceeded the safe reduction depth")

    async def _full_manuscript_review(
        self, run_id: str, run_path: Path, project: Project, constraints: str,
        manuscript: str, initial_review: dict, suffix: str = "",
        analysis: dict | None = None,
    ) -> tuple[dict, dict]:
        constraints = self._constraints_with_platform_rules(project, constraints)
        causal_checks = self._causal_chain_review_checks(constraints)
        windows = review_windows(manuscript)
        manuscript_sha256 = hashlib.sha256(manuscript.encode("utf-8")).hexdigest()
        ledger = issue_ledger(initial_review.get("issues", []))
        evidence = []
        recovery_modes = []
        previous_summary = ""
        detail_windows, detail_message = self._final_review_detail_plan(
            project, analysis, initial_review, windows,
        )
        for window in windows:
            prompt = (
                "FULL MANUSCRIPT WINDOW SUMMARY. Do not score or rewrite. Return one JSON object with "
                "summary and issues only. Keep summary under 240 Chinese characters. Return at most 4 "
                "issues; each issue must include "
                "category, severity, evidence, location, and action, with each text under 160 characters. "
                "Only record changes and evidence; do not retell the window.\n\n"
                f"WINDOW {window['index']}/{len(windows)} "
                f"CHARACTERS {window['start']}-{window['end']}\n"
                f"PREVIOUS WINDOW SUMMARY:\n{previous_summary or 'None'}\n\n"
                f"INITIAL ISSUE LEDGER:\n{json.dumps(ledger, ensure_ascii=False)}\n\n"
                f"{causal_checks}"
                f"MANUSCRIPT WINDOW:\n{window['text']}"
            )
            raw, item = await self._final_review_json(
                run_id, run_path, project, constraints, prompt,
                suffix=f"{suffix}-window-{window['index']}", recovery_kind="window",
            )
            summary = item.get("summary")
            if isinstance(summary, (dict, list)) and summary:
                summary = json.dumps(summary, ensure_ascii=False, separators=(",", ":"))
            if not isinstance(summary, str) or not summary.strip():
                raise ValueError(f"Final review window {window['index']} has no summary")
            item["summary"] = summary.strip()
            item["window"] = window["index"]
            item["start"] = window["start"]
            item["end"] = window["end"]
            item["manuscript_sha256"] = manuscript_sha256
            item["window_sha256"] = hashlib.sha256(
                window["text"].encode("utf-8")
            ).hexdigest()
            item["receipt"] = getattr(raw, "receipt", {})
            item = self._bound_final_review_window_item(item)
            item["issues"] = issue_ledger(
                item.get("issues", []), source=f"final-review-window-{window['index']}",
            )
            if item.get("_recovery_mode"):
                item["recovery_mode"] = item.pop("_recovery_mode")
            if item.get("recovery_mode"):
                recovery_modes.append(str(item["recovery_mode"]))
            if window["index"] in detail_windows:
                detail_prompt = self._final_review_compact_prompt(
                    f"WINDOW {window['index']}/{len(windows)}\n{window['text']}", "detail",
                )
                detail_raw, detail = await self._final_review_json(
                    run_id, run_path, project, constraints, detail_prompt,
                    suffix=f"{suffix}-window-{window['index']}-detail", recovery_kind="detail",
                )
                for key in ("events", "promises", "character_states", "timeline"):
                    if isinstance(detail.get(key), list):
                        item[key] = detail[key][:8]
                item["detail_receipt"] = getattr(detail_raw, "receipt", {})
            evidence.append(item)
            previous_summary = item["summary"]

        adjudication_evidence, adjudication_hierarchy = (
            await self._hierarchical_final_review_evidence(
                run_id, run_path, project, constraints, evidence, suffix,
            )
        )
        adjudication_prompt = (
            quality_profile_prompt(profile_for_project(project))
            +
            "FULL MANUSCRIPT FINAL ADJUDICATION. Use the ordered window evidence as a global story "
            "map and perform cross-window checks for timeline, character state and knowledge, causal "
            "authority/evidence, relationship transitions, setup/payoff, and premise follow-through. "
            "Return strict quality-review JSON plus reconciliations. Each initial issue must appear once "
            "with issue_id, status (resolved, partially_resolved, unresolved, uncertain, or preserved), severity, "
            "and concrete evidence. Omission never means resolved. Do not rewrite the manuscript.\n\n"
            "When one stable issue has multiple evidence_records, consider every occurrence. "
            "Contradictory occurrences must remain uncertain or unresolved rather than selecting one.\n\n"
            f"INITIAL ISSUE LEDGER:\n{json.dumps(ledger, ensure_ascii=False)}\n\n"
            f"{causal_checks}"
            f"ORDERED WINDOW EVIDENCE:\n{json.dumps(adjudication_evidence, ensure_ascii=False)}"
        )
        raw_final, payload = await self._final_review_json(
            run_id, run_path, project, constraints, adjudication_prompt,
            suffix=f"{suffix}-adjudication",
        )
        if payload.get("_recovery_mode"):
            recovery_modes.append(str(payload["_recovery_mode"]))
        review = self._review_for_project(
            payload, project, getattr(raw_final, "receipt", {}),
        )
        prior_issue_ids = [item["issue_id"] for item in ledger]
        prior_issue_id_set = set(prior_issue_ids)
        raw_reconciliations = payload.get("reconciliations", [])
        valid_reconciliations = (
            isinstance(raw_reconciliations, list)
            and all(isinstance(item, dict) for item in raw_reconciliations)
        )
        reconciliation_summary = (
            raw_reconciliations if isinstance(raw_reconciliations, dict) else None
        )
        if valid_reconciliations:
            reconciliations = raw_reconciliations
        else:
            reconciliations = [
                item for item in payload.get("issues", [])
                if isinstance(item, dict) and item.get("issue_id") in prior_issue_id_set
            ]
            self.db.add_run_event(
                run_id, "warning", "final_review_reconciliation_recovered",
                "终审返回的逐项复核格式不标准，已从问题清单恢复可核对结果",
                stage="final_review", metadata={
                    "returned_type": type(raw_reconciliations).__name__,
                    "recovered_count": len(reconciliations),
                    "expected_count": len(prior_issue_ids),
                },
            )
        audit = {
            "coverage": 1.0 if windows and evidence[-1]["end"] == len(manuscript) else 0.0,
            "window_count": len(windows),
            "reviewed_windows": len(evidence),
            "evidence_count": sum(bool(item.get("summary")) for item in evidence),
            "prior_issue_ids": prior_issue_ids,
            "prior_issues": ledger,
            "reconciliations": reconciliations,
            "windows": evidence,
            "adjudication_receipt": getattr(raw_final, "receipt", {}),
            "review_mode": "full",
            "detail_mode": "separate" if detail_windows else "compact",
            "detail_analysis": {
                "performed": bool(detail_windows),
                "window_count": len(detail_windows),
                "message": (
                    f"{detail_message}，已单独复核 {len(detail_windows)} 个正文窗口"
                    if detail_windows else detail_message
                ),
            },
            "adjudication_hierarchy": adjudication_hierarchy,
        }
        if recovery_modes:
            audit["final_review_recovery"] = {
                "attempted": True,
                "succeeded": True,
                "mode": "compact_recovery",
                "count": len(recovery_modes),
                "message": "终审原始报告不完整，系统已用精简格式恢复报告",
            }
        if reconciliation_summary is not None:
            audit["reconciliation_summary"] = reconciliation_summary
        review, gate_reasons = apply_evidence_gate(review, audit)
        review = reconcile_review_issues(
            review,
            ledger,
            reconciliations,
            reviewed_at=datetime.now(timezone.utc).isoformat(),
        )
        audit["gate_reasons"] = gate_reasons
        audit["reconciliation_counts"] = {
            status: sum(item.get("status") == status for item in audit["reconciliations"])
            for status in (
                "resolved", "partially_resolved", "unresolved", "uncertain", "preserved",
            )
        }
        atomic_write(
            run_path / "outputs" / f"final-review-evidence{suffix}.json",
            json.dumps({"windows": evidence, "audit": audit}, ensure_ascii=False, indent=2),
        )
        return review, audit

    @staticmethod
    def _causal_chain_review_checks(constraints: str) -> str:
        if "Short Story Causal Chain" not in constraints:
            return ""
        return (
            "CAUSAL CHAIN CHECKS:\n"
            "- Verify the manuscript establishes the core goal.\n"
            "- Verify opening pressure, anomalous action, reader question, and future promise create honest pull.\n"
            "- Verify obstacle-effort-result cycles create state changes instead of repetition.\n"
            "- Verify each result escalates cost, risk, knowledge, relationship, or available choice and opens the next question.\n"
            "- Verify accidents change the situation.\n"
            "- Verify reversal reinterprets earlier evidence rather than appearing from nowhere.\n"
            "- Verify question continuity and relationship progression are caused by on-page events.\n"
            "- Verify the ending answers surface goal, inner goal, and ending cost.\n\n"
        )

    async def _reader_review(self, run_id: str, run_path: Path, project: Project,
                             constraints: str, text: str, suffix: str = "",
                             model_role: str | None = None) -> dict:
        requirements = project.metadata.get("story_requirements") or {}
        profile = {
            "platform": requirements.get("platform") or project.metadata.get("platform") or "unspecified",
            "genre": project.metadata.get("genre") or "unspecified",
            "audience": requirements.get("audience") or project.metadata.get("audience")
            or "target genre readers",
            "mode": project.mode,
        }
        prompt = (
            "TARGET READER SIMULATION. Do not rewrite the story. Read only the labeled excerpts and "
            "judge whether this target reader would continue, pay, and feel the promised payoff. "
            "Identify abandonment points, weak hooks, fake suspense, unearned emotion,套路化表达, and "
            "AI-like prose. Return the same strict quality-review JSON schema plus reader_signals with "
            "would_continue (boolean), would_pay (boolean), abandonment_point (text), and payoff_felt "
            "(boolean). Use double quotes for every JSON key and string. Return one JSON object only, "
            "without Markdown fences or commentary.\n\n"
            f"READER PROFILE:\n{json.dumps(profile, ensure_ascii=False)}\n\n"
            f"LABELED EXCERPTS:\n{reader_sample(text, project.mode, limit=6000)}"
        )
        output = await self._stage(
            run_id, run_path, project, "review", constraints, prompt,
            suffix=f"-reader{suffix}", model_role=model_role or "review", allow_tools=False,
        )
        try:
            payload = self._convert_generated_object(
                output, run_path, contract_name="final_review",
            )
            return normalize_review(payload)
        except (json.JSONDecodeError, ArtifactConversionError):
            repaired = normalize_review(self._reader_json_object(output))
            self.db.add_run_event(
                run_id, "warning", "reader_review_repaired",
                "Reader review returned malformed JSON and was repaired locally",
                stage="review", metadata={"strategy": "conservative_json_repair"},
            )
            return repaired

    async def _incremental_manuscript_review(
        self, run_id: str, run_path: Path, project: Project, constraints: str,
        manuscript: str, analysis: dict, baseline: dict, initial_review: dict,
        suffix: str = "", revision_source_hash: str | None = None,
        patch_groups: Sequence[dict] = (),
    ) -> tuple[dict, dict]:
        constraints = self._constraints_with_platform_rules(project, constraints)
        baseline_reasons = incremental_precheck_reasons(
            baseline, analysis, manuscript, revision_source_hash,
        )
        if baseline_reasons:
            review, audit = await self._full_manuscript_review(
                run_id, run_path, project, constraints, manuscript, initial_review, suffix,
                analysis=analysis,
            )
            audit.update({
                "review_mode": "full_fallback",
                "fallback_reasons": baseline_reasons,
            })
            return review, audit
        changes = diff_manuscripts(
            baseline["manuscript"], manuscript, baseline["analysis"], analysis,
            mode="long" if project.mode == "long" else "short",
            patch_groups=patch_groups,
        )
        scope = select_review_scope(baseline, analysis, changes)
        scope_reasons = incremental_precheck_reasons(
            baseline, analysis, manuscript, revision_source_hash,
            scope=scope, changes_present=bool(changes.get("ranges")),
        )
        if scope_reasons:
            review, audit = await self._full_manuscript_review(
                run_id, run_path, project, constraints, manuscript, initial_review, suffix,
                analysis=analysis,
            )
            audit.update({
                "review_mode": "full_fallback",
                "fallback_reasons": scope_reasons,
                "incremental_scope": scope,
            })
            return review, audit
        full, fallback_reasons = requires_full_review(
            scope, changes, analysis, patch_groups=patch_groups,
            source_manuscript=baseline["manuscript"], current_manuscript=manuscript,
        )
        if full:
            review, audit = await self._full_manuscript_review(
                run_id, run_path, project, constraints, manuscript, initial_review, suffix,
                analysis=analysis,
            )
            audit.update({
                "review_mode": "full_fallback",
                "fallback_reasons": fallback_reasons,
                "incremental_scope": scope,
            })
            return review, audit

        selected = set(scope["selected_windows"])
        evidence = []
        ledger = baseline.get("issue_ledger", [])
        baseline_by_index = {
            item.get("window", item.get("index")): item
            for item in baseline.get("evidence", [])
        }
        for window in analysis.get("windows", []):
            if window["index"] not in selected:
                continue
            prompt = (
                "INCREMENTAL FINAL REVIEW EVIDENCE. Do not rewrite. Review the current window "
                "against its first-full-review baseline and the structured local change evidence. "
                "Return JSON with summary and issues only.\n\n"
                f"SELECTION REASONS:\n{json.dumps(scope['reasons'].get(str(window['index']), []), ensure_ascii=False)}\n\n"
                f"BASELINE EVIDENCE:\n{json.dumps(baseline_by_index.get(window['index'], {}), ensure_ascii=False)}\n\n"
                f"CHANGES:\n{json.dumps(changes, ensure_ascii=False)}\n\n"
                f"CURRENT WINDOW:\n{window['text']}"
            )
            raw, item = await self._final_review_json(
                run_id, run_path, project, constraints, prompt,
                suffix=f"{suffix}-incremental-window-{window['index']}",
                recovery_kind="window",
            )
            summary = item.get("summary")
            if not isinstance(summary, str) or not summary.strip():
                raise ValueError(f"Incremental review window {window['index']} has no summary")
            item.update({
                "window": window["index"], "start": window["start"], "end": window["end"],
                "receipt": getattr(raw, "receipt", {}),
            })
            evidence.append(item)

        prompt = (
            quality_profile_prompt(profile_for_project(project))
            +
            "INCREMENTAL FINAL ADJUDICATION. Reconcile every prior issue and judge only whether "
            "the correction remains globally safe. Return strict quality-review JSON plus "
            "reconciliations. Every reconciliation status must be exactly resolved, "
            "partially_resolved, unresolved, uncertain, or preserved. "
            "Set request_full_review=true if evidence is insufficient.\n\n"
            f"BASELINE REVIEW:\n{json.dumps(baseline.get('review', {}), ensure_ascii=False)}\n\n"
            f"ISSUE LEDGER:\n{json.dumps(ledger, ensure_ascii=False)}\n\n"
            f"CHANGES:\n{json.dumps(changes, ensure_ascii=False)}\n\n"
            f"SELECTED EVIDENCE:\n{json.dumps(evidence, ensure_ascii=False)}"
        )
        raw, payload = await self._final_review_json(
            run_id, run_path, project, constraints, prompt,
            suffix=f"{suffix}-incremental-adjudication",
        )
        if payload.get("request_full_review"):
            changes["reviewer_requested_full"] = True
            review, audit = await self._full_manuscript_review(
                run_id, run_path, project, constraints, manuscript, initial_review, suffix,
                analysis=analysis,
            )
            audit.update({"review_mode": "full_fallback",
                          "fallback_reasons": ["reviewer_requested_full"]})
            return review, audit
        review = self._review_for_project(
            payload, project, getattr(raw, "receipt", {}),
        )
        review, gate_reasons = apply_incremental_gate(
            review, baseline, scope, analysis, manuscript,
            payload.get("reconciliations", []),
        )
        if gate_reasons:
            full_review, audit = await self._full_manuscript_review(
                run_id, run_path, project, constraints, manuscript, initial_review, suffix,
                analysis=analysis,
            )
            audit.update({"review_mode": "full_fallback", "fallback_reasons": gate_reasons})
            return full_review, audit
        review = reconcile_review_issues(
            review,
            ledger,
            payload.get("reconciliations", []),
            reviewed_at=datetime.now(timezone.utc).isoformat(),
        )
        full_input = sum(len(item.get("text", "")) for item in analysis.get("windows", []))
        reviewed_input = sum(len(item.get("text", "")) for item in analysis.get("windows", [])
                             if item["index"] in selected)
        audit = {
            "coverage": 1.0,
            "review_mode": "incremental",
            "window_count": len(analysis.get("windows", [])),
            "reviewed_windows": len(evidence),
            "selected_windows": sorted(selected),
            "selection_reasons": scope["reasons"],
            "windows": evidence,
            "reconciliations": payload.get("reconciliations", []),
            "estimated_full_input_characters": full_input,
            "reviewed_input_characters": reviewed_input,
            "estimated_saved_input_characters": max(0, full_input - reviewed_input),
            "adjudication_receipt": getattr(raw, "receipt", {}),
        }
        atomic_write(
            run_path / "outputs" / f"incremental-review{suffix}.json",
            json.dumps({"changes": changes, "scope": scope, "audit": audit},
                       ensure_ascii=False, indent=2),
        )
        return review, audit

    @staticmethod
    def _planning_uses_tools(state) -> bool:
        return state.revision > 1

    @staticmethod
    def _short_segment_count(target_words: int) -> int:
        if target_words <= 8000:
            return 1
        return min(12, max(2, math.ceil(target_words / 2500)))

    @classmethod
    def _short_plan_segments(cls, plan: str, count: int) -> list[str]:
        if count == 1:
            return [plan.strip()] if plan.strip() else []
        headings = cls._short_plan_headings(plan)
        by_number: dict[int, str] = {}
        for position, (match, number) in enumerate(headings):
            if number is None or not 1 <= number <= count:
                continue
            level = len(match.group("marks"))
            end = len(plan)
            for following, following_number in headings[position + 1:]:
                if (following_number is not None
                        or len(following.group("marks")) <= level):
                    end = following.start()
                    break
            by_number.setdefault(number, plan[match.start():end].strip())
        return [by_number[number] for number in range(1, count + 1) if number in by_number]

    @staticmethod
    def _mask_nonsemantic_markdown(text: str) -> str:
        """Mask comments and fenced examples while preserving source offsets."""
        characters = list(str(text or ""))

        def mask(start: int, end: int) -> None:
            for index in range(start, end):
                if characters[index] not in "\r\n":
                    characters[index] = " "

        for comment in re.finditer(r"<!--.*?(?:-->|\Z)", text, flags=re.DOTALL):
            mask(comment.start(), comment.end())

        visible = "".join(characters)
        fence_character = ""
        fence_length = 0
        offset = 0
        for line in visible.splitlines(keepends=True):
            fence = re.match(r"^[ ]{0,3}(?P<mark>`{3,}|~{3,})", line)
            if fence_character:
                mask(offset, offset + len(line))
                if (fence and fence.group("mark")[0] == fence_character
                        and len(fence.group("mark")) >= fence_length):
                    fence_character = ""
                    fence_length = 0
            elif fence:
                fence_character = fence.group("mark")[0]
                fence_length = len(fence.group("mark"))
                mask(offset, offset + len(line))
            offset += len(line)
        return "".join(characters)

    @classmethod
    def _short_plan_headings(cls, plan: str) -> list[tuple[re.Match, int | None]]:
        comparison = cls._short_plan_comparison_view(plan)
        identities = cls._short_plan_heading_identities(plan)
        identity_by_start = {
            match.start(): numbers for match, numbers in identities
        }
        hash_identities = [
            (match, numbers) for match, numbers in identities
            if str(match.group("marks")).startswith("#")
        ]
        hash_matches = list(re.finditer(
            r"(?m)^[ ]{0,3}(?P<marks>#{1,6})[ \t]*(?P<title>\S.*)$",
            comparison,
        ))
        headings: list[tuple[re.Match, int | None]] = []
        if hash_identities:
            root_level = min(
                len(match.group("marks"))
                for match, _numbers in hash_identities
            )
            for match in hash_matches:
                level = len(match.group("marks"))
                if level > root_level:
                    continue
                numbers = identity_by_start.get(match.start(), [])
                number = (
                    numbers[0]
                    if level == root_level and len(numbers) == 1 else None
                )
                headings.append((match, number))
        else:
            # Standalone bold/HTML segment headings have no Markdown level.
            # Keep ATX headings as legacy boundaries so a trailing appendix
            # cannot leak into the last formal segment.
            headings.extend((match, None) for match in hash_matches)

        headings.extend(
            (match, numbers[0] if len(numbers) == 1 else None)
            for match, numbers in identities
            if not str(match.group("marks")).startswith("#")
        )
        deduplicated = {
            match.start(): (match, number) for match, number in headings
        }
        return sorted(deduplicated.values(), key=lambda item: item[0].start())

    @classmethod
    def _short_plan_heading_identities(
        cls, plan: str,
    ) -> list[tuple[re.Match, list[int]]]:
        """Return root heading identities while preserving Markdown hierarchy."""
        comparison = cls._short_plan_comparison_view(plan)
        token = r"\d{1,2}|十二|十一|十|九|八|七|六|五|四|三|二|两|一"
        identity = re.compile(
            rf"(?:"
            rf"(?:第\s*)?(?:{token})\s*(?:个\s*)?"
            rf"(?:(?:写作|规划)?(?:分)?段(?:落)?)"
            rf"|(?:(?:写作|规划)?(?:分)?段(?:落)?)\s*(?:{token})"
            rf"|(?:planning\s+)?segment\s*[-_]?\s*\d{{1,2}}"
            rf")",
            re.IGNORECASE,
        )
        reversed_prefix = (
            r"(?:段规划|规划段|分段规划|写作段规划|"
            r"plan(?:ning)?\s+segment|segment\s+plan)\s*[:：/]?\s*"
        )

        def numbers(title: str) -> list[int]:
            matches = list(identity.finditer(title))
            if not matches:
                return []
            first = matches[0]
            prefix = re.sub(
                r"^[*_`\s]+|[*_`\s]+$", "", title[:first.start()],
            )
            root = not prefix or bool(re.fullmatch(
                reversed_prefix,
                prefix,
                flags=re.IGNORECASE,
            ))
            if not root:
                return []
            result: list[int] = []
            for match in matches:
                identity_text = match.group(0)
                number = parse_segment_number(
                    identity_text, allow_scene=False,
                )
                if number is None:
                    english_identity = re.search(
                        r"(?i)\bsegment\s*[-_]?\s*(?P<number>\d{1,2})\b",
                        identity_text,
                    )
                    if english_identity:
                        number = int(english_identity.group("number"))
                if number is not None and number not in result:
                    result.append(number)
            return result

        hash_matches = list(re.finditer(
            r"(?m)^[ ]{0,3}(?P<marks>#{1,6})[ \t]*(?P<title>\S.*)$",
            comparison,
        ))
        hash_values = [
            (match, numbers(match.group("title"))) for match in hash_matches
            if numbers(match.group("title"))
        ]
        if hash_values:
            minimum_level = min(len(match.group("marks")) for match, _value in hash_values)
            return [
                item for item in hash_values
                if len(item[0].group("marks")) == minimum_level
            ]
        wrapped_patterns = (
            r"(?m)^[ ]{0,3}(?P<marks>\*\*|__)[ \t]*"
            r"(?P<title>\S.*?)[ \t]*(?P=marks)"
            r"(?P<tail>[ \t]*(?:[:：·•—–-][^\r\n]*)?)[ \t]*$",
            r"(?im)^[ ]{0,3}<(?P<marks>strong|b)>[ \t]*"
            r"(?P<title>\S.*?)[ \t]*</(?P=marks)>"
            r"(?P<tail>[ \t]*(?:[:：·•—–-][^\r\n]*)?)[ \t]*$",
        )
        wrapped_values: list[tuple[re.Match, list[int]]] = []
        for pattern in wrapped_patterns:
            for match in re.finditer(pattern, comparison):
                title = match.group("title") + str(match.group("tail") or "")
                values = numbers(title)
                if values:
                    wrapped_values.append((match, values))
        return sorted(wrapped_values, key=lambda item: item[0].start())

    @classmethod
    def _short_plan_comparison_view(cls, text: str) -> str:
        """Normalize width for labels and IDs while preserving source offsets."""
        return cls._mask_nonsemantic_markdown(
            planning_protocol_comparison_view(text),
        )

    @classmethod
    def _short_plan_field(cls, segment: str, field: str) -> str:
        value = extract_planning_field(segment, field)
        if value or field != "event":
            return value

        # Providers may place an explicit event realization beside a separate
        # causal-chain explanation. Both are useful narrative material, but
        # only the former owns the closed ``event`` role. Resolve that semantic
        # precedence here without copying, deleting, or relabeling source text.
        candidates = []
        for item in compile_planning_segment(segment).values("event"):
            label = unicodedata.normalize("NFKC", item.label).casefold()
            compact = re.sub(r"[^0-9a-z\u3400-\u9fff]+", "", label)
            causal_companion = any(
                marker in compact for marker in ("因果链", "causalchain")
            ) and not any(marker in compact for marker in (
                "事件", "event", "节拍", "beat", "叙事推进", "剧情推进",
            ))
            if not causal_companion:
                candidates.append(item.value.strip())
        distinct = {
            re.sub(r"\s+", " ", candidate).strip(): candidate
            for candidate in candidates if candidate
        }
        return next(iter(distinct.values())) if len(distinct) == 1 else ""

    @classmethod
    def _short_plan_issues(cls, project: Project, state: dict, plan: str,
                           count: int) -> list[str]:
        issues = []
        if SHORT_CAUSAL_CHAIN_START in plan or SHORT_CAUSAL_CHAIN_END in plan:
            issues.append("规划稿附带的因果链 JSON 格式不完整")
        conflicts = detect_canon_conflicts(project, state, plan)
        if conflicts:
            labels = "、".join(
                f"{item['label']}（{item['current_value']} / {item['candidate_value']}）"
                for item in conflicts
            )
            issues.append(f"人物或地点与正式设定不一致：{labels}")
        if count == 1:
            return issues
        segments = cls._short_plan_segments(plan, count)
        heading_numbers = [
            number for _match, number in cls._short_plan_headings(plan)
            if number is not None
        ]
        if heading_numbers and heading_numbers != list(range(1, count + 1)):
            issues.append(f"规划稿分段标题必须恰好按第 1 至第 {count} 段各出现一次")
        if len(segments) != count:
            issues.append(f"规划稿需要明确列出第 1 至第 {count} 段各自负责的事件")
        else:
            if any(len(re.sub(r"\s+", "", segment)) < 80 for segment in segments):
                issues.append("有分段没有写清本段事件、结果和交接问题")
            missing_handoffs = []
            for index, segment in enumerate(segments, 1):
                if any(
                    not cls._short_plan_field(segment, field)
                    for field in cls.SHORT_PLAN_FIELD_ALIASES
                ):
                    missing_handoffs.append(index)
            if missing_handoffs:
                joined = "、".join(map(str, missing_handoffs))
                issues.append(
                    f"第 {joined} 段缺少事件ID、大纲依据、段首承接、本段事件或段末交接，"
                    "无法确认剧情分工与前后衔接"
                )
        formal_outline = state.get("outline") or {}
        outline = str(formal_outline.get("content") or "")
        if outline.strip():
            # Keep this gate on the same executable-event authority used by
            # planning adaptation and the execution manifest. The public
            # ``outline_events`` projection omits hierarchy metadata; feeding
            # it back into ``narrative_outline_events`` can therefore promote
            # a structural heading such as ``## 第 1 段`` into a required
            # story event after its nested events have already been selected.
            required_events = narrative_outline_event_contracts(outline)
            # Structural headings, themes, and writing directives are valid
            # outline references for traceability, but they never become
            # required executable events or participate in story order. Keep
            # the broad registry only for unknown-ID validation and use the
            # hierarchy-aware contracts for coverage and chronology.
            event_map = outline_events(outline)
        else:
            event_map = formal_outline.get("events") or []
            required_events = narrative_outline_events(event_map)
        if event_map and len(segments) == count:
            valid = {str(item["id"]).upper() for item in event_map}
            claimed = [cls._short_plan_event_ids(segment) for segment in segments]
            for segment_number, (segment_text, event_ids) in enumerate(
                zip(segments, claimed, strict=True), 1,
            ):
                for issue in planning_event_body_issues(segment_text, event_ids):
                    issues.append(
                        f"第 {segment_number} 段：{issue['message']}"
                        f"（{issue.get('event_id') or '事件顺序'}）"
                    )
            flattened = [event_id for group in claimed for event_id in group]
            invalid = sorted(set(flattened) - valid)
            if invalid:
                issues.append(f"规划稿使用了不存在的事件 ID：{'、'.join(invalid)}")
        if required_events and len(segments) == count:
            required = {str(item["id"]).upper() for item in required_events}
            claimed = [cls._short_plan_event_ids(segment) for segment in segments]
            flattened = [event_id for group in claimed for event_id in group]
            missing = [
                str(item["id"]) for item in required_events
                if str(item["id"]).upper() not in flattened
            ]
            order = {
                str(item["id"]).upper(): index
                for index, item in enumerate(required_events)
            }
            labels = {
                str(item["id"]).upper(): str(item.get("label") or item["id"])
                for item in required_events
            }
            collapsed: list[tuple[int, str]] = []
            for segment_number, group in enumerate(claimed, 1):
                for event_id in group:
                    if event_id not in required:
                        continue
                    if not collapsed or event_id != collapsed[-1][1]:
                        collapsed.append((segment_number, event_id))
            if missing:
                issues.append(f"这些正式大纲事件还没有分配到写作段：{'、'.join(missing)}")
            reversal = next((
                (previous_segment, previous, current_segment, current)
                for (previous_segment, previous), (current_segment, current)
                in zip(collapsed, collapsed[1:])
                if order[current] < order[previous]
            ), None)
            if reversal:
                previous_segment, previous, current_segment, current = reversal
                issues.append(
                    "写作段认领的大纲事件顺序发生倒退："
                    f"第 {previous_segment} 段 {previous}（{labels[previous]}）之后，"
                    f"第 {current_segment} 段又认领 {current}（{labels[current]}）"
                )
        normalized = [re.sub(r"\W+", "", segment) for segment in segments]
        if any(
            SequenceMatcher(None, normalized[left], normalized[right]).ratio() >= 0.86
            for left in range(len(normalized)) for right in range(left + 1, len(normalized))
        ):
            issues.append("不同分段承担了过于相似的事件，需要重新分配")
        return issues

    @classmethod
    def _short_plan_handoff(cls, segment: str) -> str:
        return (cls._short_plan_field(segment, "handoff") or segment.strip())[-700:]

    @classmethod
    def _short_plan_event_ids(cls, segment: str) -> list[str]:
        field = cls._short_plan_field(segment, "event_id")
        return planning_event_ids(field or segment, formal_only=True)

    @classmethod
    def _short_plan_declared_event_ids(cls, segment: str) -> list[str]:
        """Return only event IDs declared as packet ownership.

        A capacity packet can mention neighbouring event IDs in its prose. The
        general ``_short_plan_event_ids`` helper intentionally remains broad
        for legacy parsing and diagnostics, but merge ownership must be closed
        under composition: body references cannot turn into claimed events.
        Prefer the explicit event-ID field and accept a fallback only when the
        entire packet contains one unambiguous ID. Otherwise return an empty
        declaration so the merge fails closed and requests a canonical retry.
        """
        declared = cls._short_plan_field(segment, "event_id")
        if declared:
            ids = planning_event_ids(declared, formal_only=True)
            if ids:
                return ids

        structural_ids = cls._short_plan_structural_owned_event_ids(segment)
        if structural_ids:
            return structural_ids

        # A complete packet may declare ownership on each event title rather
        # than in one standalone field (for example ``### 第一拍（EV-...）``).
        # Only heading/list lines inside the owned-event field are eligible;
        # prose references in handoffs or narrative paragraphs remain
        # descriptive and cannot claim a neighbouring event.
        event_body = cls._short_plan_field(segment, "event")
        if event_body:
            declared_from_titles: list[str] = []
            for event_id, _start, _end in cls._short_plan_structural_event_spans(
                event_body,
            ):
                if event_id not in declared_from_titles:
                    declared_from_titles.append(event_id)
            if declared_from_titles:
                return declared_from_titles

        all_ids = cls._short_plan_event_ids(segment)
        return all_ids if len(all_ids) == 1 else []

    @classmethod
    def _draft_segment_findings(
        cls, part: str, target: int, previous_parts: list[str],
        location_catalog: dict[str, LocationRef] | None = None,
    ) -> list[dict]:
        findings: list[dict] = []
        han = effective_han_characters(part)
        minimum_han, maximum_han = target_bounds(target)
        if han > maximum_han:
            findings.append({
                "code": "overlength",
                "message": f"本段写了 {han} 个正文汉字，明显超过约 {target} 字的范围",
                "blocking": True,
                "han_characters": han,
                "target_characters": target,
            })
        if han < minimum_han and (han > 0 or not part.strip()):
            findings.append({
                "code": "underlength",
                "message": f"本段只有 {han} 个正文汉字，主要事件可能没有写完整",
                "blocking": True,
                "han_characters": han,
                "target_characters": target,
            })
        blocking = [
            item for item in analyze_prose(part).get("findings", [])
            if item.get("blocking")
        ]
        if blocking:
            findings.append({
                "code": "prose_invalid",
                "message": "正文夹带了写作说明、异常文字或重复内容",
                "blocking": True,
            })
        current_paragraphs = [
            re.sub(r"\s+", "", value)
            for value in re.split(r"\n\s*\n", part)
            if len(re.sub(r"\s+", "", value)) >= 60
        ]
        prior_paragraphs = [
            re.sub(r"\s+", "", value)
            for prior in previous_parts
            for value in re.split(r"\n\s*\n", prior)
            if len(re.sub(r"\s+", "", value)) >= 60
        ]
        if any(
            SequenceMatcher(None, current, prior).ratio() >= 0.92
            for current in current_paragraphs for prior in prior_paragraphs
        ):
            findings.append({
                "code": "duplicate_prose",
                "message": "本段重复了前面已经写过的场景或段落",
                "blocking": True,
            })
        if previous_parts and location_catalog:
            for finding in assess_scene_transition(
                previous_parts[-1], part, location_catalog,
            ):
                message = str(finding.get("message") or "")
                if finding.get("code") == "scene_transition_missing":
                    message = "本段开头换了场景，但没有交代时间、地点或人物如何过渡"
                findings.append({**finding, "message": message})
        return findings

    @classmethod
    def _draft_segment_issues(
        cls, part: str, target: int, previous_parts: list[str],
        location_catalog: dict[str, LocationRef] | None = None,
    ) -> list[str]:
        return [
            str(item["message"])
            for item in cls._draft_segment_findings(
                part, target, previous_parts, location_catalog,
            )
            if item.get("blocking")
        ]

    @classmethod
    def _split_segments(cls, text: str) -> list[str]:
        return [part.strip() for part in text.split(cls.SHORT_SEGMENT_SEPARATOR) if part.strip()]

    @classmethod
    def _split_polish_segments(cls, text: str, target: int = 1400,
                               maximum: int = 1800) -> list[str]:
        chunks: list[str] = []
        for original in cls._split_segments(text):
            first_chunk = len(chunks)
            paragraphs = [item.strip() for item in re.split(r"\n\s*\n", original) if item.strip()]
            units: list[str] = []
            for paragraph in paragraphs:
                units.append(paragraph)
            current: list[str] = []
            size = 0
            for unit in units:
                added = len(unit) + (2 if current else 0)
                if current and size + added > maximum:
                    chunks.append("\n\n".join(current))
                    current, size = [], 0
                current.append(unit)
                size += len(unit) + (2 if len(current) > 1 else 0)
                if size >= target:
                    chunks.append("\n\n".join(current))
                    current, size = [], 0
            if current:
                chunks.append("\n\n".join(current))
            if len(chunks) - first_chunk > 1 and len(chunks[-1]) < 800:
                merged = chunks[-2] + "\n\n" + chunks[-1]
                if len(merged) <= maximum + 400:
                    chunks[-2:] = [merged]
        return chunks

    @classmethod
    def _short_checkpoint_context(
        cls, project: Project, state_revision: int, state: dict,
        constraints: str, segment_count: int,
    ) -> dict:
        outline = str(((state.get("outline") or {}).get("content")) or "")
        context = {
            "version": cls.SHORT_CHECKPOINT_VERSION,
            "project_id": project.id,
            "outline_sha256": hashlib.sha256(outline.encode("utf-8")).hexdigest(),
            "constraints_sha256": hashlib.sha256(
                constraints.encode("utf-8")
            ).hexdigest(),
            "story_state_revision": int(state_revision),
            "story_state_sha256": hashlib.sha256(json.dumps(
                state, ensure_ascii=False, sort_keys=True, default=str,
            ).encode("utf-8")).hexdigest(),
            "target_words": int(project.metadata["target_words"]),
            "segment_count": int(segment_count),
        }
        context["generation_context_sha256"] = hashlib.sha256(json.dumps(
            context, ensure_ascii=False, sort_keys=True, separators=(",", ":"),
        ).encode("utf-8")).hexdigest()
        return context

    @staticmethod
    def _checkpoint_segment_events(
        execution_manifest: ShortExecutionManifest, draft_integrity: dict,
    ) -> dict:
        beat_by_id = {beat.beat_id: beat for beat in execution_manifest.beats}
        semantic_receipts = draft_integrity.get("semantic_segment_receipts")
        semantic_receipts = semantic_receipts if isinstance(semantic_receipts, list) else []
        segments = []
        for offset, contract in enumerate(execution_manifest.segments):
            beat_ids = list(contract.beat_ids)
            assignment = {
                "segment": contract.segment,
                "event_ids": beat_ids,
                "source_event_ids": list(dict.fromkeys(
                    beat_by_id[beat_id].source_event_id for beat_id in beat_ids
                )),
                "handoff": "；".join(item.state for item in contract.exit_state),
            }
            if offset < len(semantic_receipts) and isinstance(
                semantic_receipts[offset], dict,
            ):
                assignment["semantic_receipt"] = semantic_receipts[offset]
            segments.append(assignment)
        return {"segments": segments}

    @classmethod
    def _save_short_checkpoint(cls, outputs: Path, context: dict) -> None:
        plan = (outputs / "planning.md").read_text(encoding="utf-8")
        draft = (outputs / "draft.md").read_text(encoding="utf-8")
        execution_index = json.loads(
            (outputs / "short-execution-index.json").read_text(encoding="utf-8"),
        )
        execution_manifest = parse_execution_manifest(execution_index)
        causal_chain_text = (outputs / "short-causal-chain.json").read_text(
            encoding="utf-8",
        )
        causal_chain = json.loads(causal_chain_text)
        causal_chain_sha256 = hashlib.sha256(json.dumps(
            causal_chain, ensure_ascii=False, sort_keys=True, separators=(",", ":"),
        ).encode("utf-8")).hexdigest()
        adaptation_path = outputs / "planning-adaptations.json"
        planning_adaptation = None
        planning_adaptation_sha256 = ""
        if adaptation_path.is_file():
            planning_adaptation = json.loads(
                adaptation_path.read_text(encoding="utf-8"),
            )
            planning_adaptation_sha256 = planning_adaptation_artifact_sha256(
                planning_adaptation,
            )
        draft_integrity_text = (outputs / "draft-integrity.json").read_text(
            encoding="utf-8",
        )
        draft_integrity = json.loads(draft_integrity_text)
        planning_sha256 = hashlib.sha256(plan.encode("utf-8")).hexdigest()
        draft_sha256 = hashlib.sha256(draft.encode("utf-8")).hexdigest()
        manifest_sha256 = execution_manifest_sha256(execution_manifest)
        execution_authority_payload = {
            "project_id": context.get("project_id"),
            "state_revision": context.get("story_state_revision"),
            "constraints_sha256": context.get("constraints_sha256"),
            "outline_sha256": context.get("outline_sha256"),
            "planning_sha256": planning_sha256,
            "causal_chain_sha256": causal_chain_sha256,
            "segment_count": context.get("segment_count"),
        }
        if planning_adaptation_sha256:
            execution_authority_payload["planning_adaptation_sha256"] = (
                planning_adaptation_sha256
            )
        expected_execution_authority = hashlib.sha256(json.dumps(
            execution_authority_payload,
            ensure_ascii=False, sort_keys=True, separators=(",", ":"),
        ).encode(
            "utf-8",
        )).hexdigest()
        segment_events_text = json.dumps(
            cls._checkpoint_segment_events(execution_manifest, draft_integrity),
            ensure_ascii=False, indent=2,
        )
        checkpoint_issues = [
            code for code, invalid in (
                ("manifest_status", execution_manifest.status != "ready"),
                ("manifest_receipt", bool(
                    execution_manifest_receipt_binding_issues(execution_manifest)
                )),
                ("causal_chain_hash", execution_manifest.causal_chain_sha256 != causal_chain_sha256),
                ("planning_hash", execution_manifest.planning_sha256 != planning_sha256),
                ("outline_hash", execution_manifest.outline_sha256 != context.get("outline_sha256")),
                ("execution_authority", execution_manifest.authority_sha256 != expected_execution_authority),
                ("integrity_status", draft_integrity.get("status") != "passed"),
                ("integrity_manifest", draft_integrity.get("execution_manifest_sha256") != manifest_sha256),
                ("integrity_draft", draft_integrity.get("draft_sha256") != draft_sha256),
                ("integrity_plan", draft_integrity.get("plan_sha256") != planning_sha256),
                ("integrity_constraints", draft_integrity.get("base_constraints_sha256") != context.get("constraints_sha256")),
                ("integrity_story_state", draft_integrity.get("story_state_sha256") != context.get("story_state_sha256")),
                ("planning_adaptation", bool(planning_adaptation) and (
                    planning_adaptation.get("status") != "ready"
                    or planning_adaptation.get("outline_sha256") != context.get("outline_sha256")
                    or planning_adaptation.get("planning_sha256") != planning_sha256
                    or planning_adaptation.get("segment_count") != context.get("segment_count")
                )),
            ) if invalid
        ]
        if checkpoint_issues:
            raise ValueError(
                "完整短篇检查点缺少已通过的执行索引或整篇核验："
                + "、".join(checkpoint_issues)
            )
        atomic_write(outputs / "segment-events.json", segment_events_text)
        receipt_text = json.dumps(
            execution_manifest.semantic_receipt,
            ensure_ascii=False, sort_keys=True, separators=(",", ":"),
        )
        checkpoint_payload = {
            **context,
            "planning_sha256": planning_sha256,
            "draft_sha256": draft_sha256,
            "execution_manifest_sha256": manifest_sha256,
            "execution_manifest_receipt_sha256": hashlib.sha256(
                receipt_text.encode("utf-8"),
            ).hexdigest(),
            "causal_chain_artifact_sha256": hashlib.sha256(
                causal_chain_text.encode("utf-8"),
            ).hexdigest(),
            "segment_events_sha256": hashlib.sha256(
                segment_events_text.encode("utf-8"),
            ).hexdigest(),
            "draft_integrity_sha256": hashlib.sha256(
                draft_integrity_text.encode("utf-8"),
            ).hexdigest(),
        }
        if planning_adaptation_sha256:
            checkpoint_payload["planning_adaptation_sha256"] = planning_adaptation_sha256
        atomic_write(
            outputs / "short-checkpoint.json",
            json.dumps(checkpoint_payload, ensure_ascii=False, indent=2, sort_keys=True),
        )

    def _find_short_checkpoint(self, project: Project, current_run_id: str,
                               segment_count: int, context: dict) -> Path | None:
        for run in self.db.list_runs(project.id):
            if run["workflow"] != "short-story":
                continue
            if (run["id"] != current_run_id
                    and run["status"] not in {"failed", "cancelled"}):
                continue
            outputs = project.path / "runs" / run["id"] / "outputs"
            plan_path = outputs / "planning.md"
            draft_path = outputs / "draft.md"
            manifest_path = outputs / "short-checkpoint.json"
            execution_index_path = outputs / "short-execution-index.json"
            draft_integrity_path = outputs / "draft-integrity.json"
            causal_chain_path = outputs / "short-causal-chain.json"
            segment_events_path = outputs / "segment-events.json"
            if (not plan_path.is_file() or not draft_path.is_file()
                    or not manifest_path.is_file()
                    or not execution_index_path.is_file()
                    or not draft_integrity_path.is_file()
                    or not causal_chain_path.is_file()
                    or not segment_events_path.is_file()):
                continue
            try:
                manifest = json.loads(manifest_path.read_text(encoding="utf-8"))
                plan_text = plan_path.read_text(encoding="utf-8")
                draft = draft_path.read_text(encoding="utf-8")
                execution_index = parse_execution_manifest(json.loads(
                    execution_index_path.read_text(encoding="utf-8"),
                ))
                draft_integrity_text = draft_integrity_path.read_text(encoding="utf-8")
                draft_integrity = json.loads(draft_integrity_text)
                causal_chain_text = causal_chain_path.read_text(encoding="utf-8")
                causal_chain = json.loads(causal_chain_text)
                causal_chain_sha256 = hashlib.sha256(json.dumps(
                    causal_chain, ensure_ascii=False, sort_keys=True,
                    separators=(",", ":"),
                ).encode("utf-8")).hexdigest()
                segment_events_text = segment_events_path.read_text(encoding="utf-8")
                segment_events = json.loads(segment_events_text)
            except (OSError, UnicodeError, json.JSONDecodeError, TypeError, ValueError):
                continue
            adaptation_sha256 = str(manifest.get("planning_adaptation_sha256") or "")
            planning_adaptation = None
            if adaptation_sha256:
                adaptation_path = outputs / "planning-adaptations.json"
                try:
                    planning_adaptation = json.loads(
                        adaptation_path.read_text(encoding="utf-8"),
                    )
                except (OSError, UnicodeError, json.JSONDecodeError, TypeError):
                    continue
                if (
                    planning_adaptation_artifact_sha256(planning_adaptation)
                    != adaptation_sha256
                ):
                    continue
            planning_sha256 = hashlib.sha256(plan_text.encode("utf-8")).hexdigest()
            draft_sha256 = hashlib.sha256(draft.encode("utf-8")).hexdigest()
            execution_manifest_hash = execution_manifest_sha256(execution_index)
            receipt_text = json.dumps(
                execution_index.semantic_receipt,
                ensure_ascii=False, sort_keys=True, separators=(",", ":"),
            )
            execution_authority_payload = {
                "project_id": context.get("project_id"),
                "state_revision": context.get("story_state_revision"),
                "constraints_sha256": context.get("constraints_sha256"),
                "outline_sha256": context.get("outline_sha256"),
                "planning_sha256": planning_sha256,
                "causal_chain_sha256": causal_chain_sha256,
                "segment_count": context.get("segment_count"),
            }
            if adaptation_sha256:
                execution_authority_payload["planning_adaptation_sha256"] = adaptation_sha256
            expected_execution_authority = hashlib.sha256(json.dumps(
                execution_authority_payload,
                ensure_ascii=False, sort_keys=True, separators=(",", ":"),
            ).encode(
                "utf-8",
            )).hexdigest()
            if (
                not isinstance(manifest, dict)
                or any(manifest.get(key) != value for key, value in context.items())
                or manifest.get("planning_sha256")
                != planning_sha256
                or manifest.get("draft_sha256")
                != draft_sha256
                or execution_index.status != "ready"
                or execution_manifest_receipt_binding_issues(execution_index)
                or execution_index.causal_chain_sha256 != causal_chain_sha256
                or execution_index.planning_sha256 != planning_sha256
                or execution_index.outline_sha256 != context.get("outline_sha256")
                or execution_index.authority_sha256 != expected_execution_authority
                or manifest.get("execution_manifest_sha256")
                != execution_manifest_hash
                or manifest.get("execution_manifest_receipt_sha256")
                != hashlib.sha256(receipt_text.encode("utf-8")).hexdigest()
                or draft_integrity.get("status") != "passed"
                or draft_integrity.get("draft_sha256")
                != draft_sha256
                or draft_integrity.get("execution_manifest_sha256")
                != execution_manifest_hash
                or draft_integrity.get("plan_sha256") != planning_sha256
                or draft_integrity.get("base_constraints_sha256")
                != context.get("constraints_sha256")
                or draft_integrity.get("story_state_sha256")
                != context.get("story_state_sha256")
                or segment_events != self._checkpoint_segment_events(
                    execution_index, draft_integrity,
                )
                or manifest.get("draft_integrity_sha256")
                != hashlib.sha256(
                    draft_integrity_text.encode("utf-8"),
                ).hexdigest()
                or manifest.get("causal_chain_artifact_sha256")
                != hashlib.sha256(causal_chain_text.encode("utf-8")).hexdigest()
                or manifest.get("segment_events_sha256")
                != hashlib.sha256(segment_events_text.encode("utf-8")).hexdigest()
                or bool(adaptation_sha256) and (
                    not isinstance(planning_adaptation, dict)
                    or planning_adaptation.get("status") != "ready"
                    or planning_adaptation.get("outline_sha256") != context.get("outline_sha256")
                    or planning_adaptation.get("planning_sha256") != planning_sha256
                    or planning_adaptation.get("segment_count") != context.get("segment_count")
                )
            ):
                continue
            plan = plan_text.strip()
            if plan and len(self._split_segments(draft)) == segment_count:
                return outputs
        return None

    @classmethod
    def _restore_short_checkpoint(
        cls, source: Path, outputs: Path, context: dict,
    ) -> tuple[str, str, str, dict]:
        """Copy every validated full-checkpoint artifact into the current run."""
        plan = (source / "planning.md").read_text(encoding="utf-8")
        draft, source_artifact = cls._short_checkpoint_manuscript(
            source, int(context["segment_count"]),
        )
        integrity_source = source / "draft-integrity.json"
        if source_artifact == "best-candidate.md":
            quality_checkpoint = load_quality_checkpoint(source.parent) or {}
            integrity_ref = quality_checkpoint.get("narrative_integrity") or {}
            integrity_source = source.parent / str(integrity_ref.get("path") or "")
        atomic_write(outputs / "planning.md", plan)
        atomic_write(outputs / "draft.md", draft)
        for filename in (
            "short-causal-chain.json", "short-execution-index.json",
            "segment-events.json",
        ):
            atomic_write(
                outputs / filename,
                (source / filename).read_text(encoding="utf-8"),
            )
        adaptation_source = source / "planning-adaptations.json"
        if adaptation_source.is_file():
            atomic_write(
                outputs / "planning-adaptations.json",
                adaptation_source.read_text(encoding="utf-8"),
            )
        atomic_write(
            outputs / "draft-integrity.json",
            integrity_source.read_text(encoding="utf-8"),
        )
        if source_artifact == "best-candidate.md":
            atomic_write(outputs / "best-candidate.md", draft)
        cls._save_short_checkpoint(outputs, context)
        causal_chain = json.loads(
            (outputs / "short-causal-chain.json").read_text(encoding="utf-8"),
        )
        return plan, draft, source_artifact, causal_chain

    def _find_short_partial_checkpoint(
        self, project: Project, current_run_id: str, state_revision: int,
        state: dict, constraints: str, segment_count: int,
    ) -> Path | None:
        for run in self.db.list_runs(project.id):
            if run["workflow"] != "short-story":
                continue
            if (run["id"] != current_run_id
                    and run["status"] not in {"failed", "cancelled"}):
                continue
            outputs = project.path / "runs" / run["id"] / "outputs"
            plan_path = outputs / "planning.md"
            chain_path = outputs / "short-causal-chain.json"
            index_path = outputs / "short-execution-index.json"
            checkpoint_root = outputs / "draft-checkpoints"
            if not (
                plan_path.is_file() and chain_path.is_file() and index_path.is_file()
                and checkpoint_root.is_dir()
                and any(checkpoint_root.glob("segment-*.json"))
            ):
                continue
            try:
                plan = plan_path.read_text(encoding="utf-8")
                chain = json.loads(chain_path.read_text(encoding="utf-8"))
                index = json.loads(index_path.read_text(encoding="utf-8"))
            except (OSError, UnicodeError, json.JSONDecodeError, AttributeError):
                continue
            if legacy_execution_index_requires_rebuild(index):
                continue
            formal_outline = state.get("outline") or {}
            formal_outline_content = str(formal_outline.get("content") or "")
            formal_outline_events = (
                narrative_outline_event_contracts(formal_outline_content)
                if formal_outline_content.strip()
                else formal_outline.get("events") or []
            )
            planning_adaptation = None
            adaptation_path = outputs / "planning-adaptations.json"
            if adaptation_path.is_file():
                try:
                    planning_adaptation = json.loads(
                        adaptation_path.read_text(encoding="utf-8"),
                    )
                except (OSError, UnicodeError, json.JSONDecodeError, TypeError):
                    continue
                if not self._planning_adaptation_artifact_valid(
                    planning_adaptation, state, plan, formal_outline_events,
                    segment_count,
                ):
                    continue
            hashes, authority_text, expected_events = self._short_execution_authority(
                project, state_revision, state, constraints, plan, chain,
                formal_outline_events, segment_count, planning_adaptation,
            )
            try:
                execution_manifest = parse_execution_manifest(index)
                execution_issues = execution_manifest_issues(
                    execution_manifest,
                    expected_event_ids=[
                        str(item.get("id") or "").strip().upper()
                        for item in expected_events
                        if str(item.get("id") or "").strip()
                    ],
                    segment_count=segment_count,
                    authority_hashes=hashes,
                    expected_events=expected_events,
                )
                validate_execution_manifest_receipt(
                    execution_manifest, authority_text,
                    execution_manifest.semantic_receipt,
                )
            except (TypeError, ValueError):
                continue
            if (
                execution_manifest.status != "ready"
                or execution_issues
                or self._short_plan_issues(project, state, plan, segment_count)
                or analyze_short_causal_chain(
                    chain, int(project.metadata["target_words"]),
                )["status"] == "invalid"
            ):
                continue
            manifest_hash = execution_manifest_sha256(execution_manifest)
            manifest_segments = {
                item.segment: item for item in execution_manifest.segments
            }
            beat_by_id = {
                item.beat_id: item for item in execution_manifest.beats
            }
            segment_plans = self._short_plan_segments(plan, segment_count)
            target = math.ceil(
                int(project.metadata["target_words"]) / segment_count,
            )
            augmented_constraints = constraints + (
                "\n\n# Short Story Causal Chain\n\n"
                + compact_causal_chain(chain)
            )
            story_state_sha256 = hashlib.sha256(json.dumps(
                state, ensure_ascii=False, sort_keys=True, default=str,
            ).encode("utf-8")).hexdigest()
            location_catalog = build_location_catalog(project.path, state)
            draft_authority_hash = hashlib.sha256(json.dumps({
                "plan": plan,
                "constraints": augmented_constraints,
                "target_words": int(project.metadata["target_words"]),
                "segment_count": segment_count,
                "story_state_sha256": story_state_sha256,
                "execution_manifest_sha256": manifest_hash,
                "location_catalog": sorted(
                    (alias, ref.name, ref.root)
                    for alias, ref in location_catalog.items()
                ),
            }, ensure_ascii=False, sort_keys=True).encode("utf-8")).hexdigest()
            accepted_parts: list[str] = []
            for number in range(1, segment_count + 1):
                checkpoint_path = checkpoint_root / f"segment-{number:02d}.json"
                if not checkpoint_path.is_file():
                    break
                try:
                    checkpoint = json.loads(
                        checkpoint_path.read_text(encoding="utf-8"),
                    )
                    text = str(checkpoint.get("text") or "")
                    assignment = checkpoint.get("assignment") or {}
                    manifest_segment = manifest_segments[number]
                    beat_ids = list(manifest_segment.beat_ids)
                    source_event_ids = list(dict.fromkeys(
                        beat_by_id[beat_id].source_event_id for beat_id in beat_ids
                    ))
                    handoff = "；".join(
                        assertion.state for assertion in manifest_segment.exit_state
                    )
                    previous_sha = (
                        hashlib.sha256(accepted_parts[-1].encode("utf-8")).hexdigest()
                        if accepted_parts else ""
                    )
                    contract = DraftTaskContract(
                        authority_sha256=draft_authority_hash,
                        task_id=f"segment-{number:02d}", parent_task_id="", depth=0,
                        target_han=target, event_ids=tuple(source_event_ids),
                        scope="恢复检查点原子节拍",
                        entry_state="恢复检查点入口状态",
                        exit_requirement=handoff,
                        execution_manifest_sha256=manifest_hash,
                        beat_ids=tuple(beat_ids),
                        **_draft_narrative_contract_fields(project),
                        prohibited_future_beat_ids=(
                            manifest_segment.prohibited_future_beat_ids
                        ),
                    )
                    validate_semantic_receipt(
                        contract, text, checkpoint.get("semantic_receipt"),
                    )
                except (OSError, UnicodeError, json.JSONDecodeError, TypeError, ValueError):
                    break
                if (
                    checkpoint.get("version") != 3
                    or checkpoint.get("authority_sha256") != draft_authority_hash
                    or checkpoint.get("execution_manifest_sha256") != manifest_hash
                    or checkpoint.get("previous_sha256") != previous_sha
                    or checkpoint.get("segment_plan_sha256") != hashlib.sha256(
                        segment_plans[number - 1].encode("utf-8"),
                    ).hexdigest()
                    or checkpoint.get("text_sha256") != hashlib.sha256(
                        text.encode("utf-8"),
                    ).hexdigest()
                    or assignment.get("segment") != number
                    or assignment.get("event_ids") != beat_ids
                    or assignment.get("source_event_ids") != source_event_ids
                    or assignment.get("handoff") != handoff
                    or self._draft_segment_issues(
                        text, target, accepted_parts, location_catalog,
                    )
                ):
                    break
                accepted_parts.append(text)
            if not accepted_parts:
                continue
            return outputs
        return None

    @classmethod
    def _short_checkpoint_manuscript(cls, outputs: Path,
                                     segment_count: int) -> tuple[str, str]:
        quality_checkpoint = load_quality_checkpoint(outputs.parent)
        protected_best = False
        if quality_checkpoint and quality_checkpoint.get("manuscript_path") == (
            "outputs/best-candidate.md"
        ):
            integrity_ref = quality_checkpoint.get("narrative_integrity")
            if isinstance(integrity_ref, dict):
                integrity_path = outputs.parent / str(integrity_ref.get("path") or "")
                try:
                    integrity_text = integrity_path.read_text(encoding="utf-8")
                    integrity = json.loads(integrity_text)
                except (OSError, UnicodeError, json.JSONDecodeError):
                    integrity = None
                protected_best = bool(
                    isinstance(integrity, dict)
                    and integrity.get("status") == "passed"
                    and integrity.get("draft_sha256")
                    == quality_checkpoint.get("manuscript_hash")
                    and hashlib.sha256(integrity_text.encode("utf-8")).hexdigest()
                    == integrity_ref.get("sha256")
                )
        filenames = (
            ("best-candidate.md", "draft.md")
            if protected_best else ("draft.md",)
        )
        for filename in filenames:
            path = outputs / filename
            if not path.is_file():
                continue
            text = path.read_text(encoding="utf-8")
            if len(cls._split_segments(text)) == segment_count:
                return text, filename
        raise ValueError("Short-story checkpoint has no complete manuscript")

    def _find_short_stage_output(self, project: Project, current_run_id: str,
                                 filename: str) -> Path | None:
        path = project.path / "runs" / current_run_id / "outputs" / filename
        return path if path.is_file() and path.stat().st_size else None

    @staticmethod
    def _compact_polish_prompt(*, authority_packet,
                               local_findings: list,
                               review_findings: dict | None = None) -> str:
        return (
            "普通润色精简恢复。只处理当前正文片段，不扩写片段外内容。"
            "只返回修改后的正文，不解释、不分析。\n\n"
            + render_polish_authority_packet(authority_packet, advisory={
                "local_findings": local_findings,
                "review_findings": review_findings or {"issues": []},
            })
        )

    @staticmethod
    def _polish_part_spans(text: str, parts: list[str]) -> list[tuple[int, int]]:
        spans = []
        cursor = 0
        for part in parts:
            start = text.find(part, cursor)
            if start < 0:
                start = cursor
            end = start + len(part)
            spans.append((start, end))
            cursor = end
        return spans

    @staticmethod
    def _polish_narrative_context(
        ledger: dict, segment: str, start: int, end: int,
        previous_handoff: str = "",
    ) -> dict:
        normalized_segment = segment.lower()

        def related(item: dict) -> bool:
            overlaps = int(item.get("start", -1)) < end and int(item.get("end", -1)) > start
            anchors = [str(value).lower() for value in item.get("anchors", []) if value]
            return overlaps or any(anchor in normalized_segment for anchor in anchors)

        def open_items(key: str) -> list[dict]:
            return [
                {
                    "text": str(item.get("text") or "")[:180],
                    "status": item.get("status", "unresolved"),
                }
                for item in ledger.get(key, [])
                if isinstance(item, dict)
                and item.get("status") == "unresolved"
                and related(item)
            ][:2]

        scenes = []
        for scene in ledger.get("scenes", []):
            if not isinstance(scene, dict) or not related(scene):
                continue
            scenes.append({
                "entry_state": scene.get("entry_state"),
                "exit_state": scene.get("exit_state"),
                "state_changes": [
                    str(item.get("evidence") or "")[:160]
                    for item in scene.get("state_changes", []) if isinstance(item, dict)
                ][:3],
            })
            if len(scenes) == 2:
                break
        items_by_id = {
            item.get("id"): item
            for key in ("questions", "promises", "setups", "payoffs")
            for item in ledger.get(key, [])
            if isinstance(item, dict) and item.get("id")
        }
        relations = []
        for relation in ledger.get("relations", []):
            if not isinstance(relation, dict) or not related(relation):
                continue
            source = items_by_id.get(relation.get("from_id"), {})
            target = items_by_id.get(relation.get("to_id"), {})
            relations.append({
                "关系": relation.get("kind"),
                "前文": str(source.get("text") or "")[:140],
                "本窗或后文": str(target.get("text") or relation.get("evidence") or "")[:140],
            })
            if len(relations) == 2:
                break
        return {
            "上一窗实际交接状态": previous_handoff[:300],
            "本窗未兑现问题": open_items("questions"),
            "本窗未兑现承诺": open_items("promises"),
            "本窗伏笔": open_items("setups"),
            "本窗关联的提问与兑现": relations,
            "本窗场景状态": scenes,
        }

    @staticmethod
    def _polish_exit_state(text: str) -> str:
        scenes = build_narrative_ledger(text).get("scenes", [])
        return next((
            str(scene.get("exit_state"))
            for scene in reversed(scenes)
            if isinstance(scene, dict) and scene.get("exit_state")
        ), "")

    @staticmethod
    def _raise_for_unusable_polish_output(
        text: str, source_characters: int, maximum_characters: int,
        minimum_characters: int = 0,
    ) -> None:
        receipt = getattr(text, "receipt", {})
        if receipt.get("finish_reason") == "max_tokens":
            raise RuntimeError("polish output incomplete (finish_reason=max_tokens)")
        if source_characters >= 200 and len(text.strip()) > maximum_characters:
            raise RuntimeError(
                f"polish output exceeds allowed maximum ({len(text.strip())} > "
                f"{maximum_characters})"
            )
        if (source_characters >= 200 and minimum_characters > 0
                and len(text.strip()) < minimum_characters):
            raise RuntimeError(
                f"polish output is below allowed minimum ({len(text.strip())} < "
                f"{minimum_characters})"
            )

    @staticmethod
    def _polish_input_tokens(value: object) -> int:
        receipt = getattr(value, "receipt", None)
        if isinstance(receipt, dict):
            try:
                return max(0, int(receipt.get("input_tokens", 0) or 0))
            except (TypeError, ValueError):
                return 0
        match = re.search(r"input_tokens=(\d+)", str(value))
        return int(match.group(1)) if match else 0

    async def _ordinary_polish_segment(
        self, run_id: str, run_path: Path, project: Project, constraints: str,
        source: str, full_prompt: str, compact_prompt: str, suffix: str,
        minimum_characters: int, maximum_characters: int, configured_fallback: bool,
        metadata: dict,
    ) -> tuple[str, bool, bool, bool, int]:
        consumed_input_tokens = 0

        async def request(*, prompt: str, fallback: bool, compact: bool,
                          attempt_suffix: str) -> str:
            nonlocal consumed_input_tokens
            try:
                polished = await self._stage(
                    run_id, run_path, project, "polish", constraints, prompt,
                    suffix=attempt_suffix, allow_tools=False,
                    prefer_configured_fallback=fallback,
                    output_source_characters=len(source),
                    primary_only=not fallback,
                    retry_polish_output_limit=True,
                    compact_input=compact,
                )
                consumed_input_tokens += int(
                    getattr(polished, "receipt", {}).get("input_tokens", 0) or 0
                )
                self._raise_for_unusable_polish_output(
                    polished, len(source), maximum_characters, minimum_characters,
                )
                return polished
            except asyncio.CancelledError:
                raise
            except Exception as exc:
                consumed_input_tokens += self._polish_input_tokens(exc)
                raise

        prompt = full_prompt
        compact_used = False
        primary_transport_retried = False
        primary_error: Exception | None = None
        while True:
            try:
                polished = await request(
                    prompt=prompt, fallback=False, compact=compact_used,
                    attempt_suffix=(f"{suffix}-input-compact" if compact_used else suffix),
                )
                return polished, False, compact_used, False, consumed_input_tokens
            except asyncio.CancelledError:
                raise
            except Exception as exc:
                kind = classify_model_failure(exc)
                if kind == "provider_rejection":
                    raise
                if kind == "input_context_overflow" and not compact_used:
                    compact_used = True
                    prompt = compact_prompt
                    self.db.add_run_event(
                        run_id, "warning", "polish_input_compact_retry",
                        "当前模型明确拒绝了过长输入，正在保留叙事权威后压缩建议重试",
                        stage="polish", metadata={
                            **metadata, "error": describe_error(exc)[:500],
                            "route": "primary",
                            "failure_class": "input_context_overflow",
                        },
                    )
                    continue
                if kind in {"input_context_overflow", "output_limit"}:
                    raise
                if kind == "transport_interrupted" and not primary_transport_retried:
                    primary_transport_retried = True
                    self.db.add_run_event(
                        run_id, "warning", "polish_transport_retry",
                        "润色请求因网络中断，正在同一路由使用相同内容重试一次",
                        stage="polish", metadata={
                            **metadata, "error": describe_error(exc)[:500],
                            "route": "primary",
                            "failure_class": "transport_interrupted",
                        },
                    )
                    continue
                primary_error = exc
                break

        if configured_fallback:
            fallback_compact = compact_used
            fallback_prompt = compact_prompt if fallback_compact else full_prompt
            while True:
                self.db.add_run_event(
                    run_id, "warning", "polish_configured_fallback",
                    "首选润色路由未产生可用正文，正在使用配置的备用路由",
                    stage="polish", metadata={
                        **metadata, "error": describe_error(primary_error)[:500],
                        "compact_input": fallback_compact,
                        "failure_class": classify_model_failure(primary_error),
                    },
                )
                try:
                    polished = await request(
                        prompt=fallback_prompt, fallback=True, compact=fallback_compact,
                        attempt_suffix=f"{suffix}-fallback"
                        + ("-input-compact" if fallback_compact else ""),
                    )
                    return polished, False, fallback_compact, True, consumed_input_tokens
                except asyncio.CancelledError:
                    raise
                except Exception as exc:
                    kind = classify_model_failure(exc)
                    if kind == "provider_rejection":
                        raise
                    if kind == "input_context_overflow" and not fallback_compact:
                        fallback_compact = True
                        compact_used = True
                        fallback_prompt = compact_prompt
                        self.db.add_run_event(
                            run_id, "warning", "polish_input_compact_retry",
                            "备用模型明确拒绝了过长输入，正在保留叙事权威后压缩建议重试",
                            stage="polish", metadata={
                                **metadata, "error": describe_error(exc)[:500],
                                "route": "fallback",
                                "failure_class": "input_context_overflow",
                            },
                        )
                        continue
                    if kind in {"input_context_overflow", "output_limit"}:
                        raise
                    primary_error = exc
                    break

        self.db.add_run_event(
            run_id, "warning", "polish_segment_preserved",
            "本段未完成精修，已保留原文并继续",
            stage="polish", metadata={
                **metadata, "error": describe_error(primary_error)[:500],
                "failure_class": classify_model_failure(primary_error),
            },
        )
        return (
            source, True, compact_used, configured_fallback,
            consumed_input_tokens,
        )

    @staticmethod
    def _manifest_segment_contract(
        project: Project,
        manifest: ShortExecutionManifest,
        source_integrity: dict,
        manifest_segment,
        prose: str,
        index: int,
    ) -> DraftTaskContract:
        beat_by_id = {beat.beat_id: beat for beat in manifest.beats}
        beat_ids = list(manifest_segment.beat_ids)
        return DraftTaskContract(
            authority_sha256=str(
                source_integrity.get("authority_sha256")
                or manifest.authority_sha256
            ),
            task_id=f"segment-{index:02d}",
            parent_task_id="",
            depth=0,
            target_han=max(1, effective_han_characters(prose)),
            event_ids=tuple(dict.fromkeys(
                beat_by_id[beat_id].source_event_id for beat_id in beat_ids
            )),
            scope="\n".join(
                f"{beat_id}：{beat_by_id[beat_id].action}"
                for beat_id in beat_ids
            ),
            entry_state="；".join(
                item.state for item in manifest_segment.entry_state
            ),
            exit_requirement="；".join(
                item.state for item in manifest_segment.exit_state
            ),
            execution_manifest_sha256=execution_manifest_sha256(manifest),
            beat_ids=tuple(beat_ids),
            **_draft_narrative_contract_fields(project),
            prohibited_future_beat_ids=(
                manifest_segment.prohibited_future_beat_ids
            ),
        )

    @classmethod
    def _semantic_authority_bundle(
        cls, semantic_authority: object,
    ) -> tuple[ShortExecutionManifest, dict, list[str]]:
        if not isinstance(semantic_authority, dict):
            raise ValueError("候选稿没有可复核的原子节拍权威资料")
        manifest = parse_execution_manifest(
            semantic_authority.get("execution_manifest"),
        )
        source_integrity = semantic_authority.get("source_integrity")
        source_text = semantic_authority.get("source_text")
        source_segments = semantic_authority.get("source_segments")
        if not isinstance(source_integrity, dict):
            raise ValueError("候选稿缺少可复核的语义完整性资料")
        if not (
            isinstance(source_segments, list)
            and source_segments
            and all(isinstance(item, str) and item for item in source_segments)
        ):
            source_segments = cls._split_segments(
                source_text if isinstance(source_text, str) else "",
            )
        clean_source = "\n\n".join(source_segments)
        segmented_source = cls.SHORT_SEGMENT_SEPARATOR.join(source_segments)
        integrity_source_hashes = {
            hashlib.sha256(value.encode("utf-8")).hexdigest()
            for value in (clean_source, segmented_source)
        }
        if (
            not isinstance(source_text, str)
            or not source_text
            or source_text not in {clean_source, segmented_source}
            or source_integrity.get("draft_sha256") not in integrity_source_hashes
            or manifest.status != "ready"
            or execution_manifest_receipt_binding_issues(manifest)
            or source_integrity.get("status") != "passed"
            or source_integrity.get("execution_manifest_sha256")
            != execution_manifest_sha256(manifest)
            or len(source_segments) != len(manifest.segments)
        ):
            raise ValueError("候选稿绑定的原子节拍权威资料已经失效")
        return manifest, source_integrity, list(source_segments)

    @classmethod
    def _candidate_segments_from_clean_source(
        cls, source: str, candidate: str, source_segments: list[str],
    ) -> list[str]:
        """Project a marker-free candidate back onto immutable segment borders."""
        if len(source_segments) == 1:
            return [candidate.strip()] if candidate.strip() else []
        segmented_source = cls.SHORT_SEGMENT_SEPARATOR.join(source_segments)
        if source == segmented_source:
            candidate_segments = cls._split_segments(candidate)
            if len(candidate_segments) != len(source_segments):
                raise DraftSemanticValidationError("story-boundary", [{
                    "code": "segment_boundary",
                    "message": "返修或润色结果改变了正式分段边界",
                    "expected_segments": len(source_segments),
                    "actual_segments": len(candidate_segments),
                }])
            return candidate_segments

        clean_source = "\n\n".join(source_segments)
        if source != clean_source:
            raise ValueError("候选稿与原子节拍权威的发布态正文不一致")
        if candidate == source:
            return list(source_segments)

        opcodes = SequenceMatcher(
            None, source, candidate, autojunk=False,
        ).get_opcodes()
        separator_ranges = []
        cursor = 0
        for part in source_segments[:-1]:
            cursor += len(part)
            separator_ranges.append((cursor, cursor + 2))
            cursor += 2

        candidate_separators = []
        for start, end in separator_ranges:
            match = next((
                (i1, i2, j1, j2)
                for tag, i1, i2, j1, j2 in opcodes
                if tag == "equal" and i1 <= start and end <= i2
            ), None)
            if match is None:
                raise DraftSemanticValidationError("story-boundary", [{
                    "code": "segment_boundary",
                    "message": "返修或润色结果改动了正式分段交界",
                    "source_range": [start, end],
                }])
            i1, _i2, j1, _j2 = match
            candidate_start = j1 + start - i1
            candidate_end = j1 + end - i1
            if candidate[candidate_start:candidate_end] != "\n\n":
                raise DraftSemanticValidationError("story-boundary", [{
                    "code": "segment_boundary",
                    "message": "返修或润色结果改动了正式分段交界",
                    "source_range": [start, end],
                }])
            candidate_separators.append((candidate_start, candidate_end))

        parts = []
        cursor = 0
        for start, end in candidate_separators:
            parts.append(candidate[cursor:start])
            cursor = end
        parts.append(candidate[cursor:])
        if (
            len(parts) != len(source_segments)
            or any(not part.strip() for part in parts)
            or "\n\n".join(parts) != candidate
        ):
            raise DraftSemanticValidationError("story-boundary", [{
                "code": "segment_boundary",
                "message": "返修或润色结果无法还原完整正式分段",
                "expected_segments": len(source_segments),
                "actual_segments": len(parts),
            }])
        return parts

    async def _verify_atomic_candidate_semantics(
        self,
        run_id: str,
        run_path: Path,
        project: Project,
        constraints: str,
        source: str,
        candidate: str,
        semantic_authority: object,
        *,
        suffix: str,
        failure_stage: str,
        verify_whole: bool,
    ) -> dict:
        manifest, source_integrity, authority_source_parts = (
            self._semantic_authority_bundle(semantic_authority)
        )
        source_parts = self._candidate_segments_from_clean_source(
            str(semantic_authority.get("source_text") or ""),
            source,
            authority_source_parts,
        )
        candidate_parts = self._candidate_segments_from_clean_source(
            source, candidate, source_parts,
        )
        if (
            len(source_parts) != len(candidate_parts)
            or len(candidate_parts) != len(manifest.segments)
        ):
            raise DraftSemanticValidationError("story-boundary", [{
                "code": "segment_boundary",
                "message": "返修或润色结果改变了正式分段边界",
                "expected_segments": len(manifest.segments),
                "actual_segments": len(candidate_parts),
            }])
        source_receipts = source_integrity.get("semantic_segment_receipts")
        if (
            not isinstance(source_receipts, list)
            or len(source_receipts) != len(source_parts)
        ):
            raise ValueError("验收前原文缺少完整的分段语义回执")
        all_beat_ids = [beat.beat_id for beat in manifest.beats]
        receipts = []
        changed_segments = []
        for index, (source_part, candidate_part, manifest_segment) in enumerate(
            zip(source_parts, candidate_parts, manifest.segments, strict=True), 1,
        ):
            contract = self._manifest_segment_contract(
                project, manifest, source_integrity, manifest_segment,
                candidate_part, index,
            )
            if candidate_part == source_part:
                receipt = validate_semantic_receipt(
                    contract, candidate_part, source_receipts[index - 1],
                )
            else:
                changed_segments.append(index)
                receipt = await self._verify_draft_semantic_node(
                    run_id, run_path, project, constraints, contract,
                    candidate_part,
                    [
                        beat_id for beat_id in all_beat_ids
                        if beat_id not in manifest_segment.beat_ids
                    ],
                    suffix=f"{suffix}-segment-{index:02d}",
                    failure_stage=failure_stage,
                )
            receipts.append(receipt)
        expected_beat_ids = [
            beat_id
            for segment in manifest.segments
            for beat_id in segment.beat_ids
        ]
        whole_receipt = None
        if verify_whole:
            if candidate == source:
                try:
                    whole_receipt = validate_whole_draft_receipt(
                        str(
                            source_integrity.get("authority_sha256")
                            or manifest.authority_sha256
                        ),
                        source, source_parts, expected_beat_ids,
                        source_integrity.get("whole_semantic_receipt"),
                    )
                except (TypeError, ValueError):
                    whole_receipt = None
            if whole_receipt is None:
                whole_receipt = await self._verify_whole_draft_semantics(
                    run_id, run_path, project, constraints,
                    str(
                        source_integrity.get("authority_sha256")
                        or manifest.authority_sha256
                    ),
                    candidate, candidate_parts, expected_beat_ids, receipts,
                    failure_stage=failure_stage,
                )
        segment_integrity = []
        previous_hash = ""
        for index, (candidate_part, manifest_segment) in enumerate(
            zip(candidate_parts, manifest.segments, strict=True), 1,
        ):
            text_hash = self._text_hash(candidate_part)
            segment_integrity.append({
                "segment": index,
                "event_ids": list(manifest_segment.beat_ids),
                "handoff": "；".join(
                    item.state for item in manifest_segment.exit_state
                ),
                "han_characters": effective_han_characters(candidate_part),
                "previous_sha256": previous_hash,
                "text_sha256": text_hash,
            })
            previous_hash = text_hash
        return {
            **source_integrity,
            "version": 5,
            "status": "passed",
            "source_draft_sha256": self._text_hash(source),
            "draft_sha256": self._text_hash(candidate),
            "publication_sha256": self._text_hash(candidate),
            "publication_segment_lengths": [
                len(part) for part in candidate_parts
            ],
            "segments": segment_integrity,
            "execution_manifest_sha256": execution_manifest_sha256(manifest),
            "accepted_event_ids": expected_beat_ids,
            "semantic_segment_receipts": receipts,
            "whole_semantic_receipt": whole_receipt,
            "changed_segments": changed_segments,
            "issues": [],
        }

    async def _recover_short_revision_semantic_subset(
        self,
        run_id: str,
        run_path: Path,
        project: Project,
        constraints: str,
        source: str,
        semantic_authority: dict,
        adopted_records: list[dict],
        initial_issues: list[dict],
    ) -> dict:
        """Keep a bounded deterministic adopted subset that passes whole-story review."""

        def replay(selected: list[dict]) -> tuple[str, list[dict], list[dict]]:
            candidate = source
            groups: list[dict] = []
            results: list[dict] = []
            for record in selected:
                patch_group = record.get("patch_group")
                if not isinstance(patch_group, dict):
                    raise ValueError("返修组缺少可重放修改合同")
                result = {
                    "group_id": record["group_id"],
                    **apply_patch_group(
                        candidate, patch_group, self._text_hash(candidate),
                    ),
                }
                if result.get("accepted") is not True:
                    raise ValueError("返修组无法在安全组合中完整重放")
                candidate = result["text"]
                groups.append(patch_group)
                results.append(result)
            return candidate, groups, results

        trials: list[list[dict]] = []
        seen: set[tuple[str, ...]] = set()

        def add_trial(records: list[dict]) -> None:
            identity = tuple(str(item.get("group_id") or "") for item in records)
            if identity not in seen:
                seen.add(identity)
                trials.append(records)

        for rejected in reversed(adopted_records):
            add_trial([item for item in adopted_records if item is not rejected])
        for retained_count in range(len(adopted_records) - 2, -1, -1):
            add_trial(list(adopted_records[:retained_count]))
        add_trial([])

        last_error: Exception | None = None
        for trial_number, selected in enumerate(trials, 1):
            try:
                candidate, groups, results = replay(selected)
                integrity = await self._verify_atomic_candidate_semantics(
                    run_id, run_path, project, constraints, source, candidate,
                    semantic_authority,
                    suffix=f"-revision-final-isolation-{trial_number}",
                    failure_stage="repair_groups", verify_whole=True,
                )
            except asyncio.CancelledError:
                raise
            except (DraftSemanticValidationError, ValueError) as exc:
                last_error = exc
                continue

            selected_ids = {
                str(item.get("group_id") or "") for item in selected
            }
            rejected = [
                item for item in adopted_records
                if str(item.get("group_id") or "") not in selected_ids
            ]
            rejected_issue_ids = {
                str(issue_id)
                for record in rejected
                for issue_id in record.get("issue_ids", [])
                if str(issue_id)
            }
            for record in rejected:
                record.update({
                    "decision": "rejected",
                    "decision_override": "whole_semantic_conflict",
                    "status": "rejected_after_final_semantic_gate",
                    "message": (
                        "该修改与已采用修改合并后破坏整篇因果，"
                        "已自动撤销并重新列为未解决"
                    ),
                    "semantic_issues": initial_issues,
                })
            self.db.add_run_event(
                run_id, "warning", "short_revision_semantic_subset_restored",
                "已隔离并撤销造成整篇冲突的修改组，其余安全修改继续进入终审",
                stage="revision_semantic_gate", metadata={
                    "retained_group_ids": [
                        str(item.get("group_id") or "") for item in selected
                    ],
                    "rejected_group_ids": [
                        str(item.get("group_id") or "") for item in rejected
                    ],
                    "rejected_issue_ids": sorted(rejected_issue_ids),
                    "initial_issues": initial_issues,
                },
            )
            return {
                "candidate": candidate,
                "records": selected,
                "groups": groups,
                "results": results,
                "integrity": integrity,
                "rejected_issue_ids": rejected_issue_ids,
            }
        if last_error is not None:
            raise last_error
        raise ValueError("无法构造通过整篇语义复核的返修组合")

    async def _recover_polish_semantic_subset(
        self,
        run_id: str,
        run_path: Path,
        project: Project,
        constraints: str,
        source: str,
        source_parts: list[str],
        candidate_parts: list[str],
        manifest: ShortExecutionManifest,
        source_integrity: dict,
        candidate_receipts: list[dict],
        source_receipts: list[dict],
        source_whole_receipt: dict,
        expected_beat_ids: list[str],
    ) -> dict:
        """Retain a bounded deterministic whole-story-safe polish subset."""
        changed_segments = [
            index for index, (source_part, candidate_part) in enumerate(
                zip(source_parts, candidate_parts, strict=True), 1,
            )
            if source_part != candidate_part
        ]
        authority_sha256 = str(
            source_integrity.get("authority_sha256")
            or manifest.authority_sha256
        )
        seen: set[tuple[int, ...]] = set()

        async def verify(selected: list[int]) -> dict | None:
            identity = tuple(sorted(selected))
            if identity in seen:
                return None
            seen.add(identity)
            selected_set = set(identity)
            trial_parts = [
                candidate_part if index in selected_set else source_part
                for index, (source_part, candidate_part) in enumerate(
                    zip(source_parts, candidate_parts, strict=True), 1,
                )
            ]
            trial_receipts = [
                candidate_receipts[index - 1]
                if index in selected_set else source_receipts[index - 1]
                for index in range(1, len(source_parts) + 1)
            ]
            trial = self.SHORT_SEGMENT_SEPARATOR.join(trial_parts)
            if not identity:
                return {
                    "parts": trial_parts,
                    "receipts": trial_receipts,
                    "whole_receipt": source_whole_receipt,
                    "retained_segments": [],
                }
            try:
                whole_receipt = await self._verify_whole_draft_semantics(
                    run_id, run_path, project, constraints,
                    authority_sha256, trial, trial_parts, expected_beat_ids,
                    trial_receipts, failure_stage="polish",
                )
            except asyncio.CancelledError:
                raise
            except Exception:
                return None
            return {
                "parts": trial_parts,
                "receipts": trial_receipts,
                "whole_receipt": whole_receipt,
                "retained_segments": list(identity),
            }

        # A single conflicting unit is the common production shape. Try every
        # one-unit rollback first so the first passing result retains n-1 safe
        # segments without an exponential subset search.
        for rejected_segment in reversed(changed_segments):
            recovered = await verify([
                segment for segment in changed_segments
                if segment != rejected_segment
            ])
            if recovered is not None:
                recovered["rejected_segments"] = [
                    segment for segment in changed_segments
                    if segment not in recovered["retained_segments"]
                ]
                return recovered

        # Multiple interacting conflicts use a linear monotonic rebuild from
        # the already accepted source. Each accepted addition becomes the next
        # trial base, so a failed middle segment cannot prevent a later safe
        # segment from being retained.
        retained: list[int] = []
        best = await verify([])
        for segment in changed_segments:
            recovered = await verify([*retained, segment])
            if recovered is not None:
                retained = list(recovered["retained_segments"])
                best = recovered
        if best is None:
            raise ValueError("验收前正文无法通过润色子集恢复的整篇语义复核")
        best["rejected_segments"] = [
            segment for segment in changed_segments
            if segment not in set(best["retained_segments"])
        ]
        return best

    async def _repair_short_revision_semantic_group(
        self,
        run_id: str,
        run_path: Path,
        project: Project,
        constraints: str,
        contract: dict,
        issue: dict,
        group_id: str,
        candidate_before: str,
        rejected_candidate: str,
        rejected_patch_group: dict,
        initial_error: DraftSemanticValidationError,
    ) -> tuple[dict, dict, dict]:
        semantic_authority = contract.get("semantic_authority")
        manifest, source_integrity, authority_source_parts = (
            self._semantic_authority_bundle(semantic_authority)
        )
        authority_source = str(semantic_authority.get("source_text") or "")
        before_parts = self._candidate_segments_from_clean_source(
            authority_source, candidate_before, authority_source_parts,
        )
        rejected_parts = self._candidate_segments_from_clean_source(
            candidate_before, rejected_candidate, before_parts,
        )
        authorized_segments: set[int] = set()
        for patch in rejected_patch_group.get("patches", []):
            if not isinstance(patch, dict):
                continue
            old_text = patch.get("old_text")
            if not isinstance(old_text, str) or not old_text:
                continue
            matches = [
                index for index, part in enumerate(before_parts, 1)
                if old_text in part
            ]
            if len(matches) == 1:
                authorized_segments.add(matches[0])
        affected_segments = []
        if (
            len(before_parts) == len(rejected_parts)
            and len(before_parts) == len(manifest.segments)
        ):
            rejected_changed_segments = {
                index
                for index, (before_part, rejected_part) in enumerate(
                    zip(before_parts, rejected_parts, strict=True), 1,
                )
                if before_part != rejected_part
            }
            if (
                not rejected_changed_segments
                or not rejected_changed_segments.issubset(authorized_segments)
            ):
                raise DraftSemanticValidationError(group_id, [{
                    "code": "semantic_repair_scope",
                    "message": "失败修改越过了原修改锚点所在的正式段，已拒绝扩大返修范围",
                }])
            for index, (before_part, rejected_part, manifest_segment) in enumerate(
                zip(before_parts, rejected_parts, manifest.segments, strict=True), 1,
            ):
                if before_part == rejected_part:
                    continue
                segment_contract = self._manifest_segment_contract(
                    project, manifest, source_integrity, manifest_segment,
                    before_part, index,
                )
                affected_segments.append({
                    "segment": index,
                    "contract": asdict(segment_contract),
                    "accepted_before": before_part,
                    "rejected_candidate": rejected_part,
                })
        if not affected_segments:
            for index in sorted(authorized_segments):
                if index < 1 or index > len(manifest.segments):
                    continue
                before_part = before_parts[index - 1]
                segment_contract = self._manifest_segment_contract(
                    project, manifest, source_integrity,
                    manifest.segments[index - 1], before_part, index,
                )
                affected_segments.append({
                    "segment": index,
                    "contract": asdict(segment_contract),
                    "accepted_before": before_part,
                    "rejected_candidate": before_part,
                })
        if not affected_segments:
            raise DraftSemanticValidationError(group_id, [{
                "code": "semantic_repair_scope",
                "message": "无法把失败修改绑定到唯一正式段，已拒绝扩大返修范围",
            }])
        authorized_segments = {
            int(item["segment"]) for item in affected_segments
        }
        latest_error = initial_error
        for attempt, mode in enumerate((
            "minimal_atomic_patch", "rewrite_affected_formal_segment",
        ), 1):
            request = {
                "schema": "targeted-atomic-semantic-repair-v1",
                "group_id": group_id,
                "candidate_hash": self._text_hash(candidate_before),
                "issue": issue,
                "repair_attempt": attempt,
                "repair_mode": mode,
                "semantic_failures": latest_error.issues,
                "rejected_patch_group": rejected_patch_group,
                "affected_segments": affected_segments,
                "instructions": (
                    "只返回一个 JSON 修改合同，并且只能处理当前 group_id 和 issue_id。"
                    "修改必须相对于 candidate_hash 对应的验收前候选稿；不得修改其他正式段，"
                    "不得增加或提前消费后续原子节拍。优先做最小补丁；当 repair_mode 要求"
                    "重写正式段时，可以完整替换 affected_segments 中的当前段，但必须保留"
                    "入口状态、出口状态、人物执行者、视角和全部已拥有节拍。"
                ),
            }
            try:
                raw = await self._stage(
                    run_id, run_path, project, "revision_plan", constraints,
                    json.dumps(request, ensure_ascii=False),
                    suffix=f"-repair-{group_id}-atomic-{attempt}",
                    allow_tools=False,
                    output_source_characters=sum(
                        len(item["accepted_before"])
                        for item in affected_segments
                    ) or len(str(issue.get("evidence") or "")),
                    targeted_retry=True,
                )
                value = normalize_repair_contract(
                    self._convert_generated_object(
                        raw, run_path, contract_name="revision_plan",
                    ), candidate_before, {group_id},
                )
                if len(value["groups"]) != 1:
                    raise ValueError("语义返修必须一次只返回一个修改组")
                repaired_group = value["groups"][0]
                if (
                    repaired_group.get("group_id") != group_id
                    or repaired_group.get("issue_ids") != [group_id]
                    or repaired_group.get("kind") != "semantic"
                ):
                    raise ValueError("语义返修返回了未授权的修改组")
                if attempt == 1:
                    original_anchors = [
                        str(item.get("old_text") or "")
                        for item in rejected_patch_group.get("patches", [])
                        if isinstance(item, dict) and item.get("old_text")
                    ]
                    if any(
                        not any(
                            anchor == str(item.get("old_text") or "")
                            or anchor in str(item.get("old_text") or "")
                            for anchor in original_anchors
                        )
                        for item in repaired_group.get("patches", [])
                        if isinstance(item, dict)
                    ):
                        raise ValueError(
                            "最小语义返修越过了原修改锚点"
                        )
                repaired_result = {
                    "group_id": group_id,
                    **apply_patch_group(
                        candidate_before, repaired_group,
                        self._text_hash(candidate_before),
                    ),
                }
                if repaired_result.get("accepted") is not True:
                    raise ValueError("语义返修补丁未通过原子应用检查")
                repaired_integrity = await self._verify_atomic_candidate_semantics(
                    run_id, run_path, project, constraints,
                    str(contract["semantic_authority"].get("source_text") or ""),
                    repaired_result["text"], semantic_authority,
                    suffix=f"-repair-{group_id}-atomic-{attempt}",
                    failure_stage="repair_groups", verify_whole=False,
                )
                all_changed_segments = {
                    int(index)
                    for index in repaired_integrity.get("changed_segments", [])
                }
                repaired_parts = self._candidate_segments_from_clean_source(
                    candidate_before, repaired_result["text"], before_parts,
                )
                changed_segments = {
                    index
                    for index, (before_part, repaired_part) in enumerate(
                        zip(before_parts, repaired_parts, strict=True), 1,
                    )
                    if before_part != repaired_part
                }
                if (
                    not changed_segments
                    or not changed_segments.issubset(authorized_segments)
                ):
                    raise ValueError(
                        "语义返修越过了当前修改组授权的正式段范围"
                    )
                quality_blockers = []
                for index in sorted(changed_segments):
                    quality_assessment = assess_polish_candidate(
                        before_parts[index - 1], repaired_parts[index - 1],
                        minimum_ratio=0.60, maximum_ratio=1.60,
                    )
                    quality_blockers.extend(
                        quality_assessment.get("hard_reasons") or []
                    )
                    quality_blockers.extend(
                        reason
                        for reason in quality_assessment.get("reasons", [])
                        if "regression" in str(reason)
                    )
                quality_blockers.extend(validate_locked_facts(
                    candidate_before, repaired_result["text"],
                    contract["story_state"]["data"],
                ))
                passage_validation = validate_passage_protections(
                    candidate_before, repaired_result["text"],
                    contract["passage_locks"],
                )
                quality_blockers.extend(
                    item.get("message") or item.get("id") or "passage_lock"
                    for item in passage_validation.get("conflicts", [])
                )
                if quality_blockers:
                    raise DraftSemanticValidationError(group_id, [{
                        "code": "semantic_repair_quality",
                        "message": (
                            "语义返修造成文笔、篇幅、锁定事实或保护片段回退"
                        ),
                        "blocking_reasons": list(dict.fromkeys(
                            str(reason) for reason in quality_blockers
                        )),
                    }])
            except asyncio.CancelledError:
                raise
            except DraftSemanticValidationError as exc:
                latest_error = exc
                continue
            except (json.JSONDecodeError, TypeError, ValueError) as exc:
                latest_error = DraftSemanticValidationError(group_id, [{
                    "code": "semantic_repair_contract",
                    "message": str(exc),
                }])
                continue
            self.db.add_run_event(
                run_id, "success", "short_revision_semantic_repaired",
                "当前修改组已按原子节拍错误证据完成自动修正",
                stage="repair_groups", metadata={
                    "group_id": group_id,
                    "attempt": attempt,
                    "mode": mode,
                    "changed_segments": sorted(changed_segments),
                    "candidate_changed_segments": sorted(all_changed_segments),
                },
            )
            return repaired_group, repaired_result, repaired_integrity
        raise latest_error

    async def _repair_polish_semantic_segment(
        self,
        run_id: str,
        run_path: Path,
        project: Project,
        constraints: str,
        contract: DraftTaskContract,
        accepted_source: str,
        rejected_candidate: str,
        outside_beat_ids: list[str],
        initial_error: DraftSemanticValidationError,
        *,
        suffix: str,
    ) -> tuple[str, dict] | None:
        latest_error = initial_error
        for attempt, mode in enumerate((
            "minimal_prose_repair", "rewrite_complete_formal_segment",
        ), 1):
            prompt = (
                "ATOMIC_SEMANTIC_PROSE_REPAIR. Return revised prose only. Do not explain. "
                "Repair only the current formal segment. Preserve its useful dialogue, detail, "
                "voice, pacing, and length unless they directly cause a listed failure. Never add "
                "a prohibited future beat or rewrite another segment. The result must satisfy the "
                "exact actor/action ownership, viewpoint, entry state, exit state, and causal order.\n\n"
                f"REPAIR MODE: {mode}\n"
                f"TASK CONTRACT: {json.dumps(asdict(contract), ensure_ascii=False)}\n"
                f"SEMANTIC FAILURES: {json.dumps(latest_error.issues, ensure_ascii=False)}\n"
                f"ACCEPTED SOURCE SEGMENT:\n{accepted_source}\n\n"
                f"REJECTED POLISH CANDIDATE:\n{rejected_candidate}"
            )
            try:
                repaired = str(await self._stage(
                    run_id, run_path, project, "polish", constraints, prompt,
                    suffix=f"{suffix}-semantic-repair-{attempt}",
                    allow_tools=False,
                    output_source_characters=len(accepted_source),
                    targeted_retry=True,
                )).strip()
                if (
                    not repaired
                    or self.SHORT_SEGMENT_SEPARATOR.strip() in repaired
                    or effective_han_characters(repaired)
                    < max(1, math.floor(effective_han_characters(accepted_source) * 0.60))
                    or effective_han_characters(repaired)
                    > math.ceil(effective_han_characters(accepted_source) * 1.60)
                ):
                    raise DraftSemanticValidationError(contract.task_id, [{
                        "code": "semantic_repair_shape",
                        "message": "语义修复结果为空、改变分段边界或篇幅失真",
                    }])
                receipt = await self._verify_draft_semantic_node(
                    run_id, run_path, project, constraints, contract, repaired,
                    outside_beat_ids,
                    suffix=f"{suffix}-semantic-repair-{attempt}",
                    failure_stage="polish",
                )
                quality_assessment = assess_polish_candidate(
                    accepted_source, repaired,
                    minimum_ratio=0.60, maximum_ratio=1.60,
                )
                quality_blockers = list(
                    quality_assessment.get("hard_reasons") or []
                )
                quality_blockers.extend(
                    reason
                    for reason in quality_assessment.get("reasons", [])
                    if "regression" in str(reason)
                )
                locked_failures = validate_locked_facts(
                    accepted_source, repaired,
                    self.story_states.ensure(project.id, project.path).data,
                )
                passage_validation = validate_passage_protections(
                    accepted_source, repaired,
                    applicable_passage_locks(
                        self.db.list_locks(project.id), accepted_source,
                    ),
                )
                quality_blockers.extend(locked_failures)
                quality_blockers.extend(
                    item.get("message") or item.get("id") or "passage_lock"
                    for item in passage_validation.get("conflicts", [])
                )
                if quality_blockers:
                    raise DraftSemanticValidationError(contract.task_id, [{
                        "code": "semantic_repair_quality",
                        "message": "语义修复造成文笔、锁定事实或保护片段质量回退",
                        "blocking_reasons": list(dict.fromkeys(quality_blockers)),
                    }])
            except asyncio.CancelledError:
                raise
            except DraftSemanticValidationError as exc:
                latest_error = exc
                continue
            except Exception as exc:
                self.db.add_run_event(
                    run_id, "warning", "polish_semantic_repair_unavailable",
                    "语义修复模型本轮不可用，已保留验收前原段",
                    stage="polish", metadata={
                        "task_id": contract.task_id,
                        "attempt": attempt,
                        "failure_class": classify_model_failure(exc),
                    },
                )
                return None
            self.db.add_run_event(
                run_id, "success", "polish_semantic_repaired",
                "润色段已按原子节拍错误证据完成自动修正",
                stage="polish", metadata={
                    "task_id": contract.task_id,
                    "attempt": attempt,
                    "mode": mode,
                },
            )
            return repaired, receipt
        self.db.add_run_event(
            run_id, "warning", "polish_semantic_repair_exhausted",
            "当前正式段两次语义修复仍未通过，已恢复验收前原段",
            stage="polish", metadata={
                "task_id": contract.task_id,
                "issues": latest_error.issues,
            },
        )
        return None

    async def _verify_draft_semantic_node(
        self,
        run_id: str,
        run_path: Path,
        project: Project,
        constraints: str,
        contract: DraftTaskContract,
        prose: str,
        outside_event_ids: list[str],
        *,
        suffix: str,
        failure_stage: str = "draft",
    ) -> dict:
        prose_sha256 = hashlib.sha256(prose.encode("utf-8")).hexdigest()
        atomic = bool(contract.beat_ids)
        owned_label = "beat" if atomic else "event"
        prompt = (
            "DRAFT_SEMANTIC_VALIDATION. Independently verify the immutable prose against its task "
            "contract. Do not rewrite or score. Return one JSON object with authority_sha256, "
            "execution_manifest_sha256, task_id, prose_sha256, "
            + (
                "beat_receipts (one per owned atomic beat in exact order, each with beat_id, "
                "evidence, actor_action_valid, actor_action_evidence, state_valid, state_evidence, "
                "scene_order_valid, and scene_order_evidence), outside_beat_ids, future_beat_ids, "
                "viewpoint_valid, viewpoint_evidence, "
                if atomic else
                "event_receipts (one per owned event in exact order, each with event_id and an "
                "exact prose evidence excerpt), outside_event_ids, "
            )
            + "entry and exit objects (satisfied=true and exact prose evidence), "
            "causal_order_valid, causal_order_evidence, and summary. Every evidence field must be "
            "copied exactly from PROSE. Actor/action identity must match the contract actor, not a "
            "different character performing a similar action. State validation covers location, "
            "time, knowledge, and boundary state. If a "
            "requirement is absent, report it honestly; never infer success from the contract text.\n\n"
            f"AUTHORITY SHA256: {contract.authority_sha256}\n"
            f"TASK CONTRACT: {json.dumps(contract.__dict__, ensure_ascii=False)}\n"
            f"OTHER TASK {owned_label.upper()} IDS: {json.dumps(outside_event_ids)}\n"
            f"PROSE SHA256: {prose_sha256}\n"
            f"PROSE:\n{prose}"
        )
        protocol_codes = {
            "invalid_receipt", "authority_hash", "task_identity", "manifest_hash",
            "prose_hash", "beat_receipt_schema", "event_receipt_schema",
            "beat_coverage", "event_coverage", "beat_evidence", "event_evidence",
            "actor_action_evidence", "state_continuity_evidence",
            "scene_order_evidence", "entry_evidence", "exit_evidence",
            "viewpoint_evidence", "causal_order_evidence", "missing_summary",
        }
        raw_receipt: dict = {}
        receipt_issues: list[dict] = []
        for receipt_attempt in range(2):
            attempt_prompt = prompt
            if receipt_issues:
                attempt_prompt += (
                    "\n\nRECEIPT PROTOCOL ISSUES. The prose is immutable; correct only the "
                    "JSON verdict and exact evidence bindings:\n"
                    + json.dumps(receipt_issues, ensure_ascii=False, indent=2)
                )
            raw = await self._stage(
                run_id, run_path, project, "review", constraints, attempt_prompt,
                suffix=f"{suffix}-semantic"
                + ("-receipt-retry" if receipt_attempt else ""),
                allow_tools=False,
                expected_output_characters=max(
                    800, len(contract.beat_ids or contract.event_ids) * 320,
                ),
                route_capacity_guard=True,
                story_skeleton_override=self._stage_story_skeleton(
                    project, constraints, run_path,
                    owner_event_ids=list(contract.event_ids), index_only=True,
                ),
                bounded_protocol_output=True,
                compact_input=True,
            )
            try:
                raw_receipt = self._convert_generated_object(
                    raw, run_path, contract_name="draft_semantic_receipt",
                )
            except (json.JSONDecodeError, ValueError) as exc:
                receipt_issues = [{
                    "code": "invalid_receipt", "message": str(exc),
                }]
            else:
                raw_receipt, evidence_repairs = align_semantic_receipt_evidence(
                    contract, prose, raw_receipt,
                )
                if evidence_repairs:
                    self.db.add_run_event(
                        run_id, "success", "semantic_receipt_evidence_aligned",
                        "语义审核中的非连续引文已安全对齐到唯一原文片段",
                        stage=failure_stage, metadata={
                            "task_id": contract.task_id,
                            "prose_sha256": prose_sha256,
                            "repair_count": len(evidence_repairs),
                            "repaired_paths": evidence_repairs,
                        },
                    )
                receipt_issues = semantic_receipt_issues(
                    contract, prose, raw_receipt,
                )
                if not receipt_issues:
                    return validate_semantic_receipt(contract, prose, raw_receipt)
            if receipt_attempt == 0 and all(
                item.get("code") in protocol_codes for item in receipt_issues
            ):
                self.db.add_run_event(
                    run_id, "info", "semantic_receipt_protocol_retry",
                    "语义审核回执格式或哈希不完整，正在保持正文不变并重试审核回执",
                    stage=failure_stage, metadata={
                        "task_id": contract.task_id,
                        "issues": receipt_issues,
                    },
                )
                continue
            break
        if receipt_issues:
            event_type = {
                "draft": "draft_semantic_gate_failed",
                "polish": "polish_semantic_gate_failed",
                "repair_groups": "short_revision_semantic_gate_failed",
            }.get(failure_stage, "semantic_gate_failed")
            message = {
                "draft": "正文事件、入口或出口缺少可核对原文证据，将完整重写当前范围",
                "polish": "润色结果改变了原子节拍、状态、顺序或视角，正在定向修复当前正式段",
                "repair_groups": "定向返修改变了原子节拍、状态、顺序或视角，正在重做当前修改组",
            }.get(failure_stage, "候选正文未通过原子节拍语义复核")
            self.db.add_run_event(
                run_id, "warning", event_type, message,
                stage=failure_stage, metadata={
                    "task_id": contract.task_id,
                    "event_ids": list(contract.event_ids),
                    "beat_ids": list(contract.beat_ids),
                    "prose_sha256": prose_sha256,
                    "error": "；".join(
                        str(item.get("message") or item.get("code"))
                        for item in receipt_issues
                    ),
                    "issues": receipt_issues,
                },
            )
            raise DraftSemanticValidationError(contract.task_id, receipt_issues)
        return validate_semantic_receipt(contract, prose, raw_receipt)

    async def _verify_whole_draft_semantics(
        self,
        run_id: str,
        run_path: Path,
        project: Project,
        constraints: str,
        authority_sha256: str,
        draft: str,
        segments: list[str],
        expected_event_ids: list[str],
        segment_receipts: list[dict],
        *,
        failure_stage: str = "draft",
    ) -> dict:
        draft_sha256 = hashlib.sha256(draft.encode("utf-8")).hexdigest()
        segment_sha256 = [
            hashlib.sha256(segment.encode("utf-8")).hexdigest() for segment in segments
        ]
        evidence_packet = []
        receipt_sha256: list[str] = []
        for index, receipt in enumerate(segment_receipts, 1):
            receipt_sha256.append(canonical_sha256(receipt))
            compact_beats = [
                {
                    "beat_id": item.get("beat_id"),
                    "evidence": item.get("evidence"),
                }
                for item in receipt.get("beat_receipts", [])
                if isinstance(item, dict)
            ]
            compact_events = [
                {
                    "event_id": item.get("event_id"),
                    "evidence": item.get("evidence"),
                }
                for item in receipt.get("event_receipts", [])
                if isinstance(item, dict)
            ]
            evidence_packet.append({
                "segment": index,
                "prose_sha256": receipt.get("prose_sha256"),
                "semantic_receipt_sha256": receipt_sha256[-1],
                "beat_receipts": compact_beats,
                "event_receipts": compact_events,
                "entry": receipt.get("entry"),
                "exit": receipt.get("exit"),
                "causal_order_evidence": receipt.get("causal_order_evidence"),
                "summary": receipt.get("summary"),
            })
        whole_authority_index = json.dumps({
            "schema": "whole-semantic-authority-index-v1",
            "authority_sha256": authority_sha256,
            "draft_sha256": draft_sha256,
            "segment_sha256": segment_sha256,
            "semantic_receipt_sha256": receipt_sha256,
            "event_ids": expected_event_ids,
        }, ensure_ascii=False, separators=(",", ":"))
        prompt = (
            "DRAFT_WHOLE_SEMANTIC_VALIDATION. Independently adjudicate the ordered, hash-bound "
            "segment evidence as one complete story. Do not rewrite or score. Return one JSON object "
            "with authority_sha256, draft_sha256, segment_sha256, event_ids, missing_event_ids, "
            "duplicate_event_ids, out_of_order_event_ids, causal_order_valid, continuity_valid, "
            "ending_valid, commitments_valid, evidence (exact excerpts already present in the draft), "
            "and summary. Do not claim success when any transition, causal step, promise, climax, or "
            "ending cannot be proven by the ordered evidence.\n\n"
            f"AUTHORITY SHA256: {authority_sha256}\n"
            f"DRAFT SHA256: {draft_sha256}\n"
            f"SEGMENT SHA256: {json.dumps(segment_sha256)}\n"
            f"EXPECTED EVENT IDS: {json.dumps(expected_event_ids)}\n"
            f"ORDERED SEGMENT EVIDENCE: {json.dumps(evidence_packet, ensure_ascii=False)}\n"
            f"OPENING EXCERPT: {draft[:1200]}\n"
            f"ENDING EXCERPT: {draft[-1600:]}"
        )
        protocol_codes = {
            "receipt_schema", "authority_hash", "draft_hash", "segment_manifest",
            "event_manifest", "evidence_schema", "evidence_unbound",
            "missing_summary",
        }
        receipt_issues: list[dict] = []
        last_error = "whole draft receipt is invalid"
        for receipt_attempt in range(2):
            attempt_prompt = prompt
            if receipt_issues:
                attempt_prompt += (
                    "\n\nWHOLE RECEIPT PROTOCOL ISSUES. The draft and ordered evidence are "
                    "immutable; correct only the JSON verdict, hashes, manifests, and exact "
                    "evidence excerpts:\n"
                    + json.dumps(receipt_issues, ensure_ascii=False, indent=2)
                )
            raw = await self._stage(
                run_id, run_path, project, "review", constraints, attempt_prompt,
                suffix="-draft-whole-semantic"
                + ("-receipt-retry" if receipt_attempt else ""),
                allow_tools=False,
                expected_output_characters=max(
                    1200, 900 + len(expected_event_ids) * 48,
                ),
                route_capacity_guard=True,
                capacity_splitter=lambda details: (
                    self._verify_whole_draft_semantics_capacity_split(
                        run_id, run_path, project, constraints,
                        authority_sha256, draft, segments,
                        expected_event_ids, evidence_packet,
                        whole_authority_index, details=details,
                        failure_stage=failure_stage,
                    )
                ),
                story_skeleton_override=whole_authority_index,
                bounded_protocol_output=True,
                compact_input=True,
            )
            try:
                raw_receipt = self._convert_generated_object(
                    raw, run_path, contract_name="draft_semantic_receipt",
                )
            except (json.JSONDecodeError, ValueError) as exc:
                receipt_issues = [{
                    "code": "receipt_schema", "message": str(exc),
                }]
            else:
                raw_receipt, evidence_repairs = (
                    align_whole_draft_receipt_evidence(
                        authority_sha256, draft, segments,
                        expected_event_ids, raw_receipt,
                    )
                )
                if evidence_repairs:
                    self.db.add_run_event(
                        run_id, "success",
                        "whole_semantic_receipt_evidence_aligned",
                        "整篇审核中的非连续引文已安全对齐到唯一正文片段",
                        stage=failure_stage, metadata={
                            "draft_sha256": draft_sha256,
                            "repair_count": len(evidence_repairs),
                            "repaired_paths": evidence_repairs,
                        },
                    )
                receipt_issues = whole_draft_receipt_issues(
                    authority_sha256, draft, segments, expected_event_ids,
                    raw_receipt,
                )
                if not receipt_issues:
                    return validate_whole_draft_receipt(
                        authority_sha256, draft, segments, expected_event_ids,
                        raw_receipt,
                    )
            last_error = "；".join(
                str(item.get("message") or item.get("code"))
                for item in receipt_issues
            )
            if receipt_attempt == 0 and all(
                item.get("code") in protocol_codes for item in receipt_issues
            ):
                self.db.add_run_event(
                    run_id, "info", "whole_semantic_receipt_protocol_retry",
                    "整篇语义审核回执格式、哈希或证据绑定不完整，正在保持正文不变并重试回执",
                    stage=failure_stage, metadata={
                        "draft_sha256": draft_sha256,
                        "issues": receipt_issues,
                    },
                )
                continue
            break
        if receipt_issues:
            event_type = {
                "draft": "draft_whole_semantic_gate_failed",
                "polish": "polish_whole_semantic_gate_failed",
                "repair_groups": "short_revision_whole_semantic_gate_failed",
            }.get(failure_stage, "whole_semantic_gate_failed")
            message = {
                "draft": "正文整篇因果、连续性或结局证据未通过核对，已停止进入精修",
                "polish": "润色合并稿未通过整篇因果和连续性核对，未进入质量晋升",
                "repair_groups": "定向返修合并稿未通过整篇因果和连续性核对，未调用终审",
            }.get(failure_stage, "候选稿未通过整篇语义完整性核对")
            self.db.add_run_event(
                run_id, "error", event_type, message,
                stage=failure_stage, metadata={
                    "draft_sha256": draft_sha256,
                    "event_count": len(expected_event_ids),
                    "error": last_error,
                    "issues": receipt_issues,
                },
            )
            raise ValueError(f"整篇语义完整性检查未通过：{last_error}")
        raise ValueError("整篇语义完整性检查未通过：审核回执为空")

    async def _verify_whole_draft_semantics_capacity_split(
        self,
        run_id: str,
        run_path: Path,
        project: Project,
        constraints: str,
        authority_sha256: str,
        draft: str,
        segments: list[str],
        expected_event_ids: list[str],
        evidence_packet: list[dict],
        whole_authority_index: str,
        *,
        details: dict,
        failure_stage: str,
    ) -> str:
        """Map adjacent semantic boundaries, then reduce one global verdict."""

        draft_sha256 = hashlib.sha256(draft.encode("utf-8")).hexdigest()
        segment_sha256 = [
            hashlib.sha256(segment.encode("utf-8")).hexdigest()
            for segment in segments
        ]

        def packet_event_ids(packet: dict) -> list[str]:
            return [
                str(item.get("beat_id") or item.get("event_id") or "")
                for field in ("beat_receipts", "event_receipts")
                for item in packet.get(field, [])
                if isinstance(item, dict)
                and str(item.get("beat_id") or item.get("event_id") or "")
            ]

        windows = (
            [(0, 0)] if len(evidence_packet) == 1 else
            [(index, index + 1) for index in range(len(evidence_packet) - 1)]
        )
        window_receipts: list[dict] = []
        protocol_codes = {
            "receipt_schema", "authority_hash", "draft_hash",
            "segment_manifest", "event_manifest", "evidence_schema",
            "evidence_unbound", "missing_summary",
        }
        for start, end in windows:
            packets = evidence_packet[start:end + 1]
            window_event_ids = [
                event_id for packet in packets
                for event_id in packet_event_ids(packet)
            ]
            expected_segments = list(range(start + 1, end + 2))
            expected_hashes = segment_sha256[start:end + 1]
            owns_ending = end == len(evidence_packet) - 1
            prompt = (
                "DRAFT_WHOLE_SEMANTIC_WINDOW_V1. Review only this ordered adjacent "
                "evidence window. Do not rewrite or score. Return one JSON object with "
                "authority_sha256, draft_sha256, segment_numbers, segment_sha256, "
                "event_ids, missing_event_ids, duplicate_event_ids, "
                "out_of_order_event_ids, causal_order_valid, continuity_valid, "
                "commitment_flow_valid, ending_valid, evidence (exact excerpts already "
                "present in the immutable draft), and summary. ending_valid means the "
                "window does not falsely close the story; when owns_ending is true it "
                "must also prove the confirmed ending.\n\n"
                f"AUTHORITY SHA256: {authority_sha256}\n"
                f"DRAFT SHA256: {draft_sha256}\n"
                f"SEGMENT NUMBERS: {json.dumps(expected_segments)}\n"
                f"SEGMENT SHA256: {json.dumps(expected_hashes)}\n"
                f"EVENT IDS: {json.dumps(window_event_ids)}\n"
                f"OWNS ENDING: {json.dumps(owns_ending)}\n"
                "ORDERED WINDOW EVIDENCE: "
                + json.dumps(packets, ensure_ascii=False)
            )
            issues: list[dict] = []
            window_receipt: dict = {}
            for attempt in range(2):
                attempt_prompt = prompt
                if issues:
                    attempt_prompt += (
                        "\n\nWINDOW RECEIPT PROTOCOL ISSUES. Keep the immutable "
                        "evidence unchanged and correct only the receipt:\n"
                        + json.dumps(issues, ensure_ascii=False)
                    )
                raw = await self._stage(
                    run_id, run_path, project, "review", constraints,
                    attempt_prompt,
                    suffix=(
                        f"-draft-whole-window-{start + 1:02d}-{end + 1:02d}"
                        + ("-receipt-retry" if attempt else "")
                    ),
                    allow_tools=False,
                    expected_output_characters=max(
                        900, 700 + len(window_event_ids) * 40,
                    ),
                    route_capacity_guard=True,
                    story_skeleton_override=json.dumps({
                        "schema": "whole-semantic-window-authority-v1",
                        "authority_sha256": authority_sha256,
                        "draft_sha256": draft_sha256,
                        "segment_numbers": expected_segments,
                        "segment_sha256": expected_hashes,
                        "event_ids": window_event_ids,
                    }, separators=(",", ":")),
                    bounded_protocol_output=True,
                    compact_input=True,
                )
                try:
                    window_receipt = self._convert_generated_object(
                        raw, run_path, contract_name="draft_semantic_receipt",
                    )
                except (json.JSONDecodeError, ValueError) as exc:
                    issues = [{"code": "receipt_schema", "message": str(exc)}]
                else:
                    evidence = window_receipt.get("evidence")
                    if isinstance(evidence, list):
                        for item in evidence:
                            if not isinstance(item, dict):
                                continue
                            excerpt = str(item.get("excerpt") or "").strip()
                            if excerpt and excerpt not in draft:
                                rebound = align_unique_evidence_span(draft, excerpt)
                                if rebound:
                                    item["excerpt"] = rebound
                    issues = []

                    def issue(code: str, message: str) -> None:
                        issues.append({"code": code, "message": message})

                    if window_receipt.get("authority_sha256") != authority_sha256:
                        issue("authority_hash", "window authority hash is stale")
                    if window_receipt.get("draft_sha256") != draft_sha256:
                        issue("draft_hash", "window draft hash is stale")
                    if window_receipt.get("segment_numbers") != expected_segments:
                        issue("segment_manifest", "window segment order is incomplete")
                    if window_receipt.get("segment_sha256") != expected_hashes:
                        issue("segment_manifest", "window segment hashes are incomplete")
                    if window_receipt.get("event_ids") != window_event_ids:
                        issue("event_manifest", "window event order is incomplete")
                    for field in (
                        "missing_event_ids", "duplicate_event_ids",
                        "out_of_order_event_ids",
                    ):
                        if window_receipt.get(field) != []:
                            issue(field, f"window {field} is not empty")
                    for field in (
                        "causal_order_valid", "continuity_valid",
                        "commitment_flow_valid", "ending_valid",
                    ):
                        if window_receipt.get(field) is not True:
                            issue(field, f"window {field} is not satisfied")
                    evidence = window_receipt.get("evidence")
                    if not isinstance(evidence, list) or not evidence:
                        issue("evidence_schema", "window evidence is missing")
                    else:
                        for item in evidence:
                            excerpt = (
                                str(item.get("excerpt") or "").strip()
                                if isinstance(item, dict) else ""
                            )
                            if not excerpt or excerpt not in draft:
                                issue(
                                    "evidence_unbound",
                                    "window evidence is not bound to draft",
                                )
                    if not str(window_receipt.get("summary") or "").strip():
                        issue("missing_summary", "window summary is missing")
                    if not issues:
                        break
                if attempt == 0 and all(
                    item.get("code") in protocol_codes for item in issues
                ):
                    continue
                break
            if issues:
                raise DraftSemanticValidationError(
                    f"whole-window-{start + 1}-{end + 1}", issues,
                )
            window_receipts.append(window_receipt)
            self.db.add_run_event(
                run_id, "success", "whole_semantic_window_ready",
                "整篇语义分包窗口已通过相邻因果与状态核对",
                stage=failure_stage, metadata={
                    "segment_numbers": expected_segments,
                    "event_count": len(window_event_ids),
                    "receipt_sha256": canonical_sha256(window_receipt),
                },
            )

        reducer_prompt = (
            "DRAFT_WHOLE_SEMANTIC_REDUCE_V1. Reduce the ordered, independently "
            "validated adjacent-window receipts into one whole-story verdict. Do not "
            "rewrite or score. Return one JSON object with authority_sha256, "
            "draft_sha256, segment_sha256, event_ids, missing_event_ids, "
            "duplicate_event_ids, out_of_order_event_ids, causal_order_valid, "
            "continuity_valid, ending_valid, commitments_valid, evidence (exact "
            "excerpts already present in the immutable draft), and summary. Never "
            "turn a negative window verdict into success.\n\n"
            f"WHOLE AUTHORITY INDEX: {whole_authority_index}\n"
            "ORDERED WINDOW RECEIPTS: "
            + json.dumps(window_receipts, ensure_ascii=False)
            + f"\nOPENING EXCERPT: {draft[:1200]}"
            + f"\nENDING EXCERPT: {draft[-1600:]}"
        )
        reducer_issues: list[dict] = []
        for attempt in range(2):
            attempt_prompt = reducer_prompt
            if reducer_issues:
                attempt_prompt += (
                    "\n\nREDUCER RECEIPT PROTOCOL ISSUES. Correct only the receipt:\n"
                    + json.dumps(reducer_issues, ensure_ascii=False)
                )
            raw = await self._stage(
                run_id, run_path, project, "review", constraints,
                attempt_prompt,
                suffix="-draft-whole-semantic-reducer"
                + ("-receipt-retry" if attempt else ""),
                allow_tools=False,
                expected_output_characters=max(
                    1200, 900 + len(expected_event_ids) * 48,
                ),
                route_capacity_guard=True,
                story_skeleton_override=whole_authority_index,
                bounded_protocol_output=True,
                compact_input=True,
            )
            try:
                receipt = self._convert_generated_object(
                    raw, run_path, contract_name="draft_semantic_receipt",
                )
            except (json.JSONDecodeError, ValueError) as exc:
                reducer_issues = [{
                    "code": "receipt_schema", "message": str(exc),
                }]
            else:
                receipt, _repairs = align_whole_draft_receipt_evidence(
                    authority_sha256, draft, segments,
                    expected_event_ids, receipt,
                )
                reducer_issues = whole_draft_receipt_issues(
                    authority_sha256, draft, segments,
                    expected_event_ids, receipt,
                )
                if not reducer_issues:
                    validated = validate_whole_draft_receipt(
                        authority_sha256, draft, segments,
                        expected_event_ids, receipt,
                    )
                    self.db.add_run_event(
                        run_id, "success", "whole_semantic_capacity_reduced",
                        "整篇语义窗口已归并为完整、哈希绑定的全局回执",
                        stage=failure_stage, metadata={
                            "trigger": details.get("trigger"),
                            "window_count": len(window_receipts),
                            "draft_sha256": draft_sha256,
                        },
                    )
                    return json.dumps(validated, ensure_ascii=False)
            if attempt == 0 and all(
                item.get("code") in protocol_codes
                for item in reducer_issues
            ):
                continue
            break
        raise DraftSemanticValidationError("whole-reducer", reducer_issues)

    async def _draft_short_in_segments(self, run_id: str, run_path: Path, project: Project,
                                        constraints: str, plan: str) -> str:
        target_words = int(project.metadata["target_words"])
        count = self._short_segment_count(target_words)
        target = math.ceil(target_words / count)
        segment_plans = self._short_plan_segments(plan, count)
        if len(segment_plans) != count:
            raise ValueError("规划稿没有明确每一段负责的事件，尚未生成正文")
        manifest_path = run_path / "outputs" / "short-execution-index.json"
        try:
            execution_manifest = parse_execution_manifest(json.loads(
                manifest_path.read_text(encoding="utf-8"),
            ))
        except (OSError, UnicodeError, json.JSONDecodeError, TypeError, ValueError) as exc:
            raise ValueError("正文开始前缺少有效的原子节拍执行索引") from exc
        if (
            execution_manifest.status != "ready"
            or len(execution_manifest.segments) != count
        ):
            raise ValueError("原子节拍执行索引尚未就绪或分段数量不一致")
        execution_manifest_hash = execution_manifest_sha256(execution_manifest)
        manifest_segments = {
            item.segment: item for item in execution_manifest.segments
        }
        beat_by_id = {item.beat_id: item for item in execution_manifest.beats}
        authoritative_state = self.story_states.ensure(project.id, project.path).data
        story_state_sha256 = hashlib.sha256(json.dumps(
            authoritative_state, ensure_ascii=False, sort_keys=True, default=str,
        ).encode("utf-8")).hexdigest()
        location_catalog = build_location_catalog(project.path, authoritative_state)
        ownership = "\n".join(
            f"第 {index} 段：{next((line.lstrip('# ').strip() for line in block.splitlines() if line.strip()), '未命名')}"
            for index, block in enumerate(segment_plans, 1)
        )
        legacy_authority_payload = {
            "plan": plan,
            "constraints": constraints,
            "target_words": target_words,
            "segment_count": count,
        }
        authority_payload = {
            **legacy_authority_payload,
            "story_state_sha256": story_state_sha256,
            "execution_manifest_sha256": execution_manifest_hash,
        }
        authority_hash = hashlib.sha256(json.dumps({
            **authority_payload,
            "location_catalog": sorted(
                (alias, ref.name, ref.root)
                for alias, ref in location_catalog.items()
            ),
        }, ensure_ascii=False, sort_keys=True).encode("utf-8")).hexdigest()
        compatible_authority_hashes = {authority_hash}
        checkpoint_root = run_path / "outputs" / "draft-checkpoints"
        parts: list[str] = []
        event_assignments: list[dict] = []
        all_expected_event_ids = [
            beat_id
            for segment_number in range(1, count + 1)
            for beat_id in manifest_segments[segment_number].beat_ids
        ]
        segment_semantic_receipts: list[dict] = []
        for index in range(1, count + 1):
            self.db.add_run_event(
                run_id, "info", "segment_started", f"开始生成正文第 {index}/{count} 段",
                stage="draft", metadata={"segment": index, "total": count, "target_words": target},
            )
            previous_tail = parts[-1][-1200:] if parts else "这是开篇，无上一段。"
            previous_plan_tail = (
                self._short_plan_handoff(segment_plans[index - 2])
                if index > 1 else "这是开篇，无上一段交接状态。"
            )
            checkpoint_path = checkpoint_root / f"segment-{index:02d}.json"
            previous_hash = (
                hashlib.sha256(parts[-1].encode("utf-8")).hexdigest() if parts else ""
            )
            try:
                checkpoint = json.loads(checkpoint_path.read_text(encoding="utf-8"))
            except (OSError, json.JSONDecodeError, AttributeError):
                checkpoint = {}
            cached_part = str(checkpoint.get("text") or "")
            cached_assignment = checkpoint.get("assignment") or {}
            manifest_segment = manifest_segments[index]
            expected_event_ids = list(manifest_segment.beat_ids)
            source_event_ids = list(dict.fromkeys(
                beat_by_id[beat_id].source_event_id for beat_id in expected_event_ids
            ))
            expected_handoff = "；".join(
                assertion.state for assertion in manifest_segment.exit_state
            )
            expected_entry = "；".join(
                assertion.state for assertion in manifest_segment.entry_state
            )
            prompt = (
                f"整篇分工：\n{ownership}\n\n"
                "正文必须服从正式规划、设定与因果链。不得提前写后续分段的事件，也不得重写前面已经发生的场景。"
                "人物、地点、因果和结局均以正式设定为准。开头必须承接上一段结束时的人物位置、动作、"
                "关系和知情状态；如果当前任务需要换时间或换场景，开头必须用自然过渡交代清楚。\n\n"
                "本段原子节拍契约：\n"
                + json.dumps(asdict(manifest_segment), ensure_ascii=False, indent=2)
            )
            root_contract = DraftTaskContract(
                authority_sha256=authority_hash,
                task_id=f"segment-{index:02d}",
                parent_task_id="",
                depth=0,
                target_han=target,
                event_ids=tuple(source_event_ids),
                scope=(
                    f"本次只写第 {index}/{count} 段，唯一负责的原子节拍：\n"
                    + "\n".join(
                        f"{beat_id}：{beat_by_id[beat_id].action}"
                        for beat_id in expected_event_ids
                    )
                    + "\n\n已验收规划分段：\n" + segment_plans[index - 1]
                ),
                entry_state=(
                    f"执行索引入口状态：\n{expected_entry}\n\n"
                    f"上一段计划交接：\n{previous_plan_tail}\n\n"
                    f"上一段正文结尾：\n{previous_tail}"
                ),
                exit_requirement=expected_handoff,
                execution_manifest_sha256=execution_manifest_hash,
                beat_ids=tuple(expected_event_ids),
                **_draft_narrative_contract_fields(project),
                prohibited_future_beat_ids=manifest_segment.prohibited_future_beat_ids,
            )
            cache_structurally_valid = (
                checkpoint.get("version") == 3
                and checkpoint.get("authority_sha256") in compatible_authority_hashes
                and checkpoint.get("execution_manifest_sha256")
                == execution_manifest_hash
                and checkpoint.get("previous_sha256") == previous_hash
                and checkpoint.get("segment_plan_sha256") == hashlib.sha256(
                    segment_plans[index - 1].encode("utf-8")
                ).hexdigest()
                and checkpoint.get("text_sha256")
                == hashlib.sha256(cached_part.encode("utf-8")).hexdigest()
                and cached_assignment.get("segment") == index
                and cached_assignment.get("event_ids") == expected_event_ids
                and cached_assignment.get("source_event_ids") == source_event_ids
                and cached_assignment.get("handoff") == expected_handoff
                and cached_part
                and not self._draft_segment_issues(
                    cached_part, target, parts, location_catalog,
                )
            )
            cached_semantic_receipt = None
            if cache_structurally_valid and expected_event_ids:
                try:
                    cached_semantic_receipt = validate_semantic_receipt(
                        root_contract, cached_part, checkpoint.get("semantic_receipt"),
                    )
                except ValueError:
                    cached_semantic_receipt = await self._verify_draft_semantic_node(
                        run_id, run_path, project, constraints, root_contract,
                        cached_part,
                        [
                            event_id for event_id in all_expected_event_ids
                            if event_id not in expected_event_ids
                        ],
                        suffix=f"-part-{index:02d}-checkpoint",
                    )
                    checkpoint = {
                        **checkpoint,
                        "version": 3,
                        "semantic_receipt": cached_semantic_receipt,
                    }
                    atomic_write(
                        checkpoint_path,
                        json.dumps(checkpoint, ensure_ascii=False, indent=2),
                    )
            if cache_structurally_valid:
                parts.append(cached_part)
                assignment = {
                    **cached_assignment,
                    **({"semantic_receipt": cached_semantic_receipt}
                       if cached_semantic_receipt else {}),
                }
                event_assignments.append(assignment)
                if cached_semantic_receipt:
                    segment_semantic_receipts.append(cached_semantic_receipt)
                atomic_write(
                    run_path / "outputs" / "segment-events.json",
                    json.dumps({"segments": event_assignments}, ensure_ascii=False, indent=2),
                )
                self.db.add_run_event(
                    run_id, "success", "draft_checkpoint_reused",
                    f"正文第 {index}/{count} 段已从内部检查点恢复",
                    stage="draft", metadata={"segment": index, "total": count},
                )
                continue
            semantic_receipt_nodes: list[tuple[DraftTaskContract, dict]] = []
            part = await self._draft_short_segment_task(
                run_id, run_path, project, constraints, prompt,
                suffix=f"-part-{index:02d}", target=target,
                previous_parts=parts, event_ids=expected_event_ids,
                location_catalog=location_catalog, contract=root_contract,
                semantic_all_event_ids=(
                    all_expected_event_ids if expected_event_ids else None
                ),
                semantic_receipt_sink=semantic_receipt_nodes,
            )
            issues = (
                self._draft_segment_issues(part, target, parts, location_catalog)
                if count > 1 else []
            )
            if issues:
                self.db.add_run_event(
                    run_id, "error", "draft_segment_gate_failed",
                    f"正文第 {index}/{count} 段未通过契约内检查，已停止后续生成",
                    stage="draft", metadata={"segment": index, "issues": issues},
                )
                raise ValueError(
                    f"正文第 {index} 段未通过本地检查，已有进度已保留"
                )
            verified_nodes = [receipt for _contract, receipt in semantic_receipt_nodes]
            root_semantic_receipt = None
            if expected_event_ids:
                for node_contract, receipt in semantic_receipt_nodes:
                    if node_contract.task_id == root_contract.task_id:
                        root_semantic_receipt = receipt
                if root_semantic_receipt is None:
                    raise ValueError(
                        f"正文第 {index} 段缺少父级语义验收回执"
                    )
                segment_semantic_receipts.append(root_semantic_receipt)
            warnings = [
                finding for finding in self._draft_segment_findings(
                    part, target, parts, location_catalog,
                ) if not finding.get("blocking")
            ]
            if warnings:
                self.db.add_run_event(
                    run_id, "warning", "draft_segment_continuity_warning",
                    f"正文第 {index}/{count} 段存在无法确定的场景衔接，已记录但不会单独阻断",
                    stage="draft", metadata={
                        "segment": index,
                        "issues": warnings,
                    },
                )
            parts.append(part.strip())
            assignment = {
                "segment": index,
                "event_ids": expected_event_ids,
                "source_event_ids": source_event_ids,
                "handoff": expected_handoff,
                **({
                    "semantic_receipt": root_semantic_receipt,
                    "semantic_node_receipts": verified_nodes,
                } if root_semantic_receipt else {}),
            }
            event_assignments.append(assignment)
            atomic_write(checkpoint_path, json.dumps({
                "version": 3,
                "authority_sha256": authority_hash,
                "execution_manifest_sha256": execution_manifest_hash,
                "previous_sha256": previous_hash,
                "segment_plan_sha256": hashlib.sha256(
                    segment_plans[index - 1].encode("utf-8")
                ).hexdigest(),
                "text_sha256": hashlib.sha256(part.strip().encode("utf-8")).hexdigest(),
                "text": part.strip(),
                "assignment": assignment,
                **({"semantic_receipt": root_semantic_receipt}
                   if root_semantic_receipt else {}),
            }, ensure_ascii=False, indent=2))
            atomic_write(
                run_path / "outputs" / "segment-events.json",
                json.dumps({"segments": event_assignments}, ensure_ascii=False, indent=2),
            )
            self.db.add_run_event(
                run_id, "success", "segment_completed", f"正文第 {index}/{count} 段生成完成",
                stage="draft", metadata={
                    "segment": index, "total": count, "characters": len(part),
                    "event_ids": assignment["event_ids"], "handoff": assignment["handoff"],
                },
            )
        draft = self.SHORT_SEGMENT_SEPARATOR.join(parts)
        expected_event_ids = all_expected_event_ids
        whole_semantic_receipt = None
        if expected_event_ids:
            if len(segment_semantic_receipts) != len(parts):
                raise ValueError("正文分段缺少完整语义验收回执")
            whole_semantic_receipt = await self._verify_whole_draft_semantics(
                run_id, run_path, project, constraints, authority_hash,
                draft, parts, expected_event_ids, segment_semantic_receipts,
            )
            accepted_event_ids = [
                str(event.get("beat_id") or event.get("event_id") or "")
                for receipt in segment_semantic_receipts
                for event in (
                    receipt.get("beat_receipts")
                    or receipt.get("event_receipts", [])
                )
            ]
        else:
            accepted_event_ids = [
                event_id
                for assignment in event_assignments
                for event_id in assignment.get("event_ids", [])
            ]
        integrity_issues = []
        current_story_state_sha256 = hashlib.sha256(json.dumps(
            self.story_states.ensure(project.id, project.path).data,
            ensure_ascii=False, sort_keys=True, default=str,
        ).encode("utf-8")).hexdigest()
        if current_story_state_sha256 != story_state_sha256:
            integrity_issues.append("正文生成期间权威 StoryState 已变化")
        if len(parts) != count or len(event_assignments) != count:
            integrity_issues.append("正文段数量与正式分工不一致")
        if accepted_event_ids != expected_event_ids:
            integrity_issues.append("正文事件覆盖发生遗漏、重复或顺序变化")
        for segment_index, part in enumerate(parts):
            segment_issues = [
                str(finding["message"])
                for finding in self._draft_segment_findings(
                    part, target, parts[:segment_index], location_catalog,
                )
                if finding.get("blocking") and finding.get("code") != "underlength"
            ]
            if segment_issues:
                integrity_issues.append(
                    f"第 {segment_index + 1} 段未通过整段复核：" + "；".join(segment_issues)
                )
        segment_receipts = []
        previous_segment_hash = ""
        for segment_index, (part, assignment) in enumerate(
            zip(parts, event_assignments), 1,
        ):
            text_hash = hashlib.sha256(part.encode("utf-8")).hexdigest()
            segment_receipts.append({
                "segment": segment_index,
                "event_ids": list(assignment.get("event_ids", [])),
                "handoff": str(assignment.get("handoff") or ""),
                "han_characters": effective_han_characters(part),
                "previous_sha256": previous_segment_hash,
                "text_sha256": text_hash,
            })
            previous_segment_hash = text_hash
        integrity = {
            "version": 3,
            "status": "failed" if integrity_issues else "passed",
            "authority_sha256": authority_hash,
            "execution_manifest_sha256": execution_manifest_hash,
            "plan_sha256": hashlib.sha256(plan.encode("utf-8")).hexdigest(),
            "constraints_sha256": hashlib.sha256(constraints.encode("utf-8")).hexdigest(),
            "base_constraints_sha256": hashlib.sha256(
                constraints.split("\n\n# Short Story Causal Chain\n\n", 1)[0].encode(
                    "utf-8",
                ),
            ).hexdigest(),
            "story_state_sha256": story_state_sha256,
            "draft_sha256": hashlib.sha256(draft.encode("utf-8")).hexdigest(),
            "expected_event_ids": expected_event_ids,
            "accepted_event_ids": accepted_event_ids,
            "segments": segment_receipts,
            "semantic_segment_receipts": segment_semantic_receipts,
            "whole_semantic_receipt": whole_semantic_receipt,
            "issues": integrity_issues,
        }
        atomic_write(
            run_path / "outputs" / "draft-integrity.json",
            json.dumps(integrity, ensure_ascii=False, indent=2),
        )
        if integrity_issues:
            self.db.add_run_event(
                run_id, "error", "draft_integrity_failed",
                "正文整段与整篇核验未通过，已停止进入后续流程",
                stage="draft", metadata={"issues": integrity_issues},
            )
            raise ValueError("正文整篇完整性检查未通过：" + "；".join(integrity_issues))
        atomic_write(run_path / "outputs" / "draft.md", draft)
        self.db.add_run_event(
            run_id, "success", "draft_integrity_passed",
            "正文全部分段、正式事件与衔接哈希已通过整篇核验",
            stage="draft", metadata={
                "segments": len(parts), "event_count": len(accepted_event_ids),
                "draft_sha256": integrity["draft_sha256"],
            },
        )
        return draft

    async def _draft_short_segment_task(
        self, run_id: str, run_path: Path, project: Project, constraints: str,
        prompt: str, *, suffix: str, target: int, previous_parts: list[str],
        event_ids: list[str] | None = None,
        location_catalog: dict[str, LocationRef] | None = None,
        depth: int = 0,
        contract: DraftTaskContract | None = None,
        retry_count: int = 0,
        node_sink: list[tuple[DraftTaskContract, str]] | None = None,
        semantic_all_event_ids: list[str] | None = None,
        semantic_receipt_sink: list[tuple[DraftTaskContract, dict]] | None = None,
    ) -> str:
        """Generate one owned segment and split when one response cannot own it."""
        owned_event_ids = list(event_ids or [])
        node_sink_start = len(node_sink) if node_sink is not None else 0
        semantic_sink_start = (
            len(semantic_receipt_sink)
            if semantic_receipt_sink is not None else 0
        )
        if contract is None:
            authority_hash = hashlib.sha256(prompt.encode("utf-8")).hexdigest()
            contract = DraftTaskContract(
                authority_sha256=authority_hash,
                task_id=suffix.lstrip("-") or "draft-segment",
                parent_task_id="",
                depth=depth,
                target_han=target,
                event_ids=tuple(owned_event_ids),
                scope=(
                    "完成当前写作段正式事件：" + "、".join(owned_event_ids)
                    if owned_event_ids else "完成当前写作段的入口、冲突推进与段末交接"
                ),
                entry_state=(
                    previous_parts[-1][-1200:] if previous_parts else "正文开篇，无前置正文"
                ),
                exit_requirement="完成本段状态变化，不提前写后续写作段事件",
                **_draft_narrative_contract_fields(project),
            )
        elif (
            contract.target_han != target
            or list(contract.beat_ids or contract.event_ids) != owned_event_ids
        ):
            raise ValueError("正文子任务参数与执行契约不一致")
        rendered_prompt = render_draft_task_prompt(prompt, contract)

        async def accept_node(value: str) -> str:
            narrative_issues = first_person_prose_issues(contract, str(value))
            if narrative_issues:
                raise DraftSemanticValidationError(contract.task_id, narrative_issues)
            semantic_receipt = None
            if semantic_all_event_ids is not None and contract.event_ids:
                owned_semantic_ids = set(contract.beat_ids or contract.event_ids)
                semantic_receipt = await self._verify_draft_semantic_node(
                    run_id, run_path, project, constraints, contract, str(value),
                    [
                        event_id for event_id in semantic_all_event_ids
                        if event_id not in owned_semantic_ids
                    ],
                    suffix=f"{suffix}-{contract.task_id.replace('/', '-')}",
                )
            if node_sink is not None:
                node_sink.append((contract, str(value)))
            if semantic_receipt_sink is not None and semantic_receipt is not None:
                semantic_receipt_sink.append((contract, semantic_receipt))
            return value

        async def retry_same_scope(findings: list[dict]) -> str:
            if retry_count >= 2:
                semantic = any(
                    item.get("semantic") is True
                    or item.get("code") == "semantic_contract_failed"
                    for item in findings
                )
                if semantic:
                    self.db.add_run_event(
                        run_id, "error", "draft_semantic_rewrite_exhausted",
                        "当前正文范围完整重写两次后仍缺少语义证据，已保留上游合格分段并停止",
                        stage="draft", metadata={
                            "task_id": contract.task_id,
                            "beat_ids": list(contract.beat_ids),
                            "issues": findings,
                        },
                    )
                raise ValueError(
                    (
                        "正文语义完整性检查在同一事件范围自动重写两次后仍未通过："
                        if semantic else
                        "正文子任务在同一事件范围重试后仍未通过检查："
                    )
                    + "；".join(str(item.get("message") or item.get("code")) for item in findings)
                )
            if node_sink is not None:
                del node_sink[node_sink_start:]
            if semantic_receipt_sink is not None:
                del semantic_receipt_sink[semantic_sink_start:]
            self.db.add_run_event(
                run_id, "warning", "draft_task_scope_retry",
                "正文子任务未通过叶子检查，正在保持事件范围重新生成",
                stage="draft", metadata={
                    "suffix": suffix, "depth": depth,
                    "target_characters": target,
                    "target_range": list(target_bounds(target)),
                    "event_ids": owned_event_ids,
                    "issue_codes": [str(item.get("code") or "incomplete") for item in findings],
                },
            )
            retry_contract = DraftTaskContract(
                authority_sha256=contract.authority_sha256,
                task_id=contract.task_id,
                parent_task_id=contract.parent_task_id,
                depth=contract.depth,
                target_han=contract.target_han,
                event_ids=contract.event_ids,
                scope=contract.scope,
                entry_state=contract.entry_state,
                exit_requirement=(
                    contract.exit_requirement
                    + "；修正上次检查问题："
                    + "；".join(str(item.get("message") or item.get("code")) for item in findings)
                ),
                previous_sibling_sha256=contract.previous_sibling_sha256,
                execution_manifest_sha256=contract.execution_manifest_sha256,
                beat_ids=contract.beat_ids,
                viewpoint=contract.viewpoint,
                narrative_mode=contract.narrative_mode,
                narrator_character_id=contract.narrator_character_id,
                narrator_name=contract.narrator_name,
                self_reference=contract.self_reference,
                prohibited_future_beat_ids=contract.prohibited_future_beat_ids,
            )
            retried = await self._draft_short_segment_task(
                run_id, run_path, project, constraints, prompt,
                suffix=f"{suffix}-scope-retry", target=target,
                previous_parts=previous_parts, event_ids=owned_event_ids,
                location_catalog=location_catalog, depth=depth,
                contract=retry_contract, retry_count=retry_count + 1,
                node_sink=node_sink,
                semantic_all_event_ids=semantic_all_event_ids,
                semantic_receipt_sink=semantic_receipt_sink,
            )
            return retried

        async def accept_or_retry(value: str) -> str:
            try:
                return await accept_node(value)
            except DraftSemanticValidationError as exc:
                return await retry_same_scope([
                    {**item, "semantic": True} for item in exc.issues
                ])

        reason = "output_limit"
        han_characters = 0
        try:
            part = await self._stage(
                run_id, run_path, project, "draft", constraints, rendered_prompt,
                suffix=suffix, allow_tools=False,
                expected_output_characters=target,
                completion_check=lambda value: not self._draft_segment_issues(
                    value, target, previous_parts, location_catalog,
                ),
            )
        except IncompleteModelOutputError as exc:
            han_characters = effective_han_characters(str(exc.partial))
            if depth >= 2 or target < 800 or len(owned_event_ids) < 2:
                if retry_count < 1:
                    return await retry_same_scope([{
                        "code": "output_limit",
                        "message": "供应商未完整返回当前事件范围",
                    }])
                raise
        else:
            receipt = getattr(part, "receipt", {})
            finish_reason = normalize_finish_reason(
                receipt.get("finish_reason") if isinstance(receipt, dict) else None
            )
            findings = [
                finding for finding in self._draft_segment_findings(
                    part, target, previous_parts, location_catalog,
                ) if finding.get("blocking")
            ]
            if not findings:
                try:
                    return await accept_node(part)
                except DraftSemanticValidationError as exc:
                    return await retry_same_scope([
                        {**item, "semantic": True} for item in exc.issues
                    ])
            underlength = next((
                finding for finding in findings if finding.get("code") == "underlength"
            ), None)
            if any(finding.get("code") != "underlength" for finding in findings):
                return await retry_same_scope(findings)
            if finish_reason not in {"stop", "end_turn", "completed", "complete"}:
                return await retry_same_scope([{
                    **underlength,
                    "code": "unknown_terminal_underlength",
                    "message": "供应商没有提供可确认完整结束的状态，不能验收偏短正文",
                }])
            # Han-count recovery is meaningful only after the response proves it
            # contains Chinese prose. Other-language projects keep using their
            # normal prose/quality gates instead of being split on a zero metric.
            han_characters = int(underlength.get("han_characters") or 0)
            if han_characters <= 0:
                return await accept_or_retry(part)
            if depth >= 2 or target < 800 or len(owned_event_ids) < 2:
                return await retry_same_scope(findings)
            reason = "normal_finish_underlength"
        split_at = max(1, math.ceil(len(owned_event_ids) / 2))
        first_event_ids = owned_event_ids[:split_at]
        second_event_ids = owned_event_ids[split_at:]
        if owned_event_ids and not exact_event_partition(
            tuple(owned_event_ids), tuple(first_event_ids), tuple(second_event_ids),
        ):
            return await retry_same_scope([{
                "code": "indivisible_event_scope",
                "message": "当前正式事件不能无损拆成两个连续范围",
            }])

        def source_events(values: list[str]) -> tuple[str, ...]:
            return tuple(dict.fromkeys(value.split("/", 1)[0] for value in values))

        def child_scope(values: list[str], label: str) -> str:
            action_lines = [
                line.strip()
                for line in contract.scope.splitlines()
                if any(beat_id in line for beat_id in values)
            ]
            return label + "\n" + "\n".join(
                action_lines or [f"{beat_id}：仅执行该原子节拍" for beat_id in values]
            )

        child_authority = prompt.split("\n\n本段原子节拍契约：", 1)[0].rstrip() + (
            "\n\n当前为自动拆分后的原子子任务；CURRENT_TASK_CONTRACT 是唯一可执行范围。"
            "父任务只提供不可变故事背景，不授权执行父任务其余节拍。"
        )

        self.db.add_run_event(
            run_id, "warning", "draft_task_split",
            (
                "正文正常结束但篇幅不足，已按本段事件和因果推进自动拆分"
                if reason == "normal_finish_underlength"
                else "单次正文子任务无法完整返回，已按本段事件和因果推进自动拆分"
            ),
            stage="draft", metadata={
                "suffix": suffix, "depth": depth + 1, "target_characters": target,
                "target_range": list(target_bounds(target)),
                "subtasks": 2, "reason": reason,
                "han_characters": han_characters,
                "issue_codes": [
                    "underlength" if reason == "normal_finish_underlength"
                    else "output_limit"
                ],
                "event_ids": owned_event_ids,
            },
        )
        first_target = max(400, target // 2)
        first_contract = DraftTaskContract(
            authority_sha256=contract.authority_sha256,
            task_id=f"{contract.task_id}/sub-1",
            parent_task_id=contract.task_id,
            depth=depth + 1,
            target_han=first_target,
            event_ids=source_events(first_event_ids),
            scope=child_scope(first_event_ids, "内部子任务 1/2：只完成以下节拍"),
            entry_state=contract.entry_state,
            exit_requirement="在当前事件范围结束处留下自然交接，不总结且不进入第二子任务事件",
            execution_manifest_sha256=contract.execution_manifest_sha256,
            beat_ids=tuple(first_event_ids) if contract.beat_ids else (),
            viewpoint=contract.viewpoint,
            narrative_mode=contract.narrative_mode,
            narrator_character_id=contract.narrator_character_id,
            narrator_name=contract.narrator_name,
            self_reference=contract.self_reference,
            prohibited_future_beat_ids=tuple(dict.fromkeys([
                *second_event_ids, *contract.prohibited_future_beat_ids,
            ])) if contract.beat_ids else (),
        )
        first = await self._draft_short_segment_task(
            run_id, run_path, project, constraints,
            child_authority,
            suffix=f"{suffix}-sub-1", target=first_target,
            previous_parts=previous_parts, event_ids=first_event_ids,
            location_catalog=location_catalog, depth=depth + 1,
            contract=first_contract, node_sink=node_sink,
            semantic_all_event_ids=semantic_all_event_ids,
            semantic_receipt_sink=semantic_receipt_sink,
        )
        first_han = effective_han_characters(first)
        second_target = residual_target(target, first_han)
        first_hash = hashlib.sha256(first.strip().encode("utf-8")).hexdigest()
        second_contract = DraftTaskContract(
            authority_sha256=contract.authority_sha256,
            task_id=f"{contract.task_id}/sub-2",
            parent_task_id=contract.task_id,
            depth=depth + 1,
            target_han=second_target,
            event_ids=source_events(second_event_ids),
            scope=child_scope(second_event_ids, "内部子任务 2/2：只完成以下节拍并抵达父段出口"),
            entry_state=(
                f"承接已验收前半，内容哈希 {first_hash}。前半结尾：\n{first[-1200:]}"
            ),
            exit_requirement=contract.exit_requirement,
            previous_sibling_sha256=first_hash,
            execution_manifest_sha256=contract.execution_manifest_sha256,
            beat_ids=tuple(second_event_ids) if contract.beat_ids else (),
            viewpoint=contract.viewpoint,
            narrative_mode=contract.narrative_mode,
            narrator_character_id=contract.narrator_character_id,
            narrator_name=contract.narrator_name,
            self_reference=contract.self_reference,
            prohibited_future_beat_ids=contract.prohibited_future_beat_ids,
        )
        second = await self._draft_short_segment_task(
            run_id, run_path, project, constraints,
            child_authority,
            suffix=f"{suffix}-sub-2", target=second_target,
            previous_parts=[*previous_parts, first], event_ids=second_event_ids,
            location_catalog=location_catalog, depth=depth + 1,
            contract=second_contract, node_sink=node_sink,
            semantic_all_event_ids=semantic_all_event_ids,
            semantic_receipt_sink=semantic_receipt_sink,
        )
        combined = f"{first.strip()}\n\n{second.strip()}"
        remaining = self._draft_segment_issues(
            combined, target, previous_parts, location_catalog,
        )
        if remaining:
            return await retry_same_scope([{
                "code": "split_parent_contract_failed",
                "message": str(item),
            } for item in remaining])
        self.db.add_run_event(
            run_id, "success", "draft_task_split_completed",
            "自动拆分后的两个正文子任务已通过父段完整性与衔接检查",
            stage="draft", metadata={
                "suffix": suffix,
                "parent_task_id": contract.task_id,
                "authority_sha256": contract.authority_sha256,
                "child_targets": [first_target, second_target],
                "child_event_ids": [first_event_ids, second_event_ids],
                "child_sha256": [
                    hashlib.sha256(first.strip().encode("utf-8")).hexdigest(),
                    hashlib.sha256(second.strip().encode("utf-8")).hexdigest(),
                ],
                "combined_sha256": hashlib.sha256(combined.encode("utf-8")).hexdigest(),
            },
        )
        return await accept_or_retry(combined)

    async def _polish_short_segments(self, run_id: str, run_path: Path, project: Project,
                                     constraints: str, text: str, findings: str,
                                     suffix: str = "", structural: bool = False,
                                     recovery_depth: int = 0,
                                     recovery_rule: str | None = None,
                                     prepared_revision_plan: dict | None = None,
                                     round_cap_override: int | None = None,
                                     batch_number: int = 1,
                                     targeted_context: dict | None = None) -> str:
        original_parts = self._split_segments(text)
        execution_manifest = None
        source_draft_integrity: dict = {}
        try:
            candidate_manifest = parse_execution_manifest(json.loads(
                (run_path / "outputs" / "short-execution-index.json").read_text(
                    encoding="utf-8",
                ),
            ))
            source_draft_integrity = json.loads(
                (run_path / "outputs" / "draft-integrity.json").read_text(
                    encoding="utf-8",
                )
            )
        except (OSError, UnicodeError, json.JSONDecodeError, TypeError, ValueError):
            candidate_manifest = None
            source_draft_integrity = {}
        if (
            candidate_manifest is not None
            and candidate_manifest.status == "ready"
            and not execution_manifest_receipt_binding_issues(candidate_manifest)
            and len(candidate_manifest.segments) == len(original_parts)
            and source_draft_integrity.get("status") == "passed"
            and source_draft_integrity.get("execution_manifest_sha256")
            == execution_manifest_sha256(candidate_manifest)
            and source_draft_integrity.get("draft_sha256")
            == hashlib.sha256(text.encode("utf-8")).hexdigest()
        ):
            execution_manifest = candidate_manifest

        def boundary_paragraph(segment: str, *, first: bool) -> str:
            paragraphs = [item.strip() for item in re.split(r"\n\s*\n", segment) if item.strip()]
            return (paragraphs[0] if first else paragraphs[-1]) if paragraphs else ""

        targeted = bool(structural or targeted_context)
        grouped_parts = (
            [(part, group) for group, part in enumerate(original_parts, 1)]
            if targeted else [
                (part, group)
                for group, original in enumerate(original_parts, 1)
                for part in self._split_polish_segments(original)
            ]
        )
        parts = [item[0] for item in grouped_parts]
        part_groups = [item[1] for item in grouped_parts]
        part_spans = self._polish_part_spans(text, parts)
        narrative_ledger = (
            self._analyze_manuscript(
                text, run_path, project, f"polish-source{suffix}",
            ).get("narrative_ledger", {})
            if recovery_depth == 0 else build_narrative_ledger(text)
        )
        revision_plan = None
        compacted_findings: dict | None = None
        event_path = run_path / "outputs" / "segment-events.json"
        try:
            event_assignments = json.loads(event_path.read_text(encoding="utf-8")).get(
                "segments", [],
            )
        except (OSError, json.JSONDecodeError, AttributeError):
            event_assignments = []
        story_map = segment_map(original_parts, event_assignments=event_assignments)
        authoritative_state = self.story_states.ensure(project.id, project.path).data
        passage_service = PassageProtectionService(self.db)
        project_passage_locks = self.db.list_locks(project.id)
        if structural and targeted_context is None and len(parts) > 1:
            if prepared_revision_plan is None:
                revision_plan = await self._plan_structural_revision(
                    run_id, run_path, project, constraints, findings, story_map, suffix,
                )
                full_plan = {
                    **revision_plan,
                    "tasks": [
                        *revision_plan["tasks"],
                        *revision_plan.get("deferred_tasks", []),
                    ],
                }
                full_plan, target_corrections = align_revision_plan_targets(
                    full_plan, original_parts,
                )
                revision_plan = self._normalized_revision_plan(
                    full_plan, len(story_map), max_target_ratio=0.4,
                    require_checks=bool(full_plan.get("checks")),
                    defer_excess_targets=True,
                )
            else:
                target_corrections = []
                revision_plan = self._normalized_revision_plan(
                    prepared_revision_plan, len(story_map), max_target_ratio=0.4,
                    require_checks=bool(prepared_revision_plan.get("checks")),
                    defer_excess_targets=True,
                )
            if target_corrections:
                atomic_write(
                    run_path / "outputs" / f"revision-plan{suffix}.json",
                    json.dumps(revision_plan, ensure_ascii=False, indent=2),
                )
                self.db.add_run_event(
                    run_id, "warning", "revision_targets_aligned",
                    "Runtime corrected revision targets using exact manuscript search",
                    stage="revision_plan", metadata={"corrections": target_corrections},
                )
        elif not targeted and recovery_rule is None:
            try:
                compacted_findings = compact_polish_findings(json.loads(findings))
                findings = json.dumps(compacted_findings, ensure_ascii=False)
            except (json.JSONDecodeError, TypeError, AttributeError):
                findings = findings[:4000]
        revision_rule = recovery_rule or (
            "You may replace or remove implausible events and reorder material inside this segment "
            "to resolve the findings. Preserve the core premise, required ending, established facts, "
            "and approximate length."
            if targeted else
            "Preserve events and length; remove AI-like phrasing and apply the findings."
        )
        style_profile = ensure_style_profile(project)
        polished_parts: list[str] = []
        accepted_history_metrics: list[dict[str, float]] = []
        prose_policy = load_prose_validation_policy(project.path)
        primary_circuit_open = any(
            event["event_type"] == "polish_circuit_opened"
            for event in self.db.list_run_events(run_id)
        )
        preserved_segments = 0
        binding = self.db.get_role_binding("polish") or {}
        retry_signature = self._polish_retry_signature(binding)
        configured_fallback = bool(
            binding.get("fallback_provider_id") and binding.get("fallback_model_id")
            and hasattr(self.gateway, "complete_configured_fallback")
        )
        checkpoint_root = (
            run_path / "outputs" / "polish-checkpoints" / (suffix.strip("-") or "initial")
        )
        round_input_tokens = 0
        round_cap = (round_cap_override if round_cap_override is not None
                     else self._polish_round_input_cap(targeted, len(parts)))
        previous_handoff_state = ""
        part_authority_hashes: dict[int, str] = {}
        for index, part in enumerate(parts, 1):
            group = part_groups[index - 1]
            if revision_plan and group not in revision_plan["target_segments"]:
                polished_parts.append(part)
                previous_handoff_state = self._polish_exit_state(part)
                continue
            if round_input_tokens >= round_cap:
                self.db.add_run_event(
                    run_id, "error", "token_budget_exhausted",
                    "Polish input token budget exhausted; stopped before the next model call",
                    stage="polish", metadata={
                        "limit": "round",
                        "round_input_tokens": round_input_tokens,
                        "round_cap": round_cap,
                        "next_segment": index,
                    },
                )
                raise PolishTokenBudgetError("Polish round input token budget exhausted")
            previous_tail = polished_parts[-1][-800:] if polished_parts else ""
            next_head = parts[index][:800] if index < len(parts) else ""
            local_report = analyze_prose(part)
            start, end = part_spans[index - 1]
            window_findings = (
                filter_polish_findings_for_segment(compacted_findings, part)
                if compacted_findings is not None else None
            )
            narrative_context = self._polish_narrative_context(
                narrative_ledger, part, start, end, previous_handoff_state,
            )
            passage_locks = applicable_passage_locks(project_passage_locks, part)
            if targeted_context:
                tasks = targeted_context["tasks"]
                linked_checks = targeted_context["checks"]
                global_facts = targeted_context["global_facts"]
                previous_context = (
                    boundary_paragraph(parts[index - 2], first=False) if index > 1
                    else targeted_context["previous_paragraph"]
                )
                next_context = (
                    boundary_paragraph(parts[index], first=True) if index < len(parts)
                    else targeted_context["next_paragraph"]
                )
            elif revision_plan:
                tasks = [task for task in revision_plan["tasks"] if group in task["segments"]]
                task_issue_ids = {
                    issue_id for task in tasks for issue_id in task.get("issue_ids", [])
                }
                linked_checks = [
                    check for check in revision_plan["checks"]
                    if task_issue_ids.intersection(check.get("issue_ids", []))
                ]
                global_facts = revision_plan["global_facts"]
                previous_context = (
                    boundary_paragraph(original_parts[group - 2], first=False) if group > 1 else ""
                )
                next_context = (
                    boundary_paragraph(original_parts[group], first=True)
                    if group < len(original_parts) else ""
                )
            else:
                tasks = []
                linked_checks = []
                global_facts = []
                previous_context = previous_tail
                next_context = next_head
            voice = character_fingerprints(project.path, part)
            positions = list(dict.fromkeys(
                task["seven_step_position"] for task in tasks
                if task.get("seven_step_position")
            ))
            seven_step_position = "；".join(positions) if positions else "未标注"
            current_targeted_context = {
                "tasks": tasks,
                "checks": linked_checks,
                "global_facts": global_facts,
                "previous_paragraph": previous_context,
                "next_paragraph": next_context,
                "seven_step_position": seven_step_position,
                "segment": (targeted_context or {}).get("segment", group),
            }
            findings_for_window = (
                json.dumps(window_findings, ensure_ascii=False)
                if window_findings is not None else findings
            )
            plan_context = (
                f"GLOBAL FACTS AND LOCKS:\n{json.dumps(revision_plan['global_facts'], ensure_ascii=False)}\n\n"
                f"TASKS FOR THIS SEGMENT:\n{json.dumps(tasks, ensure_ascii=False)}\n\n"
                f"DETERMINISTIC CHECKS:\n{json.dumps(revision_plan['checks'], ensure_ascii=False)}\n\n"
                f"COMPACT FULL STORY MAP:\n{json.dumps(story_map, ensure_ascii=False)}\n\n"
                if revision_plan else (
                    f"STRUCTURED FINDINGS FOR THIS WINDOW:\n{findings_for_window}\n\n"
                    f"NARRATIVE STATE FOR THIS WINDOW:\n"
                    f"{json.dumps(narrative_context, ensure_ascii=False)}\n\n"
                )
            )
            preferred_minimum_ratio = 0.60 if targeted else 0.70
            minimum_ratio, maximum_ratio = ((0.50, 1.80) if targeted else (0.70, 1.60))
            minimum_characters = math.floor(len(part) * preferred_minimum_ratio)
            maximum_characters = math.ceil(len(part) * maximum_ratio)
            length_contract = (
                f" Return between {minimum_characters} and {maximum_characters} characters. "
                "Do not repeat adjacent scenes, include analysis, or rewrite material outside "
                "this manuscript segment."
            )
            story_entry = story_map[group - 1] if 0 < group <= len(story_map) else {}
            protected_authority = [{
                "id": lock.get("id"),
                "label": lock.get("label"),
                "mode": lock.get("mode"),
                "allow_next_change": bool(lock.get("allow_next_change")),
            } for lock in passage_locks]
            ending = authoritative_state.get("ending")
            authority_packet = build_polish_authority_packet(
                source=part,
                event_ids=story_entry.get("event_ids", []),
                causal_goal=str(story_entry.get("handoff") or ""),
                previous_exit=previous_handoff_state or previous_context,
                next_entry=next_context,
                character_state={
                    "states": authoritative_state.get("character_states", {}),
                    "voice": voice,
                },
                locked_facts=[
                    *authoritative_state.get("locked_facts", []),
                    *authoritative_state.get("confirmed_facts", []),
                    *global_facts,
                ],
                ending_constraints=[ending] if ending else [],
                narrative_state=narrative_context,
                style_rules=[style_profile],
                protected_passages=protected_authority,
                allowed_scope={
                    "segment": current_targeted_context["segment"],
                    "minimum_characters": minimum_characters,
                    "maximum_characters": maximum_characters,
                    "edit_rule": revision_rule,
                },
            )
            authority_hash = authority_packet_sha256(authority_packet)
            part_authority_hashes[index] = authority_hash
            if targeted and (revision_plan or targeted_context):
                prompt = (
                    f"STYLE PROFILE:\n{style_profile}\n\n"
                    f"RELEVANT CHARACTER VOICES:\n"
                    f"{voice}\n\n"
                    + revision_patch_context(
                        issue={
                            "tasks": tasks,
                            "edit_rule": revision_rule + length_contract,
                        },
                        target_paragraph=part,
                        previous_paragraph=previous_context,
                        next_paragraph=next_context,
                        evidence_summaries=linked_checks,
                        seven_step_position=seven_step_position,
                        authoritative_facts=[
                            *authoritative_state.get("locked_facts", []),
                            *authoritative_state.get("confirmed_facts", []),
                            *global_facts,
                        ],
                        protected_passages=[{
                            "id": lock.get("id"),
                            "label": lock.get("label"),
                            "mode": lock.get("mode"),
                            "allow_next_change": bool(lock.get("allow_next_change")),
                        } for lock in passage_locks],
                        allowed_range={
                            "segment": current_targeted_context["segment"],
                            "minimum_characters": minimum_characters,
                            "maximum_characters": maximum_characters,
                        },
                        word_target=len(part),
                    )
                )
            else:
                prompt = (
                    "POLISH THE CURRENT MANUSCRIPT SEGMENT. Return revised prose only.\n"
                    f"EDIT PERMISSION: {revision_rule + length_contract}\n\n"
                    f"LOCAL PROSE FINDINGS:\n"
                    f"{json.dumps(local_report['findings'], ensure_ascii=False)}\n\n"
                    + plan_context
                    + render_polish_authority_packet(authority_packet)
                )
            compact_prompt = self._compact_polish_prompt(
                authority_packet=authority_packet,
                local_findings=local_report["findings"],
                review_findings=window_findings,
            )
            part_suffix = f"{suffix}-part-{index:02d}"
            cached = self._load_polish_checkpoint(
                checkpoint_root, index, part, retry_signature,
                authority_hash=authority_hash,
            )
            if cached is not None:
                polished_parts.append(cached)
                accepted_history_metrics.append(prose_metrics(cached))
                previous_handoff_state = self._polish_exit_state(cached)
                self.db.add_run_event(
                    run_id, "success", "polish_checkpoint_reused",
                    f"润色第 {index}/{len(parts)} 段已从检查点恢复",
                    stage="polish", metadata={"segment": index, "route": "checkpoint"},
                )
                if not targeted:
                    self.db.add_run_event(
                        run_id, "info", "polish_segment_progress",
                        f"已完成 {index} / {len(parts)} 段，其中 {preserved_segments} 段保留原文",
                        stage="polish", metadata={
                            "segment": index, "total": len(parts),
                            "completed": index, "preserved": preserved_segments,
                        },
                    )
                continue
            priority = bool(targeted or index in {1, len(parts)} or local_report["findings"])
            prefer_configured = bool(
                targeted and configured_fallback
                and (primary_circuit_open or not priority)
            )
            route = (
                "circuit_fallback" if primary_circuit_open and prefer_configured else
                "configured_fallback" if prefer_configured else "primary"
            )
            self.db.add_run_event(
                run_id, "info", "polish_segment_route",
                f"润色第 {index}/{len(parts)} 段路由：{route}",
                stage="polish", metadata={
                    "segment": index, "total": len(parts), "route": route,
                    "priority": priority, "characters": len(part),
                },
            )
            targeted_group_failed = False
            ordinary_preserved = False
            compact_recovery_used = False
            ordinary_input_tokens = 0
            split_recovery_used = False

            async def split_failed_segment(exc: Exception) -> str:
                nonlocal ordinary_preserved, split_recovery_used
                children = self._split_failed_polish_segment(part)
                if recovery_depth >= 2 or children is None:
                    if not targeted:
                        ordinary_preserved = True
                        self.db.add_run_event(
                            run_id, "warning", "polish_capacity_preserved",
                            "当前父段没有可安全拆分的段落边界，已保留原文并继续",
                            stage="polish", metadata={
                                "segment": index, "characters": len(part),
                                "split_depth": recovery_depth,
                                "error": describe_error(exc)[:500],
                                "failure_class": classify_model_failure(exc),
                            },
                        )
                        self.db.add_run_event(
                            run_id, "warning", "polish_segment_preserved",
                            "当前片段无法安全拆分，已保留完整父段并继续",
                            stage="polish", metadata={
                                "segment": index, "failure_kind": classify_model_failure(exc),
                            },
                        )
                        return part
                    raise exc
                self.db.add_run_event(
                    run_id, "warning", "polish_segment_split",
                    "模型输出受限，正在拆分当前片段后重试",
                    stage="polish", metadata={
                        "segment": index, "characters": len(part),
                        "child_characters": [len(child) for child in children],
                        "split_depth": recovery_depth + 1, "failed_route": route,
                        "error": describe_error(exc),
                        "failure_class": classify_model_failure(exc),
                    },
                )
                child_suffix = f"{part_suffix}-split-{recovery_depth + 1}"
                recovered = await self._polish_short_segments(
                    run_id, run_path, project, constraints,
                    self.SHORT_SEGMENT_SEPARATOR.join(children), findings_for_window,
                    suffix=child_suffix,
                    structural=False, recovery_depth=recovery_depth + 1,
                    recovery_rule=revision_rule,
                    targeted_context=current_targeted_context if targeted else None,
                )
                child_checkpoint_root = (
                    run_path / "outputs" / "polish-checkpoints" / child_suffix.strip("-")
                )
                child_checkpoints = []
                for child_index in range(1, len(children) + 1):
                    checkpoint_path = child_checkpoint_root / f"part-{child_index:02d}.json"
                    try:
                        child_checkpoints.append(json.loads(
                            checkpoint_path.read_text(encoding="utf-8")
                        ))
                    except (OSError, json.JSONDecodeError):
                        child_checkpoints.append({})
                if not all(item.get("accepted") is True for item in child_checkpoints):
                    ordinary_preserved = True
                    self.db.add_run_event(
                        run_id, "warning", "polish_split_child_rejected",
                        "拆分后的子段没有全部通过验收，整个父段已保留原文",
                        stage="polish", metadata={
                            "segment": index,
                            "child_statuses": [item.get("status") for item in child_checkpoints],
                        },
                    )
                    return part
                split_recovery_used = True
                return recovered.replace(self.SHORT_SEGMENT_SEPARATOR, "\n\n")

            try:
                if not targeted:
                    (polished_part, ordinary_preserved, compact_recovery_used,
                     _ordinary_fallback_used,
                     ordinary_input_tokens) = await self._ordinary_polish_segment(
                        run_id, run_path, project, constraints, part, prompt,
                        compact_prompt, part_suffix, minimum_characters,
                        maximum_characters, configured_fallback, {
                            "segment": index, "total": len(parts),
                            "completed": index - 1,
                            "preserved": preserved_segments,
                        },
                    )
                else:
                    polished_part = await self._stage(
                        run_id, run_path, project, "polish", constraints, prompt,
                        suffix=part_suffix, allow_tools=False,
                        prefer_configured_fallback=prefer_configured,
                        output_source_characters=len(part),
                        targeted_retry=True,
                    )
                if (targeted
                        and getattr(polished_part, "receipt", {}).get("fallback_used")):
                    primary_circuit_open = True
                    self.db.add_run_event(
                        run_id, "warning", "polish_circuit_opened",
                        "润色主模型已回退成功，本轮后续重点段直接使用配置备用模型",
                        stage="polish", metadata={"segment": index},
                    )
            except asyncio.CancelledError:
                raise
            except TargetedGroupError as exc:
                targeted_group_failed = True
                polished_part = part
                self.db.add_run_event(
                    run_id, "warning", "targeted_group_failed",
                    "当前定向修订片段的首选和备用模型均失败，已保留原文并继续其他片段",
                    stage="polish", metadata={
                        "segment": index, "characters": len(part),
                        "error": describe_error(exc),
                    },
                )
            except Exception as exc:
                failure_kind = classify_model_failure(exc)
                if failure_kind == "provider_rejection":
                    raise
                if failure_kind in {"input_context_overflow", "output_limit"}:
                    polished_part = await split_failed_segment(exc)
                elif failure_kind == "transport_interrupted":
                    ordinary_preserved = True
                    polished_part = part
                    self.db.add_run_event(
                        run_id, "warning", "polish_segment_preserved",
                        "润色路由因网络波动全部失败，已保留当前父段且不拆分正文",
                        stage="polish", metadata={
                            "segment": index, "error": describe_error(exc)[:500],
                        },
                    )
                else:
                    raise
            round_input_tokens += (
                int(getattr(polished_part, "receipt", {}).get("input_tokens", 0) or 0)
                if targeted else ordinary_input_tokens
            )
            required = re.findall(r"(?m)^##\s+(.+)$", voice)
            assessment = assess_polish_candidate(
                part, polished_part, required,
                minimum_ratio=minimum_ratio, maximum_ratio=maximum_ratio,
                policy=prose_policy,
                history_metrics=accepted_history_metrics,
                narrative_context=narrative_context,
            )
            if targeted_group_failed:
                assessment["accepted"] = False
                assessment["reasons"].append("targeted_model_routes_failed")
            if ordinary_preserved:
                assessment["accepted"] = False
                assessment["reasons"].append("model_routes_failed")
            if split_recovery_used:
                _, duplicate_blocks = remove_consecutive_duplicate_blocks(polished_part)
                if duplicate_blocks:
                    assessment["accepted"] = False
                    assessment["hard_reasons"].append("split_parent_duplicate")
                    assessment["reasons"].append("split_parent_duplicate")
            rhythm_reasons = {
                "sentence_rhythm_not_improved",
                "timestamp_scene_fragment_not_improved",
                "dialogue_ping_pong_not_improved",
            }
            if targeted:
                assessment["reasons"] = [
                    reason for reason in assessment["reasons"]
                    if reason not in rhythm_reasons
                ]
                assessment["accepted"] = not assessment["reasons"]
            locked_failures = validate_locked_facts(part, polished_part, authoritative_state)
            if locked_failures:
                assessment["accepted"] = False
                assessment["reasons"].extend(locked_failures)
            passage_validation = validate_passage_protections(
                part, polished_part, passage_locks,
            )
            if passage_validation["conflicts"]:
                assessment["accepted"] = False
                assessment["reasons"].extend(
                    f"passage_protection:{item['id']}"
                    for item in passage_validation["conflicts"]
                )
            if (not assessment["accepted"]
                    and assessment.get("disposition") == "targeted_repair"
                    and not assessment.get("hard_reasons")
                    and not locked_failures and not passage_validation["conflicts"]
                    and not ordinary_preserved and not split_recovery_used):
                signal_codes = {
                    code
                    for signal in assessment.get("soft_signals", [])
                    for code in signal.get("codes", [signal.get("code")])
                    if code
                }
                evidence_findings = [
                    finding for finding in local_report["findings"]
                    if finding.get("code") in signal_codes
                ]
                repair_advisory = {
                    "soft_signals": assessment.get("soft_signals", []),
                    "evidence_findings": evidence_findings,
                    "instruction": (
                        "Edit only the evidenced local spans. Preserve all other wording, "
                        "events, facts, transitions, and length."
                    ),
                }
                repair_prompt = (
                    "TARGETED LOCAL PROSE REPAIR. Return revised prose only. Do not rewrite "
                    "unrelated sentences.\n\n"
                    + render_polish_authority_packet(
                        authority_packet, advisory=repair_advisory,
                    )
                )
                repair_compact_prompt = (
                    "TARGETED LOCAL PROSE REPAIR UNDER INPUT PRESSURE. Return revised prose only.\n\n"
                    + render_polish_authority_packet(
                        authority_packet,
                        advisory={"soft_signals": assessment.get("soft_signals", [])},
                    )
                )
                self.db.add_run_event(
                    run_id, "warning", "polish_targeted_repair",
                    f"润色第 {index}/{len(parts)} 段仅对有证据的局部问题定向修复",
                    stage="polish", metadata={
                        "segment": index,
                        "signal_families": assessment.get("signal_families", []),
                        "signal_codes": sorted(signal_codes),
                        "raw_metrics": {
                            "source": local_report.get("metrics", {}),
                            "candidate": assessment.get("diagnostics", {}).get("metrics", {}),
                        },
                        "baseline": assessment.get("baseline", {}),
                        "policy_source_ids": list(prose_policy.source_ids),
                        "evidence_spans": evidence_findings,
                        "authority_hash": authority_hash,
                    },
                )
                if signal_codes.intersection(rhythm_reasons):
                    self.db.add_run_event(
                        run_id, "warning", "polish_rhythm_retry",
                        f"润色第 {index}/{len(parts)} 段韵律软信号触发局部修复",
                        stage="polish", metadata={
                            "segment": index, "reasons": sorted(
                                signal_codes.intersection(rhythm_reasons)
                            ),
                        },
                    )
                try:
                    (repair_candidate, repair_preserved, repair_compact_used,
                     _repair_fallback_used, repair_input_tokens) = (
                        await self._ordinary_polish_segment(
                            run_id, run_path, project, constraints, part,
                            repair_prompt, repair_compact_prompt,
                            f"{part_suffix}-targeted-repair",
                            minimum_characters, maximum_characters,
                            configured_fallback, {
                                "segment": index, "total": len(parts),
                                "recovery": "targeted_repair",
                            },
                        )
                    )
                    round_input_tokens += repair_input_tokens
                    ordinary_preserved = bool(ordinary_preserved or repair_preserved)
                    compact_recovery_used = bool(
                        compact_recovery_used or repair_compact_used
                    )
                    polished_part = repair_candidate
                except asyncio.CancelledError:
                    raise
                except Exception as exc:
                    failure_kind = classify_model_failure(exc)
                    if failure_kind == "provider_rejection":
                        raise
                    if failure_kind in {"input_context_overflow", "output_limit"}:
                        polished_part = await split_failed_segment(exc)
                    else:
                        ordinary_preserved = True
                        polished_part = part
                assessment = assess_polish_candidate(
                    part, polished_part, required,
                    minimum_ratio=minimum_ratio, maximum_ratio=maximum_ratio,
                    policy=prose_policy,
                    history_metrics=accepted_history_metrics,
                    narrative_context=narrative_context,
                )
                locked_failures = validate_locked_facts(
                    part, polished_part, authoritative_state,
                )
                if locked_failures:
                    assessment["accepted"] = False
                    assessment["reasons"].extend(locked_failures)
                passage_validation = validate_passage_protections(
                    part, polished_part, passage_locks,
                )
                if passage_validation["conflicts"]:
                    assessment["accepted"] = False
                    assessment["reasons"].extend(
                        f"passage_protection:{item['id']}"
                        for item in passage_validation["conflicts"]
                    )
                if ordinary_preserved:
                    assessment["accepted"] = False
                    if "model_routes_failed" not in assessment["reasons"]:
                        assessment["reasons"].append("model_routes_failed")
            if ordinary_preserved:
                assessment["accepted"] = False
                if "model_routes_failed" not in assessment["reasons"]:
                    assessment["reasons"].append("model_routes_failed")
            accepted = bool(assessment["accepted"])
            if accepted and assessment.get("disposition") == "pass_with_style_allowance":
                self.db.add_run_event(
                    run_id, "success", "polish_style_allowance",
                    f"润色第 {index}/{len(parts)} 段按项目文风规则保留局部节奏",
                    stage="polish", metadata={
                        "segment": index,
                        "style_allowances": assessment.get("style_allowances", []),
                        "policy_source_ids": list(prose_policy.source_ids),
                        "raw_metrics": {
                            "source": local_report.get("metrics", {}),
                            "candidate": assessment.get("diagnostics", {}).get("metrics", {}),
                        },
                        "baseline": assessment.get("baseline", {}),
                        "authority_hash": authority_hash,
                    },
                )
            conditional_length = bool(
                accepted and targeted and assessment["ratio"] < preferred_minimum_ratio
            )
            if conditional_length and revision_plan:
                local_check_failures = check_source_local_constraints(
                    part, polished_part, revision_plan,
                )
                if local_check_failures:
                    accepted = False
                    conditional_length = False
                    assessment["accepted"] = False
                    assessment["reasons"].extend(local_check_failures)
            if conditional_length:
                self.db.add_run_event(
                    run_id, "warning", "polish_conditional_length",
                    "Compressed structural candidate accepted conditionally for final review",
                    stage="polish", metadata={
                        "segment": index,
                        "ratio": assessment["ratio"],
                        "preferred_minimum_ratio": preferred_minimum_ratio,
                        "hard_minimum_ratio": minimum_ratio,
                        "review_required": True,
                    },
                )
            if not assessment["accepted"]:
                if split_recovery_used:
                    self.db.add_run_event(
                        run_id, "warning", "polish_split_parent_rejected",
                        "拆分子段合并后未通过父段整体验收，已原子回退为父段原文",
                        stage="polish", metadata={
                            "segment": index, "reasons": assessment["reasons"],
                            "authority_hash": authority_hash,
                        },
                    )
                if passage_validation["conflicts"]:
                    self.db.add_run_event(
                        run_id, "warning", "passage_protection_conflict",
                        "模型修改了受保护片段，已保留原文",
                        stage="polish", metadata={
                            "segment": index,
                            "protection_ids": [
                                item["id"] for item in passage_validation["conflicts"]
                            ],
                            "labels": [
                                item["label"] for item in passage_validation["conflicts"]
                            ],
                        },
                    )
                self.db.add_run_event(
                    run_id, "warning", "polish_output_rejected",
                    f"润色第 {index}/{len(parts)} 段未通过本地验收，已保留原文",
                    stage="polish", metadata={
                        "segment": index,
                        "original_characters": len(part),
                        "candidate_characters": len(polished_part.strip()),
                        "ratio": assessment["ratio"],
                        "minimum_characters": minimum_characters,
                        "maximum_characters": maximum_characters,
                        "candidate_preview": polished_part.strip()[:240],
                        "reasons": assessment["reasons"],
                    },
                )
                polished_part = part
            elif passage_validation["consumed"]:
                passage_service.consume_allowed_changes(
                    project.id, passage_validation["consumed"],
                )
            polished_part = polished_part.strip()
            polished_parts.append(polished_part)
            if accepted:
                accepted_history_metrics.append(prose_metrics(polished_part))
            previous_handoff_state = self._polish_exit_state(polished_part)
            change_evidence = diff_manuscripts(
                part, polished_part,
                analyze_manuscript(part, nlp_analyze=None),
                analyze_manuscript(polished_part, nlp_analyze=None),
            )
            if accepted:
                self._save_polish_checkpoint(
                    checkpoint_root, index, part, polished_part,
                    change_evidence=change_evidence,
                    authority_hash=authority_hash,
                )
            elif not targeted:
                if not ordinary_preserved:
                    self.db.add_run_event(
                        run_id, "warning", "polish_segment_preserved",
                        "本段未完成精修，已保留原文并继续",
                        stage="polish", metadata={
                            "segment": index, "total": len(parts),
                            "completed": index, "preserved": preserved_segments + 1,
                            "reasons": assessment["reasons"],
                        },
                    )
                preserved_segments += 1
                self._save_polish_checkpoint(
                    checkpoint_root, index, part, part,
                    status="preserved_source", retry_signature=retry_signature,
                    accepted=False,
                    change_evidence=change_evidence,
                    authority_hash=authority_hash,
                )
            if not targeted:
                self.db.add_run_event(
                    run_id, "info", "polish_segment_progress",
                    f"已完成 {index} / {len(parts)} 段，其中 {preserved_segments} 段保留原文",
                    stage="polish", metadata={
                        "segment": index, "total": len(parts),
                        "completed": index, "preserved": preserved_segments,
                    },
                )
        restored_groups: list[str] = []
        for group in range(1, len(original_parts) + 1):
            restored_groups.append("\n\n".join(
                part for part, part_group in zip(polished_parts, part_groups)
                if part_group == group
            ))
        polished = self.SHORT_SEGMENT_SEPARATOR.join(restored_groups)
        polished, duplicate_removals = remove_consecutive_duplicate_blocks(polished)
        polished, repairs = normalize_chinese_prose(polished)
        if duplicate_removals:
            repairs.append("consecutive_duplicate_blocks")
        if repairs:
            self.db.add_run_event(
                run_id, "success", "local_format_repair",
                "已在本地修复机械格式问题",
                stage="polish", metadata={"repairs": repairs},
            )
        if execution_manifest is not None:
            candidate_groups = self._split_segments(polished)
            if len(candidate_groups) != len(original_parts):
                candidate_groups = list(original_parts)
                polished = text
                self.db.add_run_event(
                    run_id, "warning", "polish_semantic_gate_failed",
                    "润色结果改变了正式分段边界，已保留验收前原文",
                    stage="polish", metadata={
                        "expected_segments": len(original_parts),
                        "actual_segments": len(self._split_segments(polished)),
                    },
                )
            beat_by_id = {
                beat.beat_id: beat for beat in execution_manifest.beats
            }
            all_beat_ids = [beat.beat_id for beat in execution_manifest.beats]
            source_receipts = source_draft_integrity.get(
                "semantic_segment_receipts",
            )
            source_receipts = (
                source_receipts if isinstance(source_receipts, list) else []
            )
            semantic_receipts: list[dict] = []
            for group, (source_group, candidate_group, manifest_segment) in enumerate(
                zip(original_parts, candidate_groups, execution_manifest.segments), 1,
            ):
                beat_ids = list(manifest_segment.beat_ids)
                contract = DraftTaskContract(
                    authority_sha256=str(
                        source_draft_integrity.get("authority_sha256")
                        or execution_manifest.authority_sha256
                    ),
                    task_id=f"segment-{group:02d}",
                    parent_task_id="",
                    depth=0,
                    target_han=max(1, effective_han_characters(candidate_group)),
                    event_ids=tuple(dict.fromkeys(
                        beat_by_id[beat_id].source_event_id for beat_id in beat_ids
                    )),
                    scope="\n".join(
                        f"{beat_id}：{beat_by_id[beat_id].action}"
                        for beat_id in beat_ids
                    ),
                    entry_state="；".join(
                        item.state for item in manifest_segment.entry_state
                    ),
                    exit_requirement="；".join(
                        item.state for item in manifest_segment.exit_state
                    ),
                    execution_manifest_sha256=execution_manifest_sha256(
                        execution_manifest,
                    ),
                    beat_ids=tuple(beat_ids),
                    **_draft_narrative_contract_fields(project),
                    prohibited_future_beat_ids=(
                        manifest_segment.prohibited_future_beat_ids
                    ),
                )
                receipt = None
                if candidate_group == source_group and group <= len(source_receipts):
                    try:
                        receipt = validate_semantic_receipt(
                            contract, candidate_group, source_receipts[group - 1],
                        )
                    except ValueError:
                        receipt = None
                if receipt is None:
                    try:
                        receipt = await self._verify_draft_semantic_node(
                            run_id, run_path, project, constraints, contract,
                            candidate_group,
                            [beat_id for beat_id in all_beat_ids if beat_id not in beat_ids],
                            suffix=f"{suffix}-polish-segment-{group:02d}",
                            failure_stage="polish",
                        )
                    except DraftSemanticValidationError as exc:
                        outside_beat_ids = [
                            beat_id for beat_id in all_beat_ids
                            if beat_id not in beat_ids
                        ]
                        repaired = await self._repair_polish_semantic_segment(
                            run_id, run_path, project, constraints, contract,
                            source_group, candidate_group, outside_beat_ids, exc,
                            suffix=f"{suffix}-polish-segment-{group:02d}",
                        )
                        group_part_indexes = [
                            part_index
                            for part_index, part_group in enumerate(part_groups, 1)
                            if part_group == group
                        ]
                        if repaired is not None:
                            repaired_group, receipt = repaired
                            candidate_groups[group - 1] = repaired_group
                            if len(group_part_indexes) == 1:
                                part_index = group_part_indexes[0]
                                self._save_polish_checkpoint(
                                    checkpoint_root, part_index,
                                    parts[part_index - 1], repaired_group,
                                    status="semantic_repaired",
                                    retry_signature=retry_signature, accepted=True,
                                    authority_hash=part_authority_hashes.get(part_index),
                                )
                            else:
                                for part_index in group_part_indexes:
                                    self._save_polish_checkpoint(
                                        checkpoint_root, part_index,
                                        parts[part_index - 1], parts[part_index - 1],
                                        status="semantic_repaired_requires_replay",
                                        retry_signature=retry_signature, accepted=False,
                                        authority_hash=part_authority_hashes.get(part_index),
                                    )
                        else:
                            candidate_groups[group - 1] = source_group
                            for part_index in group_part_indexes:
                                self._save_polish_checkpoint(
                                    checkpoint_root, part_index,
                                    parts[part_index - 1], parts[part_index - 1],
                                    status="semantic_drift_preserved",
                                    retry_signature=retry_signature, accepted=False,
                                    authority_hash=part_authority_hashes.get(part_index),
                                )
                            try:
                                receipt = validate_semantic_receipt(
                                    contract, source_group,
                                    source_receipts[group - 1],
                                )
                            except (IndexError, ValueError):
                                receipt = await self._verify_draft_semantic_node(
                                    run_id, run_path, project, constraints, contract,
                                    source_group, outside_beat_ids,
                                    suffix=f"{suffix}-polish-source-{group:02d}",
                                    failure_stage="polish",
                                )
                            self.db.add_run_event(
                                run_id, "warning", "polish_segment_preserved",
                                "润色候选两次语义修复仍未通过，已恢复完整验收原段",
                                stage="polish", metadata={
                                    "segment": group, "issues": exc.issues,
                                },
                            )
                semantic_receipts.append(receipt)
            polished = self.SHORT_SEGMENT_SEPARATOR.join(candidate_groups)
            expected_beat_ids = [
                beat_id
                for segment in execution_manifest.segments
                for beat_id in segment.beat_ids
            ]
            semantic_authority_sha256 = str(
                source_draft_integrity.get("authority_sha256")
                or execution_manifest.authority_sha256
            )
            try:
                whole_receipt = await self._verify_whole_draft_semantics(
                    run_id, run_path, project, constraints,
                    semantic_authority_sha256,
                    polished, candidate_groups, expected_beat_ids,
                    semantic_receipts, failure_stage="polish",
                )
            except asyncio.CancelledError:
                raise
            except Exception as whole_error:
                source_semantic_receipts: list[dict] = []
                try:
                    for group, (source_group, manifest_segment) in enumerate(
                        zip(
                            original_parts, execution_manifest.segments,
                            strict=True,
                        ),
                        1,
                    ):
                        source_contract = self._manifest_segment_contract(
                            project, execution_manifest, source_draft_integrity,
                            manifest_segment, source_group, group,
                        )
                        source_semantic_receipts.append(
                            validate_semantic_receipt(
                                source_contract, source_group,
                                source_receipts[group - 1],
                            )
                        )
                    whole_receipt = validate_whole_draft_receipt(
                        semantic_authority_sha256, text, original_parts,
                        expected_beat_ids,
                        source_draft_integrity.get("whole_semantic_receipt"),
                    )
                except (IndexError, TypeError, ValueError):
                    source_semantic_receipts = []
                    for group, (source_group, manifest_segment) in enumerate(
                        zip(
                            original_parts, execution_manifest.segments,
                            strict=True,
                        ),
                        1,
                    ):
                        source_contract = self._manifest_segment_contract(
                            project, execution_manifest, source_draft_integrity,
                            manifest_segment, source_group, group,
                        )
                        source_semantic_receipts.append(
                            await self._verify_draft_semantic_node(
                                run_id, run_path, project, constraints,
                                source_contract, source_group,
                                [
                                    beat_id for beat_id in all_beat_ids
                                    if beat_id not in manifest_segment.beat_ids
                                ],
                                suffix=(
                                    f"{suffix}-polish-whole-source-"
                                    f"{group:02d}"
                                ),
                                failure_stage="polish",
                            )
                        )
                    whole_receipt = await self._verify_whole_draft_semantics(
                        run_id, run_path, project, constraints,
                        semantic_authority_sha256,
                        text, original_parts, expected_beat_ids,
                        source_semantic_receipts, failure_stage="polish",
                    )
                rejected_sha256 = hashlib.sha256(
                    polished.encode("utf-8"),
                ).hexdigest()
                recovered_subset = await self._recover_polish_semantic_subset(
                    run_id, run_path, project, constraints,
                    text, original_parts, candidate_groups,
                    execution_manifest, source_draft_integrity,
                    semantic_receipts, source_semantic_receipts,
                    whole_receipt, expected_beat_ids,
                )
                candidate_groups = list(recovered_subset["parts"])
                semantic_receipts = list(recovered_subset["receipts"])
                whole_receipt = dict(recovered_subset["whole_receipt"])
                retained_segments = list(
                    recovered_subset["retained_segments"]
                )
                rejected_segments = list(
                    recovered_subset["rejected_segments"]
                )
                polished = self.SHORT_SEGMENT_SEPARATOR.join(candidate_groups)
                for rejected_group in rejected_segments:
                    for part_index, part_group in enumerate(part_groups, 1):
                        if part_group != rejected_group:
                            continue
                        self._save_polish_checkpoint(
                            checkpoint_root, part_index,
                            parts[part_index - 1], parts[part_index - 1],
                            status="whole_semantic_conflict_preserved",
                            retry_signature=retry_signature,
                            accepted=False,
                            authority_hash=part_authority_hashes.get(part_index),
                        )
                subset_retained = bool(retained_segments)
                self.db.add_run_event(
                    run_id, "warning", (
                        "polish_semantic_subset_restored"
                        if subset_retained else
                        "polish_whole_semantic_preserved"
                    ),
                    (
                        "已隔离造成整篇冲突的润色段，其余通过复核的润色继续进入后续流程"
                        if subset_retained else
                        "润色合并稿未能保持整篇因果，已恢复全部验收前正文并继续后续流程"
                    ),
                    stage="polish", metadata={
                        "rejected_draft_sha256": rejected_sha256,
                        "restored_draft_sha256": hashlib.sha256(
                            polished.encode("utf-8"),
                        ).hexdigest(),
                        "retained_segments": retained_segments,
                        "rejected_segments": rejected_segments,
                        "failure_class": classify_model_failure(whole_error),
                        "error": str(whole_error)[:500],
                    },
                )
            segment_integrity = []
            previous_hash = ""
            for group, (candidate_group, manifest_segment) in enumerate(
                zip(candidate_groups, execution_manifest.segments), 1,
            ):
                text_hash = hashlib.sha256(candidate_group.encode("utf-8")).hexdigest()
                segment_integrity.append({
                    "segment": group,
                    "event_ids": list(manifest_segment.beat_ids),
                    "handoff": "；".join(
                        item.state for item in manifest_segment.exit_state
                    ),
                    "han_characters": effective_han_characters(candidate_group),
                    "previous_sha256": previous_hash,
                    "text_sha256": text_hash,
                })
                previous_hash = text_hash
            polish_integrity = {
                **source_draft_integrity,
                "version": 4,
                "status": "passed",
                "source_draft_sha256": hashlib.sha256(text.encode("utf-8")).hexdigest(),
                "draft_sha256": hashlib.sha256(polished.encode("utf-8")).hexdigest(),
                "publication_sha256": hashlib.sha256(
                    "\n\n".join(candidate_groups).encode("utf-8"),
                ).hexdigest(),
                "publication_segment_lengths": [
                    len(part) for part in candidate_groups
                ],
                "segments": segment_integrity,
                "accepted_event_ids": expected_beat_ids,
                "semantic_segment_receipts": semantic_receipts,
                "whole_semantic_receipt": whole_receipt,
                "issues": [],
            }
            atomic_write(
                run_path / "outputs" / f"polish-integrity{suffix}.json",
                json.dumps(polish_integrity, ensure_ascii=False, indent=2),
            )
        if revision_plan:
            failures = check_revision_constraints(polished, revision_plan)
            final_failures = failures
            atomic_write(
                run_path / "outputs" / f"revision-checks{suffix}.json",
                json.dumps({"failures": failures}, ensure_ascii=False, indent=2),
            )
            if failures:
                self.db.add_run_event(
                    run_id, "warning", "revision_checks_failed",
                    "Structural revision still violates deterministic checks",
                    stage="polish", metadata={"failures": failures},
                )
            deferred_tasks = revision_plan.get("deferred_tasks", [])
            if deferred_tasks:
                remaining_plan = {
                    "global_facts": revision_plan["global_facts"],
                    "checks": revision_plan["checks"],
                    "tasks": deferred_tasks,
                }
                next_plan = self._normalized_revision_plan(
                    remaining_plan, len(original_parts), max_target_ratio=0.4,
                    require_checks=bool(remaining_plan["checks"]),
                    defer_excess_targets=True,
                )
                self.db.add_run_event(
                    run_id, "info", "revision_batch_continued",
                    "当前批次已完成，正在继续处理同一返修计划的下一批场景",
                    stage="polish", metadata={
                        "completed_segments": revision_plan["target_segments"],
                        "next_segments": next_plan["target_segments"],
                        "remaining_segments": next_plan["deferred_segments"],
                    },
                )
                polished = await self._polish_short_segments(
                    run_id, run_path, project, constraints, polished, findings,
                    suffix=f"{suffix}-batch-{batch_number + 1}", structural=True,
                    prepared_revision_plan=remaining_plan,
                    round_cap_override=max(0, round_cap - round_input_tokens),
                    batch_number=batch_number + 1,
                )
                final_failures = check_revision_constraints(polished, revision_plan)
                atomic_write(
                    run_path / "outputs" / f"revision-checks{suffix}.json",
                    json.dumps({"failures": final_failures}, ensure_ascii=False, indent=2),
                )
            regression_failures = []
            for check in revision_plan.get("checks", []):
                if not isinstance(check, dict):
                    continue
                value = str(check.get("value") or "")
                if not value:
                    continue
                if (
                    check.get("kind") == "required_text"
                    and value in text
                    and value not in polished
                ):
                    regression_failures.append(
                        f"required text removed: {value}"
                    )
                elif (
                    check.get("kind") == "forbidden_text"
                    and polished.count(value) > text.count(value)
                ):
                    regression_failures.append(
                        f"forbidden text increased: {value}"
                    )
            if regression_failures:
                rejected_sha256 = hashlib.sha256(
                    polished.encode("utf-8"),
                ).hexdigest()
                polished = text
                self.db.add_run_event(
                    run_id, "warning", "revision_checks_preserved",
                    "结构返修未满足确定性修改合同，已恢复本轮返修前完整候选稿",
                    stage="polish", metadata={
                        "failures": final_failures,
                        "regressions": regression_failures,
                        "rejected_draft_sha256": rejected_sha256,
                        "restored_draft_sha256": hashlib.sha256(
                            text.encode("utf-8"),
                        ).hexdigest(),
                    },
                )
        atomic_write(run_path / "outputs" / f"polish{suffix}.md", polished)
        return polished

    @classmethod
    def _polish_round_input_cap(cls, structural: bool, segment_count: int) -> int:
        if structural:
            return cls.STRUCTURAL_POLISH_INPUT_CAP
        return max(cls.INITIAL_POLISH_INPUT_CAP, segment_count * 20_000)

    @staticmethod
    def _split_failed_polish_segment(text: str, minimum: int = 400) -> tuple[str, str] | None:
        paragraphs = [item.strip() for item in re.split(r"\n\s*\n", text) if item.strip()]
        if len(paragraphs) < 2 or len(text) < minimum * 2:
            return None
        midpoint = len(text) / 2
        split_at = min(range(1, len(paragraphs)), key=lambda index: abs(
            len("\n\n".join(paragraphs[:index])) - midpoint
        ))
        left = "\n\n".join(paragraphs[:split_at])
        right = "\n\n".join(paragraphs[split_at:])
        return (left, right) if min(len(left), len(right)) >= minimum else None

    async def _plan_structural_revision(self, run_id: str, run_path: Path, project: Project,
                                        constraints: str, findings: str,
                                        story_map: list[dict], suffix: str) -> dict:
        try:
            review = compact_review(json.loads(findings))
        except (json.JSONDecodeError, TypeError):
            review = {"issues": [{"action": findings}]}
        hard_categories = {
            "canon", "canon_conflict", "logic_continuity", "manuscript_corruption",
            "missing_required_content", "production_text", "story_structure",
        }
        require_checks = any(
            issue.get("severity") == "critical" or issue.get("category") in hard_categories
            for issue in review.get("issues", []) if isinstance(issue, dict)
        )
        prompt = (
            "Create a minimal structural revision plan for this segmented manuscript. Map every "
            "review issue to one separate task and the exact scene_id/segment numbers that must "
            "change. Order tasks by urgency and never target unrelated scenes. The Runtime will "
            "apply at most 40% of scenes in the current batch and defer the rest. "
            "Return one JSON object only with: global_facts (string array), checks (array of objects "
            "using kind required_text or forbidden_text, value, and issue_ids), and tasks (array with "
            "segments as integer array, instruction as text, issue_ids as the exact related review "
            "issue IDs, and optional seven_step_position only when the review evidence names it). "
            "Include at least one literal deterministic check "
            "for hard fact, canon, duplication, or required-content issues. Do not combine all review "
            "issues into one instruction. Checks must be unambiguous manuscript text constraints; "
            "semantic judgments belong in the scene task.\n\n"
            f"COMPLETE REVIEW FINDINGS:\n{json.dumps(review, ensure_ascii=False)}\n\n"
            f"COMPACT SEGMENT MAP:\n{json.dumps(story_map, ensure_ascii=False)}"
        )
        try:
            try:
                output = await self._stage(
                    run_id, run_path, project, "revision_plan", constraints, prompt,
                    suffix=f"{suffix}-revision-plan", model_role="planning", allow_tools=False,
                    targeted_retry=True,
                )
                try:
                    payload = self._convert_generated_object(
                        output, run_path, contract_name="revision_plan",
                    )
                    plan = self._normalized_revision_plan(
                        payload, len(story_map), max_target_ratio=0.4,
                        require_checks=require_checks, defer_excess_targets=True,
                    )
                except (json.JSONDecodeError, ValueError):
                    repair = schema_repair_prompt(output, "repair_revision_plan_v1")
                    output = await self._stage(
                        run_id, run_path, project, "revision_plan", constraints, repair,
                        suffix=f"{suffix}-revision-plan-repair", model_role="planning",
                        allow_tools=False, targeted_retry=True,
                    )
                    payload = self._convert_generated_object(
                        output, run_path, contract_name="revision_plan",
                    )
                    plan = self._normalized_revision_plan(
                        payload, len(story_map), max_target_ratio=0.4,
                        require_checks=require_checks, defer_excess_targets=True,
                    )
            except asyncio.CancelledError:
                raise
            except Exception as exc:
                self.db.add_run_event(
                    run_id, "warning", "model_fallback",
                    "Revision planning model failed; retrying with the review role",
                    stage="revision_plan", metadata={
                        "fallback_role": "review", "error": str(exc),
                    },
                )
                output = await self._stage(
                    run_id, run_path, project, "revision_plan", constraints, prompt,
                    suffix=f"{suffix}-revision-plan-fallback", model_role="review",
                    allow_tools=False, targeted_retry=True,
                )
                plan = self._normalized_revision_plan(
                    self._convert_generated_object(
                        output, run_path, contract_name="revision_plan",
                    ), len(story_map),
                    max_target_ratio=0.4, require_checks=require_checks,
                    defer_excess_targets=True,
                )
            event_type, severity = "revision_planned", "success"
        except asyncio.CancelledError:
            raise
        except Exception as exc:
            self.db.add_run_event(
                run_id, "error", "revision_plan_blocked",
                "Structural revision plan is invalid; revision stopped to preserve the best candidate",
                stage="revision_plan",
                metadata={"error": str(exc)},
            )
            raise RevisionPlanError(f"Structural revision plan failed: {exc}") from exc
        else:
            if plan.get("deferred_segments"):
                self.db.add_run_event(
                    run_id, "info", "revision_plan_deferred",
                    "返修范围较大，已分批处理；其余场景将在下一轮复核后继续",
                    stage="revision_plan", metadata={
                        "current_segments": plan["target_segments"],
                        "deferred_segments": plan["deferred_segments"],
                    },
                )
            self.db.add_run_event(
                run_id, severity, event_type, "Structural revision plan created",
                stage="revision_plan", metadata={
                    "target_segments": plan["target_segments"],
                    "deferred_segments": plan.get("deferred_segments", []),
                    "task_count": len(plan["tasks"]),
                    "check_count": len(plan["checks"]),
                },
            )
        atomic_write(
            run_path / "outputs" / f"revision-plan{suffix}.json",
            json.dumps(plan, ensure_ascii=False, indent=2),
        )
        return plan

    @staticmethod
    def _previous_quality_best(run_path: Path) -> dict | None:
        checkpoint = reconcile_legacy_checkpoint(run_path)
        if checkpoint is None:
            return None
        return {**checkpoint, "text": checkpoint_manuscript(run_path, checkpoint)}

    @staticmethod
    def _stage_context_labels(constraints: str, user: str = "") -> list[str]:
        combined = f"{constraints}\n{user}"
        markers = (
            ("CONFIRMED STORY FACTS", "已确认事实"),
            ("Program-enforced locked story facts", "锁定事实"),
            ("Current Confirmed Outline", "正式大纲"),
            ("Confirmed Long-form Execution Plan", "长篇执行计划"),
            ("Executable Prose Baseline", "基础文笔"),
            ("Confirmed Creative Blueprint", "创作蓝图"),
            ("Short Story Causal Chain", "七步剧情结构"),
            ("Advisory Market Baseline", "同类市场基线"),
            ("Character Voice Profiles", "人物说话方式"),
            ("RELEVANT CHARACTER VOICES", "人物说话方式"),
            ("Character Knowledge Boundaries", "人物认知边界"),
            ("Scene Briefs", "场景安排"),
            ("COMPACT FULL STORY MAP", "全文剧情位置图"),
            ("NARRATIVE STATE FOR THIS WINDOW", "伏笔与场景状态"),
            ("PROJECT STYLE PROFILE", "作品文风"),
            ("STYLE PROFILE", "作品文风"),
        )
        return list(dict.fromkeys(
            label for marker, label in markers if marker in combined
        ))

    @staticmethod
    def _write_quality_report(run_path: Path, report: dict) -> None:
        atomic_write(
            run_path / "outputs" / "quality-report.json",
            json.dumps(report, ensure_ascii=False, indent=2),
        )

    def _halt_quality_revision(self, run_id: str, run_path: Path, report: dict,
                               candidate: str, error: Exception) -> None:
        reason = (
            "revision_plan_invalid" if isinstance(error, RevisionPlanError)
            else "token_budget_exhausted"
        )
        report["status"] = "halted"
        report["halt_reason"] = reason
        report["failure_reasons"] = [str(error)]
        atomic_write(run_path / "outputs" / "best-candidate.md", candidate)
        self._write_quality_report(run_path, report)
        self.db.add_run_event(
            run_id, "error", "quality_revision_halted",
            "Quality revision stopped and preserved the best candidate",
            stage="quality", metadata={"reason": reason, "error": str(error)},
        )
        raise RuntimeError(
            f"Quality revision halted; preserved best candidate ({reason})"
        ) from error

    @staticmethod
    def _semantic_owner_event_ids(value: str) -> list[str]:
        return planning_event_ids(value)

    @classmethod
    def _project_authority_text(
        cls, value: str, owner_event_ids: Sequence[str],
    ) -> str:
        text = str(value or "").replace("\r\n", "\n").replace("\r", "\n").strip()
        owners = {str(item).strip().upper() for item in owner_event_ids if str(item).strip()}
        if not text or not owners:
            return text
        selected = []
        for block in (
            item.strip()
            for item in re.split(r"\n[ \t]*\n+", text)
            if item.strip()
        ):
            block_ids = set(cls._semantic_owner_event_ids(block))
            if block_ids & owners:
                selected.append(block)
        return "\n\n".join(selected)

    def _stage_story_skeleton(
        self, project: Project, constraints: str, run_path: Path | None = None,
        *, relevant_context: str = "",
        owner_event_ids: Sequence[str] | None = None,
        index_only: bool = False,
    ) -> str:
        state = self.story_states.ensure(project.id, project.path).data
        outline = state.get("outline") if isinstance(state.get("outline"), dict) else {}
        marker = "# Short Story Causal Chain"
        causal = ""
        if marker in constraints:
            causal = constraints.split(marker, 1)[1].strip()
        execution_manifest = None
        draft_integrity = None
        if run_path is not None:
            try:
                execution_manifest = json.loads(
                    (run_path / "outputs" / "short-execution-index.json").read_text(
                        encoding="utf-8",
                    )
                )
            except (OSError, UnicodeError, json.JSONDecodeError):
                execution_manifest = None
            if isinstance(execution_manifest, dict):
                try:
                    parsed_manifest = parse_execution_manifest(execution_manifest)
                except (TypeError, ValueError):
                    execution_manifest = None
                else:
                    if (
                        parsed_manifest.status != "ready"
                        or execution_manifest_receipt_binding_issues(parsed_manifest)
                    ):
                        execution_manifest = None
                    else:
                        receipt = parsed_manifest.semantic_receipt
                        execution_manifest = {
                            **execution_manifest,
                            "semantic_receipt": {
                                "formal_plot_unchanged": receipt.get(
                                    "formal_plot_unchanged"
                                ),
                                "summary": receipt.get("summary"),
                            },
                        }
            try:
                draft_integrity = json.loads(
                    (run_path / "outputs" / "draft-integrity.json").read_text(
                        encoding="utf-8",
                    )
                )
            except (OSError, UnicodeError, json.JSONDecodeError):
                draft_integrity = None
            if isinstance(draft_integrity, dict):
                draft_integrity = {
                    key: draft_integrity.get(key)
                    for key in (
                        "version", "status", "authority_sha256",
                        "execution_manifest_sha256", "draft_sha256",
                        "expected_event_ids", "accepted_event_ids", "segments", "issues",
                    )
                }
        requested_owner_ids = list(dict.fromkeys(
            str(item).strip().upper()
            for item in (
                owner_event_ids
                if owner_event_ids is not None
                else self._semantic_owner_event_ids(relevant_context)
            )
            if str(item).strip()
        ))
        # Automatic projection is only safe for a bounded current ownership
        # scope. Some whole-story prompts intentionally enumerate every event.
        if owner_event_ids is None and len(requested_owner_ids) > 12:
            requested_owner_ids = []
        outline_text = str(outline.get("content") or "")
        full_outline_ids = self._semantic_owner_event_ids(outline_text)
        if index_only:
            projected_outline = ""
            projected_causal = ""
            if isinstance(execution_manifest, dict):
                try:
                    parsed_index_manifest = parse_execution_manifest(
                        execution_manifest,
                    )
                except (TypeError, ValueError):
                    execution_manifest = None
                else:
                    requested_set = set(requested_owner_ids)
                    indexed_beats = [
                        beat for beat in parsed_index_manifest.beats
                        if not requested_set or (
                            beat.beat_id.upper() in requested_set
                            or beat.source_event_id.upper() in requested_set
                        )
                    ]
                    indexed_beat_ids = {beat.beat_id for beat in indexed_beats}
                    execution_manifest = {
                        "version": parsed_index_manifest.version,
                        "status": parsed_index_manifest.status,
                        "authority_sha256": parsed_index_manifest.authority_sha256,
                        "manifest_sha256": execution_manifest_sha256(
                            parsed_index_manifest,
                        ),
                        "beat_index": [{
                            "beat_id": beat.beat_id,
                            "source_event_id": beat.source_event_id,
                            "owner_segment": beat.owner_segment,
                            "order": beat.order,
                        } for beat in indexed_beats],
                        "segment_index": [{
                            "segment": item.segment,
                            "beat_ids": [
                                beat_id for beat_id in item.beat_ids
                                if not requested_set or beat_id in indexed_beat_ids
                            ],
                        } for item in parsed_index_manifest.segments if (
                            not requested_set
                            or any(beat_id in indexed_beat_ids for beat_id in item.beat_ids)
                        )],
                    }
            if isinstance(draft_integrity, dict):
                draft_integrity = {
                    key: draft_integrity.get(key)
                    for key in (
                        "version", "status", "authority_sha256",
                        "execution_manifest_sha256", "draft_sha256",
                        "expected_event_ids", "accepted_event_ids", "issues",
                    )
                }
        elif requested_owner_ids:
            projected_outline = self._project_authority_text(
                outline_text, requested_owner_ids,
            )
            projected_causal = self._project_authority_text(
                causal, requested_owner_ids,
            )
            if isinstance(execution_manifest, dict):
                segments = execution_manifest.get("segments")
                if isinstance(segments, list):
                    execution_manifest = {
                        **execution_manifest,
                        "segments": [
                            item for item in segments
                            if isinstance(item, dict) and set(
                                self._semantic_owner_event_ids(json.dumps(
                                    item, ensure_ascii=False,
                                ))
                            ) & set(requested_owner_ids)
                        ],
                    }
            if isinstance(draft_integrity, dict):
                segments = draft_integrity.get("segments")
                if isinstance(segments, list):
                    draft_integrity = {
                        **draft_integrity,
                        "segments": [
                            item for item in segments
                            if isinstance(item, dict) and set(
                                str(value).strip().upper()
                                for value in item.get("event_ids", [])
                            ) & set(requested_owner_ids)
                        ],
                    }
        else:
            projected_outline = outline_text
            projected_causal = causal
        payload = {
            "project": {
                key: project.metadata.get(key)
                for key in (
                    "title", "genre", "premise", "pov", "tone",
                    "target_words", "must_include", "must_avoid",
                )
                if project.metadata.get(key) not in (None, "")
            },
            "formal_outline": projected_outline,
            "authority_projection": {
                "owner_event_ids": requested_owner_ids,
                "formal_outline_sha256": hashlib.sha256(
                    outline_text.encode("utf-8"),
                ).hexdigest(),
                "formal_event_ids": full_outline_ids,
                "causal_chain_sha256": hashlib.sha256(
                    causal.encode("utf-8"),
                ).hexdigest(),
                "projection_mode": (
                    "hash_bound_index"
                    if index_only else (
                        "event_owned_exact_blocks" if requested_owner_ids else "complete"
                    )
                ),
            },
            "confirmed_facts": state.get("confirmed_facts", []),
            "locked_facts": state.get("locked_facts", []),
            "ending": state.get("ending"),
            "character_states": state.get("character_states", {}),
            "causal_chain": projected_causal,
            "execution_manifest": execution_manifest,
            "draft_integrity": draft_integrity,
        }
        return json.dumps(payload, ensure_ascii=False, sort_keys=True, default=str)

    @staticmethod
    def _stage_contract_envelope(stage: str, user: str) -> dict:
        envelope = {
            "stage": stage,
            "user_sha256": hashlib.sha256(user.encode("utf-8")).hexdigest(),
        }
        for pattern in (
            r"CURRENT_TASK_CONTRACT:\s*(\{[^\n]+\})",
            r"TASK CONTRACT:\s*(\{[^\n]+\})",
        ):
            match = re.search(pattern, user)
            if not match:
                continue
            try:
                contract = json.loads(match.group(1))
            except json.JSONDecodeError:
                continue
            if isinstance(contract, dict):
                envelope.update({
                    key: contract.get(key)
                    for key in (
                        "task_id", "beat_ids", "event_ids", "entry_state",
                        "exit_requirement", "prohibited_future_beat_ids",
                        "execution_manifest_sha256", "viewpoint",
                    )
                    if contract.get(key) not in (None, "", [], {})
                })
            break
        return envelope

    def _quality_assessed_event(self, run_id: str, source: str, review: dict,
                                attempt: int | None = None) -> None:
        metadata = {
            "source": source,
            "score": review["score"],
            "dimensions": review["dimensions"],
            "hard_fail": review["hard_fail"],
            "decision": review["decision"],
        }
        if attempt is not None:
            metadata["attempt"] = attempt
        self.db.add_run_event(
            run_id, "info", "quality_assessed",
            f"{source} 质量评分：{review['score']}",
            stage="quality", metadata=metadata,
        )

    @staticmethod
    def _completion_check_safe(
        check: Callable[[str], bool], value: str,
    ) -> bool:
        try:
            return bool(check(value))
        except (TypeError, ValueError, json.JSONDecodeError):
            return False

    async def _stage(self, run_id: str, run_path: Path, project: Project, stage: str,
                     constraints: str, user: str, suffix: str = "",
                     model_role: str | None = None, allow_tools: bool = True,
                     prefer_configured_fallback: bool = False,
                     output_source_characters: int | None = None,
                     targeted_retry: bool = False,
                     primary_only: bool = False,
                     retry_polish_output_limit: bool = True,
                     expected_output_characters: int | None = None,
                     completion_check: Callable[[str], bool] | None = None,
                     compact_input: bool = False,
                     route_capacity_guard: bool = False,
                     capacity_splitter: Callable[[dict], object] | None = None,
                     story_skeleton_override: str | None = None,
                     bounded_protocol_output: bool = False,
                     scoped_creative_output: bool = False,
                     structured_contract: StructuredArtifactContract | None = None,
                     defer_route_failure_audit: bool = False,
                     protocol_system_contract: str | None = None) -> str:
        node_key = f"{stage}{suffix}"
        stage_system = protocol_system_contract or STAGE_SYSTEM[stage]
        current_state = self.story_states.get(project.id)
        node_authority_sha256 = hashlib.sha256(json.dumps({
            "project_id": project.id,
            "story_state_revision": current_state.revision if current_state else 0,
            "stage": stage,
            "model_role": model_role or stage,
        }, ensure_ascii=False, sort_keys=True, separators=(",", ":")).encode(
            "utf-8",
        )).hexdigest()
        node_input_sha256 = hashlib.sha256(
            (stage_system + "\n\0" + constraints + "\n\0" + user).encode("utf-8"),
        ).hexdigest()
        if protocol_system_contract is not None and not bounded_protocol_output:
            raise ValueError(
                "protocol_system_contract requires bounded_protocol_output"
            )
        if bounded_protocol_output and scoped_creative_output:
            raise ValueError(
                "a model call cannot use protocol and creative output budgets together"
            )
        if primary_only and prefer_configured_fallback:
            raise ValueError(
                "a route-isolated model call cannot select primary and fallback together"
            )
        if structured_contract is not None and (
            primary_only or prefer_configured_fallback
        ):
            raise ValueError(
                "structured route selection must be owned by its contract executor"
            )
        if (
            route_capacity_guard
            and capacity_splitter is None
            and not bounded_protocol_output
            and not scoped_creative_output
        ):
            raise ValueError(
                "route_capacity_guard requires a semantic splitter, bounded "
                "protocol output, or scoped creative output"
            )
        self.db.update_run(run_id, "running", stage)
        self.db.add_run_event(run_id, "info", "stage_started", f"开始执行 {stage}", stage=stage)
        required = REQUIRED_SKILLS[stage]
        commands = None
        cwd = None
        skill = self.skills.skills(project.path).get("story-maintenance") if stage == "maintenance" else None
        if skill and skill.executable:
            commands = {"story-maintenance": ["scripts/story.js", "validate", "."]}
            cwd = project.path
        try:
            identity = (
                self._maintenance_story_identity(project)
                if stage == "maintenance" and skill and skill.executable
                else nullcontext()
            )
            with identity:
                skill_run = self.skills.run_required(stage, required, commands, cwd, project.path)
            if OPTIONAL_PROMPT_SKILLS.get(stage) and hasattr(self.skills, "load_optional_prompts"):
                optional = self.skills.load_optional_prompts(
                    stage, OPTIONAL_PROMPT_SKILLS[stage], project.path,
                )
                skill_run = type(skill_run)(
                    "\n\n".join(item for item in (skill_run.prompt, optional.prompt) if item),
                    [*skill_run.receipts, *optional.receipts],
                )
            skills = [receipt.skill_name for receipt in skill_run.receipts]
            layered_context = stage in {
                "planning", "draft", "polish", "review",
                "revision_plan", "final_review",
            }
            gateway_role = model_role or stage
            preliminary_output_budget = self._output_budget_for_call(
                stage, output_source_characters, gateway_role,
                prefer_configured_fallback,
                expected_output_characters=expected_output_characters,
                bounded_protocol_output=bounded_protocol_output,
                scoped_creative_output=scoped_creative_output,
            )
            preliminary_fallback_budget = (
                self._output_budget_for_call(
                    stage, output_source_characters, gateway_role, True,
                    expected_output_characters=expected_output_characters,
                    bounded_protocol_output=bounded_protocol_output,
                    scoped_creative_output=scoped_creative_output,
                )
                if route_capacity_guard and not prefer_configured_fallback
                and not primary_only else None
            )
            preliminary_route_reserve = max(
                preliminary_output_budget or 0,
                preliminary_fallback_budget or 0,
            )
            compact_context = layered_context
            model_skill_prompt = (
                self.skill_prompts.compact(skill_run.prompt, skill_run.receipts)
                if compact_context else skill_run.prompt
            )
            source_constraints = constraints
            if stage == "polish":
                project_constraints = (project.path / "constraints.md").read_text(encoding="utf-8")
                if project_constraints not in source_constraints:
                    source_constraints += (
                        "\n\nPROJECT-SPECIFIC CONSTRAINTS:\n" + project_constraints
                    )
            model_constraints = source_constraints
            if compact_context:
                model_constraints = self.constraint_prompts.compact_for_stage(
                    source_constraints, stage=stage, focus=user,
                )
            style = (
                f"\n\nPROJECT STYLE PROFILE:\n{ensure_style_profile(project)}"
                if stage == "draft"
                and project.metadata.get("style_sample_scope") == "draft_and_polish"
                else ""
            )
            context_packet = None
            if layered_context:
                story_state = self.story_states.ensure(project.id, project.path).data
                narrative_findings = validate_narrative_graph(
                    story_state.get("narrative_graph"),
                    genres=(story_state.get("narrative_rule_profile") or {}).get(
                        "genres", [],
                    ),
                )
                if any(item.severity == "hard" for item in narrative_findings):
                    raise ValueError(
                        "StoryState narrative graph contains unresolved hard findings: "
                        + ", ".join(item.code for item in narrative_findings)
                    )
                narrative_contract = ensure_narrative_contract(project)
                if (
                    narrative_contract.status != "ready"
                    and stage in {"draft", "polish", "revision_plan", "final_review"}
                ):
                    raise ValueError(
                        "第一人称叙述者尚未确认；请选择本书中代表“我”的人物后继续原流程"
                    )
                explicit_invariants = {
                    "viewpoint": project.metadata.get("pov"),
                    "narrative_contract": render_narrative_contract(
                        narrative_contract,
                    ),
                    "tone": project.metadata.get("tone"),
                    "must_include": project.metadata.get("must_include"),
                    "must_avoid": project.metadata.get("must_avoid"),
                    "confirmed_ending": story_state.get("ending"),
                    "knowledge_boundaries": story_state.get("character_states"),
                    "narrative_fact_graph": story_state.get("narrative_graph"),
                    "narrative_rule_profile": story_state.get("narrative_rule_profile"),
                    "formal_plot_unchanged": "不得改写已经确认的正式大纲和因果结局。",
                    "whole_story_logic": (
                        "任何拆分、重试、润色、审核和返修都不得破坏整篇因果、人物状态、"
                        "时间线、伏笔兑现和结局逻辑。"
                    ),
                    "atomic_beat_ownership": (
                        "当前任务只能执行自己拥有的原子节拍，不得提前执行后续节拍或重复已完成节拍。"
                    ),
                }
                advisory = (
                    model_constraints + "\n\nSkill instructions (advisory):\n"
                    + model_skill_prompt + style
                )
                context_packet = build_stage_context_packet(
                    stage=stage,
                    current_contract=self._stage_contract_envelope(stage, user),
                    constraints=source_constraints,
                    skill_prompt=skill_run.prompt,
                    explicit_invariants=explicit_invariants,
                    relevant_context=user,
                    global_skeleton=(
                        story_skeleton_override
                        if story_skeleton_override is not None
                        else self._stage_story_skeleton(
                            project, source_constraints, run_path,
                            relevant_context=user,
                        )
                    ),
                    advisory=advisory,
                    output_reserve=preliminary_route_reserve,
                    advisory_max_chars=3000 if compact_input else 8000,
                )
                coverage_issues = validate_rule_coverage(context_packet)
                if coverage_issues:
                    raise ValueError(
                        "模型上下文缺少强制叙事规则："
                        + json.dumps(coverage_issues, ensure_ascii=False)
                    )
                system = (
                    f"{stage_system}\n\n"
                    "Skill instructions and story authority are supplied in the layered context.\n\n"
                    + render_stage_system_context(context_packet)
                )
            else:
                system = (
                    f"{stage_system}\n\nHARD CONSTRAINTS:\n{model_constraints}"
                    f"\n\n{model_skill_prompt}{style}"
                )
            estimated_input_tokens = estimate_input_tokens(system + "\n" + user)
            if stage == "polish" and compact_input and not layered_context:
                model_constraints = ConstraintPromptCompactor(max_chars=4000).compact_for_stage(
                    source_constraints, stage=stage, focus=user,
                )
                model_skill_prompt = SkillPromptCompactor(max_chars=5000).compact(
                    skill_run.prompt, skill_run.receipts,
                )
                system = (
                    f"{stage_system}\n\nHARD CONSTRAINTS:\n{model_constraints}"
                    f"\n\n{model_skill_prompt}{style}"
                )
                estimated_input_tokens = estimate_input_tokens(system + "\n" + user)
            provider_ceiling = self._provider_output_ceiling(
                gateway_role, prefer_configured_fallback,
            )
            output_budget = self._output_budget_for_call(
                stage, output_source_characters, gateway_role,
                prefer_configured_fallback,
                expected_output_characters=expected_output_characters,
                input_tokens=estimated_input_tokens,
                bounded_protocol_output=bounded_protocol_output,
                scoped_creative_output=scoped_creative_output,
            )
            fallback_output_budget = (
                self._output_budget_for_call(
                    stage, output_source_characters, gateway_role, True,
                    expected_output_characters=expected_output_characters,
                    input_tokens=estimated_input_tokens,
                    bounded_protocol_output=bounded_protocol_output,
                    scoped_creative_output=scoped_creative_output,
                )
                if not prefer_configured_fallback and not primary_only else None
            )
            route_output_reserve = max(
                output_budget or 0,
                fallback_output_budget or 0,
            )
            if context_packet is not None:
                context_packet = replace(context_packet, metrics={
                    **context_packet.metrics,
                    "output_reserve_tokens": route_output_reserve,
                })
            context_window = (
                self._route_safe_context_window(
                    gateway_role,
                    prefer_configured_fallback=prefer_configured_fallback,
                    include_configured_fallback=(
                        route_capacity_guard
                        and not prefer_configured_fallback
                        and not primary_only
                    ),
                )
                if route_capacity_guard else
                self._provider_context_window(
                    gateway_role, prefer_configured_fallback,
                )
            )

            async def complete_capacity_split(details: dict) -> StageText:
                trigger = str(details.get("trigger") or "preflight")
                self.db.add_run_event(
                    run_id, "warning", "stage_capacity_split_requested",
                    (
                        f"{stage} 输出连续触达路由上限，正在缩小语义所有权而不是重复同一请求"
                        if trigger == "output_limit" else
                        f"{stage} 供应商报告上下文超限，正在按语义所有权切换分包拓扑"
                        if trigger == "provider" else
                        f"{stage} 请求接近上下文安全线，正在按语义所有权切换分包拓扑"
                    ),
                    stage=stage, metadata={
                        "trigger": trigger,
                        "pressure": details.get("pressure"),
                        "estimated_input_tokens": details.get(
                            "estimated_input_tokens"
                        ),
                        "authority_input_tokens": details.get(
                            "authority_input_tokens"
                        ),
                        "output_reserve": details.get("output_reserve"),
                        "context_window": details.get("context_window"),
                        **({
                            "provider_error_sha256": hashlib.sha256(
                                str(details.get("provider_error")).encode(
                                    "utf-8", errors="replace",
                                ),
                            ).hexdigest(),
                        } if details.get("provider_error") else {}),
                    },
                )
                try:
                    split_result = capacity_splitter(details)  # type: ignore[misc]
                    if hasattr(split_result, "__await__"):
                        split_result = await split_result
                except asyncio.CancelledError:
                    raise
                except Exception as split_exc:
                    # The semantic splitter is a new recovery boundary.  Its
                    # failure must not inherit the provider-capacity exception
                    # that selected this topology.
                    raise split_exc from None
                split_text = str(split_result or "")
                if completion_check is not None and not completion_check(split_text):
                    raise RuntimeError(
                        f"{stage} capacity split returned an incomplete artifact"
                    )
                self.db.add_run_event(
                    run_id, "success", "stage_capacity_split_completed",
                    f"{stage} 已完成语义分包并合并为完整审核回执",
                    stage=stage, metadata={
                        "trigger": trigger,
                        "pressure": details.get("pressure"),
                        "output_characters": len(split_text),
                    },
                )
                return StageText(split_text, {
                    "execution_mode": "capacity_split",
                    "completion_status": "complete",
                    "pressure": details.get("pressure"),
                    "trigger": trigger,
                })

            if layered_context and context_window:
                authority_input_tokens = sum(
                    item["estimated_tokens"]
                    for name, item in context_packet.metrics["layers"].items()
                    if name != "advisory"
                ) if context_packet is not None else estimated_input_tokens
                pressure = classify_input_pressure(
                    full_input_tokens=estimated_input_tokens,
                    authority_input_tokens=authority_input_tokens,
                    output_reserve=route_output_reserve,
                    context_window=context_window,
                )
                if (
                    pressure == "compact"
                    and context_packet is not None
                    and context_packet.metrics["layers"]["advisory"][
                        "estimated_tokens"
                    ] > 0
                ):
                    before_input_tokens = estimated_input_tokens
                    before_output_reserve = route_output_reserve
                    context_packet = build_stage_context_packet(
                        stage=stage,
                        current_contract=self._stage_contract_envelope(stage, user),
                        constraints=source_constraints,
                        skill_prompt=skill_run.prompt,
                        explicit_invariants=explicit_invariants,
                        relevant_context=user,
                        global_skeleton=(
                            story_skeleton_override
                            if story_skeleton_override is not None
                            else self._stage_story_skeleton(
                                project, source_constraints, run_path,
                                relevant_context=user,
                            )
                        ),
                        advisory="",
                        output_reserve=preliminary_route_reserve,
                        advisory_max_chars=0,
                    )
                    coverage_issues = validate_rule_coverage(context_packet)
                    if coverage_issues:
                        raise ValueError(
                            "模型上下文缺少强制叙事规则："
                            + json.dumps(coverage_issues, ensure_ascii=False)
                        )
                    system = (
                        f"{stage_system}\n\n"
                        "Skill instructions and story authority are supplied in the layered context.\n\n"
                        + render_stage_system_context(context_packet)
                    )
                    estimated_input_tokens = estimate_input_tokens(
                        system + "\n" + user,
                    )
                    output_budget = self._output_budget_for_call(
                        stage, output_source_characters, gateway_role,
                        prefer_configured_fallback,
                        expected_output_characters=expected_output_characters,
                        input_tokens=estimated_input_tokens,
                        bounded_protocol_output=bounded_protocol_output,
                        scoped_creative_output=scoped_creative_output,
                    )
                    fallback_output_budget = (
                        self._output_budget_for_call(
                            stage, output_source_characters, gateway_role, True,
                            expected_output_characters=expected_output_characters,
                            input_tokens=estimated_input_tokens,
                            bounded_protocol_output=bounded_protocol_output,
                            scoped_creative_output=scoped_creative_output,
                        )
                        if not prefer_configured_fallback and not primary_only
                        else None
                    )
                    route_output_reserve = max(
                        output_budget or 0, fallback_output_budget or 0,
                    )
                    context_packet = replace(context_packet, metrics={
                        **context_packet.metrics,
                        "output_reserve_tokens": route_output_reserve,
                    })
                    authority_input_tokens = sum(
                        item["estimated_tokens"]
                        for name, item in context_packet.metrics["layers"].items()
                        if name != "advisory"
                    )
                    pressure = classify_input_pressure(
                        full_input_tokens=estimated_input_tokens,
                        authority_input_tokens=authority_input_tokens,
                        output_reserve=route_output_reserve,
                        context_window=context_window,
                    )
                    self.db.add_run_event(
                        run_id, "info", "stage_advisory_context_shed",
                        f"{stage} 接近上下文安全线，已移除非权威建议层并保留全部强制故事权威",
                        stage=stage, metadata={
                            "before_required_tokens": (
                                before_input_tokens + before_output_reserve
                            ),
                            "after_required_tokens": (
                                estimated_input_tokens + route_output_reserve
                            ),
                            "context_window": context_window,
                            "remaining_pressure": pressure,
                        },
                    )
                if pressure in {"compact", "split"}:
                    capacity_error = ContextCapacityPreflightError(
                        pressure=pressure,
                        estimated_input_tokens=estimated_input_tokens,
                        authority_input_tokens=authority_input_tokens,
                        output_reserve=route_output_reserve,
                        context_window=context_window,
                    )
                    if capacity_splitter is None:
                        raise capacity_error
                    return await complete_capacity_split({
                        "trigger": "preflight",
                        "pressure": pressure,
                        "estimated_input_tokens": estimated_input_tokens,
                        "authority_input_tokens": authority_input_tokens,
                        "output_reserve": route_output_reserve,
                        "context_window": context_window,
                    })
            confirmed_context = self._stage_context_labels(
                model_constraints, user + style,
            )
            self.db.add_run_event(
                run_id, "success", "skills_loaded", f"已加载 {len(skills)} 个 Skill",
                stage=stage, metadata={
                    "skills": skills,
                    "prompt_characters": len(model_skill_prompt),
                    "source_prompt_characters": len(skill_run.prompt),
                    "compact_prompt": model_skill_prompt != skill_run.prompt,
                    "compact_input": compact_input,
                    "constraint_characters": len(model_constraints),
                    "source_constraint_characters": len(source_constraints),
                    "compact_constraints": model_constraints != source_constraints,
                    "confirmed_context": confirmed_context,
                    **({
                        "context_packet_sha256": context_packet_sha256(context_packet),
                        "context_layers": context_packet.metrics["layers"],
                        "removed_duplicate_rules": context_packet.metrics[
                            "removed_duplicate_rules"
                        ],
                        "filtered_advisory_characters": context_packet.metrics[
                            "filtered_advisory_characters"
                        ],
                    } if context_packet else {}),
                },
            )
            if stage == "polish":
                self.db.add_run_event(
                    run_id, "info", "polish_input_sized",
                    "Polish request context sized before provider call",
                    stage=stage, metadata={
                        "estimated_input_tokens": estimated_input_tokens,
                        "user_characters": len(user), "system_characters": len(system),
                    },
                )
            fallback_ceiling = self._provider_output_ceiling(gateway_role, True)
            effective_ceiling = provider_ceiling or output_budget
            fallback_budget = fallback_output_budget
            if fallback_budget is None:
                fallback_budget = self._output_budget_for_call(
                    stage, output_source_characters, gateway_role, True,
                    expected_output_characters=expected_output_characters,
                    input_tokens=estimated_input_tokens,
                    bounded_protocol_output=bounded_protocol_output,
                    scoped_creative_output=scoped_creative_output,
                )
            fallback_effective_ceiling = fallback_ceiling or fallback_budget
            if targeted_retry and output_source_characters is not None:
                output_budget = patch_output_budget(
                    output_source_characters, effective_ceiling or 1,
                )
                fallback_budget = patch_output_budget(
                    output_source_characters, fallback_effective_ceiling or 1,
                )
            output_limit_expanded_once = False
            structured_route_available = False
            if structured_contract is not None and isinstance(
                self.gateway, ModelGateway,
            ):
                structured_route_available = any(
                    capability_satisfies(
                        capability, StructuredOutputRequirement.STRICT,
                    )
                    for capability in self.gateway.configured_structured_capabilities(
                        gateway_role, include_capability_roster=True,
                    )
                )
                if not structured_route_available:
                    self.db.add_run_event(
                        run_id,
                        "warning",
                        "structured_output_plain_fallback",
                        "当前第三方模型路由未声明严格结构化能力，已使用 Runtime 控制字段的安全文本模式",
                        stage=stage,
                        metadata={
                            "contract": structured_contract.name,
                            "role": gateway_role,
                        },
                    )
            provider_capacity_split: dict | None = None
            try:
                if structured_route_available:
                    result = await self.gateway.complete_structured(
                        gateway_role,
                        system,
                        user,
                        structured_contract,
                        max_output_tokens=output_budget,
                        fallback_max_output_tokens=fallback_budget,
                        allow_capability_roster=True,
                    )
                elif allow_tools and hasattr(self.gateway, "complete_with_tools"):
                    toolbox = StoryToolbox(project, self.memory)
                    result = await self.gateway.complete_with_tools(
                        gateway_role, system, user, toolbox,
                        fallback_context=lambda: json.dumps(
                            self.memory.context(project.id, user[:500]), ensure_ascii=False,
                        ),
                        run_id=run_id,
                        max_output_tokens=output_budget,
                    )
                elif prefer_configured_fallback:
                    if (
                        defer_route_failure_audit
                        and not hasattr(self.gateway, "complete_configured_fallback")
                    ):
                        raise RuntimeError(
                            "configured fallback route interface unavailable"
                        )
                    if hasattr(self.gateway, "complete_configured_fallback"):
                        result = await self.gateway.complete_configured_fallback(
                            gateway_role, system, user,
                            max_output_tokens=output_budget,
                        )
                    else:
                        result = await self.gateway.complete(
                            gateway_role, system, user,
                            max_output_tokens=output_budget,
                        )
                elif primary_only:
                    if defer_route_failure_audit and not hasattr(
                        self.gateway, "complete_primary"
                    ):
                        raise RuntimeError("primary route interface unavailable")
                    if hasattr(self.gateway, "complete_primary"):
                        result = await self.gateway.complete_primary(
                            gateway_role, system, user,
                            max_output_tokens=output_budget,
                        )
                    else:
                        result = await self.gateway.complete(
                            gateway_role, system, user,
                            max_output_tokens=output_budget,
                        )
                elif isinstance(self.gateway, ModelGateway):
                    result = await self.gateway.complete(
                        gateway_role, system, user,
                        max_output_tokens=output_budget,
                        fallback_max_output_tokens=fallback_budget,
                    )
                else:
                    result = await self.gateway.complete(
                        gateway_role, system, user,
                        max_output_tokens=output_budget,
                    )
            except asyncio.CancelledError:
                raise
            except Exception as exc:
                if (
                    route_capacity_guard
                    and capacity_splitter is not None
                    and classify_model_failure(exc) == "input_context_overflow"
                ):
                    provider_capacity_split = {
                        "trigger": "provider",
                        "pressure": "split",
                        "estimated_input_tokens": estimated_input_tokens,
                        "authority_input_tokens": (
                            sum(
                                item["estimated_tokens"]
                                for name, item in context_packet.metrics["layers"].items()
                                if name != "advisory"
                            )
                            if context_packet is not None else estimated_input_tokens
                        ),
                        "output_reserve": route_output_reserve,
                        "context_window": context_window,
                        "provider_error": str(exc)[:500],
                    }
                elif not targeted_retry:
                    raise
                else:
                    execution_attempt = (
                        2 if isinstance(exc, ModelRoutesExhaustedError) else 1
                    )
                    decision = next_retry_action(
                        failure_kind="execution", attempt=execution_attempt,
                        current_limit=output_budget or 1,
                        provider_limit=effective_ceiling or output_budget or 1,
                    )
                    if (decision["action"] == "fallback"
                            and not prefer_configured_fallback
                            and hasattr(self.gateway, "complete_configured_fallback")):
                        try:
                            result = await self.gateway.complete_configured_fallback(
                                gateway_role, system, user,
                                max_output_tokens=fallback_budget,
                            )
                        except asyncio.CancelledError:
                            raise
                        except Exception as fallback_exc:
                            stop = next_retry_action(
                                failure_kind="execution", attempt=2,
                                current_limit=fallback_budget or 1,
                                provider_limit=(
                                    fallback_effective_ceiling or fallback_budget or 1
                                ),
                            )
                            assert stop["action"] == "stop"
                            raise TargetedGroupError(
                                str(fallback_exc)
                            ) from fallback_exc
                    else:
                        raise TargetedGroupError(str(exc)) from exc
            if provider_capacity_split is not None:
                return await complete_capacity_split(provider_capacity_split)
            result.receipt.setdefault("requested_max_output_tokens", output_budget)
            if (stage == "review" and gateway_role == "review" and not allow_tools
                    and not result.text.strip()
                    and result.receipt.get("finish_reason") == "max_tokens"):
                used_fallback = bool(
                    prefer_configured_fallback
                    or result.receipt.get("fallback_used")
                    or result.receipt.get("configured_fallback_direct")
                )
                review_retry_ceiling = (
                    fallback_ceiling if used_fallback else provider_ceiling
                )
                review_retry_budget = min(8192, review_retry_ceiling or 8192)
                self.db.add_run_event(
                    run_id, "warning", "review_max_tokens_retry",
                    "Review output hit its token limit; retrying the same route with full budget",
                    stage=stage, metadata={
                        "previous_budget": output_budget,
                        "retry_budget": review_retry_budget,
                        "model_name": result.receipt.get("model_name"),
                    },
                )
                retry_system = system + (
                    "\n\nDo not expose reasoning. Return only the compact review JSON. "
                    "Keep at most five highest-severity issues per category."
                )
                if used_fallback and hasattr(self.gateway, "complete_configured_fallback"):
                    result = await self.gateway.complete_configured_fallback(
                        gateway_role, retry_system, user,
                        max_output_tokens=review_retry_budget,
                    )
                elif primary_only:
                    if defer_route_failure_audit and not hasattr(
                        self.gateway, "complete_primary"
                    ):
                        raise RuntimeError("primary route interface unavailable")
                    if hasattr(self.gateway, "complete_primary"):
                        result = await self.gateway.complete_primary(
                            gateway_role, retry_system, user,
                            max_output_tokens=review_retry_budget,
                        )
                    else:
                        result = await self.gateway.complete(
                            gateway_role, retry_system, user,
                            max_output_tokens=review_retry_budget,
                        )
                else:
                    result = await self.gateway.complete(
                        gateway_role, retry_system, user,
                        max_output_tokens=review_retry_budget,
                    )
                result.receipt.setdefault(
                    "requested_max_output_tokens", review_retry_budget,
                )
                output_limit_expanded_once = True
                used_fallback = bool(
                    used_fallback
                    or result.receipt.get("fallback_used")
                    or result.receipt.get("configured_fallback_direct")
                )
                if (not result.text.strip() and not used_fallback and not primary_only
                        and hasattr(self.gateway, "complete_configured_fallback")):
                    self.db.add_run_event(
                        run_id, "warning", "review_configured_fallback",
                        "Review retry remained empty; using the review role configured fallback",
                        stage=stage,
                    )
                    result = await self.gateway.complete_configured_fallback(
                        gateway_role, retry_system, user,
                        max_output_tokens=min(8192, fallback_ceiling or 8192),
                    )
                    result.receipt.setdefault(
                        "requested_max_output_tokens", min(8192, fallback_ceiling or 8192),
                    )
            if (retry_polish_output_limit and stage == "polish"
                    and gateway_role == "polish" and not allow_tools
                    and not result.text.strip()
                    and result.receipt.get("finish_reason") in {"tool_use", "tool_calls"}):
                self.db.add_run_event(
                    run_id, "warning", "polish_tool_use_retry",
                    "Polish returned a tool call without prose; retrying once without tools",
                    stage=stage,
                )
                retry_system = system + (
                    "\n\nNo tools are available for this request. Return only the polished prose."
                )
                if prefer_configured_fallback and hasattr(
                    self.gateway, "complete_configured_fallback"
                ):
                    result = await self.gateway.complete_configured_fallback(
                        gateway_role, retry_system, user,
                        max_output_tokens=output_budget,
                    )
                else:
                    result = await self.gateway.complete(
                        gateway_role, retry_system, user,
                        max_output_tokens=output_budget,
                    )
                result.receipt.setdefault("requested_max_output_tokens", output_budget)
            if (not retry_polish_output_limit and stage == "polish"
                    and gateway_role == "polish" and output_limited(result.receipt)):
                error = RuntimeError(
                    "polish output incomplete (finish_reason=max_tokens)"
                )
                error.receipt = result.receipt
                raise error
            if output_limited(result.receipt):
                complete_at_limit = False
                if completion_check is not None:
                    try:
                        complete_at_limit = bool(completion_check(result.text))
                    except (TypeError, ValueError, json.JSONDecodeError):
                        complete_at_limit = False
                if complete_at_limit:
                    result.receipt["completion_status"] = "complete_at_limit"
                    self.db.add_run_event(
                        run_id, "warning", "output_limit_complete",
                        f"{stage} reached the route output limit but passed an independent completeness check",
                        stage=stage, metadata={
                            "requested_max_output_tokens": result.receipt.get(
                                "requested_max_output_tokens"
                            ),
                            "model_name": result.receipt.get("model_name"),
                        },
                    )
                else:
                    actual_model = self.db.get_model(
                        str(result.receipt.get("model_id") or "")
                    ) or {}
                    if not actual_model:
                        binding = self.db.get_role_binding(gateway_role) or {}
                        selected_key = (
                            "fallback_model_id"
                            if prefer_configured_fallback
                            or result.receipt.get("fallback_used")
                            or result.receipt.get("configured_fallback_direct")
                            else "primary_model_id"
                        )
                        actual_model = self.db.get_model(
                            str(binding.get(selected_key) or "")
                        ) or {}
                    previous_budget = int(
                        result.receipt.get("requested_max_output_tokens")
                        or output_budget or 1
                    )
                    retry_budget = expanded_output_budget(
                        previous_budget,
                        input_tokens=estimated_input_tokens,
                        context_window=actual_model.get("context_window"),
                        declared_output_ceiling=actual_model.get("max_output_tokens"),
                    )
                    if (not output_limit_expanded_once
                            and retry_budget and retry_budget > previous_budget):
                        self.db.add_run_event(
                            run_id, "warning", (
                                "polish_output_limit_retry"
                                if stage == "polish" else "output_limit_expanded"
                            ),
                            f"{stage} output may be truncated; retrying the same route with more headroom",
                            stage=stage, metadata={
                                "previous_budget": previous_budget,
                                "retry_budget": retry_budget,
                                "model_name": result.receipt.get("model_name"),
                                "failure_class": "output_limit",
                            },
                        )
                        used_fallback = bool(
                            prefer_configured_fallback
                            or result.receipt.get("fallback_used")
                            or result.receipt.get("configured_fallback_direct")
                        )
                        if structured_route_available:
                            result = await self.gateway.complete_structured(
                                gateway_role,
                                system,
                                user,
                                structured_contract,
                                max_output_tokens=retry_budget,
                                fallback_max_output_tokens=retry_budget,
                            )
                        elif used_fallback and hasattr(
                            self.gateway, "complete_configured_fallback"
                        ):
                            result = await self.gateway.complete_configured_fallback(
                                gateway_role, system, user,
                                max_output_tokens=retry_budget,
                            )
                        elif allow_tools and hasattr(self.gateway, "complete_with_tools"):
                            toolbox = StoryToolbox(project, self.memory)
                            result = await self.gateway.complete_with_tools(
                                gateway_role, system, user, toolbox,
                                fallback_context=lambda: json.dumps(
                                    self.memory.context(project.id, user[:500]),
                                    ensure_ascii=False,
                                ),
                                run_id=run_id,
                                max_output_tokens=retry_budget,
                            )
                        elif hasattr(self.gateway, "complete_primary"):
                            result = await self.gateway.complete_primary(
                                gateway_role, system, user,
                                max_output_tokens=retry_budget,
                            )
                        else:
                            result = await self.gateway.complete(
                                gateway_role, system, user,
                                max_output_tokens=retry_budget,
                            )
                        result.receipt.setdefault(
                            "requested_max_output_tokens", retry_budget,
                        )
                    retry_complete = not output_limited(result.receipt)
                    if not retry_complete and completion_check is not None:
                        try:
                            retry_complete = bool(completion_check(result.text))
                        except (TypeError, ValueError, json.JSONDecodeError):
                            retry_complete = False
                    if not retry_complete:
                        if capacity_splitter is not None:
                            return await complete_capacity_split({
                                "trigger": "output_limit",
                                "pressure": "split",
                                "estimated_input_tokens": estimated_input_tokens,
                                "authority_input_tokens": (
                                    sum(
                                        item["estimated_tokens"]
                                        for name, item in context_packet.metrics[
                                            "layers"
                                        ].items()
                                        if name != "advisory"
                                    )
                                    if context_packet is not None
                                    else estimated_input_tokens
                                ),
                                "output_reserve": route_output_reserve,
                                "context_window": context_window,
                                "provider_error": (
                                    "model output remained incomplete after one "
                                    "verified-headroom retry"
                                ),
                            })
                        partial = StageText(result.text, {
                            **result.receipt, "completion_status": "recoverable_partial",
                        })
                        raise IncompleteModelOutputError(stage, partial)
                    result.receipt["completion_status"] = (
                        "complete_at_limit" if output_limited(result.receipt) else "complete"
                    )
            if invalid_terminal_output(result.receipt):
                error = RuntimeError(
                    f"{stage} provider returned terminal state "
                    f"{result.receipt.get('finish_reason')}"
                )
                error.receipt = result.receipt
                raise error
            if not result.text.strip():
                error = RuntimeError(
                    f"{stage} model returned empty output "
                    f"(model={result.receipt.get('model_name', 'unknown')}, "
                    f"input_tokens={result.receipt.get('input_tokens', 0)}, "
                    f"output_tokens={result.receipt.get('output_tokens', 0)}, "
                    f"finish_reason={result.receipt.get('finish_reason', 'unknown')})"
                )
                error.receipt = result.receipt
                raise error
            if result.receipt.get("fallback_used"):
                fallback_metadata = {
                    "fallback_type": "configured",
                    "provider_id": result.receipt.get("provider_id"),
                    "model_id": result.receipt.get("model_id"),
                    "model_name": result.receipt.get("model_name"),
                    "primary_provider_id": result.receipt.get(
                        "fallback_from_provider_id"
                    ),
                    "primary_model_id": result.receipt.get(
                        "fallback_from_model_id"
                    ),
                }
                if (self.db.get_run(run_id) or {}).get(
                    "workflow"
                ) != "short-revision":
                    fallback_metadata["primary_error"] = result.receipt.get(
                        "primary_error"
                    )
                self.db.add_run_event(
                    run_id, "warning", "model_fallback",
                    f"{stage} 首选模型失败，已使用该角色配置的备用模型",
                    stage=stage, metadata=fallback_metadata,
                )
            name = f"{stage}{suffix}"
            atomic_write(run_path / "outputs" / f"{name}.md", result.text)
            receipt = {"model": result.receipt, "skills": [receipt.__dict__ for receipt in skill_run.receipts]}
            atomic_write(run_path / "receipts" / f"{name}.json", json.dumps(receipt, ensure_ascii=False, indent=2))
            self.db.save_workflow_node_checkpoint(
                run_id=run_id,
                node_key=node_key,
                authority_sha256=node_authority_sha256,
                input_sha256=node_input_sha256,
                output_sha256=hashlib.sha256(result.text.encode("utf-8")).hexdigest(),
                status="generated_complete",
                validation_stage=(
                    "syntax"
                    if completion_check is not None
                    and self._completion_check_safe(completion_check, result.text)
                    else "transport"
                ),
                route_fingerprint=str(result.receipt.get("route_fingerprint") or ""),
                payload={
                    "provider_id": result.receipt.get("provider_id"),
                    "model_id": result.receipt.get("model_id"),
                    "execution_mode": result.receipt.get("execution_mode"),
                    "finish_reason": result.receipt.get("finish_reason"),
                },
            )
            stage_completed_message = (
                "模型已返回，正在校验终审格式"
                if stage == "final_review" else
                f"{stage} 模型已返回，正在进行本阶段校验"
            )
            self.db.add_run_event(
                run_id, "success", "stage_completed", stage_completed_message, stage=stage,
                metadata={
                    "provider_id": result.receipt.get("provider_id"),
                    "model_name": result.receipt.get("model_name"),
                    "input_tokens": result.receipt.get("input_tokens", 0),
                    "output_tokens": result.receipt.get("output_tokens", 0),
                    "execution_mode": result.receipt.get("execution_mode"),
                    "skills": skills,
                },
            )
            return StageText(result.text, result.receipt)
        except asyncio.CancelledError:
            self.db.add_run_event(run_id, "warning", "stage_cancelled", f"{stage} 已终止", stage=stage)
            raise
        except Exception as exc:
            try:
                self.db.save_workflow_node_checkpoint(
                    run_id=run_id,
                    node_key=node_key,
                    authority_sha256=node_authority_sha256,
                    input_sha256=node_input_sha256,
                    output_sha256="",
                    status="failed",
                    payload={"error_type": type(exc).__name__},
                )
            except Exception:
                # Checkpoint observability must never mask the actual workflow
                # failure or alter the existing recovery path.
                pass
            if isinstance(exc, ContextCapacityPreflightError):
                self.db.add_run_event(
                    run_id, "warning", "stage_capacity_split_required",
                    f"{stage} 需要按语义所有权拆分后重试，尚未调用模型",
                    stage=stage, metadata={
                        "pressure": exc.pressure,
                        "estimated_input_tokens": exc.estimated_input_tokens,
                        "authority_input_tokens": exc.authority_input_tokens,
                        "output_reserve": exc.output_reserve,
                        "context_window": exc.context_window,
                    },
                )
                raise
            if isinstance(exc, IncompleteModelOutputError):
                if stage == "review":
                    self.db.add_run_event(
                        run_id, "error", "review_incomplete",
                        "审核模型已返回但内容仍不完整，未生成审核分数",
                        stage=stage, metadata={
                            "finish_reason": exc.receipt.get("finish_reason"),
                        },
                    )
                self.db.add_run_event(
                    run_id, "warning", "stage_recoverable_partial",
                    f"{stage} 返回了可恢复但不完整的内容，等待拆分或续跑",
                    stage=stage, metadata={
                        "finish_reason": exc.receipt.get("finish_reason"),
                        "model_name": exc.receipt.get("model_name"),
                    },
                )
                raise
            if defer_route_failure_audit:
                raise
            short_revision = (self.db.get_run(run_id) or {}).get(
                "workflow"
            ) == "short-revision"
            if stage == "review":
                self.db.add_run_event(
                    run_id, "error", "review_incomplete",
                    (
                        "终审模型未返回可用结果。"
                        if short_revision else
                        "Review primary and configured fallback did not produce usable output"
                    ),
                    stage=stage,
                    metadata={} if short_revision else {"error": str(exc)},
                )
            self.db.add_run_event(
                run_id, "error", "stage_failed",
                (
                    "定向返修模型阶段未完成，已保留可恢复进度。"
                    if short_revision else describe_error(exc)
                ),
                stage=stage,
            )
            raise

    async def _stage_with_role_fallback(
        self, run_id: str, run_path: Path, project: Project, stage: str,
        constraints: str, user: str, fallback_role: str, suffix: str = "",
        allow_tools: bool = True,
    ) -> str:
        try:
            return await self._stage(
                run_id, run_path, project, stage, constraints, user,
                suffix=suffix, allow_tools=allow_tools,
            )
        except asyncio.CancelledError:
            raise
        except Exception as exc:
            short_revision = (self.db.get_run(run_id) or {}).get(
                "workflow"
            ) == "short-revision"
            self.db.add_run_event(
                run_id, "warning", "model_fallback",
                f"{stage} 首选模型失败，已切换到 {fallback_role} 角色模型",
                stage=stage, metadata={
                    "fallback_role": fallback_role,
                    **({} if short_revision else {"error": str(exc)}),
                },
            )
            return await self._stage(
                run_id, run_path, project, stage, constraints, user,
                suffix=f"{suffix}-fallback", model_role=fallback_role,
                allow_tools=allow_tools,
            )

    def _protocol_receipt_attempt_plan(
        self, role: str, *, same_route_attempts: int,
    ) -> tuple[ProtocolReceiptAttempt, ...]:
        """Resolve one bounded route schedule for any immutable receipt."""

        binding = self.db.get_role_binding(role) or {}
        configured_fallback_available = bool(
            binding.get("fallback_provider_id")
            and binding.get("fallback_model_id")
            and hasattr(self.gateway, "complete_configured_fallback")
        )
        return protocol_receipt_attempts(
            same_route_attempts=same_route_attempts,
            configured_fallback_available=configured_fallback_available,
            fallback_attempts=2,
        )

    async def _execute_protocol_receipt_attempt(
        self, run_id: str, *, stage: str, boundary: str,
        attempt: ProtocolReceiptAttempt,
        unit_metadata: Mapping[str, object],
        operation: Callable[[], Awaitable[StageText]],
    ) -> tuple[StageText | None, ReliabilityFailure | None]:
        """Execute one explicit route and return a typed, hash-only failure."""

        unit_sha256 = hashlib.sha256(json.dumps(
            dict(unit_metadata), ensure_ascii=False, sort_keys=True,
            separators=(",", ":"), default=str,
        ).encode("utf-8")).hexdigest()
        circuit_state = self.protocol_route_circuit.acquire(
            run_id, stage, attempt.route,
        )
        if circuit_state == "open":
            prior_code, prior_class = self.protocol_route_circuit.last_failure(
                run_id, stage, attempt.route,
            )
            failure = ReliabilityFailure(
                code=prior_code,
                failure_class=prior_class,
                boundary=boundary,
                unit_id=f"{boundary}:{unit_sha256[:16]}",
                protocol_only=True,
                retryable=not attempt.is_last,
            )
            self.db.add_run_event(
                run_id, "warning", "protocol_receipt_route_circuit_bypassed",
                "The selected immutable-receipt route is temporarily open; "
                "the bounded schedule will continue without another doomed call.",
                stage=stage, metadata={
                    "boundary": boundary,
                    "route": attempt.route,
                    "route_attempt": attempt.route_attempt,
                    "attempt_index": attempt.attempt_index,
                    "failure_class": failure.failure_class.value,
                    "failure_code": failure.code,
                    "circuit_code": "protocol_route_circuit_open",
                    "retryable": failure.retryable,
                    **dict(unit_metadata),
                },
            )
            return None, failure
        if circuit_state == "half_open":
            self.db.add_run_event(
                run_id, "info", "protocol_receipt_route_circuit_half_open",
                "The route cooldown elapsed; one bounded recovery probe is allowed.",
                stage=stage, metadata={
                    "boundary": boundary,
                    "route": attempt.route,
                    "attempt_index": attempt.attempt_index,
                    **dict(unit_metadata),
                },
            )
        try:
            result = await operation()
        except asyncio.CancelledError:
            raise
        except Exception as exc:
            failure_kind = (
                "transport_interrupted"
                if isinstance(
                    exc, (ConnectionError, TimeoutError, TransportInterruptedError),
                )
                else classify_model_failure(exc)
            )
            failure_class = {
                "provider_rejection": FailureClass.CREDENTIAL,
                "input_context_overflow": FailureClass.CONTEXT_CAPACITY,
                "transport_interrupted": FailureClass.TRANSPORT,
                "output_limit": FailureClass.OUTPUT_TRUNCATION,
                "normal_invalid_output": FailureClass.UNKNOWN,
            }[failure_kind]
            route_execution_failure = failure_kind in {
                "provider_rejection", "transport_interrupted",
            }
            if route_execution_failure:
                circuit_opened = self.protocol_route_circuit.record_execution_failure(
                    run_id, stage, attempt.route,
                    failure_code=f"protocol_route_{failure_kind}",
                    failure_class=failure_class,
                )
            else:
                circuit_opened = False
                self.protocol_route_circuit.record_route_response(
                    run_id, stage, attempt.route,
                )
            code = f"protocol_route_{failure_kind}"
            error_sha256 = hashlib.sha256(
                describe_error(exc).encode("utf-8", errors="replace"),
            ).hexdigest()
            failure = ReliabilityFailure(
                code=code,
                failure_class=failure_class,
                boundary=boundary,
                unit_id=f"{boundary}:{unit_sha256[:16]}",
                protocol_only=True,
                retryable=not attempt.is_last,
            )
            self.db.add_run_event(
                run_id, "warning", "protocol_receipt_route_failed",
                "鏈€灏忓洖鎵х殑褰撳墠璺敱鎵ц澶辫触锛屽凡淇濈暀涓嶅彲鍙樻潈濞佸苟鎸夌被鍨嬪寲璺敱璁″垝缁х画",
                stage=stage, metadata={
                    "boundary": boundary,
                    "route": attempt.route,
                    "route_attempt": attempt.route_attempt,
                    "attempt_index": attempt.attempt_index,
                    "failure_class": failure_class.value,
                    "failure_kind": failure_kind,
                    "failure_code": code,
                    "error_sha256": error_sha256,
                    "exception_type": type(exc).__name__,
                    "retryable": failure.retryable,
                    **dict(unit_metadata),
                },
            )
            if circuit_opened:
                self.db.add_run_event(
                    run_id, "warning", "protocol_receipt_route_circuit_opened",
                    "Repeated route-execution failures opened the run-scoped "
                    "immutable-receipt circuit.",
                    stage=stage, metadata={
                        "boundary": boundary,
                        "route": attempt.route,
                        "failure_class": failure_class.value,
                        "failure_code": code,
                        **dict(unit_metadata),
                    },
                )
            if failure_class == FailureClass.CONTEXT_CAPACITY:
                raise
            return None, failure
        circuit_closed = self.protocol_route_circuit.record_route_response(
            run_id, stage, attempt.route,
        )
        if circuit_closed:
            self.db.add_run_event(
                run_id, "success", "protocol_receipt_route_circuit_closed",
                "The half-open route produced a response and rejoined the schedule.",
                stage=stage, metadata={
                    "boundary": boundary,
                    "route": attempt.route,
                    **dict(unit_metadata),
                },
            )
        return result, None

    def _record_protocol_receipt_fallback(
        self, run_id: str, *, stage: str, boundary: str,
        unit_metadata: Mapping[str, object], issues: Sequence[object],
    ) -> None:
        """Audit route escalation without persisting model or story text."""

        issue_codes: list[str] = []
        for issue in issues:
            if isinstance(issue, dict):
                code = str(issue.get("code") or issue.get("key") or "").strip()
            else:
                code = str(issue).split(":", 1)[0].strip()
            if code and code not in issue_codes:
                issue_codes.append(code)
        self.db.add_run_event(
            run_id, "warning", "protocol_receipt_model_fallback",
            "同一路由未形成可验证回执，正在保持原权威并切换配置的备用模型重审回执",
            stage=stage, metadata={
                "boundary": boundary,
                "failure_class": FailureClass.SYNTAX_PROTOCOL.value,
                "recovery_action": "fallback_capable_route",
                "issue_codes": issue_codes,
                **dict(unit_metadata),
            },
        )

    def _begin_run(self, project: Project, workflow: str,
                   run_id: str | None) -> tuple[str, Path]:
        run_id = run_id or uuid.uuid4().hex
        run_path = project.path / "runs" / run_id
        (run_path / "outputs").mkdir(parents=True, exist_ok=True)
        (run_path / "receipts").mkdir(exist_ok=True)
        if self.db.get_run(run_id) is None:
            self.db.create_run(run_id, project.id, workflow)
        else:
            self.db.update_run(run_id, "running", "starting")
        return run_id, run_path

    @staticmethod
    def _load_polish_checkpoint(root: Path, index: int, source: str,
                                 retry_signature: str | None = None,
                                 authority_hash: str | None = None) -> str | None:
        path = root / f"part-{index:02d}.json"
        if not path.is_file():
            return None
        try:
            value = json.loads(path.read_text(encoding="utf-8"))
        except (json.JSONDecodeError, OSError):
            return None
        digest = hashlib.sha256(source.encode("utf-8")).hexdigest()
        polished = value.get("polished")
        if "accepted" in value and value["accepted"] is not True:
            return None
        if (value.get("status") == "preserved_after_retry"
                and value.get("retry_signature") != retry_signature):
            return None
        if authority_hash is not None and value.get("authority_hash") != authority_hash:
            return None
        source_hash = value.get("source_sha256", value.get("source_hash"))
        return polished if source_hash == digest and isinstance(polished, str) else None

    @classmethod
    def _polish_checkpoint_progress(cls, root: Path, parts: list[str],
                                    retry_signature: str | None = None) -> tuple[int, int]:
        valid = [cls._load_polish_checkpoint(root, index, part, retry_signature) is not None
                 for index, part in enumerate(parts, 1)]
        return sum(valid), next((index for index, done in enumerate(valid, 1) if not done), len(parts))

    @staticmethod
    def _polish_retry_signature(binding: dict) -> str:
        return hashlib.sha256(json.dumps({
            "policy": "rhythm-v2",
            "primary_provider_id": binding.get("primary_provider_id"),
            "primary_model_id": binding.get("primary_model_id"),
            "fallback_provider_id": binding.get("fallback_provider_id"),
            "fallback_model_id": binding.get("fallback_model_id"),
        }, sort_keys=True).encode("utf-8")).hexdigest()

    @staticmethod
    def _save_polish_checkpoint(root: Path, index: int, source: str, polished: str,
                                 status: str = "accepted",
                                 retry_signature: str | None = None,
                                 accepted: bool = True,
                                 change_evidence: dict | None = None,
                                 authority_hash: str | None = None) -> None:
        source_hash = hashlib.sha256(source.encode("utf-8")).hexdigest()
        checkpoint = {
            "polished": polished,
            "accepted": accepted,
            "status": status,
            "retry_signature": retry_signature,
            "authority_hash": authority_hash,
            "change_evidence": change_evidence or {"ranges": [], "changed_ratio": 0.0},
        }
        checkpoint["source_sha256" if accepted else "source_hash"] = source_hash
        atomic_write(
            root / f"part-{index:02d}.json",
            json.dumps(checkpoint, ensure_ascii=False, indent=2),
        )

    def _post_write_maintenance(self, run_id: str, project: Project) -> None:
        skill = self.skills.skills(project.path).get("story-maintenance")
        if not skill or not skill.executable:
            return
        with self._maintenance_story_identity(project):
            for command in (
                ["scripts/story.js", "wordcount", ".", "--write"],
                ["scripts/story.js", "reindex", "."],
                ["scripts/story.js", "validate", "."],
            ):
                self.skills.run_required("archive", ["story-maintenance"], {"story-maintenance": command}, project.path, project.path)

    @staticmethod
    @contextmanager
    def _maintenance_story_identity(project: Project) -> Iterator[None]:
        story_path = project.path / "story.md"
        original = story_path.read_text(encoding="utf-8")
        compatible, count = re.subn(
            r"(?m)^title:.*$", f"title: {project.id}", original, count=1,
        )
        if count != 1:
            raise ValueError("story.md requires a title field")
        atomic_write(story_path, compatible)
        try:
            yield
        finally:
            atomic_write(story_path, original)

    def _volume_for_chapter(self, project: Project, chapter_number: int) -> dict | None:
        path = project.path / "memory" / "volumes.json"
        if not path.is_file():
            return None
        data = json.loads(path.read_text(encoding="utf-8"))
        return next((volume for volume in data.get("volumes", [])
                     if int(volume.get("start_chapter", 0)) <= chapter_number <= int(volume.get("end_chapter", -1))), None)

    def _is_volume_end(self, project: Project, chapter_number: int) -> bool:
        volume = self._volume_for_chapter(project, chapter_number)
        return bool(volume and chapter_number == int(volume.get("end_chapter", -1)))

    def _ensure_previous_volume_passed(self, project: Project, chapter_number: int) -> None:
        volume = self._volume_for_chapter(project, chapter_number)
        if not volume or chapter_number != int(volume.get("start_chapter", 0)) or chapter_number == 1:
            return
        previous = int(volume["number"]) - 1
        audit = project.path / "memory" / "audits" / f"volume-{previous:02d}.json"
        if not audit.is_file() or json.loads(audit.read_text(encoding="utf-8")).get("status") != "passed":
            raise RuntimeError(f"Previous volume audit is not passed: volume {previous}")

    async def _audit_volume_boundary(self, run_id: str, run_path: Path, project: Project,
                                     chapter_number: int, constraints: str) -> None:
        volume = self._volume_for_chapter(project, chapter_number)
        if not volume or chapter_number != int(volume.get("end_chapter", -1)):
            return
        parts = []
        for number in range(int(volume["start_chapter"]), chapter_number + 1):
            path = project.path / "chapters" / f"chapter-{number:02d}.md"
            if path.is_file():
                parts.append(f"CHAPTER {number}:\n{path.read_text(encoding='utf-8')[:4000]}")
        evidence = json.dumps(volume, ensure_ascii=False) + "\n\n" + "\n\n".join(parts)
        text = await self._stage(run_id, run_path, project, "final_review", constraints, evidence,
                                 suffix=f"-volume-{int(volume['number']):02d}")
        review = self._review(text)
        passed, _ = quality_gate(review)
        report = {**review, "volume": int(volume["number"]),
                  "status": "passed" if passed else "blocked"}
        audit = project.path / "memory" / "audits" / f"volume-{int(volume['number']):02d}.json"
        atomic_write(audit, json.dumps(report, ensure_ascii=False, indent=2))
        for issue in review.get("issues", []):
            self.memory.record_drift(project.id, "volume-audit", int(100 - review["score"]), str(issue))
        if report["status"] == "blocked":
            raise RuntimeError(f"Volume audit blocked volume {volume['number']}")

    async def _run_in_crewai(self, pipeline):
        self.crewai_data_dir.mkdir(parents=True, exist_ok=True)
        configure_runtime_environment(self.db.path.parent, self.crewai_data_dir)
        from crewai.flow.flow import Flow, start

        primary_error: BaseException | None = None
        primary_traceback = None

        class RuntimeFlow(Flow):
            @start()
            async def execute(self):
                nonlocal primary_error, primary_traceback
                try:
                    return await pipeline()
                except BaseException as exc:
                    primary_error = exc
                    primary_traceback = exc.__traceback__
                    raise

        runtime = RuntimeFlow()
        try:
            return await runtime.kickoff_async()
        except BaseException as wrapper_error:
            if primary_error is not None and wrapper_error is not primary_error:
                # CrewAI performs event, trace and memory cleanup after the
                # pipeline exits. A cleanup failure must not replace the
                # actionable workflow error that triggered recovery.
                raise primary_error.with_traceback(primary_traceback) from wrapper_error
            raise

    @staticmethod
    def _json_object(text: str) -> dict:
        return GeneratedArtifactGateway().convert_object(
            text, contract_name="generated_narrative_artifact",
        ).payload

    @staticmethod
    def _normalized_revision_plan(value: dict, segment_count: int, **kwargs) -> dict:
        def normalized_issue_ids(raw) -> list[str]:
            values = [raw] if isinstance(raw, str) else raw if isinstance(raw, list) else []
            return sorted({item.strip() for item in values
                           if isinstance(item, str) and item.strip()})

        plan = normalize_revision_plan(value, segment_count, **kwargs)
        raw_checks = value.get("checks") if isinstance(value.get("checks"), list) else []
        for check in plan["checks"]:
            raw = next((item for item in raw_checks if isinstance(item, dict)
                        and item.get("kind") == check["kind"]
                        and str(item.get("value", "")).strip() == check["value"]), None)
            issue_ids = normalized_issue_ids((raw or {}).get("issue_ids"))
            if issue_ids:
                check["issue_ids"] = issue_ids
        raw_tasks = value.get("tasks") if isinstance(value.get("tasks"), list) else []
        for task_list in (plan["tasks"], plan.get("deferred_tasks", [])):
            for task in task_list:
                raw = next((item for item in raw_tasks if isinstance(item, dict)
                            and str(item.get("instruction", "")).strip()
                            == task["instruction"]), None)
                position = (raw or {}).get("seven_step_position")
                if isinstance(position, str) and position.strip():
                    task["seven_step_position"] = position.strip()
                issue_ids = normalized_issue_ids((raw or {}).get("issue_ids"))
                if issue_ids:
                    task["issue_ids"] = issue_ids
                else:
                    task.pop("issue_ids", None)
        return plan

    @staticmethod
    def _reader_json_object(text: str) -> dict:
        cleaned = re.sub(r"^```(?:json)?\s*|\s*```$", "", text.strip(), flags=re.IGNORECASE)
        start, end = cleaned.find("{"), cleaned.rfind("}")
        if start < 0 or end <= start:
            raise ValueError("Reader model output does not contain a JSON object")
        candidate = cleaned[start:end + 1]
        field_names = (
            "category|severity|evidence|action|commercial|story|prose|hard_fail|decision|"
            "issues|dimensions|reader_signals|would_continue|would_pay|abandonment_point|"
            "payoff_felt"
        )
        candidate = re.sub(
            rf"['’]\s*,\s*['’]({field_names})['’]\s*:",
            lambda match: f'", "{match.group(1)}":',
            candidate,
        )
        value = json.loads(candidate)
        if not isinstance(value, dict):
            raise ValueError("Reader model output must be a JSON object")
        return value

    @classmethod
    def _review(cls, text: str) -> dict:
        payload = GeneratedArtifactGateway().convert_object(
            text, contract_name="final_review",
        ).payload
        return normalize_review(payload)

    @classmethod
    def _review_for_project(
        cls, value: str | dict, project: Project, receipt: dict | None = None,
    ) -> dict:
        payload = cls._json_object(value) if isinstance(value, str) else value
        profile_id = profile_for_project(project)
        criteria = payload.get("criteria") if isinstance(payload.get("criteria"), dict) else {}
        if (profile_id == ZHihu_SHORT_V2.id
                and all(name in criteria for name in ZHihu_SHORT_V2.criterion_dimensions)):
            payload = {
                **payload,
                "dimensions": {name: 0 for name in ZHihu_SHORT_V2.dimension_weights},
            }
        review = score_review(
            normalize_review(payload), profile_id,
        )
        review["judge_signature"] = judge_signature(receipt)
        return review

    @staticmethod
    def _stage_output_budget(stage: str, source_characters: int | None = None) -> int | None:
        return stage_output_budget(stage, source_characters)

    def _output_budget_for_call(
        self, stage: str, source_characters: int | None,
        gateway_role: str, prefer_configured_fallback: bool,
        *, expected_output_characters: int | None = None,
        input_tokens: int = 0,
        bounded_protocol_output: bool = False,
        scoped_creative_output: bool = False,
    ) -> int | None:
        binding = self.db.get_role_binding(gateway_role) or {}
        model_key = (
            "fallback_model_id" if prefer_configured_fallback else "primary_model_id"
        )
        model = self.db.get_model(binding.get(model_key, "")) or {}
        expected = (
            expected_output_characters
            if expected_output_characters is not None else source_characters
        )
        if bounded_protocol_output:
            return bounded_protocol_output_budget(
                expected_output_characters=expected,
                input_tokens=input_tokens,
                context_window=model.get("context_window"),
                declared_output_ceiling=model.get("max_output_tokens"),
            )
        if scoped_creative_output:
            return scoped_creative_output_budget(
                expected_output_characters=expected,
                input_tokens=input_tokens,
                context_window=model.get("context_window"),
                declared_output_ceiling=model.get("max_output_tokens"),
            )
        return adaptive_output_budget(
            stage,
            expected_output_characters=expected,
            input_tokens=input_tokens,
            context_window=model.get("context_window"),
            declared_output_ceiling=model.get("max_output_tokens"),
        )

    def _provider_output_ceiling(self, gateway_role: str,
                                 prefer_configured_fallback: bool) -> int | None:
        binding = self.db.get_role_binding(gateway_role) or {}
        model_key = (
            "fallback_model_id" if prefer_configured_fallback else "primary_model_id"
        )
        model = self.db.get_model(binding.get(model_key, "")) or {}
        ceiling = model.get("max_output_tokens")
        return ceiling if isinstance(ceiling, int) and ceiling > 0 else None

    def _provider_context_window(self, gateway_role: str,
                                 prefer_configured_fallback: bool) -> int | None:
        binding = self.db.get_role_binding(gateway_role) or {}
        model_key = (
            "fallback_model_id" if prefer_configured_fallback else "primary_model_id"
        )
        model = self.db.get_model(binding.get(model_key, "")) or {}
        window = model.get("context_window")
        return window if isinstance(window, int) and window > 0 else None

    def _route_safe_context_window(
        self, gateway_role: str, *, prefer_configured_fallback: bool = False,
        include_configured_fallback: bool = False,
    ) -> int:
        """Return the conservative context capacity for every possible route.

        Missing provider metadata is deliberately treated as 32K.  A normal
        call that may automatically fall back is planned against the smaller
        of the primary and configured fallback routes, preventing a large
        primary prompt from being forwarded unchanged to a smaller backup.
        """
        unknown_capacity = 32_768
        selected = self._provider_context_window(
            gateway_role, prefer_configured_fallback,
        ) or unknown_capacity
        windows = [selected]
        if include_configured_fallback:
            binding = self.db.get_role_binding(gateway_role) or {}
            if binding.get("fallback_provider_id") and binding.get("fallback_model_id"):
                windows.append(
                    self._provider_context_window(gateway_role, True)
                    or unknown_capacity
                )
        return min(windows)

    @staticmethod
    def _chapter_file(project: Project, text: str, number: int = 1) -> str:
        return (
            f"---\ntitle: {project.title}\nnumber: {number}\npov: {project.metadata['pov']}\n"
            "locations: []\ncharacters: []\narcs-advanced: []\nstatus: final\nword-count: 0\n---\n\n"
            f"# Chapter {number}: {project.title}\n\n## Chapter Text\n\n{text}\n"
        )
